CREATE OR REPLACE FUNCTION "public"."_best_1rm_from_exercises"("p_exercises" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_ex        jsonb;
  v_set       jsonb;
  v_w         numeric;
  v_r         numeric;
  v_e1rm      numeric;
  v_best_e1rm numeric := NULL;
  v_best      jsonb   := NULL;
  v_name      text;
BEGIN
  IF p_exercises IS NULL OR jsonb_typeof(p_exercises) <> 'array' THEN
    RETURN NULL;
  END IF;

  FOR v_ex IN SELECT * FROM jsonb_array_elements(p_exercises) LOOP
    v_name := v_ex->>'name';
    IF jsonb_typeof(v_ex->'sets') = 'array' THEN
      FOR v_set IN SELECT * FROM jsonb_array_elements(v_ex->'sets') LOOP
        v_w := COALESCE((v_set->>'weight')::numeric, 0);
        v_r := COALESCE((v_set->>'reps')::numeric, 0);
        IF v_r > 1 THEN
          v_e1rm := v_w * (1 + v_r / 30);
        ELSE
          v_e1rm := v_w;
        END IF;
        IF v_best_e1rm IS NULL OR v_e1rm > v_best_e1rm THEN
          v_best_e1rm := v_e1rm;
          v_best := jsonb_build_object(
            'exercise', v_name,
            'weight',   v_w,
            'reps',     v_r,
            'e1rm',     v_e1rm
          );
        END IF;
      END LOOP;
    END IF;
  END LOOP;

  RETURN v_best;
END;
$$;


ALTER FUNCTION "public"."_best_1rm_from_exercises"("p_exercises" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_crew_member_week_stats"("p_user_id" "uuid", "p_since" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_combined jsonb;
BEGIN
  SELECT COALESCE(jsonb_agg(elem), '[]'::jsonb)
  INTO v_combined
  FROM public.workout_logs,
       jsonb_array_elements(
         CASE WHEN jsonb_typeof(exercises) = 'array' THEN exercises ELSE '[]'::jsonb END
       ) AS elem
  WHERE user_id = p_user_id
    AND date >= p_since;

  RETURN jsonb_build_object(
    'volume_lbs', public._duel_calc_volume(v_combined),
    'best_pr',    public._best_1rm_from_exercises(v_combined)
  );
END;
$$;


ALTER FUNCTION "public"."_crew_member_week_stats"("p_user_id" "uuid", "p_since" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_crew_war_score"("p_volume" numeric, "p_sessions" integer, "p_days" integer) RETURNS integer
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
  SELECT (
      FLOOR(LEAST(200000, GREATEST(0, COALESCE(p_volume, 0))) / 100)
    + LEAST(28, GREATEST(0, COALESCE(p_sessions, 0))) * 50
    + LEAST(7,  GREATEST(0, COALESCE(p_days, 0)))     * 100
  )::integer;
$$;


ALTER FUNCTION "public"."_crew_war_score"("p_volume" numeric, "p_sessions" integer, "p_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_duel_calc_volume"("p_exercises" "jsonb") RETURNS numeric
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_total NUMERIC := 0;
  v_ex    JSONB;
  v_set   JSONB;
BEGIN
  IF p_exercises IS NULL OR jsonb_typeof(p_exercises) <> 'array' THEN
    RETURN 0;
  END IF;
  FOR v_ex IN SELECT * FROM jsonb_array_elements(p_exercises) LOOP
    IF jsonb_typeof(v_ex->'sets') = 'array' THEN
      FOR v_set IN SELECT * FROM jsonb_array_elements(v_ex->'sets') LOOP
        v_total := v_total + COALESCE((v_set->>'weight')::NUMERIC, 0)
                           * COALESCE((v_set->>'reps')::NUMERIC, 0);
      END LOOP;
    END IF;
  END LOOP;
  RETURN v_total;
END;
$$;


ALTER FUNCTION "public"."_duel_calc_volume"("p_exercises" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_duel_metrics_from_log"("p_exercises" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_ex JSONB; v_set JSONB;
  v_vol NUMERIC := 0; v_max_reps NUMERIC := 0; v_max_weight NUMERIC := 0; v_sets INT := 0;
  v_w NUMERIC; v_r NUMERIC;
BEGIN
  IF p_exercises IS NULL OR jsonb_typeof(p_exercises) <> 'array' THEN
    RETURN jsonb_build_object('volume', 0, 'reps', 0, 'weight', 0, 'sets_completed', 0);
  END IF;
  FOR v_ex IN SELECT * FROM jsonb_array_elements(p_exercises) LOOP
    IF jsonb_typeof(v_ex->'sets') = 'array' THEN
      FOR v_set IN SELECT * FROM jsonb_array_elements(v_ex->'sets') LOOP
        v_w := COALESCE((v_set->>'weight')::NUMERIC, 0);
        v_r := COALESCE((v_set->>'reps')::NUMERIC, 0);
        v_vol := v_vol + v_w * v_r;
        IF v_r > 0 THEN v_sets := v_sets + 1; END IF;
        IF v_r > v_max_reps THEN v_max_reps := v_r; END IF;
        IF v_w > v_max_weight THEN v_max_weight := v_w; END IF;
      END LOOP;
    END IF;
  END LOOP;
  RETURN jsonb_build_object('volume', v_vol, 'reps', v_max_reps, 'weight', v_max_weight, 'sets_completed', v_sets);
END;
$$;


ALTER FUNCTION "public"."_duel_metrics_from_log"("p_exercises" "jsonb") OWNER TO "postgres";

