    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "challenger_id" "uuid" NOT NULL,
    "opponent_id" "uuid" NOT NULL,
    "type" "public"."duel_type" DEFAULT 'open'::"public"."duel_type" NOT NULL,
    "status" "public"."duel_status" DEFAULT 'pending'::"public"."duel_status" NOT NULL,
    "session_template" "jsonb",
    "target_exercise_id" "uuid",
    "window_hours" integer DEFAULT 24 NOT NULL,
    "challenger_result" "jsonb",
    "opponent_result" "jsonb",
    "winner_id" "uuid",
    "hub_posted" boolean DEFAULT false NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "expires_at" timestamp with time zone DEFAULT ("now"() + '24:00:00'::interval) NOT NULL
);


ALTER TABLE "public"."duels" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_duel_resolve_winner"("p_duel" "public"."duels") RETURNS "uuid"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_c_score NUMERIC;
  v_o_score NUMERIC;
BEGIN
  IF p_duel.challenger_result IS NULL OR p_duel.opponent_result IS NULL THEN
    RETURN NULL;
  END IF;

  IF p_duel.type = 'mirror' THEN
    v_c_score := public._duel_score_mirror(p_duel.challenger_result, p_duel.session_template);
    v_o_score := public._duel_score_mirror(p_duel.opponent_result,  p_duel.session_template);
  ELSIF p_duel.type = 'open' THEN
    v_c_score := COALESCE((p_duel.challenger_result->>'volume')::NUMERIC, 0);
    v_o_score := COALESCE((p_duel.opponent_result->>'volume')::NUMERIC,  0);
  ELSE
    v_c_score := COALESCE((p_duel.challenger_result->>'reps')::NUMERIC,
                          (p_duel.challenger_result->>'weight')::NUMERIC, 0);
    v_o_score := COALESCE((p_duel.opponent_result->>'reps')::NUMERIC,
                          (p_duel.opponent_result->>'weight')::NUMERIC, 0);
  END IF;

  IF v_c_score = v_o_score THEN RETURN NULL; END IF;
  IF v_c_score > v_o_score THEN RETURN p_duel.challenger_id; ELSE RETURN p_duel.opponent_id; END IF;
END;
$$;


ALTER FUNCTION "public"."_duel_resolve_winner"("p_duel" "public"."duels") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_duel_score_mirror"("p_result" "jsonb", "p_template" "jsonb") RETURNS integer
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_exercises  JSONB;
  v_prescribed INT := 0;
  v_completed  INT := 0;
  v_completion NUMERIC;
  v_volume_pr  NUMERIC;
  v_volume_a   NUMERIC;
  v_ratio      NUMERIC;
  v_ex         JSONB;
BEGIN
  IF p_template IS NULL THEN RETURN 0; END IF;
  v_exercises := p_template->'exercises';
  IF v_exercises IS NULL OR jsonb_typeof(v_exercises) <> 'array' THEN RETURN 0; END IF;

  FOR v_ex IN SELECT * FROM jsonb_array_elements(v_exercises) LOOP
    IF jsonb_typeof(v_ex->'sets') = 'array' THEN
      v_prescribed := v_prescribed + jsonb_array_length(v_ex->'sets');
    END IF;
  END LOOP;
  IF v_prescribed = 0 THEN RETURN 0; END IF;

  v_completed  := COALESCE((p_result->>'sets_completed')::INT, 0);
  v_completion := LEAST(v_completed::NUMERIC / v_prescribed, 1);

  v_volume_pr := public._duel_calc_volume(v_exercises);
  v_volume_a  := COALESCE((p_result->>'volume')::NUMERIC, 0);
  v_ratio     := CASE WHEN v_volume_pr > 0 THEN LEAST(v_volume_a / v_volume_pr, 1.5) ELSE 1 END;

  RETURN ROUND((v_completion * 0.6 + (v_ratio / 1.5) * 0.4) * 1000)::INT;
END;
$$;


ALTER FUNCTION "public"."_duel_score_mirror"("p_result" "jsonb", "p_template" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_notify_crew_everyone"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_sender_name TEXT;
  v_member      RECORD;
  v_preview     TEXT;
BEGIN
  IF NEW.content IS NULL OR NEW.content NOT ILIKE '%@everyone%' THEN
    RETURN NEW;
  END IF;

  SELECT username INTO v_sender_name
    FROM public.user_profiles
   WHERE id = NEW.sender_id
   LIMIT 1;

  v_preview := left(NEW.content, 80);

  FOR v_member IN
    SELECT cm.user_id, up.email
      FROM public.crew_members cm
      JOIN public.user_profiles up ON up.id = cm.user_id
     WHERE cm.crew_id = NEW.crew_id
       AND cm.user_id <> NEW.sender_id
       AND up.email IS NOT NULL
  LOOP
    INSERT INTO public.notifications
      (user_id, user_email, type, title, body, icon, link_url, metadata)
    VALUES
      (v_member.user_id,
       v_member.email,
       'crew_everyone',
       COALESCE(v_sender_name, 'Someone') || ' called @everyone',
       v_preview,
       '📣',
       '/hub',
       jsonb_build_object(
         'crew_id',    NEW.crew_id,
         'message_id', NEW.id,
         'sender_id',  NEW.sender_id,
         'sender_name', v_sender_name
       ));
  END LOOP;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."_notify_crew_everyone"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_notify_duel_result_inner"("p_recipient_id" "uuid", "p_duel_id" "uuid", "p_outcome" "text", "p_actor_name" "text" DEFAULT 'Someone'::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
      DECLARE
        v_email TEXT;
        v_lang  TEXT;
        v_text  JSONB;
      BEGIN
        SELECT email INTO v_email FROM auth.users WHERE id = p_recipient_id;
        IF v_email IS NULL THEN RETURN; END IF;
        SELECT preferred_language INTO v_lang FROM public.user_profiles WHERE id = p_recipient_id;
        v_text := public.duel_result_text(COALESCE(v_lang, 'en'), p_actor_name, p_outcome);
        INSERT INTO public.notifications
          (user_id, user_email, type, title, body, icon, link_url, metadata)
        VALUES
          (p_recipient_id, v_email, 'duel_result',
           v_text ->> 'title', NULL, '⚔️', '/duels',
           jsonb_build_object('duel_id', p_duel_id, 'outcome', p_outcome));
      END;
      $$;


ALTER FUNCTION "public"."_notify_duel_result_inner"("p_recipient_id" "uuid", "p_duel_id" "uuid", "p_outcome" "text", "p_actor_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_notify_post_like"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_post       RECORD;
  v_actor_name TEXT;
BEGIN
  IF NEW.reaction_type IS DISTINCT FROM 'like' THEN
    RETURN NEW;
  END IF;

  SELECT p.user_id, p.author_email
    INTO v_post
    FROM public.hub_posts p
   WHERE p.id = NEW.post_id;

  IF v_post.user_id IS NULL OR v_post.author_email IS NULL THEN
    RETURN NEW;
  END IF;

  IF v_post.user_id = NEW.user_id THEN
    RETURN NEW;
  END IF;

  SELECT username INTO v_actor_name
    FROM public.user_profiles
   WHERE id = NEW.user_id
   LIMIT 1;

  INSERT INTO public.notifications
    (user_id, user_email, type, title, body, icon, link_url, metadata)
  VALUES
    (v_post.user_id,
     v_post.author_email,
     'post_like',
     COALESCE(v_actor_name, split_part(COALESCE(NEW.user_email, NEW.created_by, ''), '@', 1), 'Someone')
       || ' liked your post',
     NULL,
     '❤️',
     '/hub',
     jsonb_build_object(
       'actor_id',    NEW.user_id,
       'actor_email', NEW.user_email,
       'actor_name',  v_actor_name,
       'post_id',     NEW.post_id
     ));

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."_notify_post_like"() OWNER TO "postgres";


