CREATE OR REPLACE FUNCTION "public"."_pick_loot_item"("p_rarity" "text", "p_category" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_row jsonb;
BEGIN
  SELECT jsonb_build_object('item_id', item_id, 'item_name', item_name,
                            'item_emoji', item_emoji, 'item_type', item_type)
    INTO v_row
    FROM public.loot_catalog
   WHERE item_rarity = p_rarity AND item_type = p_category AND item_type <> 'capsule'
   ORDER BY random() LIMIT 1;
  IF v_row IS NOT NULL THEN RETURN v_row; END IF;

  SELECT jsonb_build_object('item_id', item_id, 'item_name', item_name,
                            'item_emoji', item_emoji, 'item_type', item_type)
    INTO v_row
    FROM public.loot_catalog
   WHERE item_rarity = p_rarity AND item_type = 'sticker'
   ORDER BY random() LIMIT 1;
  IF v_row IS NOT NULL THEN RETURN v_row; END IF;

  SELECT jsonb_build_object('item_id', item_id, 'item_name', item_name,
                            'item_emoji', item_emoji, 'item_type', item_type)
    INTO v_row
    FROM public.loot_catalog
   WHERE item_rarity = p_rarity AND item_type <> 'capsule'
   ORDER BY random() LIMIT 1;

  IF v_row IS NULL THEN
    RAISE EXCEPTION 'no catalogue item for rarity %', p_rarity USING ERRCODE = '22023';
  END IF;
  RETURN v_row;
END;
$$;


ALTER FUNCTION "public"."_pick_loot_item"("p_rarity" "text", "p_category" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_roll_capsule_rarity"("p_uid" "uuid", "p_capsule_type" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_type       TEXT := COALESCE(p_capsule_type, 'standard');
  v_rarity     TEXT;
  v_since_epic INTEGER;
  v_since_leg  INTEGER;
  v_leg_bonus  NUMERIC := 0;
  v_pity       TEXT := 'none';
  v_epic_at    CONSTANT INTEGER := 30;
  v_leg_at     CONSTANT INTEGER := 90;
  v_soft_from  CONSTANT INTEGER := 61;
BEGIN
  SELECT COALESCE(pity_since_epic, 0), COALESCE(pity_since_legendary, 0)
    INTO v_since_epic, v_since_leg
    FROM public.user_profiles WHERE id = p_uid FOR UPDATE;

  v_since_epic := COALESCE(v_since_epic, 0) + 1;
  v_since_leg  := COALESCE(v_since_leg, 0) + 1;

  IF v_since_leg >= v_leg_at THEN
    v_rarity := 'legendary';
    v_pity   := 'legendary_guaranteed';
  ELSIF v_since_epic >= v_epic_at THEN
    IF v_type = 'premium' THEN
      v_rarity := public._weighted_pick(ARRAY['epic','legendary','animated']::TEXT[],
                                        ARRAY[0.065, 0.013, 0.002]::NUMERIC[]);
    ELSIF v_type = 'elite' THEN
      v_rarity := public._weighted_pick(ARRAY['epic','legendary','animated']::TEXT[],
                                        ARRAY[0.220, 0.070, 0.010]::NUMERIC[]);
    ELSE
      v_rarity := public._weighted_pick(ARRAY['epic','legendary','animated']::TEXT[],
                                        ARRAY[0.018, 0.002, 0.000]::NUMERIC[]);
    END IF;
    v_pity := 'epic_guaranteed';
  ELSE
    IF v_since_leg >= v_soft_from THEN
      v_leg_bonus := (v_since_leg - (v_soft_from - 1)) * 0.03;
      v_pity := 'soft';
    END IF;
    IF v_type = 'premium' THEN
      v_rarity := public._weighted_pick(
        ARRAY['common','uncommon','rare','epic','legendary','animated']::TEXT[],
        ARRAY[0.350, 0.380, 0.190, 0.065, 0.013 + v_leg_bonus, 0.002]::NUMERIC[]);
    ELSIF v_type = 'elite' THEN
      v_rarity := public._weighted_pick(
        ARRAY['common','uncommon','rare','epic','legendary','animated']::TEXT[],
        ARRAY[0.100, 0.250, 0.350, 0.220, 0.070 + v_leg_bonus, 0.010]::NUMERIC[]);
    ELSE
      v_rarity := public._weighted_pick(
        ARRAY['common','uncommon','rare','epic','legendary','animated']::TEXT[],
        ARRAY[0.600, 0.280, 0.100, 0.018, 0.002 + v_leg_bonus, 0.000]::NUMERIC[]);
    END IF;
  END IF;

  IF v_rarity IN ('legendary', 'mythic', 'animated') THEN
    v_since_leg  := 0;
    v_since_epic := 0;
  ELSIF v_rarity = 'epic' THEN
    v_since_epic := 0;
  END IF;

  UPDATE public.user_profiles
     SET pity_since_epic = v_since_epic, pity_since_legendary = v_since_leg
   WHERE id = p_uid;

  RETURN jsonb_build_object('rarity', v_rarity, 'pity', v_pity,
                            'since_epic', v_since_epic, 'since_legendary', v_since_leg);
END;
$$;


ALTER FUNCTION "public"."_roll_capsule_rarity"("p_uid" "uuid", "p_capsule_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_roll_capsule_shape"("p_capsule_type" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_type     TEXT := COALESCE(p_capsule_type, 'standard');
  v_category TEXT;
  v_variant  TEXT;
BEGIN
  -- 'theme' removed; its weight folded into 'sticker' so title/frame
  -- odds are unchanged.
  IF v_type = 'premium' THEN
    v_category := public._weighted_pick(ARRAY['title','frame','sticker']::TEXT[],
                                        ARRAY[0.12, 0.10, 0.78]::NUMERIC[]);
  ELSIF v_type = 'elite' THEN
    v_category := public._weighted_pick(ARRAY['title','frame','sticker']::TEXT[],
                                        ARRAY[0.20, 0.17, 0.63]::NUMERIC[]);
  ELSE
    v_category := public._weighted_pick(ARRAY['title','frame','sticker']::TEXT[],
                                        ARRAY[0.05, 0.04, 0.91]::NUMERIC[]);
  END IF;

  IF v_category = 'sticker' THEN
    IF v_type = 'premium' THEN
      v_variant := public._weighted_pick(ARRAY['plain','foil','gold','diamond']::TEXT[],
                                         ARRAY[0.90, 0.08, 0.02, 0.00]::NUMERIC[]);
    ELSIF v_type = 'elite' THEN
      v_variant := public._weighted_pick(ARRAY['plain','foil','gold','diamond']::TEXT[],
                                         ARRAY[0.80, 0.14, 0.05, 0.01]::NUMERIC[]);
    ELSE
      v_variant := public._weighted_pick(ARRAY['plain','foil','gold','diamond']::TEXT[],
                                         ARRAY[0.97, 0.03, 0.00, 0.00]::NUMERIC[]);
    END IF;
    IF v_variant = 'plain' THEN v_variant := NULL; END IF;
  ELSE
    v_variant := NULL;
  END IF;

  RETURN jsonb_build_object('category', v_category, 'variant', v_variant);
END;
$$;


ALTER FUNCTION "public"."_roll_capsule_shape"("p_capsule_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_tg_sync_league_member_count"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    UPDATE public.leagues SET member_count=COALESCE(member_count,0)+1 WHERE id=NEW.league_id;
    RETURN NEW;
  ELSIF TG_OP = 'DELETE' THEN
    UPDATE public.leagues SET member_count=GREATEST(0,COALESCE(member_count,0)-1) WHERE id=OLD.league_id;
    RETURN OLD;
  END IF;
  RETURN NULL;
END; $$;


ALTER FUNCTION "public"."_tg_sync_league_member_count"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_tg_validate_sticker_reaction"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_inv public.user_inventory%ROWTYPE;
BEGIN
  IF NEW.user_id IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'cannot react on behalf of another user' USING ERRCODE='42501';
  END IF;
  SELECT * INTO v_inv FROM public.user_inventory
    WHERE user_id=NEW.user_id AND item_id=NEW.item_id AND item_type='sticker'
      AND (variant IS NOT DISTINCT FROM NEW.variant) LIMIT 1;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'sticker not in your inventory: item_id=%', NEW.item_id USING ERRCODE='42501';
  END IF;
  NEW.item_rarity := COALESCE(v_inv.item_rarity, NEW.item_rarity);
  NEW.item_emoji  := COALESCE(v_inv.item_emoji,  NEW.item_emoji);
  NEW.item_name   := COALESCE(NULLIF(NEW.item_name,''), v_inv.item_name, 'Sticker');
  RETURN NEW;
END; $$;


ALTER FUNCTION "public"."_tg_validate_sticker_reaction"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_weighted_pick"("keys" "text"[], "weights" numeric[]) RETURNS "text"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE v_sum NUMERIC := 0; v_roll NUMERIC; v_cum NUMERIC := 0; v_i INT;
BEGIN
  IF keys IS NULL OR array_length(keys,1) IS NULL THEN RETURN NULL; END IF;
  FOR v_i IN 1..array_length(weights,1) LOOP v_sum := v_sum + weights[v_i]; END LOOP;
  IF v_sum <= 0 THEN RETURN keys[1]; END IF;
  v_roll := random() * v_sum;
  FOR v_i IN 1..array_length(keys,1) LOOP
    v_cum := v_cum + weights[v_i];
    IF v_roll < v_cum THEN RETURN keys[v_i]; END IF;
  END LOOP;
  RETURN keys[array_length(keys,1)];
END;
$$;


ALTER FUNCTION "public"."_weighted_pick"("keys" "text"[], "weights" numeric[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."accept_conversation"("p_conv_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_email TEXT := public.current_user_email();
BEGIN
  IF v_email = '' THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;
  IF p_conv_id IS NULL THEN
    RAISE EXCEPTION 'invalid_conversation' USING ERRCODE = '22023';
  END IF;

  UPDATE public.hub_conversations
     SET accepted_emails = (
       CASE
         WHEN v_email = ANY (
           ARRAY(
             SELECT lower(accepted_email)
               FROM unnest(coalesce(accepted_emails, ARRAY[]::text[]))
                 AS accepted_email
           )
         )
           THEN accepted_emails
         ELSE array_append(coalesce(accepted_emails, ARRAY[]::text[]), v_email)
       END
     ),
     updated_at = now()
   WHERE id = p_conv_id
     AND v_email = ANY (
       ARRAY(
         SELECT lower(participant_email)
           FROM unnest(coalesce(participant_emails, ARRAY[]::text[]))
             AS participant_email
       )
     );

  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_a_participant' USING ERRCODE = '42501';
  END IF;
END;
$$;


ALTER FUNCTION "public"."accept_conversation"("p_conv_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_purge_user_data"("p_user_id" "uuid", "p_email" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_tbl text; v_col text; v_deleted bigint;
  v_swept jsonb := '{}'::jsonb; v_errors jsonb := '[]'::jsonb;
  v_email text := lower(trim(coalesce(p_email, '')));
BEGIN
  IF p_user_id IS NULL THEN
    RAISE EXCEPTION 'admin_purge_user_data requires a user id' USING ERRCODE = '22004';
  END IF;

  UPDATE public.bounties             SET claimed_by_id = NULL WHERE claimed_by_id = p_user_id;
  UPDATE public.duels                SET winner_id     = NULL WHERE winner_id     = p_user_id;
  UPDATE public.pending_duel_invites SET claimed_by_id = NULL WHERE claimed_by_id = p_user_id;
  UPDATE public.gym_businesses       SET owner_id      = NULL WHERE owner_id      = p_user_id;

  UPDATE public.regimens
     SET user_id = NULL, created_by = 'deleted-account@flexyn.invalid',
         is_public = false, description = '',
         name = '[Deleted account] ' || left(coalesce(name, 'Regimen'), 80)
   WHERE created_by = p_email AND is_public AND coalesce(copy_count, 0) > 0;

  DELETE FROM public.bug_reports WHERE reporter_user_id = p_user_id;
  DELETE FROM public.hub_reports WHERE reporter_user_id = p_user_id;

  IF v_email <> '' THEN
    FOR v_tbl, v_col IN
      SELECT table_name, column_name FROM information_schema.columns
       WHERE table_schema = 'public'
         AND data_type IN ('text', 'character varying')
         AND column_name IN ('user_email','created_by','author_email','seller_email',
               'host_email','viewer_email','blocker_email','blocked_email','muter_email',
               'muted_email','reporter_email','follower_email','followee_email',
               'sender_email','recipient_email','claimed_by_email','owner_email')
         AND table_name NOT IN ('admin_users', 'food_items')
       ORDER BY table_name, column_name
    LOOP
      BEGIN
        EXECUTE format('DELETE FROM public.%I WHERE lower(%I) = $1', v_tbl, v_col) USING v_email;
        GET DIAGNOSTICS v_deleted = ROW_COUNT;
        IF v_deleted > 0 THEN
          v_swept := v_swept || jsonb_build_object(v_tbl || '.' || v_col, v_deleted);
        END IF;
      EXCEPTION WHEN OTHERS THEN
        v_errors := v_errors || jsonb_build_object('target', v_tbl || '.' || v_col,
                                                   'error', SQLERRM, 'code', SQLSTATE);
      END;
    END LOOP;
  END IF;

  RETURN jsonb_build_object('ok', jsonb_array_length(v_errors) = 0,
                            'swept', v_swept, 'errors', v_errors);
END;
$_$;


ALTER FUNCTION "public"."admin_purge_user_data"("p_user_id" "uuid", "p_email" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."advance_login_streak"("p_today" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid          UUID := auth.uid();
  v_server_today DATE := (now() AT TIME ZONE 'UTC')::date;
  v_streak       INT;
  v_last         DATE;
  v_longest      INT;
  v_freezes      INT;
  v_diff         INT;
  v_new_streak   INT;
  v_new_longest  INT;
  v_new_freezes  INT;
  v_freeze_used  BOOLEAN := FALSE;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501';
  END IF;
  IF p_today IS NULL OR p_today < v_server_today - 2 OR p_today > v_server_today + 2 THEN
    RAISE EXCEPTION 'p_today out of range' USING ERRCODE = '22023';
  END IF;

  SELECT login_streak, last_login_date, longest_login_streak, streak_freezes_available
    INTO v_streak, v_last, v_longest, v_freezes
    FROM public.user_profiles
   WHERE id = v_uid
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'profile not found' USING ERRCODE = '22023';
  END IF;

  v_streak  := COALESCE(v_streak, 0);
  v_longest := COALESCE(v_longest, 0);
  v_freezes := COALESCE(v_freezes, 0);

  IF v_last IS NOT NULL AND p_today <= v_last THEN
    RETURN jsonb_build_object(
      'is_new_day', FALSE,
      'streak', v_streak,
      'longest', v_longest,
      'freeze_used', FALSE,
      'freezes_remaining', v_freezes
    );
  END IF;

  IF v_last IS NULL THEN
    v_new_streak := 1;
  ELSE
    v_diff := p_today - v_last;
    IF v_diff = 1 THEN
      v_new_streak := v_streak + 1;
    ELSIF v_diff > 1 AND v_freezes > 0 THEN
      v_new_streak  := v_streak + 1;
      v_freeze_used := TRUE;
    ELSE
      v_new_streak := 1;
    END IF;
  END IF;

  v_new_longest := GREATEST(v_longest, v_new_streak);
  v_new_freezes := CASE WHEN v_freeze_used THEN GREATEST(v_freezes - 1, 0) ELSE v_freezes END;

  UPDATE public.user_profiles
     SET login_streak             = v_new_streak,
         last_login_date          = p_today,
         longest_login_streak     = v_new_longest,
         streak_freezes_available = v_new_freezes,
         updated_at               = now()
   WHERE id = v_uid;

  RETURN jsonb_build_object(
    'is_new_day', TRUE,
    'streak', v_new_streak,
    'longest', v_new_longest,
    'freeze_used', v_freeze_used,
    'freezes_remaining', v_new_freezes
  );
END;
$$;


ALTER FUNCTION "public"."advance_login_streak"("p_today" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."advance_weekly_gauntlet_statuses"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_today          DATE := (now() AT TIME ZONE 'UTC')::date;
  v_gauntlet_id    UUID;
  v_gauntlet_title TEXT;
  v_count          INTEGER := 0;
BEGIN
  UPDATE public.weekly_gauntlets
     SET status = 'closed'
   WHERE status = 'active'
     AND week_end < v_today;

  FOR v_gauntlet_id, v_gauntlet_title IN
    WITH activated AS (
      UPDATE public.weekly_gauntlets
         SET status = 'active'
       WHERE status = 'upcoming'
         AND week_start <= v_today
         AND week_end   >= v_today
       RETURNING id, title
    )
    SELECT id, title FROM activated
  LOOP
    v_count := v_count + 1;

    WITH eligible AS (
      SELECT id                                 AS notif_user_id,
             email                              AS notif_email,
             COALESCE(preferred_language, 'en') AS notif_lang
        FROM public.user_profiles
       WHERE email IS NOT NULL
         AND last_login_date IS NOT NULL
         AND last_login_date >= v_today - INTERVAL '14 days'
         AND (
               notification_prefs IS NULL
               OR (notification_prefs ->> 'engagement') IS NULL
               OR (notification_prefs ->> 'engagement') <> 'false'
             )
    ),
    claimed AS (
      INSERT INTO public.weekly_gauntlet_notifications (user_id, gauntlet_id)
      SELECT notif_user_id, v_gauntlet_id FROM eligible
      ON CONFLICT DO NOTHING
      RETURNING user_id AS claimed_user_id
    ),
    localized AS (
      SELECT notif_user_id,
             notif_email,
             public.weekly_gauntlet_started_text(notif_lang, v_gauntlet_title) AS notif_text
        FROM eligible
        JOIN claimed ON claimed_user_id = notif_user_id
    )
    INSERT INTO public.notifications
      (user_id, user_email, type, title, body, icon, link_url, metadata)
    SELECT notif_user_id,
           notif_email,
           'weekly_gauntlet_started',
           notif_text ->> 'title',
           notif_text ->> 'body',
           '🏔️',
           '/gauntlet',
           jsonb_build_object('gauntlet_id',    v_gauntlet_id,
                              'gauntlet_title', v_gauntlet_title)
      FROM localized;
  END LOOP;

  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."advance_weekly_gauntlet_statuses"() OWNER TO "postgres";


