CREATE OR REPLACE FUNCTION "public"."approve_food_item_request"("p_request_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_name      TEXT;
  v_brand     TEXT;
  v_barcode   TEXT;
  v_serving   TEXT;
  v_nutrition JSONB;
  v_vitamins  JSONB;
  v_email     TEXT;
  v_user      UUID;
  v_status    TEXT;
  v_new_id    UUID;
BEGIN
  IF NOT public.is_app_admin(auth.uid()) THEN
    RAISE EXCEPTION 'admin_only' USING ERRCODE = '42501';
  END IF;

  SELECT name, brand, barcode, serving_label, nutrition, vitamins,
         requester_email, requester_user_id, status
    INTO v_name, v_brand, v_barcode, v_serving, v_nutrition, v_vitamins,
         v_email, v_user, v_status
    FROM public.food_item_requests
   WHERE id = p_request_id;

  IF v_name IS NULL THEN
    RAISE EXCEPTION 'no such request' USING ERRCODE = '22023';
  END IF;
  IF v_status <> 'pending' THEN
    RAISE EXCEPTION 'already reviewed' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.food_items
    (created_by, user_id, name, brand, barcode, serving_label,
     calories, protein, carbs, fat, fiber, sodium,
     nutrition, vitamins, is_verified, source)
  VALUES
    (v_email, v_user, v_name, v_brand, v_barcode, COALESCE(v_serving, '1 serving'),
     (v_nutrition ->> 'calories')::NUMERIC,
     (v_nutrition ->> 'protein')::NUMERIC,
     (v_nutrition ->> 'carbs')::NUMERIC,
     (v_nutrition ->> 'fat')::NUMERIC,
     (v_nutrition ->> 'fiber')::NUMERIC,
     (v_nutrition ->> 'sodium')::NUMERIC,
     v_nutrition, v_vitamins, TRUE, 'member_request')
  RETURNING id INTO v_new_id;

  UPDATE public.food_item_requests
     SET status = 'approved', reviewed_at = now(),
         reviewed_by = auth.uid(), approved_item_id = v_new_id
   WHERE id = p_request_id;

  RETURN v_new_id;
END;
$$;


ALTER FUNCTION "public"."approve_food_item_request"("p_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approve_gym_verification"("p_verif_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_is_admin BOOLEAN;
  v_status TEXT; v_owner_id UUID; v_business_name TEXT; v_street TEXT;
  v_city TEXT; v_state TEXT; v_postal TEXT; v_country TEXT;
  v_lat NUMERIC; v_lng NUMERIC; v_phone TEXT; v_website TEXT;
  v_code TEXT; v_gym_id UUID; v_rows INT;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501'; END IF;
  SELECT public.is_app_admin(v_uid) INTO v_is_admin;
  IF NOT COALESCE(v_is_admin, FALSE) THEN RAISE EXCEPTION 'admin only' USING ERRCODE = '42501'; END IF;
  SELECT status, owner_id, business_name, street_address, city, state_code,
         postal_code, country_code, latitude, longitude, phone, website_url
    INTO v_status, v_owner_id, v_business_name, v_street, v_city, v_state,
         v_postal, v_country, v_lat, v_lng, v_phone, v_website
    FROM public.gym_verification_queue WHERE id = p_verif_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'verification record not found' USING ERRCODE = '22023'; END IF;
  IF v_status <> 'pending' THEN RAISE EXCEPTION 'already %', v_status USING ERRCODE = '22023'; END IF;
  v_code := public.generate_flexyn_code();
  INSERT INTO public.gym_businesses (
    owner_id, verification_id, name, street_address, city, state_code,
    postal_code, country_code, latitude, longitude, flexyn_code, phone, website_url
  ) VALUES (
    v_owner_id, p_verif_id, v_business_name, v_street, v_city, v_state,
    v_postal, v_country, v_lat, v_lng, v_code, v_phone, v_website
  ) RETURNING id INTO v_gym_id;
  UPDATE public.gym_verification_queue
     SET status = 'approved', reviewed_at = now(), reviewed_by = v_uid
   WHERE id = p_verif_id AND status = 'pending';
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  IF v_rows = 0 THEN RAISE EXCEPTION 'already_processed' USING ERRCODE = '22023'; END IF;
  RETURN v_gym_id;
END;
$$;


ALTER FUNCTION "public"."approve_gym_verification"("p_verif_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."auto_accept_on_send"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_email TEXT;
BEGIN
  IF NEW.conversation_id IS NULL OR NEW.created_by IS NULL THEN
    RETURN NEW;
  END IF;
  v_email := NEW.created_by;
  UPDATE public.hub_conversations
     SET accepted_emails = (
       CASE
         WHEN v_email = ANY(coalesce(accepted_emails, ARRAY[]::text[]))
           THEN accepted_emails
         ELSE array_append(coalesce(accepted_emails, ARRAY[]::text[]), v_email)
       END
     )
   WHERE id = NEW.conversation_id;
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."auto_accept_on_send"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."award_crew_progress"("p_crew_id" "uuid", "p_xp" integer, "p_trophies" integer, "p_points" integer, "p_result" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_season uuid;
  v_xp     integer;
  v_coins  integer;
  v_after  integer;
BEGIN
  IF p_crew_id IS NULL THEN
    RETURN;
  END IF;

  v_xp := LEAST(50000, GREATEST(0, COALESCE(p_xp, 0)));

  UPDATE public.crews
     SET crew_xp    = crew_xp + v_xp,
         crew_level = public.crew_level_for_xp(crew_xp + v_xp),
         trophies   = GREATEST(0, trophies + COALESCE(p_trophies, 0)),
         wars_won   = wars_won   + CASE WHEN p_result = 'win'   THEN 1 ELSE 0 END,
         wars_lost  = wars_lost  + CASE WHEN p_result = 'loss'  THEN 1 ELSE 0 END,
         wars_drawn = wars_drawn + CASE WHEN p_result = 'draw'  THEN 1 ELSE 0 END
   WHERE id = p_crew_id;

  v_coins := CASE p_result
    WHEN 'win'       THEN 200
    WHEN 'draw'      THEN 80
    WHEN 'loss'      THEN 40
    WHEN 'challenge' THEN 120
    ELSE 0
  END;

  IF NOT (v_coins = 0) THEN
    UPDATE public.crews
       SET treasury_coins = treasury_coins + v_coins
     WHERE id = p_crew_id
     RETURNING treasury_coins INTO v_after;

    INSERT INTO public.crew_treasury_ledger (crew_id, delta, balance_after, reason)
    VALUES (p_crew_id, v_coins, COALESCE(v_after, 0), p_result);
  END IF;

  v_season := public.ensure_crew_season_entry(p_crew_id);
  IF v_season IS NULL THEN
    RETURN;
  END IF;

  UPDATE public.crew_season_stats
     SET points      = points + GREATEST(0, COALESCE(p_points, 0)),
         wars_played = wars_played + CASE WHEN p_result IN ('win','loss','draw') THEN 1 ELSE 0 END,
         wars_won    = wars_won    + CASE WHEN p_result = 'win' THEN 1 ELSE 0 END,
         challenges  = challenges  + CASE WHEN p_result = 'challenge' THEN 1 ELSE 0 END,
         updated_at  = now()
   WHERE season_id = v_season AND crew_id = p_crew_id;
END;
$$;


ALTER FUNCTION "public"."award_crew_progress"("p_crew_id" "uuid", "p_xp" integer, "p_trophies" integer, "p_points" integer, "p_result" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."award_league_season_internal"("p_user_id" "uuid", "p_email" "text", "p_number" integer, "p_tier" "text", "p_champion" boolean) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_item_id  TEXT;
  v_name     TEXT;
  v_rarity   TEXT;
  v_emoji    TEXT;
  v_capsule  TEXT;
  v_exists   INTEGER;
BEGIN
  IF p_user_id IS NULL OR p_number IS NULL THEN
    RETURN;
  END IF;

  IF p_champion THEN
    v_item_id := 'league_s' || p_number || '_champion';
    v_name    := 'Champion, S' || p_number;
    v_rarity  := 'legendary';
    v_emoji   := '👑';
    v_capsule := 'elite';
  ELSE
    v_item_id := 'league_s' || p_number || '_' || COALESCE(p_tier, 'bronze');
    v_name    := 'Season ' || p_number || ' ' || initcap(COALESCE(p_tier, 'bronze'));
    v_rarity  := CASE COALESCE(p_tier, 'bronze')
                   WHEN 'legend'   THEN 'legendary'
                   WHEN 'diamond'  THEN 'epic'
                   WHEN 'platinum' THEN 'rare'
                   WHEN 'gold'     THEN 'uncommon'
                   ELSE 'common'
                 END;
    v_emoji   := CASE COALESCE(p_tier, 'bronze')
                   WHEN 'legend'   THEN '👑' WHEN 'diamond'  THEN '💎'
                   WHEN 'platinum' THEN '💠' WHEN 'gold'     THEN '🥇'
                   WHEN 'silver'   THEN '🥈' ELSE '🥉'
                 END;
    v_capsule := CASE COALESCE(p_tier, 'bronze')
                   WHEN 'legend'   THEN 'elite'
                   WHEN 'diamond'  THEN 'premium'
                   WHEN 'platinum' THEN 'premium'
                   WHEN 'gold'     THEN 'standard'
                   ELSE NULL
                 END;
  END IF;

  SELECT COUNT(*) INTO v_exists
    FROM public.user_inventory
   WHERE user_id = p_user_id AND item_id = v_item_id;

  IF v_exists = 0 THEN
    INSERT INTO public.user_inventory
      (user_id, user_email, item_id, item_name, item_emoji, item_rarity,
       item_type, acquired_via, is_listed)
    VALUES
      (p_user_id, COALESCE(p_email, ''), v_item_id, v_name, v_emoji, v_rarity,
       'title', 'league_season', FALSE);
  END IF;

  INSERT INTO public.user_trophies (user_id, user_email, trophy_id)
  VALUES (p_user_id, COALESCE(p_email, ''), v_item_id)
  ON CONFLICT (user_id, trophy_id) DO NOTHING;

  IF v_capsule IS NOT NULL THEN
    INSERT INTO public.user_capsules (user_id, user_email, capsule_type)
    VALUES (p_user_id, COALESCE(p_email, ''), v_capsule);
  END IF;
END;
$$;


ALTER FUNCTION "public"."award_league_season_internal"("p_user_id" "uuid", "p_email" "text", "p_number" integer, "p_tier" "text", "p_champion" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."award_xp_internal"("p_user_id" "uuid", "p_xp" integer) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_total_xp BIGINT; v_level INTEGER := 1; v_today INTEGER; v_grant INTEGER;
  v_daily_cap CONSTANT INTEGER := 50000;
BEGIN
  IF p_user_id IS NULL THEN RETURN; END IF;
  IF p_xp IS NULL OR p_xp <= 0 THEN RETURN; END IF;
  IF p_xp > 100000 THEN RAISE EXCEPTION 'xp out of range' USING ERRCODE = '22023'; END IF;

  SELECT COALESCE(SUM(amount), 0) INTO v_today FROM public.xp_grant_log
   WHERE user_id = p_user_id AND granted_at > now() - interval '24 hours';

  v_grant := LEAST(p_xp, GREATEST(0, v_daily_cap - v_today));
  IF v_grant <= 0 THEN RETURN; END IF;

  INSERT INTO public.xp_grant_log (user_id, amount) VALUES (p_user_id, v_grant);

  UPDATE public.user_profiles
     SET total_xp = COALESCE(total_xp, 0) + v_grant, updated_at = now()
   WHERE id = p_user_id RETURNING total_xp INTO v_total_xp;
  IF NOT FOUND THEN RETURN; END IF;

  SELECT COALESCE(MAX(level), 1) INTO v_level
    FROM public.xp_level_thresholds WHERE total_xp_required <= v_total_xp;
  UPDATE public.user_profiles SET current_level = v_level WHERE id = p_user_id;
END;
$$;


ALTER FUNCTION "public"."award_xp_internal"("p_user_id" "uuid", "p_xp" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ban_crew_member"("p_crew_id" "uuid", "p_user_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_uid    uuid := auth.uid();
  v_admin  integer;
  v_target integer;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;
  IF p_crew_id IS NULL OR p_user_id IS NULL THEN
    RAISE EXCEPTION 'crew_id and user_id required' USING ERRCODE = '22023';
  END IF;
  IF p_user_id = v_uid THEN
    RAISE EXCEPTION 'cannot ban yourself' USING ERRCODE = '22023';
  END IF;

  SELECT COUNT(*) INTO v_admin
    FROM public.crew_members
   WHERE crew_id = p_crew_id AND user_id = v_uid AND is_admin = TRUE;

  IF v_admin = 0 THEN
    RAISE EXCEPTION 'only a crew leader can ban' USING ERRCODE = '42501';
  END IF;

  SELECT COUNT(*) INTO v_target
    FROM public.crew_members
   WHERE crew_id = p_crew_id AND user_id = p_user_id AND is_admin = TRUE;

  IF NOT (v_target = 0) THEN
    RAISE EXCEPTION 'cannot ban another leader' USING ERRCODE = '42501';
  END IF;

  INSERT INTO public.crew_bans (crew_id, user_id, banned_by, reason)
  VALUES (p_crew_id, p_user_id, v_uid, NULLIF(left(COALESCE(p_reason, ''), 200), ''))
  ON CONFLICT (crew_id, user_id) DO UPDATE
    SET banned_by = v_uid, reason = NULLIF(left(COALESCE(p_reason, ''), 200), ''),
        created_at = now();

  DELETE FROM public.crew_members
   WHERE crew_id = p_crew_id AND user_id = p_user_id;

  DELETE FROM public.crew_invites
   WHERE crew_id = p_crew_id AND invited_user_id = p_user_id;

  UPDATE public.crew_join_requests
     SET status = 'rejected', decided_by = v_uid, decided_at = now()
   WHERE crew_id = p_crew_id AND user_id = p_user_id AND status = 'pending';

  RETURN jsonb_build_object('ok', TRUE, 'banned', TRUE);
END;
$$;


ALTER FUNCTION "public"."ban_crew_member"("p_crew_id" "uuid", "p_user_id" "uuid", "p_reason" "text") OWNER TO "postgres";


