CREATE OR REPLACE FUNCTION "public"."block_user_full"("p_blocked_email" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid   UUID := auth.uid();
  v_email TEXT;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;
  IF p_blocked_email IS NULL OR length(p_blocked_email) = 0 THEN
    RAISE EXCEPTION 'invalid_email' USING ERRCODE = '22023';
  END IF;

  SELECT email INTO v_email FROM public.user_profiles WHERE id = v_uid;
  IF v_email IS NULL THEN
    RAISE EXCEPTION 'profile_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF lower(v_email) = lower(p_blocked_email) THEN
    RAISE EXCEPTION 'cannot_block_self' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.user_blocks (blocker_id, blocker_email, blocked_email)
  VALUES (v_uid, v_email, p_blocked_email)
  ON CONFLICT (blocker_id, blocked_email) DO NOTHING;

  INSERT INTO public.story_blocks (blocker_id, blocker_email, blocked_email)
  VALUES (v_uid, v_email, p_blocked_email)
  ON CONFLICT (blocker_id, blocked_email) DO NOTHING;

  DELETE FROM public.hub_follows
   WHERE (lower(follower_email) = lower(v_email)
          AND lower(followee_email) = lower(p_blocked_email))
      OR (lower(follower_email) = lower(p_blocked_email)
          AND lower(followee_email) = lower(v_email));
END;
$$;


ALTER FUNCTION "public"."block_user_full"("p_blocked_email" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."bodyweight_load_factor"("p_name" "text") RETURNS numeric
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
  SELECT CASE
    WHEN lower(coalesce(p_name,'')) ~ '\m(plank|hold|hang|l[- ]?sit|wall sit)\M' THEN 0
    WHEN lower(coalesce(p_name,'')) ~ '\m(pull[- ]?up|chin[- ]?up|muscle[- ]?up)\M' THEN 1.00
    WHEN lower(coalesce(p_name,'')) ~ '\mdip\M'          THEN 0.95
    WHEN lower(coalesce(p_name,'')) ~ '\mhandstand\M'    THEN 0.90
    WHEN lower(coalesce(p_name,'')) ~ '\mpistol squat\M' THEN 0.85
    WHEN lower(coalesce(p_name,'')) ~ '\m(push[- ]?up|burpee)\M' THEN 0.65
    WHEN lower(coalesce(p_name,'')) ~ '\minverted row\M' THEN 0.55
    WHEN lower(coalesce(p_name,'')) ~ '\mleg raise\M'    THEN 0.50
    WHEN lower(coalesce(p_name,'')) ~ '\mair squat\M'    THEN 0.45
    WHEN lower(coalesce(p_name,'')) ~ '\m(sit[- ]?up|crunch)\M' THEN 0.35
    ELSE 0
  END;
$$;


ALTER FUNCTION "public"."bodyweight_load_factor"("p_name" "text") OWNER TO "postgres";


