CREATE OR REPLACE FUNCTION "public"."bump_item_sold_count"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.status = 'completed'
     AND (OLD.status IS DISTINCT FROM 'completed')
     AND NEW.item_id IS NOT NULL THEN
    INSERT INTO public.item_sold_counts (item_id, sold_count)
    VALUES (NEW.item_id, 1)
    ON CONFLICT (item_id)
    DO UPDATE SET
      sold_count = public.item_sold_counts.sold_count + 1,
      updated_at = now();
  END IF;
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."bump_item_sold_count"() OWNER TO "postgres";


