CREATE OR REPLACE FUNCTION "public"."can_moderate_gym_comment"("p_post_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_gym    uuid;
  v_author uuid;
BEGIN
  SELECT gym_id, author_id INTO v_gym, v_author
    FROM public.gym_feed_posts WHERE id = p_post_id;
  IF v_gym IS NULL THEN RETURN FALSE; END IF;
  IF v_author = auth.uid() THEN RETURN TRUE; END IF;
  RETURN public.is_gym_owner(v_gym);
END;
$$;


