CREATE OR REPLACE FUNCTION "public"."can_view_post"("p_post_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid(); v_email text; v_author text;
  v_author_id uuid; v_privacy text; v_publish_at timestamptz;
BEGIN
  IF v_uid IS NULL OR p_post_id IS NULL THEN RETURN FALSE; END IF;
  SELECT email INTO v_email FROM public.user_profiles WHERE id = v_uid;
  SELECT author_email, user_id, privacy, publish_at
    INTO v_author, v_author_id, v_privacy, v_publish_at
    FROM public.hub_posts WHERE id = p_post_id;
  IF v_author IS NULL AND v_author_id IS NULL THEN RETURN FALSE; END IF;
  IF v_author_id = v_uid
     OR (v_email IS NOT NULL AND lower(COALESCE(v_author,'')) = lower(v_email))
  THEN RETURN TRUE; END IF;
  IF v_publish_at IS NOT NULL AND v_publish_at > now() THEN RETURN FALSE; END IF;
  IF public.is_blocked(v_uid, v_author) THEN RETURN FALSE; END IF;
  IF v_privacy = 'public' THEN RETURN TRUE; END IF;
  RETURN EXISTS (SELECT 1 FROM public.hub_follows
    WHERE (follower_id = v_uid AND followee_id = v_author_id)
       OR (v_email IS NOT NULL
           AND lower(follower_email) = lower(v_email)
           AND lower(followee_email) = lower(COALESCE(v_author,''))));
END; $$;


ALTER FUNCTION "public"."can_view_post"("p_post_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."can_view_story"("p_author_id" "uuid", "p_author_email" "text", "p_privacy" "text", "p_crew_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_uid uuid := auth.uid(); v_email text; v_private boolean;
BEGIN
  IF v_uid IS NULL THEN RETURN FALSE; END IF;
  SELECT email INTO v_email FROM public.user_profiles WHERE id = v_uid;
  IF p_author_id = v_uid OR (v_email IS NOT NULL
     AND lower(COALESCE(p_author_email,'')) = lower(v_email)) THEN RETURN TRUE; END IF;
  IF EXISTS (SELECT 1 FROM public.story_blocks
              WHERE blocker_id = p_author_id AND blocked_id = v_uid) THEN RETURN FALSE; END IF;
  IF public.is_blocked(v_uid, p_author_email) THEN RETURN FALSE; END IF;
  IF p_crew_id IS NOT NULL THEN
    RETURN EXISTS (SELECT 1 FROM public.crew_members
                    WHERE crew_id = p_crew_id AND user_id = v_uid);
  END IF;
  SELECT is_private INTO v_private FROM public.user_profiles WHERE id = p_author_id;
  IF p_privacy = 'public' AND v_private IS NOT TRUE THEN RETURN TRUE; END IF;
  RETURN EXISTS (SELECT 1 FROM public.hub_follows
    WHERE (follower_id = v_uid AND followee_id = p_author_id)
       OR (v_email IS NOT NULL
           AND lower(follower_email) = lower(v_email)
           AND lower(followee_email) = lower(COALESCE(p_author_email,''))));
END; $$;


ALTER FUNCTION "public"."can_view_story"("p_author_id" "uuid", "p_author_email" "text", "p_privacy" "text", "p_crew_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_marketplace_listing"("p_listing_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_uid     UUID := auth.uid();
  v_email   TEXT;
  v_listing public.marketplace_listings%ROWTYPE;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;
  IF p_listing_id IS NULL THEN
    RAISE EXCEPTION 'listing_id required' USING ERRCODE = '22023';
  END IF;

  SELECT email INTO v_email FROM public.user_profiles WHERE id = v_uid;

  SELECT * INTO v_listing
    FROM public.marketplace_listings
   WHERE id = p_listing_id
   FOR UPDATE;

  IF v_listing.id IS NULL THEN
    RAISE EXCEPTION 'listing not found' USING ERRCODE = '22023';
  END IF;

  IF v_listing.seller_user_id IS DISTINCT FROM v_uid
     AND v_listing.seller_email IS DISTINCT FROM v_email THEN
    RAISE EXCEPTION 'not your listing' USING ERRCODE = '42501';
  END IF;

  IF v_listing.status <> 'active' THEN
    RETURN jsonb_build_object(
      'success',          TRUE,
      'already_inactive', TRUE,
      'listing_id',       p_listing_id,
      'status',           v_listing.status
    );
  END IF;

  UPDATE public.marketplace_listings
     SET status = 'cancelled'
   WHERE id = p_listing_id;

  IF v_listing.inventory_id IS NOT NULL THEN
    UPDATE public.user_inventory
       SET is_listed = FALSE
     WHERE id = v_listing.inventory_id;
  END IF;

  RETURN jsonb_build_object(
    'success',          TRUE,
    'already_inactive', FALSE,
    'listing_id',       p_listing_id,
    'inventory_id',     v_listing.inventory_id,
    'status',           'cancelled'
  );
END;
$$;


ALTER FUNCTION "public"."cancel_marketplace_listing"("p_listing_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_my_scheduled_message"("p_message_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;
  DELETE FROM public.hub_messages
   WHERE id = p_message_id
     AND user_id = v_uid
     AND status = 'scheduled';
END;
$$;


ALTER FUNCTION "public"."cancel_my_scheduled_message"("p_message_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_trade_offer"("p_offer_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_me        UUID := auth.uid();
  v_from_user UUID;
  v_from_inv  UUID;
  v_status    TEXT;
BEGIN
  IF v_me IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;

  SELECT from_user_id, from_inventory_id, status
    INTO v_from_user, v_from_inv, v_status
    FROM public.trade_offers WHERE id = p_offer_id FOR UPDATE;

  IF v_from_user IS NULL   THEN RAISE EXCEPTION 'offer_not_found'; END IF;
  IF v_from_user <> v_me   THEN RAISE EXCEPTION 'not_your_offer'; END IF;
  IF v_status <> 'pending' THEN RAISE EXCEPTION 'offer_not_pending'; END IF;

  UPDATE public.trade_offers SET status = 'cancelled', responded_at = now() WHERE id = p_offer_id;
  UPDATE public.user_inventory SET escrow_offer_id = NULL, is_listed = FALSE
   WHERE id = v_from_inv AND escrow_offer_id = p_offer_id;

  RETURN jsonb_build_object('status', 'cancelled', 'offer_id', p_offer_id);
END;
$$;


ALTER FUNCTION "public"."cancel_trade_offer"("p_offer_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cast_dm_poll_vote"("p_poll_id" "uuid", "p_option_id" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid    UUID := auth.uid();
  v_emails TEXT[];
  v_uids   UUID[];
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;
  IF p_poll_id IS NULL OR p_option_id IS NULL THEN
    RAISE EXCEPTION 'poll_id and option_id required' USING ERRCODE = '22023';
  END IF;

  SELECT participant_emails, participant_ids
    INTO v_emails, v_uids
    FROM public.hub_conversations
   WHERE id = (SELECT conversation_id FROM public.dm_polls WHERE id = p_poll_id);

  IF v_emails IS NULL OR NOT (NULLIF(public.current_user_email(), '') = ANY(v_emails) OR v_uid = ANY(v_uids)) THEN
    RAISE EXCEPTION 'not a conversation participant' USING ERRCODE = '42501';
  END IF;

  INSERT INTO public.dm_poll_votes (poll_id, user_id, option_id)
  VALUES (p_poll_id, v_uid, p_option_id)
  ON CONFLICT (poll_id, user_id)
  DO UPDATE SET option_id = EXCLUDED.option_id, voted_at = now();
END;
$$;


ALTER FUNCTION "public"."cast_dm_poll_vote"("p_poll_id" "uuid", "p_option_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cast_story_poll_vote"("p_story_id" "uuid", "p_option_id" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;
  IF p_story_id IS NULL OR p_option_id IS NULL OR length(p_option_id) = 0 THEN
    RAISE EXCEPTION 'invalid_args' USING ERRCODE = '22023';
  END IF;
  INSERT INTO public.story_poll_votes (story_id, voter_id, option_id)
  VALUES (p_story_id, v_uid, p_option_id)
  ON CONFLICT (story_id, voter_id)
  DO UPDATE SET option_id = EXCLUDED.option_id, voted_at = now();
END;
$$;


ALTER FUNCTION "public"."cast_story_poll_vote"("p_story_id" "uuid", "p_option_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_in_to_gym"("p_code" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid    UUID := auth.uid();
  v_gym_id UUID;
  v_name   TEXT;
  v_today  DATE := (now() AT TIME ZONE 'UTC')::date;
  v_rows   INT;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501';
  END IF;
  IF p_code IS NULL OR length(btrim(p_code)) = 0 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'CODE_REQUIRED');
  END IF;

  SELECT id, name INTO v_gym_id, v_name
    FROM public.gym_businesses
   WHERE flexyn_code = upper(btrim(p_code)) AND is_active = TRUE;

  IF v_gym_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'GYM_NOT_FOUND');
  END IF;

  INSERT INTO public.gym_checkins (user_id, gym_id, checkin_date)
    VALUES (v_uid, v_gym_id, v_today)
    ON CONFLICT (user_id, gym_id, checkin_date) DO NOTHING;
  GET DIAGNOSTICS v_rows = ROW_COUNT;

  RETURN jsonb_build_object(
    'ok',       true,
    'gym_id',   v_gym_id,
    'gym_name', v_name,
    'already',  v_rows = 0
  );
END;
$$;


ALTER FUNCTION "public"."check_in_to_gym"("p_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_bounty"("p_bounty_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id  UUID := auth.uid();
  v_bounty   public.bounties%ROWTYPE;
  v_coins    INT;
  v_claim_id UUID;
  v_deadline TIMESTAMPTZ;
BEGIN
  IF v_user_id IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  SELECT * INTO v_bounty FROM public.bounties WHERE id = p_bounty_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'bounty_not_found'; END IF;
  IF v_bounty.expires_at < NOW() THEN RAISE EXCEPTION 'bounty_expired'; END IF;
  IF v_bounty.target_user_id = v_user_id THEN RAISE EXCEPTION 'cannot_claim_own_bounty'; END IF;
  IF v_bounty.claimed_by_id IS NOT NULL THEN RAISE EXCEPTION 'bounty_already_claimed'; END IF;
  IF EXISTS (SELECT 1 FROM public.bounty_claims WHERE claimant_id = v_user_id AND status = 'active') THEN
    RAISE EXCEPTION 'already_have_active_claim';
  END IF;
  SELECT flex_coins INTO v_coins FROM public.user_profiles WHERE id = v_user_id FOR UPDATE;
  IF v_coins < v_bounty.entry_fee THEN RAISE EXCEPTION 'insufficient_coins'; END IF;
  UPDATE public.user_profiles SET flex_coins = flex_coins - v_bounty.entry_fee WHERE id = v_user_id;
  UPDATE public.bounties SET claimed_by_id = v_user_id WHERE id = p_bounty_id;
  v_deadline := NOW() + CASE WHEN v_bounty.difficulty = 'hard' THEN INTERVAL '72 hours' ELSE INTERVAL '48 hours' END;
  INSERT INTO public.bounty_claims (bounty_id, claimant_id, deadline) VALUES (p_bounty_id, v_user_id, v_deadline) RETURNING id INTO v_claim_id;
  RETURN v_claim_id;
END;
$$;


ALTER FUNCTION "public"."claim_bounty"("p_bounty_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_capsule_loot"("p_capsule_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid      UUID := auth.uid();
  v_type     TEXT;
  v_roll     JSONB;
  v_shape    JSONB;
  v_rarity   TEXT;
  v_category TEXT;
  v_variant  TEXT;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;
  IF p_capsule_id IS NULL THEN
    RAISE EXCEPTION 'capsule_id required' USING ERRCODE = '22023';
  END IF;

  UPDATE public.user_capsules SET is_opened = true, opened_at = now()
   WHERE id = p_capsule_id AND user_id = v_uid AND is_opened = false
  RETURNING capsule_type INTO v_type;
  IF v_type IS NULL THEN
    RAISE EXCEPTION 'capsule not found or already opened' USING ERRCODE = '22023';
  END IF;
  v_type := COALESCE(v_type, 'standard');

  v_roll     := public._roll_capsule_rarity(v_uid, v_type);
  v_rarity   := v_roll ->> 'rarity';
  v_shape    := public._roll_capsule_shape(v_type);
  v_category := v_shape ->> 'category';
  v_variant  := v_shape ->> 'variant';

  UPDATE public.user_capsules
     SET rolled_rarity = v_rarity, rolled_category = v_category, rolled_variant = v_variant
   WHERE id = p_capsule_id;

  RETURN jsonb_build_object('capsule_id', p_capsule_id, 'capsule_type', v_type,
                            'rarity', v_rarity, 'category', v_category, 'variant', v_variant,
                            'pity', v_roll ->> 'pity');
END;
$$;


ALTER FUNCTION "public"."claim_capsule_loot"("p_capsule_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_crew_xp_fuel"("p_message_id" "uuid", "p_xp" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  c_fuel_xp CONSTANT integer := 25;
  v_uid      uuid := auth.uid();
  v_crew_id  uuid;
  v_msg_type text;
  v_sender   uuid;
  v_member   integer;
  v_credit   integer;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;
  IF p_message_id IS NULL THEN
    RAISE EXCEPTION 'message_id required' USING ERRCODE = '22023';
  END IF;

  SELECT crew_id, message_type, sender_id
    INTO v_crew_id, v_msg_type, v_sender
    FROM public.crew_messages
   WHERE id = p_message_id;

  IF v_crew_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'message_not_found');
  END IF;
  IF v_msg_type IS DISTINCT FROM 'xp_fuel' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_fuel_message');
  END IF;
  IF v_sender = v_uid THEN
    RETURN jsonb_build_object('ok', false, 'error', 'own_fuel');
  END IF;

  SELECT COUNT(*)::int
    INTO v_member
    FROM public.crew_members
   WHERE crew_id = v_crew_id
     AND user_id = v_uid;
  IF v_member = 0 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_crew_member');
  END IF;

  BEGIN
    INSERT INTO public.crew_xp_claims (message_id, user_id, xp_amount)
    VALUES (p_message_id, v_uid, c_fuel_xp);
  EXCEPTION WHEN unique_violation THEN
    RETURN jsonb_build_object('ok', false, 'error', 'already_claimed');
  END;

  v_credit := public.grant_action_xp('crew_xp_fuel', c_fuel_xp);

  UPDATE public.crew_xp_claims
     SET xp_amount = v_credit
   WHERE message_id = p_message_id
     AND user_id    = v_uid;

  RETURN jsonb_build_object(
    'ok',        true,
    'xp_amount', v_credit,
    'capped',    v_credit < c_fuel_xp
  );
END;
$$;


ALTER FUNCTION "public"."claim_crew_xp_fuel"("p_message_id" "uuid", "p_xp" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_daily_chest"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid              UUID := auth.uid();
  v_email            TEXT;
  v_today_utc        DATE := (now() AT TIME ZONE 'UTC')::DATE;
  v_new_balance      INT;
  v_coins_awarded    INT := 75;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;

  -- Atomic claim: only one of N concurrent callers passes the WHERE.
  UPDATE public.user_profiles
     SET last_daily_chest_at = now(),
         flex_coins          = COALESCE(flex_coins, 0) + v_coins_awarded
   WHERE id = v_uid
     AND (last_daily_chest_at IS NULL
          OR (last_daily_chest_at AT TIME ZONE 'UTC')::DATE < v_today_utc)
  RETURNING flex_coins, email INTO v_new_balance, v_email;

  IF v_new_balance IS NULL THEN
    -- Already claimed today.
    SELECT flex_coins INTO v_new_balance
      FROM public.user_profiles
     WHERE id = v_uid;
    RETURN jsonb_build_object(
      'already_claimed', TRUE,
      'coins_awarded',   0,
      'new_balance',     COALESCE(v_new_balance, 0)
    );
  END IF;

  -- Capsule grant inside the same transaction as the coin credit.
  INSERT INTO public.user_capsules (user_id, user_email, capsule_type)
  VALUES (v_uid, v_email, 'standard');

  RETURN jsonb_build_object(
    'already_claimed', FALSE,
    'coins_awarded',   v_coins_awarded,
    'capsule_type',    'standard',
    'new_balance',     v_new_balance
  );
END;
$$;


ALTER FUNCTION "public"."claim_daily_chest"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_league_resolution"("p_league_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_row public.leagues%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE='42501'; END IF;
  IF p_league_id IS NULL THEN RETURN NULL; END IF;
  UPDATE public.leagues SET is_resolved=true
   WHERE id=p_league_id AND is_resolved=false
  RETURNING * INTO v_row;
  IF v_row.id IS NULL THEN RETURN NULL; END IF;
  RETURN to_jsonb(v_row);
END; $$;


ALTER FUNCTION "public"."claim_league_resolution"("p_league_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_pending_duel_invite"("p_token" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid                 UUID := auth.uid();
  v_invite_id           UUID;
  v_challenger_id       UUID;
  v_claimed_by_id       UUID;
  v_resulting_duel_id   UUID;
  v_expires_at          TIMESTAMPTZ;
  v_window_hours        INT;
  v_duel_type           TEXT;
  v_session_template    JSONB;
  v_target_exercise_id  TEXT;
  v_duel_id             UUID;
  v_new_expires         TIMESTAMPTZ;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;
  IF p_token IS NULL THEN
    RAISE EXCEPTION 'token required' USING ERRCODE = '22023';
  END IF;

  SELECT id, challenger_id, claimed_by_id, resulting_duel_id, expires_at,
         window_hours, duel_type, session_template, target_exercise_id
    INTO v_invite_id, v_challenger_id, v_claimed_by_id, v_resulting_duel_id, v_expires_at,
         v_window_hours, v_duel_type, v_session_template, v_target_exercise_id
    FROM public.pending_duel_invites
   WHERE claim_token = p_token
   FOR UPDATE;

  IF v_invite_id IS NULL THEN
    RAISE EXCEPTION 'invite_not_found' USING ERRCODE = '22023';
  END IF;
  IF v_claimed_by_id IS NOT NULL THEN
    IF v_claimed_by_id = v_uid AND v_resulting_duel_id IS NOT NULL THEN
      RETURN jsonb_build_object('duel_id', v_resulting_duel_id, 'already_claimed_by_you', TRUE);
    END IF;
    RAISE EXCEPTION 'invite_already_claimed' USING ERRCODE = '22023';
  END IF;
  IF v_expires_at < NOW() THEN
    RAISE EXCEPTION 'invite_expired' USING ERRCODE = '22023';
  END IF;
  IF v_challenger_id = v_uid THEN
    RAISE EXCEPTION 'cannot_claim_own_invite' USING ERRCODE = '22023';
  END IF;

  v_new_expires := NOW() + (v_window_hours || ' hours')::INTERVAL;

  INSERT INTO public.duels
    (challenger_id, opponent_id, type, status, session_template,
     target_exercise_id, window_hours, expires_at)
  VALUES
    (v_challenger_id, v_uid, v_duel_type, 'active',
     v_session_template, v_target_exercise_id,
     v_window_hours, v_new_expires)
  RETURNING id INTO v_duel_id;

  UPDATE public.pending_duel_invites
     SET claimed_by_id     = v_uid,
         claimed_at        = NOW(),
         resulting_duel_id = v_duel_id
   WHERE id = v_invite_id;

  RETURN jsonb_build_object(
    'duel_id',                v_duel_id,
    'already_claimed_by_you', FALSE
  );
END;
$$;


ALTER FUNCTION "public"."claim_pending_duel_invite"("p_token" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_perfect_day_bonus"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  c_bonus_coins CONSTANT integer := 30;
  c_bonus_xp    CONSTANT integer := 100;
  c_bonus_crew  CONSTANT integer := 50;
  v_uid         uuid := auth.uid();
  v_day         date;
  v_total       integer;
  v_claimed     integer;
  v_last        date;
  v_streak      integer;
  v_new_streak  integer;
  v_xp_credited integer := 0;
  v_new_balance integer;
  v_crew_id     uuid;
  v_crew_xp     integer := 0;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;
  v_day := (public.user_local_now(v_uid))::date;
  IF v_day IS NULL THEN
    v_day := (now() AT TIME ZONE 'utc')::date;
  END IF;
  SELECT count(*), count(claimed_at)
    INTO v_total, v_claimed
    FROM public.user_daily_quests
   WHERE user_id = v_uid AND quest_date = v_day;
  IF COALESCE(v_total, 0) = 0 OR v_claimed < v_total THEN
    RETURN jsonb_build_object('success', FALSE, 'reason', 'not_complete',
                              'claimed', COALESCE(v_claimed, 0),
                              'total',   COALESCE(v_total, 0));
  END IF;
  INSERT INTO public.user_quest_stats (user_id) VALUES (v_uid)
  ON CONFLICT (user_id) DO NOTHING;
  SELECT last_perfect_date, current_streak
    INTO v_last, v_streak
    FROM public.user_quest_stats
   WHERE user_id = v_uid
     FOR UPDATE;
  IF v_last = v_day THEN
    RETURN jsonb_build_object('success', FALSE, 'reason', 'already_claimed',
                              'streak', COALESCE(v_streak, 0));
  END IF;
  v_new_streak := CASE WHEN v_last = v_day - 1 THEN COALESCE(v_streak, 0) + 1 ELSE 1 END;
  UPDATE public.user_quest_stats
     SET last_perfect_date = v_day,
         current_streak    = v_new_streak,
         longest_streak    = GREATEST(longest_streak, v_new_streak),
         perfect_days      = perfect_days + 1,
         coins_earned      = coins_earned + c_bonus_coins,
         updated_at        = now()
   WHERE user_id = v_uid
     AND (last_perfect_date IS DISTINCT FROM v_day);
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', FALSE, 'reason', 'already_claimed',
                              'streak', v_new_streak);
  END IF;
  UPDATE public.user_profiles
     SET flex_coins = COALESCE(flex_coins, 0) + c_bonus_coins
   WHERE id = v_uid
  RETURNING flex_coins INTO v_new_balance;
  v_xp_credited := public.grant_action_xp('quest_perfect_day', c_bonus_xp);
  IF v_xp_credited > 0 THEN
    v_crew_id := public.primary_crew_id(v_uid);
    IF v_crew_id IS NOT NULL THEN
      v_crew_xp := c_bonus_crew;
      PERFORM public.award_crew_progress(v_crew_id, v_crew_xp, 0, 0, 'quest');
    END IF;
  END IF;
  UPDATE public.user_quest_stats
     SET xp_earned      = xp_earned      + v_xp_credited,
         crew_xp_earned = crew_xp_earned + v_crew_xp
   WHERE user_id = v_uid;
  RETURN jsonb_build_object(
    'success',         TRUE,
    'coins_awarded',   c_bonus_coins,
    'xp_awarded',      v_xp_credited,
    'crew_xp_awarded', v_crew_xp,
    'streak',          v_new_streak,
    'new_balance',     COALESCE(v_new_balance, 0)
  );
END;
$$;


ALTER FUNCTION "public"."claim_perfect_day_bonus"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_quest_atomic"("p_quest_row_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid          uuid := auth.uid();
  v_reward       integer;
  v_xp           integer;
  v_difficulty   text;
  v_new_balance  integer;
  v_xp_credited  integer := 0;
  v_crew_id      uuid;
  v_crew_xp      integer := 0;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;
  IF p_quest_row_id IS NULL THEN
    RAISE EXCEPTION 'quest_row_id required' USING ERRCODE = '22023';
  END IF;
  UPDATE public.user_daily_quests
     SET claimed_at = now()
   WHERE id           = p_quest_row_id
     AND user_id      = v_uid
     AND completed_at IS NOT NULL
     AND claimed_at   IS NULL
  RETURNING coin_reward, xp_reward, difficulty
       INTO v_reward, v_xp, v_difficulty;
  IF v_reward IS NULL THEN
    SELECT flex_coins INTO v_new_balance
      FROM public.user_profiles
     WHERE id = v_uid;
    RETURN jsonb_build_object(
      'success',         FALSE,
      'already_claimed', TRUE,
      'coins_awarded',   0,
      'xp_awarded',      0,
      'crew_xp_awarded', 0,
      'new_balance',     COALESCE(v_new_balance, 0)
    );
  END IF;
  UPDATE public.user_profiles
     SET flex_coins = COALESCE(flex_coins, 0) + v_reward
   WHERE id = v_uid
  RETURNING flex_coins INTO v_new_balance;
  IF COALESCE(v_xp, 0) > 0 THEN
    v_xp_credited := public.grant_action_xp('daily_quest', v_xp);
  END IF;
  IF v_xp_credited > 0 THEN
    v_crew_id := public.primary_crew_id(v_uid);
    IF v_crew_id IS NOT NULL THEN
      v_crew_xp := CASE
        WHEN v_difficulty = 'crew' THEN v_xp_credited
        ELSE CEIL(v_xp_credited * 0.25)::integer
      END;
      PERFORM public.award_crew_progress(v_crew_id, v_crew_xp, 0, 0, 'quest');
    END IF;
  END IF;
  INSERT INTO public.user_quest_stats
    (user_id, quests_claimed, coins_earned, xp_earned, crew_xp_earned, updated_at)
  VALUES (v_uid, 1, v_reward, v_xp_credited, v_crew_xp, now())
  ON CONFLICT (user_id) DO UPDATE SET
    quests_claimed = public.user_quest_stats.quests_claimed + 1,
    coins_earned   = public.user_quest_stats.coins_earned   + v_reward,
    xp_earned      = public.user_quest_stats.xp_earned      + v_xp_credited,
    crew_xp_earned = public.user_quest_stats.crew_xp_earned + v_crew_xp,
    updated_at     = now();
  RETURN jsonb_build_object(
    'success',         TRUE,
    'already_claimed', FALSE,
    'coins_awarded',   v_reward,
    'xp_awarded',      v_xp_credited,
    'crew_xp_awarded', v_crew_xp,
    'new_balance',     v_new_balance
  );
END;
$$;


ALTER FUNCTION "public"."claim_quest_atomic"("p_quest_row_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_referral"("p_code" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_code TEXT := upper(trim(COALESCE(p_code, '')));
  v_referrer UUID;
  v_already INT;
  v_ref_count INT;
  v_referrer_reward_cap CONSTANT INT := 25;
  v_referee_email TEXT; v_referrer_email TEXT;
  v_referee_username TEXT; v_referrer_username TEXT;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501'; END IF;
  IF v_code = '' OR length(v_code) <> 6 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'invalid_code'); END IF;
  SELECT COUNT(*) INTO v_already FROM public.referrals WHERE referee_id = v_uid;
  IF v_already > 0 THEN RETURN jsonb_build_object('ok', false, 'reason', 'already_claimed'); END IF;
  SELECT id, email, username INTO v_referrer, v_referrer_email, v_referrer_username
    FROM public.user_profiles WHERE referral_code = v_code;
  IF v_referrer IS NULL THEN RETURN jsonb_build_object('ok', false, 'reason', 'code_not_found'); END IF;
  IF v_referrer = v_uid THEN RETURN jsonb_build_object('ok', false, 'reason', 'self_referral'); END IF;
  SELECT email, username INTO v_referee_email, v_referee_username
    FROM public.user_profiles WHERE id = v_uid;

  SELECT COUNT(*) INTO v_ref_count FROM public.referrals WHERE referrer_id = v_referrer;

  BEGIN
    INSERT INTO public.referrals (referrer_id, referee_id, code)
    VALUES (v_referrer, v_uid, v_code);
  EXCEPTION WHEN unique_violation THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'already_claimed');
  END;

  UPDATE public.user_profiles
     SET flex_coins = COALESCE(flex_coins, 0) + 200
   WHERE id = v_uid;
  INSERT INTO public.user_capsules (user_id, user_email, capsule_type)
  VALUES (v_uid, v_referee_email, 'elite');
  INSERT INTO public.notifications (user_id, user_email, type, title, body, icon, link_url, metadata)
  VALUES
    (v_uid, v_referee_email, 'referral_success',
     'Welcome to Flexyn',
     '+200 coins and an Elite capsule for joining via ' || COALESCE(v_referrer_username, 'a friend') || '''s code.',
     '🎁', '/dashboard',
     jsonb_build_object('referrer_id', v_referrer, 'code', v_code, 'reward_coins', 200));

  IF v_ref_count < v_referrer_reward_cap THEN
    UPDATE public.user_profiles
       SET flex_coins = COALESCE(flex_coins, 0) + 200
     WHERE id = v_referrer;
    INSERT INTO public.user_capsules (user_id, user_email, capsule_type)
    VALUES (v_referrer, v_referrer_email, 'elite');
    INSERT INTO public.notifications (user_id, user_email, type, title, body, icon, link_url, metadata)
    VALUES
      (v_referrer, v_referrer_email, 'referral_success',
       COALESCE(v_referee_username, 'A friend') || ' joined Flexyn via your code',
       '+200 coins and an Elite capsule are yours.', '🎁', '/hub',
       jsonb_build_object('referee_id', v_uid, 'code', v_code, 'reward_coins', 200));
  END IF;

  RETURN jsonb_build_object('ok', true, 'referrer_id', v_referrer,
    'referrer_name', v_referrer_username, 'reward_coins', 200, 'reward_capsule', 'elite',
    'referrer_rewarded', (v_ref_count < v_referrer_reward_cap));
END;
$$;


ALTER FUNCTION "public"."claim_referral"("p_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_solo_challenge"("p_challenge_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid      UUID := auth.uid();
  v_email    TEXT;
  v_claim_id UUID;
  v_active   BOOLEAN;
  v_expires  TIMESTAMPTZ;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;

  SELECT is_active, expires_at INTO v_active, v_expires
    FROM public.solo_challenges
   WHERE id = p_challenge_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'challenge not found' USING ERRCODE = '22023';
  END IF;
  IF NOT v_active OR v_expires < NOW() THEN
    RAISE EXCEPTION 'challenge inactive or expired' USING ERRCODE = '22023';
  END IF;

  SELECT email INTO v_email FROM public.user_profiles WHERE id = v_uid;

  SELECT id INTO v_claim_id
    FROM public.solo_challenge_claims
   WHERE challenge_id = p_challenge_id
     AND user_id      = v_uid
     AND status       = 'active'
   LIMIT 1;
  IF FOUND THEN RETURN v_claim_id; END IF;

  INSERT INTO public.solo_challenge_claims (challenge_id, user_id, user_email)
  VALUES (p_challenge_id, v_uid, v_email)
  ON CONFLICT (challenge_id, user_id) DO UPDATE
    SET status = 'active',
        progress = 0,
        completed_at = NULL,
        claimed_at = NOW()
  RETURNING id INTO v_claim_id;

  RETURN v_claim_id;
END;
$$;


ALTER FUNCTION "public"."claim_solo_challenge"("p_challenge_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."storage_cleanup_queue" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "bucket_id" "text" DEFAULT 'uploads'::"text" NOT NULL,
    "object_name" "text" NOT NULL,
    "source" "text",
    "requested_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "processed_at" timestamp with time zone,
    "attempts" integer DEFAULT 0 NOT NULL,
    "last_error" "text"
);


ALTER TABLE "public"."storage_cleanup_queue" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_storage_cleanup"("p_limit" integer DEFAULT 100) RETURNS SETOF "public"."storage_cleanup_queue"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT *
    FROM public.storage_cleanup_queue
   WHERE processed_at IS NULL
     AND attempts = least(attempts, 5)
     AND NOT EXISTS (
       SELECT 1 FROM public.hub_messages
        WHERE attachment_url LIKE '%/' || object_name
     )
     AND NOT EXISTS (
       SELECT 1 FROM public.stories
        WHERE image_url LIKE '%/' || object_name
     )
     AND NOT EXISTS (
       SELECT 1 FROM public.hub_posts
        WHERE image_url LIKE '%/' || object_name
           OR video_url LIKE '%/' || object_name
     )
     AND NOT EXISTS (
       SELECT 1 FROM public.user_profiles
        WHERE avatar_url LIKE '%/' || object_name
     )
   ORDER BY requested_at
   LIMIT coalesce(p_limit, 100);
$$;


ALTER FUNCTION "public"."claim_storage_cleanup"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."clear_workout_active"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;
  UPDATE public.user_profiles SET active_until = NULL WHERE id = v_uid;
END;
$$;


ALTER FUNCTION "public"."clear_workout_active"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."comment_reply_text"("p_language" "text", "p_commenter" "text", "p_snippet" "text", "p_is_reply" boolean) RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
  SELECT jsonb_build_object(
    'title',
      CASE
        WHEN p_is_reply THEN
          CASE COALESCE(p_language, 'en')
            WHEN 'es' THEN p_commenter || ' respondió a tu comentario'
            WHEN 'fr' THEN p_commenter || ' a répondu à votre commentaire'
            WHEN 'de' THEN p_commenter || ' hat auf deinen Kommentar geantwortet'
            WHEN 'pt' THEN p_commenter || ' respondeu ao seu comentário'
            WHEN 'it' THEN p_commenter || ' ha risposto al tuo commento'
            WHEN 'ja' THEN p_commenter || 'があなたのコメントに返信しました'
            WHEN 'ko' THEN p_commenter || '님이 당신의 댓글에 답글을 달았어요'
            WHEN 'zh' THEN p_commenter || ' 回复了你的评论'
            WHEN 'ar' THEN p_commenter || ' ردّ على تعليقك'
            WHEN 'hi' THEN p_commenter || ' ने आपकी टिप्पणी का जवाब दिया'
            WHEN 'ru' THEN p_commenter || ' ответил(а) на ваш комментарий'
            WHEN 'tr' THEN p_commenter || ' yorumuna yanıt verdi'
            WHEN 'pl' THEN p_commenter || ' odpowiedział(a) na twój komentarz'
            WHEN 'nl' THEN p_commenter || ' heeft op je reactie geantwoord'
            ELSE              p_commenter || ' replied to your comment'
          END
        ELSE
          CASE COALESCE(p_language, 'en')
            WHEN 'es' THEN p_commenter || ' comentó en tu publicación'
            WHEN 'fr' THEN p_commenter || ' a commenté votre publication'
            WHEN 'de' THEN p_commenter || ' hat deinen Beitrag kommentiert'
            WHEN 'pt' THEN p_commenter || ' comentou na sua publicação'
            WHEN 'it' THEN p_commenter || ' ha commentato il tuo post'
            WHEN 'ja' THEN p_commenter || 'があなたの投稿にコメントしました'
            WHEN 'ko' THEN p_commenter || '님이 당신의 게시물에 댓글을 달았어요'
            WHEN 'zh' THEN p_commenter || ' 评论了你的帖子'
            WHEN 'ar' THEN p_commenter || ' علّق على منشورك'
            WHEN 'hi' THEN p_commenter || ' ने आपकी पोस्ट पर टिप्पणी की'
            WHEN 'ru' THEN p_commenter || ' прокомментировал(а) вашу публикацию'
            WHEN 'tr' THEN p_commenter || ' gönderine yorum yaptı'
            WHEN 'pl' THEN p_commenter || ' skomentował(a) twój post'
            WHEN 'nl' THEN p_commenter || ' heeft je bericht becommentarieerd'
            ELSE              p_commenter || ' commented on your post'
          END
      END,
    'body', COALESCE(p_snippet, '')
  );
$$;


ALTER FUNCTION "public"."comment_reply_text"("p_language" "text", "p_commenter" "text", "p_snippet" "text", "p_is_reply" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_bounty_claim"("p_claim_id" "uuid", "p_workout_log_id" "uuid" DEFAULT NULL::"uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id      UUID := auth.uid();
  v_claim_status TEXT;
  v_claim_dl     TIMESTAMPTZ;
  v_bounty_id    UUID;
  v_metric       TEXT;
  v_exercise     TEXT;
  v_target       NUMERIC;
  v_reward       INT;
  v_log_owner    UUID;
  v_exercises    JSONB;
  v_achieved     NUMERIC := 0;
  v_ex           JSONB;
  v_set          JSONB;
  v_w            NUMERIC;
  v_r            NUMERIC;
  v_week_logs    JSONB;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;
  IF p_workout_log_id IS NULL THEN
    RAISE EXCEPTION 'workout_log_required' USING ERRCODE = '22023';
  END IF;

  SELECT status, bounty_id, deadline
    INTO v_claim_status, v_bounty_id, v_claim_dl
    FROM public.bounty_claims
   WHERE id = p_claim_id AND claimant_id = v_user_id
   FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'claim_not_found'  USING ERRCODE = '22023'; END IF;
  IF v_claim_status <> 'active' THEN RAISE EXCEPTION 'claim_not_active' USING ERRCODE = '22023'; END IF;
  IF v_claim_dl < NOW() THEN RAISE EXCEPTION 'claim_expired' USING ERRCODE = '22023'; END IF;

  SELECT metric::text, exercise_name, target_value, reward
    INTO v_metric, v_exercise, v_target, v_reward
    FROM public.bounties WHERE id = v_bounty_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'bounty_not_found' USING ERRCODE = '22023'; END IF;

  SELECT user_id, exercises INTO v_log_owner, v_exercises
    FROM public.workout_logs WHERE id = p_workout_log_id;
  IF NOT FOUND OR v_log_owner <> v_user_id THEN
    RAISE EXCEPTION 'invalid_workout_log' USING ERRCODE = '42501';
  END IF;

  -- Migration 362: a flagged log cannot buy an award.
  IF public.workout_log_is_flagged(p_workout_log_id) THEN
    RAISE EXCEPTION 'implausible_workout_log' USING ERRCODE = '22023';
  END IF;

  IF v_metric = 'session_volume' THEN
    v_achieved := public._duel_calc_volume(v_exercises);
  ELSIF v_metric = 'weekly_volume' THEN
    v_achieved := 0;
    FOR v_week_logs IN
      SELECT exercises FROM public.workout_logs
       WHERE user_id = v_user_id
         AND NOT COALESCE(implausible, FALSE)
         AND created_at >= NOW() - INTERVAL '7 days'
    LOOP
      v_achieved := v_achieved + public._duel_calc_volume(v_week_logs);
    END LOOP;
  ELSIF v_metric IN ('single_lift_weight', 'single_lift_reps')
        AND v_exercise IS NOT NULL
        AND jsonb_typeof(v_exercises) = 'array' THEN
    FOR v_ex IN SELECT * FROM jsonb_array_elements(v_exercises) LOOP
      IF lower(COALESCE(v_ex->>'name', '')) = lower(v_exercise)
         AND jsonb_typeof(v_ex->'sets') = 'array' THEN
        FOR v_set IN SELECT * FROM jsonb_array_elements(v_ex->'sets') LOOP
          v_w := COALESCE((v_set->>'weight')::NUMERIC, 0);
          v_r := COALESCE((v_set->>'reps')::NUMERIC, 0);
          IF v_metric = 'single_lift_weight' AND v_w > v_achieved THEN v_achieved := v_w; END IF;
          IF v_metric = 'single_lift_reps'   AND v_r > v_achieved THEN v_achieved := v_r; END IF;
        END LOOP;
      END IF;
    END LOOP;
  ELSE
    RAISE EXCEPTION 'unsupported_metric' USING ERRCODE = '22023';
  END IF;

  IF v_achieved < v_target THEN
    RAISE EXCEPTION 'target_not_met' USING ERRCODE = '22023';
  END IF;

  UPDATE public.bounty_claims
     SET status = 'completed', completed_at = NOW(), workout_log_id = p_workout_log_id
   WHERE id = p_claim_id;

  UPDATE public.user_profiles
     SET flex_coins = flex_coins + v_reward
   WHERE id = v_user_id;
END;
$$;


ALTER FUNCTION "public"."complete_bounty_claim"("p_claim_id" "uuid", "p_workout_log_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_gauntlet_challenge"("p_sequence_number" integer, "p_workout_log_id" "uuid" DEFAULT NULL::"uuid", "p_score" double precision DEFAULT NULL::double precision) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id      UUID := auth.uid();
  v_challenge_id UUID; v_title TEXT; v_metric TEXT; v_target NUMERIC;
  v_xp_reward INT; v_coin_reward INT; v_cur_seq INT; v_next_seq INT;
  v_path_done BOOLEAN := FALSE; v_log_owner UUID; v_log_ex JSONB;
  v_agg NUMERIC; v_cnt INT; v_window INT; v_ok BOOLEAN := FALSE;
BEGIN
  IF v_user_id IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  SELECT id, title, metric, target_value, xp_reward, coin_reward
    INTO v_challenge_id, v_title, v_metric, v_target, v_xp_reward, v_coin_reward
    FROM public.gauntlet_challenges WHERE sequence_number = p_sequence_number;
  IF v_challenge_id IS NULL THEN RAISE EXCEPTION 'challenge_not_found'; END IF;
  INSERT INTO public.user_gauntlet_progress (user_id, current_challenge_sequence)
  VALUES (v_user_id, 1) ON CONFLICT (user_id) DO NOTHING;
  SELECT current_challenge_sequence INTO v_cur_seq
    FROM public.user_gauntlet_progress WHERE user_id = v_user_id FOR UPDATE;
  IF v_cur_seq <> p_sequence_number THEN RAISE EXCEPTION 'wrong_challenge'; END IF;
  IF EXISTS (SELECT 1 FROM public.user_gauntlet_completions
              WHERE user_id = v_user_id AND challenge_id = v_challenge_id) THEN
    RAISE EXCEPTION 'already_completed';
  END IF;
  IF p_workout_log_id IS NOT NULL THEN
    SELECT user_id, exercises INTO v_log_owner, v_log_ex
      FROM public.workout_logs WHERE id = p_workout_log_id;
    IF v_log_owner IS DISTINCT FROM v_user_id THEN
      RAISE EXCEPTION 'invalid_workout_log' USING ERRCODE = '42501';
    END IF;

  -- Migration 362: a flagged log cannot buy an award.
  IF public.workout_log_is_flagged(p_workout_log_id) THEN
    RAISE EXCEPTION 'implausible_workout_log' USING ERRCODE = '22023';
  END IF;
  END IF;
  IF v_metric = 'session_volume' THEN
    v_ok := (v_log_ex IS NOT NULL AND public._duel_calc_volume(v_log_ex) >= v_target);
  ELSIF v_metric = 'min_exercises_no_skip' THEN
    v_ok := (v_log_ex IS NOT NULL AND jsonb_typeof(v_log_ex) = 'array'
             AND jsonb_array_length(v_log_ex) >= v_target);
  ELSIF v_metric = 'weekly_lbs' THEN
    SELECT COALESCE(SUM(public._duel_calc_volume(exercises)), 0) INTO v_agg
      FROM public.workout_logs
     WHERE user_id = v_user_id
       AND NOT COALESCE(implausible, FALSE)
       AND date >= (date_trunc('week', (now() AT TIME ZONE 'utc')::date) - INTERVAL '1 day')::date;
    v_ok := (v_agg >= v_target);
  ELSIF v_metric IN ('sessions_in_5_days', 'sessions_in_7_days') THEN
    v_window := CASE v_metric WHEN 'sessions_in_5_days' THEN 5 ELSE 7 END;
    SELECT COUNT(DISTINCT date) INTO v_cnt FROM public.workout_logs
     WHERE user_id = v_user_id AND date >= ((now() AT TIME ZONE 'utc')::date - v_window);
    v_ok := (v_cnt >= v_target);
  ELSIF v_metric = 'consecutive_days' THEN
    SELECT COALESCE(workout_streak, 0) INTO v_cnt FROM public.user_profiles WHERE id = v_user_id;
    v_ok := (v_cnt >= v_target);
  ELSE
    v_ok := (v_log_ex IS NOT NULL);
  END IF;
  IF NOT v_ok THEN RAISE EXCEPTION 'challenge_target_not_met' USING ERRCODE = '22023'; END IF;
  INSERT INTO public.user_gauntlet_completions
    (user_id, challenge_id, sequence_number, score, workout_log_id)
  VALUES (v_user_id, v_challenge_id, p_sequence_number, p_score, p_workout_log_id);
  v_next_seq := p_sequence_number + 1;
  SELECT COUNT(*) = 0 INTO v_path_done FROM public.gauntlet_challenges WHERE sequence_number = v_next_seq;
  UPDATE public.user_gauntlet_progress SET
    current_challenge_sequence = CASE WHEN v_path_done THEN p_sequence_number ELSE v_next_seq END,
    challenges_completed = challenges_completed + 1, last_completed_at = NOW(),
    path_completed = v_path_done,
    path_completed_at = CASE WHEN v_path_done THEN NOW() ELSE NULL END
  WHERE user_id = v_user_id;
  UPDATE public.user_profiles SET
    total_xp = COALESCE(total_xp, 0) + v_xp_reward,
    lifetime_xp = COALESCE(lifetime_xp, 0) + v_xp_reward,
    flex_coins = COALESCE(flex_coins, 0) + v_coin_reward
  WHERE id = v_user_id;
  RETURN jsonb_build_object('challenge_id', v_challenge_id, 'challenge_title', v_title,
    'next_sequence', v_next_seq, 'xp_awarded', v_xp_reward, 'coins_awarded', v_coin_reward,
    'path_completed', v_path_done);
END;
$$;


ALTER FUNCTION "public"."complete_gauntlet_challenge"("p_sequence_number" integer, "p_workout_log_id" "uuid", "p_score" double precision) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_goal"("p_goal_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_email TEXT := NULLIF(public.current_user_email(), '');
  v_row RECORD;
BEGIN
  IF v_uid IS NULL OR v_email IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE='42501'; END IF;
  IF p_goal_id IS NULL THEN RAISE EXCEPTION 'goal_id required' USING ERRCODE='22023'; END IF;
  UPDATE public.goals SET status='completed', completed_at=now()
    WHERE id=p_goal_id AND created_by=v_email AND status='active'
    RETURNING id INTO v_row;
  IF v_row.id IS NULL THEN
    RETURN jsonb_build_object('completed',false,'already',true,'goal_id',p_goal_id);
  END IF;
  RETURN jsonb_build_object('completed',true,'goal_id',p_goal_id);
END; $$;


ALTER FUNCTION "public"."complete_goal"("p_goal_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_solo_challenge"("p_claim_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid           UUID := auth.uid();
  v_progress      NUMERIC;
  v_target        NUMERIC;
  v_reward        INT;
  v_status        TEXT;
  v_challenge_id  UUID;
  v_new_balance   INT;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;

  SELECT challenge_id, progress, status
    INTO v_challenge_id, v_progress, v_status
    FROM public.solo_challenge_claims
   WHERE id = p_claim_id
     AND user_id = v_uid
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'claim not found' USING ERRCODE = '22023';
  END IF;

  SELECT target_value, reward_coins
    INTO v_target, v_reward
    FROM public.solo_challenges
   WHERE id = v_challenge_id;

  IF v_status = 'completed' THEN
    SELECT flex_coins INTO v_new_balance FROM public.user_profiles WHERE id = v_uid;
    RETURN jsonb_build_object(
      'already_completed', TRUE,
      'coins_awarded',     0,
      'new_balance',       COALESCE(v_new_balance, 0)
    );
  END IF;
  IF v_progress < v_target THEN
    RAISE EXCEPTION 'progress % below target %', v_progress, v_target
      USING ERRCODE = '22023';
  END IF;

  UPDATE public.solo_challenge_claims
     SET status       = 'completed',
         completed_at = NOW()
   WHERE id = p_claim_id;

  UPDATE public.user_profiles
     SET flex_coins = COALESCE(flex_coins, 0) + v_reward
   WHERE id = v_uid
  RETURNING flex_coins INTO v_new_balance;

  RETURN jsonb_build_object(
    'already_completed', FALSE,
    'coins_awarded',     v_reward,
    'new_balance',       COALESCE(v_new_balance, 0)
  );
END;
$$;


ALTER FUNCTION "public"."complete_solo_challenge"("p_claim_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_storage_cleanup"("p_ids" "uuid"[]) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_done INTEGER := 0;
BEGIN
  IF p_ids IS NULL OR array_length(p_ids, 1) IS NULL THEN
    RETURN 0;
  END IF;
  UPDATE public.storage_cleanup_queue
     SET processed_at = now(),
         last_error   = NULL
   WHERE id = ANY (p_ids)
     AND processed_at IS NULL;
  GET DIAGNOSTICS v_done = ROW_COUNT;
  RETURN v_done;
END;
$$;


ALTER FUNCTION "public"."complete_storage_cleanup"("p_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."consume_coach_chat_quota"() RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_global_cap constant integer := 3000;
  v_user_cap   constant integer := 20;
  v_guest_cap  constant integer := 5;
  v_day        date := (now() AT TIME ZONE 'utc')::date;
  v_cap        integer;
  v_count      integer;
  v_total      integer;
  v_email      text;
  v_is_guest   boolean;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN false;
  END IF;

  SELECT lower(email) INTO v_email FROM auth.users WHERE id = auth.uid();
  IF v_email = ANY (ARRAY['keganbergeron@gmail.com']) THEN
    RETURN true;
  END IF;

  SELECT call_count INTO v_total
    FROM public.coach_chat_daily_total
   WHERE day = v_day;

  IF COALESCE(v_total, 0) >= v_global_cap THEN
    RETURN false;
  END IF;

  SELECT is_anonymous INTO v_is_guest FROM auth.users WHERE id = auth.uid();
  v_cap := CASE WHEN COALESCE(v_is_guest, false) THEN v_guest_cap ELSE v_user_cap END;

  SELECT call_count INTO v_count
    FROM public.coach_chat_quota
   WHERE user_id = auth.uid()
     AND day = v_day;

  IF COALESCE(v_count, 0) >= v_cap THEN
    RETURN false;
  END IF;

  INSERT INTO public.coach_chat_quota (user_id, day, call_count)
  VALUES (auth.uid(), v_day, 1)
  ON CONFLICT (user_id, day)
  DO UPDATE SET call_count = public.coach_chat_quota.call_count + 1
  RETURNING call_count INTO v_count;

  INSERT INTO public.coach_chat_daily_total (day, call_count)
  VALUES (v_day, 1)
  ON CONFLICT (day)
  DO UPDATE SET call_count = public.coach_chat_daily_total.call_count + 1;

  RETURN v_count <= v_cap;
END;
$$;


ALTER FUNCTION "public"."consume_coach_chat_quota"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."consume_recognize_meal_quota"() RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_global_cap constant integer := 500;
  v_cap        constant integer := 3;
  v_day        date := (now() AT TIME ZONE 'utc')::date;
  v_count      integer;
  v_total      integer;
  v_email      text;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN false;
  END IF;
  SELECT lower(email) INTO v_email FROM auth.users WHERE id = auth.uid();
  IF v_email = ANY (ARRAY['keganbergeron@gmail.com']) THEN
    RETURN true;
  END IF;
  SELECT call_count INTO v_total FROM public.recognize_meal_daily_total WHERE day = v_day;
  IF COALESCE(v_total, 0) >= v_global_cap THEN
    RETURN false;
  END IF;
  SELECT call_count INTO v_count FROM public.recognize_meal_quota
   WHERE user_id = auth.uid() AND day = v_day;
  IF COALESCE(v_count, 0) >= v_cap THEN
    RETURN false;
  END IF;
  INSERT INTO public.recognize_meal_quota (user_id, day, call_count)
  VALUES (auth.uid(), v_day, 1)
  ON CONFLICT (user_id, day)
  DO UPDATE SET call_count = public.recognize_meal_quota.call_count + 1
  RETURNING call_count INTO v_count;
  INSERT INTO public.recognize_meal_daily_total (day, call_count)
  VALUES (v_day, 1)
  ON CONFLICT (day)
  DO UPDATE SET call_count = public.recognize_meal_daily_total.call_count + 1;
  RETURN v_count <= v_cap;
END;
$$;


ALTER FUNCTION "public"."consume_recognize_meal_quota"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."contribute_crew_war_xp"("p_war_id" "uuid", "p_crew_id" "uuid", "p_xp" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_uid    uuid := auth.uid();
  v_member integer;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;
  IF p_war_id IS NULL OR p_crew_id IS NULL THEN
    RAISE EXCEPTION 'war_id and crew_id required' USING ERRCODE = '22023';
  END IF;

  SELECT COUNT(*) INTO v_member
    FROM public.crew_members WHERE crew_id = p_crew_id AND user_id = v_uid;
  IF v_member = 0 THEN
    RAISE EXCEPTION 'not a member of this crew' USING ERRCODE = '42501';
  END IF;

  PERFORM public.recompute_crew_war(p_war_id);

  RETURN jsonb_build_object('success', TRUE, 'war_id', p_war_id,
                            'derived', TRUE);
END;
$$;


ALTER FUNCTION "public"."contribute_crew_war_xp"("p_war_id" "uuid", "p_crew_id" "uuid", "p_xp" integer) OWNER TO "postgres";


