CREATE OR REPLACE FUNCTION "public"."create_crew_atomic"("p_name" "text") RETURNS "public"."crews"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_uid  uuid := auth.uid();
  v_have integer;
  v_crew public.crews;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;
  IF p_name IS NULL OR length(btrim(p_name)) = 0 THEN
    RAISE EXCEPTION 'crew name required' USING ERRCODE = '22023';
  END IF;

  SELECT COUNT(*) INTO v_have FROM public.crew_members WHERE user_id = v_uid;
  IF NOT (v_have = 0) THEN
    RAISE EXCEPTION 'already_in_crew' USING ERRCODE = '23505';
  END IF;

  INSERT INTO public.crews (name, created_by)
  VALUES (btrim(p_name), v_uid)
  RETURNING * INTO v_crew;

  INSERT INTO public.crew_members (crew_id, user_id, is_admin, role)
  VALUES (v_crew.id, v_uid, TRUE, 'leader');

  RETURN v_crew;
END;
$$;


ALTER FUNCTION "public"."create_crew_atomic"("p_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_group_conversation"("p_emails" "text"[], "p_title" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid       UUID := auth.uid();
  v_email     TEXT := NULLIF(public.current_user_email(), '');
  v_all       TEXT[];
  v_total     INTEGER;
  v_conv_id   UUID;
  v_title     TEXT;
BEGIN
  IF v_uid IS NULL OR v_email IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;
  IF p_emails IS NULL OR array_length(p_emails, 1) IS NULL THEN
    RAISE EXCEPTION 'no_participants' USING ERRCODE = '22023';
  END IF;

  SELECT ARRAY(
    SELECT DISTINCT lower(e)
      FROM unnest(p_emails) AS e
     WHERE e IS NOT NULL
       AND length(trim(e)) > 0
       AND lower(e) <> lower(v_email)
  ) INTO v_all;

  v_total := coalesce(array_length(v_all, 1), 0) + 1;
  IF v_total < 3 THEN
    RAISE EXCEPTION 'too_few_participants' USING ERRCODE = '22023';
  END IF;
  IF v_total > 10 THEN
    RAISE EXCEPTION 'too_many_participants' USING ERRCODE = '22023';
  END IF;

  v_title := nullif(trim(coalesce(p_title, '')), '');

  INSERT INTO public.hub_conversations
    (created_by, user_id, participant_emails, participant_ids,
     is_group, title, accepted_emails,
     last_message_at, created_at, updated_at)
  VALUES
    (v_email, v_uid,
     v_all || ARRAY[lower(v_email)],
     ARRAY[v_uid]::uuid[],
     TRUE, v_title, ARRAY[lower(v_email)],
     now(), now(), now())
  RETURNING id INTO v_conv_id;

  RETURN v_conv_id;
END;
$$;


ALTER FUNCTION "public"."create_group_conversation"("p_emails" "text"[], "p_title" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_marketplace_listing"("p_inventory_id" "uuid", "p_listing_type" "text", "p_asking_price" integer, "p_trade_for_rarity" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_seller_uid   UUID := auth.uid();
  v_seller_email TEXT := NULLIF(public.current_user_email(), '');
  v_inv          public.user_inventory%ROWTYPE;
  v_username     TEXT;
  v_listing_id   UUID;
BEGIN
  IF v_seller_uid IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE='42501'; END IF;
  IF p_listing_type NOT IN ('sale','trade') THEN RAISE EXCEPTION 'invalid listing_type: %', p_listing_type USING ERRCODE='22023'; END IF;
  IF p_listing_type='sale' AND (p_asking_price IS NULL OR p_asking_price<1) THEN
    RAISE EXCEPTION 'sale listings require asking_price >= 1' USING ERRCODE='22023';
  END IF;
  SELECT * INTO v_inv FROM public.user_inventory WHERE id=p_inventory_id AND user_id=v_seller_uid FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'inventory item not found or not owned by caller' USING ERRCODE='42501'; END IF;
  IF COALESCE(v_inv.is_listed,false) THEN RAISE EXCEPTION 'item already listed' USING ERRCODE='22023'; END IF;
  SELECT COALESCE(username,'') INTO v_username FROM public.user_profiles WHERE id=v_seller_uid;
  INSERT INTO public.marketplace_listings (seller_user_id,seller_email,seller_username,inventory_id,item_id,
    item_name,item_emoji,item_rarity,listing_type,asking_price,trade_for_rarity,status)
  VALUES (v_seller_uid,v_seller_email,COALESCE(v_username,''),p_inventory_id,v_inv.item_id,v_inv.item_name,
    COALESCE(v_inv.item_emoji,''),COALESCE(v_inv.item_rarity,'common'),
    p_listing_type,p_asking_price,p_trade_for_rarity,'active')
  RETURNING id INTO v_listing_id;
  UPDATE public.user_inventory SET is_listed=true WHERE id=p_inventory_id;
  RETURN v_listing_id;
END; $$;


ALTER FUNCTION "public"."create_marketplace_listing"("p_inventory_id" "uuid", "p_listing_type" "text", "p_asking_price" integer, "p_trade_for_rarity" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_notification_for"("p_user_id" "uuid", "p_type" "text", "p_title" "text", "p_body" "text", "p_icon" "text", "p_link_url" "text", "p_metadata" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_sender UUID := auth.uid();
  v_email TEXT;
  v_id UUID;
  v_allowed TEXT[] := ARRAY['friend_follow','friend_post','comment_reply','post_reaction','sticker_reaction','trade_offer'];
BEGIN
  IF v_sender IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE='42501'; END IF;
  IF p_user_id IS NULL OR p_type IS NULL THEN RAISE EXCEPTION 'user_id and type required' USING ERRCODE='22023'; END IF;
  IF NOT (p_type = ANY(v_allowed)) THEN
    RAISE EXCEPTION 'notification type % not allowed for cross-user dispatch', p_type USING ERRCODE='42501';
  END IF;
  IF p_user_id = v_sender THEN RETURN NULL; END IF;
  SELECT email INTO v_email FROM auth.users WHERE id=p_user_id;
  IF v_email IS NULL THEN RAISE EXCEPTION 'recipient not found' USING ERRCODE='22023'; END IF;
  INSERT INTO public.notifications (user_id,user_email,type,title,body,icon,link_url,metadata)
  VALUES (p_user_id,v_email,p_type,COALESCE(p_title,''),p_body,p_icon,p_link_url,COALESCE(p_metadata,'{}'::jsonb))
  RETURNING id INTO v_id;
  RETURN v_id;
END; $$;


ALTER FUNCTION "public"."create_notification_for"("p_user_id" "uuid", "p_type" "text", "p_title" "text", "p_body" "text", "p_icon" "text", "p_link_url" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_organization"("p_name" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
      DECLARE
        v_uid     UUID := auth.uid();
        v_code    TEXT;
        v_org     UUID;
        v_try     INT := 0;
        v_alpha   TEXT := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
        v_bytes   BYTEA;
        v_idx     INT;
      BEGIN
        IF v_uid IS NULL THEN
          RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501';
        END IF;
        IF COALESCE(btrim(p_name), '') = '' THEN
          RETURN jsonb_build_object('ok', false, 'error', 'NAME_REQUIRED');
        END IF;
        IF length(btrim(p_name)) > 80 THEN
          RETURN jsonb_build_object('ok', false, 'error', 'NAME_TOO_LONG');
        END IF;

        LOOP
          v_try := v_try + 1;
          v_bytes := gen_random_bytes(8);
          v_code := '';
          FOR v_idx IN 0..7 LOOP
            v_code := v_code || substr(v_alpha, (get_byte(v_bytes, v_idx) % 32) + 1, 1);
          END LOOP;
          EXIT WHEN NOT EXISTS (SELECT 1 FROM public.organizations WHERE join_code = v_code);
          IF v_try > 12 THEN
            RETURN jsonb_build_object('ok', false, 'error', 'CODE_MINT_FAILED');
          END IF;
        END LOOP;

        INSERT INTO public.organizations (name, owner_id, join_code)
          VALUES (btrim(p_name), v_uid, v_code)
          RETURNING id INTO v_org;
        INSERT INTO public.organization_members (org_id, user_id, role)
          VALUES (v_org, v_uid, 'admin')
          ON CONFLICT (org_id, user_id) DO NOTHING;

        RETURN jsonb_build_object('ok', true, 'org_id', v_org, 'join_code', v_code);
      END;
      $$;


ALTER FUNCTION "public"."create_organization"("p_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_pending_duel_invite"("p_duel_type" "text" DEFAULT 'open'::"text", "p_session_template" "jsonb" DEFAULT NULL::"jsonb", "p_target_exercise_id" "text" DEFAULT NULL::"text", "p_window_hours" integer DEFAULT 24) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid       UUID := auth.uid();
  v_username  TEXT;
  v_avatar    TEXT;
  v_token     TEXT;
  v_invite_id UUID;
  v_expires   TIMESTAMPTZ;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;
  IF p_duel_type NOT IN ('open', 'mirror', 'exercise') THEN
    RAISE EXCEPTION 'invalid duel_type' USING ERRCODE = '22023';
  END IF;
  IF p_window_hours IS NULL OR p_window_hours < 1 OR p_window_hours > 168 THEN
    RAISE EXCEPTION 'window_hours must be between 1 and 168' USING ERRCODE = '22023';
  END IF;

  SELECT username, avatar_url
    INTO v_username, v_avatar
    FROM public.user_profiles
   WHERE id = v_uid;

  v_token   := encode(gen_random_bytes(16), 'hex');
  v_expires := NOW() + (p_window_hours || ' hours')::INTERVAL + INTERVAL '7 days';

  INSERT INTO public.pending_duel_invites
    (claim_token, challenger_id, challenger_username, challenger_avatar_url,
     duel_type, session_template, target_exercise_id, window_hours, expires_at)
  VALUES
    (v_token, v_uid, v_username, v_avatar,
     p_duel_type, p_session_template, p_target_exercise_id, p_window_hours, v_expires)
  RETURNING id INTO v_invite_id;

  RETURN jsonb_build_object(
    'id',           v_invite_id,
    'token',        v_token,
    'expires_at',   v_expires,
    'duel_type',    p_duel_type,
    'window_hours', p_window_hours
  );
END;
$$;


ALTER FUNCTION "public"."create_pending_duel_invite"("p_duel_type" "text", "p_session_template" "jsonb", "p_target_exercise_id" "text", "p_window_hours" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_trade_offer"("p_from_inventory_id" "uuid", "p_to_inventory_id" "uuid", "p_listing_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_me          UUID := auth.uid();
  v_from_owner  UUID;
  v_from_listed BOOLEAN;
  v_from_escrow UUID;
  v_from_item   TEXT;
  v_from_name   TEXT;
  v_from_emoji  TEXT;
  v_from_rarity TEXT;
  v_to_owner    UUID;
  v_to_escrow   UUID;
  v_to_item     TEXT;
  v_to_name     TEXT;
  v_to_emoji    TEXT;
  v_to_rarity   TEXT;
  v_offer_id    UUID;
BEGIN
  IF v_me IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  IF p_from_inventory_id = p_to_inventory_id THEN RAISE EXCEPTION 'cannot_trade_with_self'; END IF;

  SELECT user_id, is_listed, escrow_offer_id, item_id, item_name, item_emoji, item_rarity
    INTO v_from_owner, v_from_listed, v_from_escrow, v_from_item, v_from_name, v_from_emoji, v_from_rarity
    FROM public.user_inventory WHERE id = p_from_inventory_id FOR UPDATE;

  IF v_from_owner IS NULL       THEN RAISE EXCEPTION 'offer_item_not_found'; END IF;
  IF v_from_owner <> v_me       THEN RAISE EXCEPTION 'not_your_item'; END IF;
  IF v_from_escrow IS NOT NULL  THEN RAISE EXCEPTION 'offer_item_in_escrow'; END IF;
  IF v_from_listed              THEN RAISE EXCEPTION 'offer_item_is_listed'; END IF;

  SELECT user_id, escrow_offer_id, item_id, item_name, item_emoji, item_rarity
    INTO v_to_owner, v_to_escrow, v_to_item, v_to_name, v_to_emoji, v_to_rarity
    FROM public.user_inventory WHERE id = p_to_inventory_id;

  IF v_to_owner IS NULL      THEN RAISE EXCEPTION 'target_item_not_found'; END IF;
  IF v_to_owner = v_me       THEN RAISE EXCEPTION 'cannot_trade_with_self'; END IF;
  IF v_to_escrow IS NOT NULL THEN RAISE EXCEPTION 'target_item_in_escrow'; END IF;

  INSERT INTO public.trade_offers (
    from_user_id, to_user_id, from_inventory_id, to_inventory_id, listing_id,
    from_item_id, from_item_name, from_item_emoji, from_item_rarity,
    to_item_id, to_item_name, to_item_emoji, to_item_rarity
  ) VALUES (
    v_me, v_to_owner, p_from_inventory_id, p_to_inventory_id, p_listing_id,
    v_from_item, v_from_name, v_from_emoji, v_from_rarity,
    v_to_item, v_to_name, v_to_emoji, v_to_rarity
  ) RETURNING id INTO v_offer_id;

  UPDATE public.user_inventory
     SET escrow_offer_id = v_offer_id, is_listed = TRUE
   WHERE id = p_from_inventory_id;

  RETURN v_offer_id;
END;
$$;


ALTER FUNCTION "public"."create_trade_offer"("p_from_inventory_id" "uuid", "p_to_inventory_id" "uuid", "p_listing_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_user_bounty"("p_metric" "text", "p_exercise_name" "text", "p_target_value" numeric, "p_difficulty" "text", "p_expires_at" timestamp with time zone) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid UUID := auth.uid(); v_username TEXT; v_avatar TEXT;
  v_entry INT; v_reward INT; v_id UUID; v_coins INT;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501'; END IF;
  IF p_metric NOT IN ('weekly_volume','session_volume','single_lift_weight','single_lift_reps') THEN
    RAISE EXCEPTION 'invalid metric' USING ERRCODE = '22023'; END IF;
  IF p_target_value IS NULL OR p_target_value <= 0 THEN
    RAISE EXCEPTION 'target_value must be positive' USING ERRCODE = '22023'; END IF;
  IF p_difficulty NOT IN ('easy','medium','hard') THEN
    RAISE EXCEPTION 'invalid difficulty' USING ERRCODE = '22023'; END IF;

  v_entry  := CASE p_difficulty WHEN 'easy' THEN 10 WHEN 'medium' THEN 15 ELSE 20 END;
  v_reward := CASE p_difficulty WHEN 'easy' THEN 60 WHEN 'medium' THEN 100 ELSE 175 END;

  SELECT username, avatar_url, flex_coins INTO v_username, v_avatar, v_coins
    FROM public.user_profiles WHERE id = v_uid FOR UPDATE;
  IF COALESCE(v_coins, 0) < v_reward THEN
    RAISE EXCEPTION 'insufficient_coins_to_stake' USING ERRCODE = '22023';
  END IF;

  UPDATE public.user_profiles SET flex_coins = flex_coins - v_reward WHERE id = v_uid;

  INSERT INTO public.bounties (target_user_id, target_username, target_avatar_url,
    metric, exercise_name, target_value, difficulty, entry_fee, reward,
    is_user_created, expires_at)
  VALUES (v_uid, v_username, v_avatar, p_metric, p_exercise_name, p_target_value,
    p_difficulty, v_entry, v_reward, TRUE, COALESCE(p_expires_at, now() + INTERVAL '48 hours'))
  RETURNING id INTO v_id;
  RETURN v_id;
END; $$;


ALTER FUNCTION "public"."create_user_bounty"("p_metric" "text", "p_exercise_name" "text", "p_target_value" numeric, "p_difficulty" "text", "p_expires_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."crew_can_review"("p_crew_id" "uuid", "p_user_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_rank INTEGER; v_reviewers INTEGER; v_member INTEGER;
BEGIN
  IF p_crew_id IS NULL OR p_user_id IS NULL THEN RETURN FALSE; END IF;

  v_rank := public.crew_rank(p_crew_id, p_user_id);
  IF v_rank IS NOT NULL AND v_rank >= 2 THEN RETURN TRUE; END IF;

  SELECT COUNT(*) INTO v_reviewers
    FROM public.crew_members
   WHERE crew_id = p_crew_id AND public.crew_rank(crew_id, user_id) >= 2;

  IF NOT (v_reviewers = 0) THEN RETURN FALSE; END IF;

  SELECT COUNT(*) INTO v_member
    FROM public.crew_members WHERE crew_id = p_crew_id AND user_id = p_user_id;

  RETURN NOT (v_member = 0);
END;
$$;


