CREATE OR REPLACE FUNCTION "public"."crew_level_for_xp"("p_xp" integer) RETURNS integer
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_level integer := 1;
  v_xp    integer := GREATEST(0, COALESCE(p_xp, 0));
BEGIN
  WHILE v_level = LEAST(v_level, 199) AND
        v_xp = GREATEST(v_xp, 100 * (v_level + 1) * v_level)
  LOOP
    v_level := v_level + 1;
  END LOOP;
  RETURN v_level;
END;
$$;


ALTER FUNCTION "public"."crew_level_for_xp"("p_xp" integer) OWNER TO "postgres";


