CREATE OR REPLACE FUNCTION "public"."crew_match_cadence"("p_crew_id" "uuid") RETURNS numeric
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_user  uuid;
  v_email text;
  v_sess  integer;
  v_sum   numeric := 0;
  v_n     integer := 0;
BEGIN
  FOR v_user IN
    SELECT user_id FROM public.crew_members WHERE crew_id = p_crew_id LIMIT 40
  LOOP
    SELECT lower(email) INTO v_email
      FROM public.user_profiles WHERE id = v_user;

    SELECT COUNT(*) INTO v_sess
      FROM public.workout_logs
     WHERE (user_id = v_user OR (v_email IS NOT NULL AND lower(created_by) = v_email))
       AND created_at > now() - INTERVAL '28 days'
       AND NOT COALESCE(implausible, FALSE);

    v_sum := v_sum + COALESCE(v_sess, 0);
    v_n   := v_n + 1;
  END LOOP;

  IF v_n = 0 THEN RETURN NULL; END IF;
  RETURN v_sum / v_n;
END;
$$;


ALTER FUNCTION "public"."crew_match_cadence"("p_crew_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."crew_match_gap"("p_roster_a" integer, "p_age_a" numeric, "p_str_a" numeric, "p_cad_a" numeric, "p_div_a" integer, "p_roster_b" integer, "p_age_b" numeric, "p_str_b" numeric, "p_cad_b" numeric, "p_div_b" integer) RETURNS numeric
    LANGUAGE "sql" IMMUTABLE
    AS $$
  WITH t AS (
    SELECT
      (p_roster_a IS NOT NULL AND p_roster_b IS NOT NULL
        AND NOT (COALESCE(p_roster_a,0) = COALESCE(p_roster_b,0))) AS sizes_differ,
      CASE WHEN COALESCE(p_roster_a,0) = LEAST(COALESCE(p_roster_a,0), COALESCE(p_roster_b,0))
           THEN p_str_a ELSE p_str_b END AS str_small,
      CASE WHEN COALESCE(p_roster_a,0) = LEAST(COALESCE(p_roster_a,0), COALESCE(p_roster_b,0))
           THEN p_str_b ELSE p_str_a END AS str_big
  ), adv AS (
    SELECT CASE
      WHEN sizes_differ AND str_small IS NOT NULL AND str_big IS NOT NULL
      THEN GREATEST(0.0, LEAST(1.0, (str_small - str_big) / GREATEST(str_big, 0.01)))
      ELSE 0.0 END AS advantage
    FROM t
  ), w AS (
    SELECT advantage,
           CASE WHEN advantage > 0 THEN 0.5 ELSE 2.0 END AS str_weight
    FROM adv
  )
  SELECT (
      3.0 * LEAST(1.0, ABS(COALESCE(p_div_a, 1) - COALESCE(p_div_b, 1)) / 3.0)
    + 1.2 * (ABS(COALESCE(p_roster_a, 0) - COALESCE(p_roster_b, 0))::numeric
             / GREATEST(COALESCE(p_roster_a, 0), COALESCE(p_roster_b, 0), 1))
          * (1.0 - 0.75 * advantage)
    + 1.5 * LEAST(1.0, ABS(COALESCE(p_cad_a, 0) - COALESCE(p_cad_b, 0)) / 4.0)
    + CASE WHEN p_str_a IS NOT NULL AND p_str_b IS NOT NULL
           THEN str_weight * (ABS(p_str_a - p_str_b) / GREATEST(p_str_a, p_str_b, 1))
           ELSE 0.0 END
    + CASE WHEN p_age_a IS NOT NULL AND p_age_b IS NOT NULL
           THEN 1.0 * LEAST(1.0, ABS(p_age_a - p_age_b) / 20.0)
           ELSE 0.0 END
  ) / (
      5.7
    + CASE WHEN p_str_a IS NOT NULL AND p_str_b IS NOT NULL THEN str_weight ELSE 0.0 END
    + CASE WHEN p_age_a IS NOT NULL AND p_age_b IS NOT NULL THEN 1.0 ELSE 0.0 END
  )
  FROM w;
$$;


ALTER FUNCTION "public"."crew_match_gap"("p_roster_a" integer, "p_age_a" numeric, "p_str_a" numeric, "p_cad_a" numeric, "p_div_a" integer, "p_roster_b" integer, "p_age_b" numeric, "p_str_b" numeric, "p_cad_b" numeric, "p_div_b" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."crew_match_strength"("p_crew_id" "uuid") RETURNS numeric
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_user   uuid;
  v_email  text;
  v_weight numeric;
  v_best   numeric;
  v_sum    numeric := 0;
  v_n      integer := 0;
BEGIN
  FOR v_user IN
    SELECT user_id FROM public.crew_members WHERE crew_id = p_crew_id LIMIT 40
  LOOP
    SELECT lower(email), weight_lbs INTO v_email, v_weight
      FROM public.user_profiles WHERE id = v_user;

    IF v_weight IS NOT NULL AND v_weight > 0 THEN
      SELECT MAX((public._best_1rm_from_exercises(exercises)->>'e1rm')::numeric)
        INTO v_best
        FROM public.workout_logs
       WHERE (user_id = v_user OR (v_email IS NOT NULL AND lower(created_by) = v_email))
         AND created_at > now() - INTERVAL '90 days'
         AND NOT COALESCE(implausible, FALSE);

      IF v_best IS NOT NULL THEN
        v_sum := v_sum + (v_best / v_weight);
        v_n   := v_n + 1;
      END IF;
    END IF;
  END LOOP;

  IF v_n = 0 THEN RETURN NULL; END IF;
  RETURN v_sum / v_n;
END;
$$;


ALTER FUNCTION "public"."crew_match_strength"("p_crew_id" "uuid") OWNER TO "postgres";


