CREATE OR REPLACE FUNCTION "public"."crew_members_guard_rank"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_leaders      integer;
  v_actor_leader integer;
BEGIN
  IF current_user IN ('postgres', 'service_role') THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' THEN
    NEW.role     := 'member';
    NEW.is_admin := FALSE;
    RETURN NEW;
  END IF;

  IF NOT (COALESCE(NEW.role, '') = COALESCE(OLD.role, ''))
     OR NOT (COALESCE(NEW.is_admin, FALSE) = COALESCE(OLD.is_admin, FALSE)) THEN

    SELECT COUNT(*) INTO v_actor_leader
      FROM public.crew_members
     WHERE crew_id = OLD.crew_id
       AND user_id = auth.uid()
       AND is_admin = TRUE;

    IF v_actor_leader = 0 THEN
      RAISE EXCEPTION 'only a crew leader can change ranks' USING ERRCODE = '42501';
    END IF;

    IF OLD.role = 'leader' AND NOT (NEW.role = 'leader') THEN
      SELECT COUNT(*) INTO v_leaders
        FROM public.crew_members
       WHERE crew_id = OLD.crew_id
         AND role = 'leader'
         AND NOT (user_id = OLD.user_id);

      IF v_leaders = 0 THEN
        RAISE EXCEPTION 'a crew must keep at least one leader' USING ERRCODE = '23514';
      END IF;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."crew_members_guard_rank"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."crew_members_one_crew"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_have integer;
BEGIN
  SELECT COUNT(*) INTO v_have
    FROM public.crew_members
   WHERE user_id = NEW.user_id
     AND NOT (crew_id = NEW.crew_id);

  IF NOT (v_have = 0) THEN
    RAISE EXCEPTION 'already_in_crew' USING ERRCODE = '23505';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."crew_members_one_crew"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."crew_members_sync_role"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    NEW.role := COALESCE(NEW.role,
                         CASE WHEN NEW.is_admin THEN 'leader' ELSE 'member' END);
    NEW.is_admin := (NEW.role = 'leader');
    RETURN NEW;
  END IF;

  IF NOT (COALESCE(NEW.role, '') = COALESCE(OLD.role, '')) THEN
    NEW.is_admin := (NEW.role = 'leader');
  ELSIF NOT (COALESCE(NEW.is_admin, FALSE) = COALESCE(OLD.is_admin, FALSE)) THEN
    NEW.role := CASE WHEN NEW.is_admin THEN 'leader' ELSE 'member' END;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."crew_members_sync_role"() OWNER TO "postgres";


