CREATE OR REPLACE FUNCTION "public"."current_crew_season"() RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_id   uuid;
  v_next integer;
BEGIN
  SELECT id INTO v_id
    FROM public.crew_seasons
   WHERE status = 'active'
   ORDER BY season_number DESC
   LIMIT 1;

  IF v_id IS NOT NULL THEN
    RETURN v_id;
  END IF;

  SELECT COALESCE(MAX(season_number), 0) + 1 INTO v_next FROM public.crew_seasons;

  INSERT INTO public.crew_seasons (season_number, starts_at, ends_at, status)
  VALUES (v_next, now(), now() + INTERVAL '28 days', 'active')
  ON CONFLICT DO NOTHING
  RETURNING id INTO v_id;

  IF v_id IS NULL THEN
    SELECT id INTO v_id
      FROM public.crew_seasons
     WHERE status = 'active'
     ORDER BY season_number DESC
     LIMIT 1;
  END IF;

  RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."current_crew_season"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."current_league_season"() RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_id      UUID;
  v_pending UUID;
  v_next    INTEGER;
BEGIN
  SELECT id INTO v_id
    FROM public.league_seasons
   WHERE status = 'active'
     AND starts_at = LEAST(starts_at, now())
   ORDER BY season_number DESC
   LIMIT 1;

  IF v_id IS NOT NULL THEN
    RETURN v_id;
  END IF;

  SELECT id INTO v_pending
    FROM public.league_seasons
   WHERE status = 'active'
     AND starts_at = GREATEST(starts_at, now())
     AND NOT (starts_at = now())
   ORDER BY season_number
   LIMIT 1;

  IF v_pending IS NOT NULL THEN
    RETURN NULL;
  END IF;

  SELECT COALESCE(MAX(season_number), 0) + 1 INTO v_next FROM public.league_seasons;

  INSERT INTO public.league_seasons (season_number, name, starts_at, ends_at, status)
  VALUES (v_next, public.league_season_name(v_next), now(), now() + INTERVAL '28 days', 'active')
  ON CONFLICT DO NOTHING
  RETURNING id INTO v_id;

  IF v_id IS NULL THEN
    SELECT id INTO v_id
      FROM public.league_seasons
     WHERE status = 'active'
       AND starts_at = LEAST(starts_at, now())
     ORDER BY season_number DESC
     LIMIT 1;
  END IF;

  RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."current_league_season"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."current_user_email"() RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid   UUID := auth.uid();
  v_email TEXT := lower(coalesce(auth.email(), ''));
BEGIN
  IF NOT (v_email = '') THEN
    RETURN v_email;
  END IF;
  IF v_uid IS NULL THEN
    RETURN '';
  END IF;
  SELECT lower(coalesce(email, '')) INTO v_email
    FROM public.user_profiles
   WHERE id = v_uid;
  RETURN coalesce(v_email, '');
END;
$$;


ALTER FUNCTION "public"."current_user_email"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."decide_crew_join_request"("p_crew_id" "uuid", "p_user_id" "uuid", "p_approve" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_cap INTEGER; v_count INTEGER; v_elsewhere INTEGER; v_state TEXT; v_name TEXT;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501'; END IF;
  IF p_crew_id IS NULL OR p_user_id IS NULL THEN
    RAISE EXCEPTION 'crew_id and user_id required' USING ERRCODE = '22023';
  END IF;

  IF NOT public.crew_can_review(p_crew_id, v_uid) THEN
    RAISE EXCEPTION 'only a crew moderator or leader can decide join requests'
      USING ERRCODE = '42501';
  END IF;

  SELECT status INTO v_state
    FROM public.crew_join_requests WHERE crew_id = p_crew_id AND user_id = p_user_id;

  IF v_state IS NULL THEN RAISE EXCEPTION 'no such request' USING ERRCODE = '22023'; END IF;
  IF NOT (v_state = 'pending') THEN
    RETURN jsonb_build_object('ok', TRUE, 'status', v_state, 'changed', FALSE);
  END IF;

  SELECT name INTO v_name FROM public.crews WHERE id = p_crew_id;

  IF p_approve IS NOT TRUE THEN
    UPDATE public.crew_join_requests
       SET status = 'rejected', decided_by = v_uid, decided_at = now()
     WHERE crew_id = p_crew_id AND user_id = p_user_id;

    INSERT INTO public.notifications (user_id, user_email, type, title, body, icon, link_url, metadata)
    VALUES (p_user_id,
            (SELECT email FROM public.user_profiles WHERE id = p_user_id),
            'crew_join_request',
            'Your request to join ' || COALESCE(v_name, 'a crew') || ' was declined',
            'You can apply again, or find another crew.', '📋', '/hub',
            jsonb_build_object('crew_id', p_crew_id, 'decision', 'rejected'));

    RETURN jsonb_build_object('ok', TRUE, 'status', 'rejected', 'changed', TRUE);
  END IF;

  SELECT COUNT(*) INTO v_elsewhere
    FROM public.crew_members WHERE user_id = p_user_id AND NOT (crew_id = p_crew_id);
  IF NOT (v_elsewhere = 0) THEN
    RETURN jsonb_build_object('ok', FALSE, 'reason', 'already_in_crew');
  END IF;

  SELECT COALESCE(max_capacity, 16) INTO v_cap FROM public.crews WHERE id = p_crew_id FOR UPDATE;
  SELECT COUNT(*) INTO v_count FROM public.crew_members WHERE crew_id = p_crew_id;
  IF v_count = GREATEST(v_count, v_cap) THEN
    RAISE EXCEPTION 'crew_full' USING ERRCODE = '23514';
  END IF;

  INSERT INTO public.crew_members (crew_id, user_id, is_admin, role)
  VALUES (p_crew_id, p_user_id, FALSE, 'member') ON CONFLICT DO NOTHING;

  UPDATE public.crew_join_requests
     SET status = 'approved', decided_by = v_uid, decided_at = now()
   WHERE crew_id = p_crew_id AND user_id = p_user_id;

  INSERT INTO public.notifications (user_id, user_email, type, title, body, icon, link_url, metadata)
  VALUES (p_user_id,
          (SELECT email FROM public.user_profiles WHERE id = p_user_id),
          'crew_join_request',
          'You''re in — welcome to ' || COALESCE(v_name, 'the crew'),
          'Your request was accepted. Open the crew to meet the roster.',
          '🎉', '/hub',
          jsonb_build_object('crew_id', p_crew_id, 'decision', 'approved'));

  RETURN jsonb_build_object('ok', TRUE, 'status', 'approved', 'changed', TRUE);
END;
$$;


ALTER FUNCTION "public"."decide_crew_join_request"("p_crew_id" "uuid", "p_user_id" "uuid", "p_approve" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_my_listing"("p_listing_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid       UUID := auth.uid();
  v_seller    UUID;
  v_status    TEXT;
  v_inv       UUID;
  v_offer     UUID;
  v_offer_inv UUID;
  v_offers    INTEGER := 0;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;
  IF p_listing_id IS NULL THEN
    RAISE EXCEPTION 'listing_id required' USING ERRCODE = '22023';
  END IF;

  SELECT seller_user_id, status, inventory_id
    INTO v_seller, v_status, v_inv
    FROM public.marketplace_listings
   WHERE id = p_listing_id
     FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('deleted', false, 'already_gone', true,
                              'listing_id', p_listing_id);
  END IF;

  IF v_seller IS DISTINCT FROM v_uid THEN
    RAISE EXCEPTION 'not_your_listing' USING ERRCODE = '42501';
  END IF;

  IF v_status = 'completed' THEN
    RAISE EXCEPTION 'completed_sale_cannot_be_deleted' USING ERRCODE = '42501';
  END IF;

  FOR v_offer, v_offer_inv IN
    SELECT id, from_inventory_id
      FROM public.trade_offers
     WHERE listing_id = p_listing_id
       AND status = 'pending'
       FOR UPDATE
  LOOP
    UPDATE public.trade_offers
       SET status = 'cancelled', responded_at = now()
     WHERE id = v_offer;

    UPDATE public.user_inventory
       SET escrow_offer_id = NULL, is_listed = FALSE
     WHERE id = v_offer_inv AND escrow_offer_id = v_offer;

    v_offers := v_offers + 1;
  END LOOP;

  IF v_inv IS NOT NULL THEN
    UPDATE public.user_inventory
       SET is_listed = FALSE
     WHERE id = v_inv
       AND user_id = v_uid
       AND escrow_offer_id IS NULL;
  END IF;

  DELETE FROM public.marketplace_listings WHERE id = p_listing_id;

  RETURN jsonb_build_object(
    'deleted',          true,
    'listing_id',       p_listing_id,
    'inventory_id',     v_inv,
    'offers_cancelled', v_offers);
END;
$$;


ALTER FUNCTION "public"."delete_my_listing"("p_listing_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_my_message"("p_message_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;
  UPDATE public.hub_messages
     SET deleted_at = now()
   WHERE id = p_message_id
     AND user_id = v_uid;
END;
$$;


ALTER FUNCTION "public"."delete_my_message"("p_message_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_reported_content"("p_report_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  r_type TEXT;
  r_id   UUID;
BEGIN
  IF NOT public.is_app_admin(auth.uid()) THEN
    RAISE EXCEPTION 'admin_only' USING ERRCODE = '42501';
  END IF;
  SELECT reported_type, reported_id INTO r_type, r_id
    FROM public.hub_reports
   WHERE id = p_report_id;
  IF r_type IS NULL THEN
    RAISE EXCEPTION 'report_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF r_type = 'post' THEN
    DELETE FROM public.hub_posts WHERE id = r_id;
  ELSIF r_type = 'comment' THEN
    DELETE FROM public.hub_comments WHERE id = r_id;
  END IF;
  UPDATE public.hub_reports SET status = 'actioned' WHERE id = p_report_id;
END;
$$;


ALTER FUNCTION "public"."delete_reported_content"("p_report_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."dispatch_memory_reengagement"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_today      DATE := (now() AT TIME ZONE 'UTC')::date;
  v_week_start DATE := date_trunc('week', now() AT TIME ZONE 'UTC')::date;
  v_user       RECORD;
  v_memory     RECORD;
  v_text       JSONB;
  v_count      INTEGER := 0;
  v_top_lift   TEXT;
BEGIN
  FOR v_user IN
    SELECT p.id, p.email, p.preferred_language
      FROM public.user_profiles p
     WHERE p.email IS NOT NULL
       AND p.last_login_date IS NOT NULL
       AND p.last_login_date <= v_today - INTERVAL '7 days'
       AND p.last_login_date >= v_today - INTERVAL '30 days'
       AND (p.notification_prefs IS NULL
            OR (p.notification_prefs ->> 'engagement') IS NULL
            OR (p.notification_prefs ->> 'engagement') <> 'false')
       AND NOT EXISTS (
         SELECT 1 FROM public.memory_reengagement_log mrl
          WHERE mrl.user_id = p.id AND mrl.week_start = v_week_start
       )
  LOOP
    SELECT wl.date, wl.exercises INTO v_memory
      FROM public.workout_logs wl
     WHERE wl.user_id = v_user.id
       AND wl.date IS NOT NULL
       AND EXTRACT(MONTH FROM wl.date::date) = EXTRACT(MONTH FROM v_today)
       AND EXTRACT(DAY   FROM wl.date::date) = EXTRACT(DAY   FROM v_today)
       AND wl.date::date < v_today
     ORDER BY wl.date DESC LIMIT 1;
    IF v_memory IS NULL THEN CONTINUE; END IF;

    BEGIN
      INSERT INTO public.memory_reengagement_log (user_id, week_start, memory_date)
      VALUES (v_user.id, v_week_start, v_memory.date::date);
    EXCEPTION WHEN unique_violation THEN CONTINUE; END;

    v_top_lift := NULL;
    BEGIN
      SELECT (ex_obj->>'name') || ': ' || round((s->>'weight')::numeric) || ' × ' || (s->>'reps')::text
        INTO v_top_lift
        FROM jsonb_array_elements(COALESCE(v_memory.exercises, '[]'::jsonb)) ex_obj
        CROSS JOIN LATERAL jsonb_array_elements(COALESCE(ex_obj->'sets', '[]'::jsonb)) s
       WHERE (s->>'weight')::numeric > 0
       ORDER BY (s->>'weight')::numeric DESC LIMIT 1;
    EXCEPTION WHEN OTHERS THEN v_top_lift := NULL; END;

    v_text := public.memory_reengagement_text(
      COALESCE(v_user.preferred_language, 'en'),
      EXTRACT(YEAR FROM v_today)::int - EXTRACT(YEAR FROM v_memory.date::date)::int,
      v_top_lift
    );

    INSERT INTO public.notifications
      (user_id, user_email, type, title, body, icon, link_url, metadata)
    VALUES
      (v_user.id, v_user.email, 'memory_reengagement',
       v_text ->> 'title', v_text ->> 'body', '⏪', '/dashboard',
       jsonb_build_object('memory_date', v_memory.date::date, 'top_lift', v_top_lift));
    v_count := v_count + 1;
  END LOOP;
  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."dispatch_memory_reengagement"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."distribute_league_rewards"("p_league_id" "uuid") RETURNS TABLE("user_id" "uuid", "user_email" "text", "outcome" "text", "from_tier" "text", "new_tier" "text", "coins_awarded" integer, "capsule" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_league         RECORD;
  v_already        INT;
  v_total          INT;
  v_promote        INT;
  v_demote         INT;
  v_reward_coins   INT;
  v_reward_capsule TEXT;
  v_member         RECORD;
  v_rank           INT;
  v_outcome        TEXT;
  v_new_tier       TEXT;
  v_coins          INT;
  v_capsule        TEXT;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;
  IF p_league_id IS NULL THEN
    RAISE EXCEPTION 'league_id required' USING ERRCODE = '22023';
  END IF;

  SELECT l.id, l.tier, l.week_end, l.is_resolved
    INTO v_league
    FROM public.leagues l
   WHERE l.id = p_league_id;
  IF v_league IS NULL THEN
    RAISE EXCEPTION 'league not found' USING ERRCODE = '22023';
  END IF;

  -- Idempotency guard
  SELECT COUNT(*) INTO v_already
    FROM public.league_members
   WHERE league_id = p_league_id AND rank IS NOT NULL;
  IF v_already > 0 THEN
    RETURN;
  END IF;

  -- Tier config — mirrors src/lib/leagueTiers.js
  SELECT t.promote, t.demote, t.reward_coins, t.reward_capsule
    INTO v_promote, v_demote, v_reward_coins, v_reward_capsule
    FROM (VALUES
      ('bronze',   10, 0,   50, NULL::TEXT),
      ('silver',   10, 5,  100, NULL),
      ('gold',      7, 5,  200, 'standard'),
      ('platinum',  5, 5,  350, 'premium'),
      ('diamond',   3, 5,  600, 'premium'),
      ('legend',    0, 5, 1000, 'elite')
    ) AS t(tier_id, promote, demote, reward_coins, reward_capsule)
   WHERE t.tier_id = v_league.tier;
  IF v_promote IS NULL THEN
    RAISE EXCEPTION 'unknown tier: %', v_league.tier USING ERRCODE = '22023';
  END IF;

  SELECT COUNT(*) INTO v_total
    FROM public.league_members
   WHERE league_id = p_league_id;

  v_rank := 0;
  FOR v_member IN
    SELECT lm.id, lm.user_id, lm.user_email
      FROM public.league_members lm
     WHERE lm.league_id = p_league_id
     ORDER BY lm.weekly_xp DESC NULLS LAST, lm.joined_at ASC
  LOOP
    v_rank := v_rank + 1;

    IF v_promote > 0 AND v_rank <= v_promote THEN
      v_outcome  := 'promote';
      v_new_tier := CASE v_league.tier
        WHEN 'bronze'   THEN 'silver'
        WHEN 'silver'   THEN 'gold'
        WHEN 'gold'     THEN 'platinum'
        WHEN 'platinum' THEN 'diamond'
        WHEN 'diamond'  THEN 'legend'
        ELSE v_league.tier
      END;
      v_coins   := v_reward_coins;
      v_capsule := v_reward_capsule;
    ELSIF v_demote > 0 AND v_rank > (v_total - v_demote) THEN
      v_outcome  := 'demote';
      v_new_tier := CASE v_league.tier
        WHEN 'silver'   THEN 'bronze'
        WHEN 'gold'     THEN 'silver'
        WHEN 'platinum' THEN 'gold'
        WHEN 'diamond'  THEN 'platinum'
        WHEN 'legend'   THEN 'diamond'
        ELSE v_league.tier
      END;
      v_coins   := 0;
      v_capsule := NULL;
    ELSIF v_league.tier = 'legend' AND v_rank <= 3 THEN
      v_outcome  := 'stay';
      v_new_tier := 'legend';
      v_coins    := v_reward_coins;
      v_capsule  := v_reward_capsule;
    ELSE
      v_outcome  := 'stay';
      v_new_tier := v_league.tier;
      v_coins    := 0;
      v_capsule  := NULL;
    END IF;

    UPDATE public.league_members SET rank = v_rank WHERE id = v_member.id;

    IF v_outcome IN ('promote', 'demote') THEN
      UPDATE public.user_profiles
         SET league_tier = v_new_tier
       WHERE id = v_member.user_id;
    END IF;

    IF v_coins > 0 THEN
      UPDATE public.user_profiles
         SET flex_coins = COALESCE(flex_coins, 0) + v_coins
       WHERE id = v_member.user_id;
    END IF;

    IF v_capsule IS NOT NULL THEN
      INSERT INTO public.user_capsules (user_id, user_email, capsule_type)
      VALUES (v_member.user_id, v_member.user_email, v_capsule);
    END IF;

    user_id       := v_member.user_id;
    user_email    := v_member.user_email;
    outcome       := v_outcome;
    from_tier     := v_league.tier;
    new_tier      := v_new_tier;
    coins_awarded := COALESCE(v_coins, 0);
    capsule       := v_capsule;
    RETURN NEXT;
  END LOOP;

  RETURN;
END;
$$;


ALTER FUNCTION "public"."distribute_league_rewards"("p_league_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."dm_accept_conversations_on_follow"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_follower TEXT := lower(coalesce(NEW.follower_email, ''));
  v_followee TEXT := lower(coalesce(NEW.followee_email, ''));
BEGIN
  IF v_follower = '' OR v_followee = '' OR v_follower = v_followee THEN
    RETURN NEW;
  END IF;

  DELETE FROM public.dm_request_blocks
   WHERE blocker_email = v_follower
     AND blocked_email = v_followee;

  UPDATE public.hub_conversations
     SET accepted_emails = array_append(
           coalesce(accepted_emails, ARRAY[]::text[]), v_follower),
         updated_at = now()
   WHERE coalesce(is_group, FALSE) = FALSE
     AND coalesce(array_length(participant_emails, 1), 0) = 2
     AND v_follower = ANY (
       ARRAY(
         SELECT lower(participant_email)
           FROM unnest(participant_emails) AS participant_email
       )
     )
     AND v_followee = ANY (
       ARRAY(
         SELECT lower(participant_email)
           FROM unnest(participant_emails) AS participant_email
       )
     )
     AND NOT (
       v_follower = ANY (
         ARRAY(
           SELECT lower(accepted_email)
             FROM unnest(coalesce(accepted_emails, ARRAY[]::text[]))
               AS accepted_email
         )
       )
     );

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."dm_accept_conversations_on_follow"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."dm_pending_send_allowed"("p_conv_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_email    TEXT := public.current_user_email();
  v_parts    TEXT[];
  v_accepted TEXT[];
  v_group    BOOLEAN;
  v_pending  INTEGER;
  v_sent     INTEGER;
BEGIN
  IF p_conv_id IS NULL OR v_email = '' THEN
    RETURN TRUE;
  END IF;

  SELECT participant_emails, accepted_emails, coalesce(is_group, FALSE)
    INTO v_parts, v_accepted, v_group
    FROM public.hub_conversations
   WHERE id = p_conv_id;

  IF v_parts IS NULL THEN
    RETURN TRUE;
  END IF;

  IF v_group OR NOT (coalesce(array_length(v_parts, 1), 0) = 2) THEN
    RETURN TRUE;
  END IF;

  SELECT count(*)
    INTO v_pending
    FROM unnest(v_parts) AS participant_email
   WHERE NOT (lower(participant_email) = v_email)
     AND NOT (
       lower(participant_email) = ANY (
         SELECT lower(accepted_email)
           FROM unnest(coalesce(v_accepted, ARRAY[]::text[])) AS accepted_email
       )
     );

  IF v_pending = 0 THEN
    RETURN TRUE;
  END IF;

  SELECT count(*)
    INTO v_sent
    FROM public.hub_messages
   WHERE conversation_id = p_conv_id
     AND lower(coalesce(sender_email, created_by, '')) = v_email;

  RETURN (v_sent = 0);
END;
$$;


ALTER FUNCTION "public"."dm_pending_send_allowed"("p_conv_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."dm_received_text"("p_language" "text", "p_sender_name" "text") RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
  SELECT jsonb_build_object(
    'title',
      CASE COALESCE(p_language, 'en')
        WHEN 'es' THEN 'Nuevo mensaje'      WHEN 'fr' THEN 'Nouveau message'
        WHEN 'de' THEN 'Neue Nachricht'     WHEN 'pt' THEN 'Nova mensagem'
        WHEN 'it' THEN 'Nuovo messaggio'    WHEN 'ja' THEN '新しいメッセージ'
        WHEN 'ko' THEN '새 메시지'           WHEN 'zh' THEN '新消息'
        WHEN 'ar' THEN 'رسالة جديدة'         WHEN 'hi' THEN 'नया संदेश'
        WHEN 'ru' THEN 'Новое сообщение'    WHEN 'tr' THEN 'Yeni mesaj'
        WHEN 'pl' THEN 'Nowa wiadomość'     WHEN 'nl' THEN 'Nieuw bericht'
        ELSE 'New message'
      END,
    'body',
      COALESCE(NULLIF(p_sender_name, ''), 'Someone') ||
      CASE COALESCE(p_language, 'en')
        WHEN 'es' THEN ' te envió un mensaje'        WHEN 'fr' THEN ' vous a envoyé un message'
        WHEN 'de' THEN ' hat dir eine Nachricht gesendet' WHEN 'pt' THEN ' enviou uma mensagem'
        WHEN 'it' THEN ' ti ha inviato un messaggio' WHEN 'ja' THEN ' さんからメッセージが届きました'
        WHEN 'ko' THEN ' 님이 메시지를 보냈습니다'    WHEN 'zh' THEN ' 给你发了一条消息'
        WHEN 'ar' THEN ' أرسل لك رسالة'              WHEN 'hi' THEN ' ने आपको एक संदेश भेजा'
        WHEN 'ru' THEN ' отправил вам сообщение'     WHEN 'tr' THEN ' size bir mesaj gönderdi'
        WHEN 'pl' THEN ' wysłał Ci wiadomość'        WHEN 'nl' THEN ' heeft je een bericht gestuurd'
        ELSE ' sent you a message'
      END
  );
$$;


