CREATE OR REPLACE FUNCTION "public"."enforce_bio_profanity"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF OLD.bio IS NOT DISTINCT FROM NEW.bio THEN RETURN NEW; END IF;
  IF NEW.bio IS NULL OR NEW.bio = '' THEN RETURN NEW; END IF;
  IF NOT public.is_bio_clean(NEW.bio) THEN
    RAISE EXCEPTION 'bio_profanity'
      USING ERRCODE = '23514',
            HINT    = 'Bio contains prohibited content. Edit it and try again.';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_bio_profanity"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_block_on_dm_send"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
      DECLARE
        v_sender_uid    UUID := auth.uid();
        v_sender_email  TEXT;
        v_other_emails  TEXT[];
        v_recipient_email TEXT;
        v_recipient_uid   UUID;
      BEGIN
        IF v_sender_uid IS NULL THEN
          RETURN NEW;
        END IF;
        SELECT email INTO v_sender_email FROM public.user_profiles WHERE id = v_sender_uid;
        IF v_sender_email IS NULL THEN
          RETURN NEW;
        END IF;

        SELECT array_agg(email) INTO v_other_emails
          FROM (
            SELECT unnest(participant_emails) AS email
              FROM public.hub_conversations
             WHERE id = NEW.conversation_id
          ) AS p
         WHERE email IS DISTINCT FROM v_sender_email;

        IF v_other_emails IS NULL THEN
          RETURN NEW;
        END IF;

        FOREACH v_recipient_email IN ARRAY v_other_emails LOOP
          SELECT id INTO v_recipient_uid FROM public.user_profiles WHERE email = v_recipient_email;
          IF public.is_blocked(v_sender_uid, v_recipient_email) THEN
            RAISE EXCEPTION 'dm_blocked'
              USING ERRCODE = '42501',
                    HINT    = 'You cannot send messages to this user.';
          END IF;
          IF v_recipient_uid IS NOT NULL AND public.is_blocked(v_recipient_uid, v_sender_email) THEN
            RAISE EXCEPTION 'dm_blocked'
              USING ERRCODE = '42501',
                    HINT    = 'You cannot send messages to this user.';
          END IF;
        END LOOP;
        RETURN NEW;
      END;
      $$;


ALTER FUNCTION "public"."enforce_block_on_dm_send"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_comment_profanity"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_text TEXT;
BEGIN
  v_text := COALESCE(NULLIF(NEW.body, ''), NEW.content);
  IF v_text IS NULL OR v_text = '' THEN RETURN NEW; END IF;

  IF TG_OP = 'UPDATE'
     AND OLD.body    IS NOT DISTINCT FROM NEW.body
     AND OLD.content IS NOT DISTINCT FROM NEW.content THEN
    RETURN NEW;
  END IF;

  IF NOT public.is_text_clean(v_text, FALSE) THEN
    RAISE EXCEPTION 'comment_profanity'
      USING ERRCODE = '23514',
            HINT    = 'Comment contains prohibited content. Edit it and try again.';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_comment_profanity"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_crew_message_profanity"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
      BEGIN
        IF NEW.content IS NULL OR NEW.content = '' THEN RETURN NEW; END IF;
        IF TG_OP = 'UPDATE' AND OLD.content IS NOT DISTINCT FROM NEW.content THEN
          RETURN NEW;
        END IF;
        IF NOT public.is_text_clean(NEW.content, FALSE) THEN
          RAISE EXCEPTION 'crew_message_profanity'
            USING ERRCODE = '23514',
                  HINT    = 'Crew message contains prohibited content. Edit it and try again.';
        END IF;
        RETURN NEW;
      END;
      $$;


ALTER FUNCTION "public"."enforce_crew_message_profanity"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_crew_name_profanity"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF NOT (TG_OP = 'UPDATE' AND OLD.name IS NOT DISTINCT FROM NEW.name) THEN
    IF NEW.name IS NOT NULL AND NEW.name <> '' THEN
      IF NOT public.is_text_clean(NEW.name, TRUE) THEN
        RAISE EXCEPTION 'crew_name_profanity'
          USING ERRCODE = '23514',
                HINT    = 'Crew name contains prohibited content. Pick another name.';
      END IF;
    END IF;
  END IF;

  IF NOT (TG_OP = 'UPDATE' AND OLD.description IS NOT DISTINCT FROM NEW.description) THEN
    IF NEW.description IS NOT NULL AND NEW.description <> '' THEN
      IF NOT public.is_text_clean(NEW.description, TRUE) THEN
        RAISE EXCEPTION 'crew_description_profanity'
          USING ERRCODE = '23514',
                HINT    = 'Crew description contains prohibited content. Reword it.';
      END IF;
    END IF;
  END IF;

  IF NOT (TG_OP = 'UPDATE' AND OLD.tag IS NOT DISTINCT FROM NEW.tag) THEN
    IF NEW.tag IS NOT NULL AND NEW.tag <> '' THEN
      IF NOT public.is_text_clean(NEW.tag, TRUE) THEN
        RAISE EXCEPTION 'crew_tag_profanity'
          USING ERRCODE = '23514',
                HINT    = 'Crew tag contains prohibited content. Pick another.';
      END IF;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


