CREATE OR REPLACE FUNCTION "public"."ensure_crew_season_entry"("p_crew_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_season uuid;
  v_div    integer;
BEGIN
  IF p_crew_id IS NULL THEN
    RETURN NULL;
  END IF;

  v_season := public.current_crew_season();
  IF v_season IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT COALESCE(MAX(division), 1) INTO v_div
    FROM public.crew_season_stats
   WHERE season_id = v_season;

  INSERT INTO public.crew_season_stats (season_id, crew_id, division)
  VALUES (v_season, p_crew_id, COALESCE(v_div, 1))
  ON CONFLICT (season_id, crew_id) DO NOTHING;

  RETURN v_season;
END;
$$;


ALTER FUNCTION "public"."ensure_crew_season_entry"("p_crew_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ensure_my_league"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid        UUID := auth.uid();
  v_email      TEXT := public.current_user_email();
  v_tier       TEXT;
  v_week_start DATE;
  v_week_end   DATE;
  v_league_id  UUID;
  v_member_id  UUID;
  v_league     JSONB;
  v_member     JSONB;
BEGIN
  IF v_uid IS NULL OR v_email = '' THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;

  SELECT coalesce(league_tier, 'bronze') INTO v_tier
    FROM public.user_profiles
   WHERE id = v_uid;

  v_tier := coalesce(v_tier, 'bronze');
  IF NOT (v_tier IN ('bronze', 'silver', 'gold', 'platinum', 'diamond', 'legend')) THEN
    v_tier := 'bronze';
  END IF;

  v_week_start := (date_trunc('week', CURRENT_DATE))::DATE;
  v_week_end   := v_week_start + 6;

  SELECT id, league_id INTO v_member_id, v_league_id
    FROM public.league_members
   WHERE user_id = v_uid
     AND league_id IN (
       SELECT id FROM public.leagues WHERE week_start = v_week_start
     )
   ORDER BY joined_at DESC
   LIMIT 1;

  IF v_member_id IS NULL THEN
    SELECT id INTO v_league_id
      FROM public.leagues
     WHERE tier = v_tier
       AND week_start = v_week_start
       AND is_resolved = FALSE
       AND member_count = least(member_count, 29)
     ORDER BY member_count DESC, created_at ASC
     LIMIT 1;

    IF v_league_id IS NULL THEN
      INSERT INTO public.leagues (tier, week_start, week_end, member_count, is_resolved)
      VALUES (v_tier, v_week_start, v_week_end, 0, FALSE)
      RETURNING id INTO v_league_id;
    END IF;

    INSERT INTO public.league_members (league_id, user_id, user_email, weekly_xp)
    VALUES (v_league_id, v_uid, v_email, 0)
    ON CONFLICT DO NOTHING
    RETURNING id INTO v_member_id;

    IF v_member_id IS NULL THEN
      SELECT id INTO v_member_id
        FROM public.league_members
       WHERE league_id = v_league_id
         AND user_id = v_uid
       LIMIT 1;
    END IF;
  END IF;

  SELECT to_jsonb(leagues) INTO v_league
    FROM public.leagues
   WHERE id = v_league_id;

  SELECT to_jsonb(league_members) INTO v_member
    FROM public.league_members
   WHERE id = v_member_id;

  RETURN jsonb_build_object('league', v_league, 'member', v_member);
END;
$$;


ALTER FUNCTION "public"."ensure_my_league"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fail_storage_cleanup"("p_ids" "uuid"[], "p_error" "text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_done INTEGER := 0;
BEGIN
  IF p_ids IS NULL OR array_length(p_ids, 1) IS NULL THEN
    RETURN 0;
  END IF;
  UPDATE public.storage_cleanup_queue
     SET attempts   = attempts + 1,
         last_error = left(coalesce(p_error, 'unknown'), 500)
   WHERE id = ANY (p_ids)
     AND processed_at IS NULL;
  GET DIAGNOSTICS v_done = ROW_COUNT;
  RETURN v_done;
END;
$$;


