CREATE OR REPLACE FUNCTION "public"."finalize_capsule_claim"("p_capsule_id" "uuid", "p_item_id" "text", "p_item_name" "text", "p_item_emoji" "text", "p_item_rarity" "text", "p_item_type" "text", "p_variant" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid            UUID := auth.uid();
  v_email          TEXT;
  v_is_opened      BOOLEAN;
  v_rolled_rarity  TEXT;
  v_rolled_variant TEXT;
  v_rolled_cat     TEXT;
  v_finalized      TIMESTAMPTZ;
  v_item           JSONB;
  v_inventory_id   UUID;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501'; END IF;
  IF p_capsule_id IS NULL THEN
    RAISE EXCEPTION 'capsule_id required' USING ERRCODE = '22023';
  END IF;

  SELECT is_opened, rolled_rarity, rolled_variant, rolled_category, finalized_at
    INTO v_is_opened, v_rolled_rarity, v_rolled_variant, v_rolled_cat, v_finalized
    FROM public.user_capsules
   WHERE id = p_capsule_id AND user_id = v_uid
   FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'capsule not found' USING ERRCODE = '22023'; END IF;
  IF v_is_opened IS NOT TRUE THEN
    RAISE EXCEPTION 'capsule not yet opened' USING ERRCODE = '22023';
  END IF;
  IF v_rolled_rarity IS NULL THEN
    RAISE EXCEPTION 'capsule roll missing — call claim_capsule_loot first' USING ERRCODE = '22023';
  END IF;
  IF v_finalized IS NOT NULL THEN
    RAISE EXCEPTION 'capsule already claimed' USING ERRCODE = '22023';
  END IF;

  v_item := public._pick_loot_item(v_rolled_rarity, COALESCE(v_rolled_cat, 'sticker'));

  SELECT email INTO v_email FROM public.user_profiles WHERE id = v_uid;
  IF v_email IS NULL OR v_email = '' THEN
    v_email := 'guest_' || v_uid || '@flexyn.guest';
  END IF;

  INSERT INTO public.user_inventory
    (user_id, user_email, item_id, item_name, item_emoji, item_rarity, item_type, variant, acquired_via)
  VALUES
    (v_uid, v_email, v_item ->> 'item_id', v_item ->> 'item_name', v_item ->> 'item_emoji',
     v_rolled_rarity, COALESCE(v_item ->> 'item_type', v_rolled_cat), v_rolled_variant, 'capsule')
  RETURNING id INTO v_inventory_id;

  UPDATE public.user_capsules SET finalized_at = now() WHERE id = p_capsule_id;

  RETURN jsonb_build_object(
    'ok', true, 'inventory_id', v_inventory_id,
    'item_id', v_item ->> 'item_id', 'item_name', v_item ->> 'item_name',
    'item_emoji', v_item ->> 'item_emoji',
    'item_rarity', v_rolled_rarity, 'item_variant', v_rolled_variant);
END;
$$;


ALTER FUNCTION "public"."finalize_capsule_claim"("p_capsule_id" "uuid", "p_item_id" "text", "p_item_name" "text", "p_item_emoji" "text", "p_item_rarity" "text", "p_item_type" "text", "p_variant" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fire_scheduled_workout_reminders"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_id    UUID;
  v_user  UUID;
  v_email TEXT;
  v_title TEXT;
  v_count INTEGER := 0;
BEGIN
  UPDATE public.scheduled_workouts
     SET status = 'missed'
   WHERE status = 'pending'
     AND public.user_local_now(user_id)
         > (scheduled_date + (scheduled_hour || ' hours')::interval + INTERVAL '12 hours');

  FOR v_id IN
    UPDATE public.scheduled_workouts
       SET status = 'notified', notified_at = now()
     WHERE status = 'pending'
       AND public.user_local_now(user_id)
           >= (scheduled_date + (scheduled_hour || ' hours')::interval)
    RETURNING id
  LOOP
    SELECT user_id, user_email, title INTO v_user, v_email, v_title
      FROM public.scheduled_workouts WHERE id = v_id;

    INSERT INTO public.notifications
      (user_id, user_email, type, title, body, icon, link_url, metadata)
    VALUES
      (v_user, v_email, 'workout_reminder', 'Time to train 💪',
       COALESCE(v_title, 'Your workout') || ' is ready when you are.',
       '🏋️', '/workout?scheduled=' || v_id::text,
       jsonb_build_object('scheduledWorkoutId', v_id));

    v_count := v_count + 1;
  END LOOP;

  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."fire_scheduled_workout_reminders"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."flex_coin_ledger_and_cap"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_delta       INTEGER;
  v_credited    INTEGER;
  v_headroom    INTEGER;
  v_clamped     BOOLEAN := false;
  v_source      TEXT;
  v_daily_cap   CONSTANT INTEGER := 50000;
BEGIN
  IF NEW.flex_coins IS NOT DISTINCT FROM OLD.flex_coins THEN
    RETURN NEW;
  END IF;

  v_delta := COALESCE(NEW.flex_coins, 0) - COALESCE(OLD.flex_coins, 0);

  IF v_delta > 0 THEN
    SELECT COALESCE(SUM(delta), 0) INTO v_credited
      FROM public.flex_coin_ledger
     WHERE user_id = NEW.id
       AND delta > 0
       AND created_at > now() - interval '24 hours';

    v_headroom := GREATEST(0, v_daily_cap - v_credited);
    IF v_delta > v_headroom THEN
      v_clamped := true;
      v_delta   := v_headroom;
      NEW.flex_coins := COALESCE(OLD.flex_coins, 0) + v_delta;
    END IF;

    IF v_delta = 0 THEN
      INSERT INTO public.flex_coin_ledger (user_id, delta, balance_after, actor, source, clamped)
      VALUES (NEW.id, 0, COALESCE(OLD.flex_coins, 0), current_user, NULL, true);
      RETURN NEW;
    END IF;
  END IF;

  v_source := substring(
    current_query()
    from '((?:claim|purchase|complete|grant|distribute|gift|sweep|perform|resolve|create|increment|sync|reset)_[a-z_]+)'
  );

  INSERT INTO public.flex_coin_ledger (user_id, delta, balance_after, actor, source, clamped)
  VALUES (NEW.id, v_delta, COALESCE(NEW.flex_coins, 0), current_user, v_source, v_clamped);

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."flex_coin_ledger_and_cap"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."friend_follow_text"("p_language" "text", "p_name" "text") RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
  SELECT jsonb_build_object(
    'title',
      CASE COALESCE(p_language, 'en')
        WHEN 'es' THEN p_name || ' te sigue'
        WHEN 'fr' THEN p_name || ' vous suit'
        WHEN 'de' THEN p_name || ' folgt dir jetzt'
        WHEN 'pt' THEN p_name || ' te seguiu'
        WHEN 'it' THEN p_name || ' ti segue'
        WHEN 'ja' THEN p_name || 'があなたをフォローしました'
        WHEN 'ko' THEN p_name || '님이 팔로우했어요'
        WHEN 'zh' THEN p_name || ' 关注了你'
        WHEN 'ar' THEN 'بدأ ' || p_name || ' بمتابعتك'
        WHEN 'hi' THEN p_name || ' आपको फ़ॉलो कर रहे हैं'
        WHEN 'ru' THEN p_name || ' подписался(ась) на вас'
        WHEN 'tr' THEN p_name || ' seni takip ediyor'
        WHEN 'pl' THEN p_name || ' obserwuje cię'
        WHEN 'nl' THEN p_name || ' volgt je nu'
        ELSE              p_name || ' followed you'
      END,
    'body',
      CASE COALESCE(p_language, 'en')
        WHEN 'es' THEN 'Toca para ver su perfil.'
        WHEN 'fr' THEN 'Touchez pour voir son profil.'
        WHEN 'de' THEN 'Tippe, um das Profil zu sehen.'
        WHEN 'pt' THEN 'Toque para ver o perfil.'
        WHEN 'it' THEN 'Tocca per vedere il profilo.'
        WHEN 'ja' THEN 'タップしてプロフィールを見る。'
        WHEN 'ko' THEN '탭하여 프로필을 확인하세요.'
        WHEN 'zh' THEN '点击查看其个人资料。'
        WHEN 'ar' THEN 'انقر لرؤية الملف الشخصي.'
        WHEN 'hi' THEN 'प्रोफ़ाइल देखने के लिए टैप करें।'
        WHEN 'ru' THEN 'Нажмите, чтобы посмотреть профиль.'
        WHEN 'tr' THEN 'Profili görüntülemek için dokun.'
        WHEN 'pl' THEN 'Dotknij, aby zobaczyć profil.'
        WHEN 'nl' THEN 'Tik om het profiel te bekijken.'
        ELSE              'Tap to view their profile.'
      END
  );
$$;


