CREATE OR REPLACE FUNCTION "public"."generate_flexyn_code"() RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_alphabet TEXT := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  v_code     TEXT;
  v_n        INT;
  v_i        INT;
BEGIN
  FOR v_i IN 1..50 LOOP
    v_code := '';
    FOR v_n IN 1..8 LOOP
      v_code := v_code || substr(v_alphabet, 1 + floor(random() * length(v_alphabet))::int, 1);
    END LOOP;
    IF NOT EXISTS (SELECT 1 FROM public.gym_businesses WHERE flexyn_code = v_code) THEN
      RETURN v_code;
    END IF;
  END LOOP;
  RAISE EXCEPTION 'could not generate unique flexyn code after 50 tries';
END;
$$;


