CREATE OR REPLACE FUNCTION "public"."generate_weekly_review_for"("p_user_id" "uuid", "p_week_start" "date" DEFAULT NULL::"date") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_user_id        UUID := p_user_id;
  v_week_start     DATE;
  v_week_end       DATE;
  v_week_num       INT;
  v_year           INT;
  v_week_label     TEXT;
  v_sessions       INT := 0;
  v_days_trained   INT := 0;
  v_day_flags      BOOLEAN[];
  v_volume         NUMERIC := 0;
  v_prev_volume    NUMERIC := 0;
  v_change_pct     INT;
  v_baseline       NUMERIC := 0;
  v_load_ratio     NUMERIC;
  v_sets           INT := 0;
  v_reps           INT := 0;
  v_duration       INT := 0;
  v_muscle_sets    JSONB := '{}'::JSONB;
  v_top_name       TEXT;
  v_top_weight     NUMERIC;
  v_top_reps       INT;
  v_top_is_pr      BOOLEAN := FALSE;
  v_all_time_max   NUMERIC := 0;
  v_pr_count       INT := 0;
  v_streak         INT := 0;
  v_cardio_n       INT := 0;
  v_cardio_dist    NUMERIC := 0;
  v_cardio_min     INT := 0;
  v_cardio_kcal    NUMERIC := 0;
  v_steps          INT := 0;
  v_steps_days     INT := 0;
  v_daily_steps    INT[];
  v_prev_steps     INT := 0;
  v_fuel_days      INT := 0;
  v_kcal           NUMERIC := 0;
  v_protein        NUMERIC := 0;
  v_carbs          NUMERIC := 0;
  v_fat            NUMERIC := 0;
  v_prev_kcal      NUMERIC := 0;
  v_prev_protein   NUMERIC := 0;
  v_sleep_nights   INT := 0;
  v_sleep_hours    NUMERIC;
  v_sleep_quality  NUMERIC;
  v_soreness       NUMERIC;
  v_mood_days      INT := 0;
  v_mood_avg       NUMERIC;
  v_weight_start   NUMERIC;
  v_weight_end     NUMERIC;
  v_xp_earned      INT := 0;
  v_total_xp       INT := 0;
  v_level_end      INT := 1;
  v_level_start    INT := 1;
  v_quests_done    INT := 0;
  v_coins          INT := 0;
  v_trophies       TEXT[];
  v_crew_name      TEXT;
  v_crew_msgs      INT := 0;
  v_duels_played   INT := 0;
  v_duels_won      INT := 0;
  v_league_tier    TEXT;
  v_league_rank    INT;
  v_league_xp      INT;
  v_league_days    INT;
  v_gym_days       INT := 0;
  v_goals_active   INT := 0;
  v_goals_done     INT := 0;
  v_insight        TEXT;
  v_data           JSONB;
BEGIN
  IF v_user_id IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;

  v_week_start := COALESCE(p_week_start, date_trunc('week', CURRENT_DATE)::DATE);
  v_week_end   := v_week_start + 6;
  v_week_num   := EXTRACT(week   FROM v_week_start)::INT;
  v_year       := EXTRACT(isoyear FROM v_week_start)::INT;
  v_week_label := 'Week ' || v_week_num || ', ' || v_year;

  SELECT COUNT(*)::INT,
         COUNT(DISTINCT date)::INT,
         COALESCE(SUM(COALESCE(duration_min, 0)), 0)::INT
    INTO v_sessions, v_days_trained, v_duration
    FROM public.workout_logs
   WHERE user_id = v_user_id
     AND date BETWEEN v_week_start AND v_week_end;

  SELECT ARRAY(
    SELECT EXISTS (
      SELECT 1 FROM public.workout_logs
       WHERE user_id = v_user_id
         AND date = v_week_start + offs
    )
    FROM generate_series(0, 6) AS offs
  ) INTO v_day_flags;

  SELECT COALESCE(SUM(set_weight * set_reps), 0),
         COUNT(*)::INT,
         COALESCE(SUM(set_reps), 0)::INT
    INTO v_volume, v_sets, v_reps
    FROM (
      SELECT (s->>'weight')::NUMERIC AS set_weight,
             (s->>'reps')::NUMERIC   AS set_reps
        FROM public.workout_logs,
             jsonb_array_elements(COALESCE(exercises, '[]'::jsonb)) AS ex,
             jsonb_array_elements(COALESCE(ex->'sets', '[]'::jsonb)) AS s
       WHERE user_id = v_user_id
         AND date BETWEEN v_week_start AND v_week_end
         AND (s->>'weight') ~ '^[0-9]+(\.[0-9]+)?$'
         AND (s->>'reps')   ~ '^[0-9]+(\.[0-9]+)?$'
    ) AS derived;

  SELECT COALESCE(SUM(set_weight * set_reps), 0)
    INTO v_prev_volume
    FROM (
      SELECT (s->>'weight')::NUMERIC AS set_weight,
             (s->>'reps')::NUMERIC   AS set_reps
        FROM public.workout_logs,
             jsonb_array_elements(COALESCE(exercises, '[]'::jsonb)) AS ex,
             jsonb_array_elements(COALESCE(ex->'sets', '[]'::jsonb)) AS s
       WHERE user_id = v_user_id
         AND date BETWEEN (v_week_start - 7) AND (v_week_start - 1)
         AND (s->>'weight') ~ '^[0-9]+(\.[0-9]+)?$'
         AND (s->>'reps')   ~ '^[0-9]+(\.[0-9]+)?$'
    ) AS derived_prev;

  SELECT COALESCE(SUM(set_weight * set_reps), 0) / 4.0
    INTO v_baseline
    FROM (
      SELECT (s->>'weight')::NUMERIC AS set_weight,
             (s->>'reps')::NUMERIC   AS set_reps
        FROM public.workout_logs,
             jsonb_array_elements(COALESCE(exercises, '[]'::jsonb)) AS ex,
             jsonb_array_elements(COALESCE(ex->'sets', '[]'::jsonb)) AS s
       WHERE user_id = v_user_id
         AND date BETWEEN (v_week_start - 28) AND (v_week_start - 1)
         AND (s->>'weight') ~ '^[0-9]+(\.[0-9]+)?$'
         AND (s->>'reps')   ~ '^[0-9]+(\.[0-9]+)?$'
    ) AS derived_base;

  IF v_prev_volume > 0 THEN
    v_change_pct := ROUND(((v_volume - v_prev_volume) / v_prev_volume) * 100)::INT;
  END IF;
  IF v_baseline > 0 THEN
    v_load_ratio := ROUND((v_volume / v_baseline)::NUMERIC, 2);
  END IF;

  SELECT COALESCE(jsonb_object_agg(grp, n), '{}'::JSONB)
    INTO v_muscle_sets
    FROM (
      SELECT COALESCE(NULLIF(grp_raw, ''), 'Other') AS grp, COUNT(*)::INT AS n
        FROM public.workout_logs,
             jsonb_array_elements(COALESCE(exercises, '[]'::jsonb)) AS ex,
             jsonb_array_elements(COALESCE(ex->'sets', '[]'::jsonb)) AS s,
             LATERAL jsonb_array_elements_text(
               CASE WHEN jsonb_typeof(ex->'muscle_groups') = 'array'
                      AND jsonb_array_length(ex->'muscle_groups') > 0
                    THEN ex->'muscle_groups'
                    ELSE jsonb_build_array(COALESCE(ex->>'muscle_group', 'Other'))
               END) AS grp_raw
       WHERE user_id = v_user_id
         AND date BETWEEN v_week_start AND v_week_end
       GROUP BY COALESCE(NULLIF(grp_raw, ''), 'Other')
    ) AS per_group;

  SELECT lift_name, lift_weight, lift_reps
    INTO v_top_name, v_top_weight, v_top_reps
    FROM (
      SELECT (ex->>'name')           AS lift_name,
             (s->>'weight')::NUMERIC AS lift_weight,
             (s->>'reps')::INT       AS lift_reps
        FROM public.workout_logs,
             jsonb_array_elements(COALESCE(exercises, '[]'::jsonb)) AS ex,
             jsonb_array_elements(COALESCE(ex->'sets', '[]'::jsonb)) AS s
       WHERE user_id = v_user_id
         AND date BETWEEN v_week_start AND v_week_end
         AND (s->>'weight') ~ '^[0-9]+(\.[0-9]+)?$'
         AND (s->>'reps')   ~ '^[0-9]+$'
         AND (s->>'weight')::NUMERIC > 0
         AND (s->>'reps')::INT > 0
    ) AS lifts
   ORDER BY lift_weight DESC
   LIMIT 1;

  IF v_top_name IS NOT NULL THEN
    SELECT COALESCE(MAX((s->>'weight')::NUMERIC), 0)
      INTO v_all_time_max
      FROM public.workout_logs,
           jsonb_array_elements(COALESCE(exercises, '[]'::jsonb)) AS ex,
           jsonb_array_elements(COALESCE(ex->'sets', '[]'::jsonb)) AS s
     WHERE user_id = v_user_id
       AND date < v_week_start
       AND lower(ex->>'name') = lower(v_top_name)
       AND (s->>'weight') ~ '^[0-9]+(\.[0-9]+)?$';
    v_top_is_pr := (v_top_weight > v_all_time_max);
  END IF;

  SELECT COUNT(*)::INT INTO v_pr_count
    FROM (
      SELECT lower(ex->>'name') AS lift_key,
             MAX((s->>'weight')::NUMERIC) AS best_now
        FROM public.workout_logs,
             jsonb_array_elements(COALESCE(exercises, '[]'::jsonb)) AS ex,
             jsonb_array_elements(COALESCE(ex->'sets', '[]'::jsonb)) AS s
       WHERE user_id = v_user_id
         AND date BETWEEN v_week_start AND v_week_end
         AND (s->>'weight') ~ '^[0-9]+(\.[0-9]+)?$'
         AND (s->>'weight')::NUMERIC > 0
       GROUP BY lower(ex->>'name')
    ) AS this_week
   WHERE best_now > COALESCE((
     SELECT MAX((s2->>'weight')::NUMERIC)
       FROM public.workout_logs,
            jsonb_array_elements(COALESCE(exercises, '[]'::jsonb)) AS ex2,
            jsonb_array_elements(COALESCE(ex2->'sets', '[]'::jsonb)) AS s2
      WHERE user_id = v_user_id
        AND date < v_week_start
        AND lower(ex2->>'name') = lift_key
        AND (s2->>'weight') ~ '^[0-9]+(\.[0-9]+)?$'
   ), 0);

  WITH asc_dates AS (
    SELECT DISTINCT date AS d FROM public.workout_logs
     WHERE user_id = v_user_id AND date <= v_week_end
  ),
  gapped AS (
    SELECT d, d - (ROW_NUMBER() OVER (ORDER BY d ASC))::INTEGER AS grp FROM asc_dates
  ),
  runs AS (
    SELECT grp, MAX(d) AS last_d, COUNT(*)::INT AS len FROM gapped GROUP BY grp
  )
  SELECT COALESCE((
    SELECT len FROM runs
     WHERE last_d = (SELECT MAX(d) FROM asc_dates) LIMIT 1
  ), 0) INTO v_streak;

  SELECT COUNT(*)::INT,
         COALESCE(SUM(COALESCE(distance_meters, 0)), 0),
         COALESCE(SUM(COALESCE(duration_min, ROUND(duration_seconds / 60.0), 0)), 0)::INT,
         COALESCE(SUM(COALESCE(calories, 0)), 0)
    INTO v_cardio_n, v_cardio_dist, v_cardio_min, v_cardio_kcal
    FROM public.cardio_logs
   WHERE user_id = v_user_id
     AND date BETWEEN v_week_start AND v_week_end;

  SELECT COALESCE(SUM(COALESCE(steps, 0)), 0)::INT, COUNT(*)::INT
    INTO v_steps, v_steps_days
    FROM public.step_logs
   WHERE user_id = v_user_id
     AND date BETWEEN v_week_start AND v_week_end;

  SELECT ARRAY(
    SELECT COALESCE((SELECT SUM(COALESCE(steps, 0))::INT FROM public.step_logs
                      WHERE user_id = v_user_id AND date = v_week_start + offs), 0)
    FROM generate_series(0, 6) AS offs
  ) INTO v_daily_steps;

  SELECT COALESCE(SUM(COALESCE(steps, 0)), 0)::INT INTO v_prev_steps
    FROM public.step_logs
   WHERE user_id = v_user_id
     AND date BETWEEN (v_week_start - 7) AND (v_week_start - 1);

  SELECT COUNT(DISTINCT date)::INT INTO v_fuel_days
    FROM public.nutrition_logs
   WHERE user_id = v_user_id AND date BETWEEN v_week_start AND v_week_end;

  IF v_fuel_days > 0 THEN
    SELECT ROUND(COALESCE(SUM(COALESCE(calories, 0)), 0) / v_fuel_days),
           ROUND(COALESCE(SUM(COALESCE(protein,  0)), 0) / v_fuel_days),
           ROUND(COALESCE(SUM(COALESCE(carbs,    0)), 0) / v_fuel_days),
           ROUND(COALESCE(SUM(COALESCE(fat,      0)), 0) / v_fuel_days)
      INTO v_kcal, v_protein, v_carbs, v_fat
      FROM public.nutrition_logs
     WHERE user_id = v_user_id AND date BETWEEN v_week_start AND v_week_end;
  END IF;

  SELECT COALESCE(ROUND(AVG(day_kcal)), 0), COALESCE(ROUND(AVG(day_protein)), 0)
    INTO v_prev_kcal, v_prev_protein
    FROM (
      SELECT date,
             SUM(COALESCE(calories, 0)) AS day_kcal,
             SUM(COALESCE(protein,  0)) AS day_protein
        FROM public.nutrition_logs
       WHERE user_id = v_user_id
         AND date BETWEEN (v_week_start - 7) AND (v_week_start - 1)
       GROUP BY date
    ) AS prev_days;

  SELECT COUNT(*)::INT,
         ROUND(AVG(hours)::NUMERIC, 1),
         ROUND(AVG(quality)::NUMERIC, 1),
         ROUND(AVG(soreness)::NUMERIC, 1)
    INTO v_sleep_nights, v_sleep_hours, v_sleep_quality, v_soreness
    FROM public.sleep_logs
   WHERE user_id = v_user_id AND date BETWEEN v_week_start AND v_week_end;

  SELECT COUNT(*)::INT, ROUND(AVG(mood)::NUMERIC, 1)
    INTO v_mood_days, v_mood_avg
    FROM public.mood_logs
   WHERE user_id = v_user_id AND date BETWEEN v_week_start AND v_week_end;

  SELECT weight_lbs INTO v_weight_start
    FROM public.body_metrics
   WHERE user_id = v_user_id AND date <= v_week_start AND weight_lbs IS NOT NULL
   ORDER BY date DESC LIMIT 1;

  SELECT weight_lbs INTO v_weight_end
    FROM public.body_metrics
   WHERE user_id = v_user_id AND date <= v_week_end AND weight_lbs IS NOT NULL
   ORDER BY date DESC LIMIT 1;

  SELECT COALESCE(SUM(amount), 0)::INT INTO v_xp_earned
    FROM public.xp_grant_log
   WHERE user_id = v_user_id
     AND granted_at >= v_week_start::TIMESTAMPTZ
     AND granted_at <  (v_week_end + 1)::TIMESTAMPTZ;

  SELECT COALESCE(total_xp, 0), COALESCE(current_level, 1), league_tier
    INTO v_total_xp, v_level_end, v_league_tier
    FROM public.user_profiles WHERE id = v_user_id;

  SELECT COALESCE(MAX(level), 1) INTO v_level_start
    FROM public.xp_level_thresholds
   WHERE total_xp_required <= GREATEST(0, v_total_xp - v_xp_earned);

  SELECT COUNT(*)::INT INTO v_quests_done
    FROM public.user_daily_quests
   WHERE user_id = v_user_id
     AND quest_date BETWEEN v_week_start AND v_week_end
     AND completed_at IS NOT NULL;

  SELECT COALESCE(SUM(delta), 0)::INT INTO v_coins
    FROM public.flex_coin_ledger
   WHERE user_id = v_user_id
     AND delta > 0
     AND created_at >= v_week_start::TIMESTAMPTZ
     AND created_at <  (v_week_end + 1)::TIMESTAMPTZ;

  SELECT ARRAY_AGG(trophy_id) INTO v_trophies
    FROM public.user_trophies
   WHERE user_id = v_user_id
     AND earned_at >= v_week_start::TIMESTAMPTZ
     AND earned_at <  (v_week_end + 1)::TIMESTAMPTZ;

  SELECT name INTO v_crew_name
    FROM public.crews
   WHERE id = (SELECT crew_id FROM public.crew_members WHERE user_id = v_user_id LIMIT 1);

  SELECT COUNT(*)::INT INTO v_crew_msgs
    FROM public.crew_messages
   WHERE sender_id = v_user_id
     AND created_at >= v_week_start::TIMESTAMPTZ
     AND created_at <  (v_week_end + 1)::TIMESTAMPTZ;

  SELECT COUNT(*)::INT,
         COUNT(*) FILTER (WHERE winner_id = v_user_id)::INT
    INTO v_duels_played, v_duels_won
    FROM public.duels
   WHERE (challenger_id = v_user_id OR opponent_id = v_user_id)
     AND created_at >= v_week_start::TIMESTAMPTZ
     AND created_at <  (v_week_end + 1)::TIMESTAMPTZ;

  SELECT rank, weekly_xp, active_days
    INTO v_league_rank, v_league_xp, v_league_days
    FROM public.league_members
   WHERE user_id = v_user_id
     AND league_id IN (SELECT id FROM public.leagues WHERE week_start = v_week_start)
   LIMIT 1;

  SELECT COUNT(DISTINCT checkin_date)::INT INTO v_gym_days
    FROM public.gym_checkins
   WHERE user_id = v_user_id
     AND checkin_date BETWEEN v_week_start AND v_week_end;

  SELECT COUNT(*) FILTER (WHERE status = 'active')::INT,
         COUNT(*) FILTER (
           WHERE completed_at >= v_week_start::TIMESTAMPTZ
             AND completed_at <  (v_week_end + 1)::TIMESTAMPTZ
         )::INT
    INTO v_goals_active, v_goals_done
    FROM public.goals
   WHERE user_id = v_user_id;

  v_insight := CASE
    WHEN v_sessions = 0 AND v_fuel_days = 0 AND v_cardio_n = 0
      THEN 'Nothing logged this week. The next one starts with a single set.'
    WHEN v_sessions = 0 AND (v_fuel_days > 0 OR v_cardio_n > 0)
      THEN 'No lifting this week, but you kept logging. That habit is what makes the return easy.'
    WHEN v_pr_count > 1
      THEN v_pr_count || ' personal records this week. That is not a good day — that is a training block working.'
    WHEN v_top_is_pr AND v_top_name IS NOT NULL
      THEN 'New PR on ' || v_top_name || '. Accumulated work, paid out.'
    WHEN v_load_ratio IS NOT NULL AND v_load_ratio >= 1.5
      THEN 'Volume ran ' || ROUND(v_load_ratio, 1) || '× your four-week normal. Worth watching sleep and soreness before you repeat it.'
    WHEN v_load_ratio IS NOT NULL AND v_load_ratio <= 0.6 AND v_sessions > 0
      THEN 'A lighter week than your recent normal. Deload or life — either way the baseline is still there.'
    WHEN v_days_trained >= 5
      THEN v_days_trained || ' training days. That is the top of the consistency curve.'
    WHEN v_sleep_hours IS NOT NULL AND v_sleep_hours < 6.5 AND v_sessions >= 3
      THEN 'You trained ' || v_sessions || ' times on ' || v_sleep_hours || 'h average sleep. Recovery is the ceiling on the next block.'
    WHEN v_protein > 0 AND v_sessions >= 3
      THEN v_sessions || ' sessions and ' || ROUND(v_protein) || 'g protein a day. The training and the fuel are pointing the same way.'
    WHEN v_sessions > 0
      THEN v_sessions || ' session' || CASE WHEN v_sessions = 1 THEN '' ELSE 's' END || ' logged. The trend is what matters — keep stacking.'
    ELSE 'Every rep logged is a data point. Keep stacking.'
  END;

  v_data := jsonb_build_object(
    'schema_version', 2,
    'week_start', v_week_start::TEXT,
    'week_end',   v_week_end::TEXT,
    'volume_lbs',            v_volume,
    'volume_prev_lbs',       v_prev_volume,
    'volume_change_pct',     v_change_pct,
    'workouts_count',        v_sessions,
    'workout_streak',        v_streak,
    'top_lift_name',         v_top_name,
    'top_lift_weight',       v_top_weight,
    'top_lift_reps',         v_top_reps,
    'top_lift_is_pr',        v_top_is_pr,
    'muscle_groups_trained', COALESCE((SELECT ARRAY_AGG(k) FROM jsonb_object_keys(v_muscle_sets) AS k), ARRAY[]::TEXT[]),
    'macro_days_tracked',    v_fuel_days,
    'macro_adherence_pct',   LEAST(ROUND(v_fuel_days::NUMERIC / 7 * 100)::INT, 100),
    'xp_earned',             v_xp_earned,
    'total_xp_end',          v_total_xp,
    'level_start',           v_level_start,
    'level_end',             v_level_end,
    'ai_insight',            v_insight,
    'training', jsonb_build_object(
      'sessions',      v_sessions,
      'days_trained',  v_days_trained,
      'day_flags',     COALESCE(to_jsonb(v_day_flags), '[]'::jsonb),
      'volume_lbs',    v_volume,
      'prev_lbs',      v_prev_volume,
      'change_pct',    v_change_pct,
      'baseline_lbs',  ROUND(v_baseline),
      'load_ratio',    v_load_ratio,
      'sets',          v_sets,
      'reps',          v_reps,
      'duration_min',  v_duration,
      'muscle_sets',   v_muscle_sets,
      'pr_count',      v_pr_count,
      'streak',        v_streak,
      'top_lift',      jsonb_build_object(
        'name', v_top_name, 'weight', v_top_weight,
        'reps', v_top_reps, 'is_pr', v_top_is_pr)
    ),
    'conditioning', jsonb_build_object(
      'sessions',     v_cardio_n,
      'distance_m',   v_cardio_dist,
      'duration_min', v_cardio_min,
      'calories',     ROUND(v_cardio_kcal),
      'steps',        v_steps,
      'steps_days',   v_steps_days,
      'daily_steps',  COALESCE(to_jsonb(v_daily_steps), '[]'::jsonb),
      'prev_steps',   v_prev_steps
    ),
    'fuel', jsonb_build_object(
      'days_logged',  v_fuel_days,
      'avg_calories', v_kcal,
      'avg_protein',  v_protein,
      'avg_carbs',    v_carbs,
      'avg_fat',      v_fat,
      'prev_calories',v_prev_kcal,
      'prev_protein', v_prev_protein
    ),
    'recovery', jsonb_build_object(
      'sleep_nights',  v_sleep_nights,
      'sleep_hours',   v_sleep_hours,
      'sleep_quality', v_sleep_quality,
      'soreness',      v_soreness,
      'mood_days',     v_mood_days,
      'mood_avg',      v_mood_avg,
      'weight_start',  v_weight_start,
      'weight_end',    v_weight_end,
      'weight_change', CASE WHEN v_weight_start IS NOT NULL AND v_weight_end IS NOT NULL
                            THEN ROUND(v_weight_end - v_weight_start, 1) END
    ),
    'game', jsonb_build_object(
      'xp_earned',   v_xp_earned,
      'total_xp',    v_total_xp,
      'level_start', v_level_start,
      'level_end',   v_level_end,
      'quests_done', v_quests_done,
      'coins',       v_coins,
      'trophies',    COALESCE(to_jsonb(v_trophies), '[]'::jsonb),
      'trophy_count',COALESCE(array_length(v_trophies, 1), 0)
    ),
    'people', jsonb_build_object(
      'crew_name',     v_crew_name,
      'crew_messages', v_crew_msgs,
      'duels_played',  v_duels_played,
      'duels_won',     v_duels_won,
      'league_tier',   v_league_tier,
      'league_rank',   v_league_rank,
      'league_xp',     v_league_xp,
      'league_days',   v_league_days,
      'gym_days',      v_gym_days
    ),
    'goals', jsonb_build_object(
      'active',    v_goals_active,
      'completed', v_goals_done
    )
  );

  IF v_sessions = 0 AND v_cardio_n = 0 AND v_steps_days = 0 AND v_fuel_days = 0
     AND v_sleep_nights = 0 AND v_mood_days = 0 AND v_xp_earned = 0
     AND NOT EXISTS (
       SELECT 1 FROM public.weekly_debriefs
        WHERE user_id = v_user_id AND week_number = v_week_num AND year = v_year
     )
  THEN
    RETURN jsonb_build_object(
      'week_start', v_week_start, 'week_label', v_week_label,
      'week_number', v_week_num, 'year', v_year,
      'skipped', TRUE, 'reason', 'no_activity'
    );
  END IF;

  INSERT INTO public.weekly_debriefs (user_id, week_number, year, week_label, data)
  VALUES (v_user_id, v_week_num, v_year, v_week_label, v_data)
  ON CONFLICT (user_id, week_number, year) DO UPDATE
    SET week_label = EXCLUDED.week_label,
        data       = EXCLUDED.data;

  RETURN jsonb_build_object(
    'week_start',  v_week_start,
    'week_label',  v_week_label,
    'week_number', v_week_num,
    'year',        v_year,
    'data',        v_data
  );
END;
$_$;


ALTER FUNCTION "public"."generate_weekly_review_for"("p_user_id" "uuid", "p_week_start" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_active_followees"() RETURNS TABLE("user_id" "uuid", "username" "text", "avatar_url" "text", "active_until" timestamp with time zone, "email" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
#variable_conflict use_column
DECLARE
  v_uid   UUID := auth.uid();
  v_email TEXT;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;

  SELECT email INTO v_email FROM public.user_profiles WHERE id = v_uid;

  RETURN QUERY
    WITH following AS (
      SELECT followee_email AS f_email
        FROM public.hub_follows
       WHERE follower_email = v_email
    )
    SELECT public.user_profiles.id,
           public.user_profiles.username,
           public.user_profiles.avatar_url,
           public.user_profiles.active_until,
           public.user_profiles.email
      FROM public.user_profiles
      JOIN following ON f_email = public.user_profiles.email
     WHERE public.user_profiles.active_until > now()
     ORDER BY public.user_profiles.active_until DESC
     LIMIT 50;
END;
$$;


ALTER FUNCTION "public"."get_active_followees"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_capsule_pity"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid       UUID := auth.uid();
  v_epic      INTEGER := 0;
  v_legendary INTEGER := 0;
BEGIN
  IF v_uid IS NOT NULL THEN
    SELECT COALESCE(pity_since_epic, 0), COALESCE(pity_since_legendary, 0)
      INTO v_epic, v_legendary
      FROM public.user_profiles
     WHERE id = v_uid;
  END IF;

  RETURN jsonb_build_object(
    'since_epic',      COALESCE(v_epic, 0),
    'since_legendary', COALESCE(v_legendary, 0),
    'epic_at',         30,
    'legendary_at',    90,
    'soft_pity_from',  61
  );
END;
$$;


ALTER FUNCTION "public"."get_capsule_pity"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_crew_challenge_catalog"("p_crew_id" "uuid") RETURNS TABLE("template_key" "text", "title" "text", "metric" "text", "target_value" integer, "min_crew_level" integer, "trophy_id" "text", "trophy_title" "text", "state" "text", "current_value" integer, "challenge_id" "uuid")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
#variable_conflict use_column
DECLARE
  v_uid   uuid := auth.uid();
  v_level integer;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;

  IF p_crew_id IS NULL THEN
    RAISE EXCEPTION 'crew_id required' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.crew_members
     WHERE crew_id = p_crew_id AND user_id = v_uid
  ) THEN
    RAISE EXCEPTION 'not a member of that crew' USING ERRCODE = '42501';
  END IF;

  SELECT COALESCE(crew_level, 1) INTO v_level
    FROM public.crews WHERE id = p_crew_id;

  RETURN QUERY
  WITH chased AS (
    SELECT
      public.crew_challenges.template_key  AS chased_key,
      public.crew_challenges.status        AS chased_status,
      public.crew_challenges.current_value AS chased_value,
      public.crew_challenges.id            AS chased_id
    FROM public.crew_challenges
    WHERE public.crew_challenges.crew_id = p_crew_id
      AND public.crew_challenges.template_key IS NOT NULL
  )
  SELECT
    public.crew_challenge_templates.template_key,
    public.crew_challenge_templates.title,
    public.crew_challenge_templates.metric,
    public.crew_challenge_templates.target_value,
    public.crew_challenge_templates.min_crew_level,
    public.crew_challenge_templates.trophy_id,
    public.crew_challenge_templates.trophy_title,
    CASE
      WHEN chased.chased_status = 'active'    THEN 'active'
      WHEN chased.chased_status = 'completed' THEN 'earned'
      WHEN v_level = LEAST(v_level, public.crew_challenge_templates.min_crew_level)
           AND NOT (v_level = public.crew_challenge_templates.min_crew_level)
        THEN 'locked'
      ELSE 'available'
    END AS state,
    COALESCE(chased.chased_value, 0) AS current_value,
    chased.chased_id                 AS challenge_id
  FROM public.crew_challenge_templates
  LEFT JOIN chased ON chased.chased_key = public.crew_challenge_templates.template_key
  WHERE public.crew_challenge_templates.is_active
  ORDER BY public.crew_challenge_templates.sort_order,
           public.crew_challenge_templates.template_key;
END;
$$;


ALTER FUNCTION "public"."get_crew_challenge_catalog"("p_crew_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_crew_challenge_contributions"("p_challenge_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_uid  uuid := auth.uid();
  v_crew uuid;
  v_rows jsonb;
BEGIN
  IF v_uid IS NULL OR p_challenge_id IS NULL THEN
    RETURN '[]'::jsonb;
  END IF;

  SELECT crew_id INTO v_crew
    FROM public.crew_challenges
   WHERE id = p_challenge_id;

  IF v_crew IS NULL THEN
    RETURN '[]'::jsonb;
  END IF;

  PERFORM 1 FROM public.crew_members
   WHERE crew_id = v_crew AND user_id = v_uid;
  IF NOT FOUND THEN
    RETURN '[]'::jsonb;
  END IF;

  WITH contrib AS (
    SELECT user_id AS c_user, value AS c_value
      FROM public.crew_challenge_contributions
     WHERE challenge_id = p_challenge_id
  ),
  named AS (
    SELECT
      c_user,
      c_value,
      (SELECT username   FROM public.user_profiles WHERE id = c_user) AS c_username,
      (SELECT full_name  FROM public.user_profiles WHERE id = c_user) AS c_full_name,
      (SELECT avatar_url FROM public.user_profiles WHERE id = c_user) AS c_avatar_url
    FROM contrib
  )
  SELECT COALESCE(
           jsonb_agg(
             jsonb_build_object(
               'user_id',    c_user,
               'value',      c_value,
               'username',   c_username,
               'full_name',  c_full_name,
               'avatar_url', c_avatar_url
             )
             ORDER BY c_value DESC
           ),
           '[]'::jsonb
         )
    INTO v_rows
    FROM named;

  RETURN COALESCE(v_rows, '[]'::jsonb);
END;
$$;


ALTER FUNCTION "public"."get_crew_challenge_contributions"("p_challenge_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_crew_division_standings"("p_crew_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_uid    uuid := auth.uid();
  v_season uuid;
  v_num    integer;
  v_ends   timestamptz;
  v_div    integer;
  v_rows   jsonb;
BEGIN
  IF v_uid IS NULL OR p_crew_id IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT id, season_number, ends_at INTO v_season, v_num, v_ends
    FROM public.crew_seasons
   WHERE status = 'active'
   ORDER BY season_number DESC
   LIMIT 1;

  IF v_season IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT MIN(division) INTO v_div
    FROM public.crew_season_stats
   WHERE season_id = v_season AND crew_id = p_crew_id;

  IF v_div IS NULL THEN
    RETURN jsonb_build_object(
      'season_number', v_num,
      'ends_at',       v_ends,
      'division',      NULL,
      'rows',          '[]'::jsonb
    );
  END IF;

  WITH standing AS (
    SELECT crew_id AS s_crew, points AS s_points, wars_played AS s_played,
           wars_won AS s_won, challenges AS s_chal
      FROM public.crew_season_stats
     WHERE season_id = v_season AND division = v_div
  ),
  named AS (
    SELECT
      s_crew, s_points, s_played, s_won, s_chal,
      (SELECT name       FROM public.crews WHERE id = s_crew) AS s_name,
      (SELECT tag        FROM public.crews WHERE id = s_crew) AS s_tag,
      (SELECT avatar_url FROM public.crews WHERE id = s_crew) AS s_avatar,
      (SELECT trophies   FROM public.crews WHERE id = s_crew) AS s_trophies,
      (SELECT crew_level FROM public.crews WHERE id = s_crew) AS s_level
    FROM standing
  )
  SELECT COALESCE(
           jsonb_agg(
             jsonb_build_object(
               'crew_id',    s_crew,
               'name',       s_name,
               'tag',        s_tag,
               'avatar_url', s_avatar,
               'points',     s_points,
               'played',     s_played,
               'won',        s_won,
               'challenges', s_chal,
               'trophies',   s_trophies,
               'level',      s_level,
               'is_mine',    s_crew = p_crew_id
             )
             ORDER BY s_points DESC, s_trophies DESC, s_name
           ),
           '[]'::jsonb
         )
    INTO v_rows
    FROM named;

  RETURN jsonb_build_object(
    'season_number', v_num,
    'ends_at',       v_ends,
    'division',      v_div,
    'rows',          COALESCE(v_rows, '[]'::jsonb)
  );
END;
$$;


ALTER FUNCTION "public"."get_crew_division_standings"("p_crew_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_crew_inactive_members"("p_crew_id" "uuid", "p_days" integer DEFAULT 21) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_uid    uuid := auth.uid();
  v_admin  integer;
  v_cutoff timestamptz;
  v_rows   jsonb;
BEGIN
  IF v_uid IS NULL OR p_crew_id IS NULL THEN
    RETURN '[]'::jsonb;
  END IF;

  SELECT COUNT(*) INTO v_admin
    FROM public.crew_members
   WHERE crew_id = p_crew_id AND user_id = v_uid AND is_admin = TRUE;

  IF v_admin = 0 THEN
    RETURN '[]'::jsonb;
  END IF;

  v_cutoff := now() - (LEAST(365, GREATEST(1, COALESCE(p_days, 21))) * INTERVAL '1 day');

  WITH mem AS (
    SELECT user_id AS m_user, joined_at AS m_joined
      FROM public.crew_members
     WHERE crew_id = p_crew_id
       AND NOT (user_id = v_uid)
     LIMIT 40
  ),
  seen AS (
    SELECT
      m_user,
      m_joined,
      (SELECT MAX(created_at)
         FROM public.workout_logs
        WHERE user_id = m_user
           OR lower(created_by) = (SELECT lower(email) FROM public.user_profiles
                                    WHERE id = m_user)
      ) AS m_last
    FROM mem
  )
  SELECT COALESCE(jsonb_agg(
           jsonb_build_object(
             'user_id',    m_user,
             'joined_at',  m_joined,
             'last_seen',  m_last,
             'username',   (SELECT username   FROM public.user_profiles WHERE id = m_user),
             'full_name',  (SELECT full_name  FROM public.user_profiles WHERE id = m_user),
             'avatar_url', (SELECT avatar_url FROM public.user_profiles WHERE id = m_user)
           ) ORDER BY m_last NULLS FIRST
         ), '[]'::jsonb)
    INTO v_rows
    FROM seen
   WHERE m_last IS NULL OR m_last = LEAST(m_last, v_cutoff);

  RETURN COALESCE(v_rows, '[]'::jsonb);
END;
$$;


ALTER FUNCTION "public"."get_crew_inactive_members"("p_crew_id" "uuid", "p_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_crew_treasury"("p_crew_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_uid     uuid := auth.uid();
  v_member  integer;
  v_balance integer;
  v_cap     integer;
  v_perks   jsonb;
  v_recent  jsonb;
BEGIN
  IF v_uid IS NULL OR p_crew_id IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT COUNT(*) INTO v_member
    FROM public.crew_members WHERE crew_id = p_crew_id AND user_id = v_uid;

  IF v_member = 0 THEN
    RETURN NULL;
  END IF;

  SELECT treasury_coins, COALESCE(max_capacity, 16)
    INTO v_balance, v_cap
    FROM public.crews WHERE id = p_crew_id;

  SELECT COALESCE(jsonb_agg(
           jsonb_build_object(
             'perk_key',    k_key,
             'name',        k_name,
             'description', k_desc,
             'owned',       k_owned,
             'max',         k_max,
             'price',       public.crew_perk_price(k_base, k_owned),
             'affordable',  COALESCE(v_balance, 0) = GREATEST(COALESCE(v_balance, 0),
                                                              public.crew_perk_price(k_base, k_owned)),
             'maxed',       k_owned = GREATEST(k_owned, k_max)
           ) ORDER BY k_sort
         ), '[]'::jsonb)
    INTO v_perks
    FROM (
      SELECT k_key, k_name, k_desc, k_base, k_max, k_sort,
             (SELECT COUNT(*) FROM public.crew_perk_purchases
               WHERE crew_id = p_crew_id AND perk_key = k_key) AS k_owned
        FROM (
          SELECT perk_key AS k_key, name AS k_name, description AS k_desc,
                 base_cost AS k_base, max_purchases AS k_max, sort_order AS k_sort
            FROM public.crew_perks
           WHERE active
        ) AS base
    ) AS catalogue;

  SELECT COALESCE(jsonb_agg(
           jsonb_build_object(
             'delta',         l_delta,
             'balance_after', l_after,
             'reason',        l_reason,
             'created_at',    l_when
           ) ORDER BY l_when DESC
         ), '[]'::jsonb)
    INTO v_recent
    FROM (
      SELECT delta AS l_delta, balance_after AS l_after,
             reason AS l_reason, created_at AS l_when
        FROM public.crew_treasury_ledger
       WHERE crew_id = p_crew_id
       ORDER BY created_at DESC
       LIMIT 12
    ) AS recent;

  RETURN jsonb_build_object(
    'balance',      COALESCE(v_balance, 0),
    'max_capacity', v_cap,
    'perks',        COALESCE(v_perks, '[]'::jsonb),
    'ledger',       COALESCE(v_recent, '[]'::jsonb)
  );
END;
$$;


ALTER FUNCTION "public"."get_crew_treasury"("p_crew_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_crew_trophies"("p_crew_id" "uuid") RETURNS TABLE("trophy_id" "text", "title" "text", "earned_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
  SELECT
    public.crew_trophies.trophy_id,
    public.crew_trophies.title,
    public.crew_trophies.earned_at
  FROM public.crew_trophies
  WHERE public.crew_trophies.crew_id = p_crew_id
  ORDER BY public.crew_trophies.earned_at DESC;
$$;


ALTER FUNCTION "public"."get_crew_trophies"("p_crew_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_crew_war_breakdown"("p_war_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_crew_a uuid; v_crew_b uuid; v_mine uuid;
  v_seen integer; v_rows jsonb; v_totals jsonb;
BEGIN
  IF v_uid IS NULL OR p_war_id IS NULL THEN RETURN NULL; END IF;

  SELECT crew_a_id, crew_b_id INTO v_crew_a, v_crew_b
    FROM public.crew_wars WHERE id = p_war_id;
  IF v_crew_a IS NULL THEN RETURN NULL; END IF;

  SELECT crew_id INTO v_mine FROM public.crew_members
   WHERE user_id = v_uid AND crew_id IN (v_crew_a, v_crew_b) LIMIT 1;
  IF v_mine IS NULL THEN RETURN NULL; END IF;

  SELECT COUNT(*) INTO v_seen
    FROM public.crew_war_contributions WHERE war_id = p_war_id;

  IF v_seen = 0 THEN
    RETURN jsonb_build_object('war_id', p_war_id, 'my_crew_id', v_mine,
                              'crew_a_id', v_crew_a, 'crew_b_id', v_crew_b,
                              'totals', '[]'::jsonb, 'members', '[]'::jsonb);
  END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'crew_id', t_crew, 'volume_lbs', t_vol, 'sessions', t_sess,
           'days_active', t_days, 'score', t_score) ORDER BY t_score DESC), '[]'::jsonb)
    INTO v_totals
    FROM (SELECT crew_id AS t_crew, SUM(volume_lbs) AS t_vol,
                 SUM(sessions) AS t_sess, SUM(days_active) AS t_days,
                 SUM(xp_contributed) AS t_score
            FROM public.crew_war_contributions
           WHERE war_id = p_war_id GROUP BY crew_id) AS sides;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'user_id',     m_user,
           'crew_id',     m_crew,
           'score',       m_score,
           'volume_lbs',  CASE WHEN m_crew = v_mine THEN m_vol  ELSE NULL END,
           'sessions',    CASE WHEN m_crew = v_mine THEN m_sess ELSE NULL END,
           'days_active', CASE WHEN m_crew = v_mine THEN m_days ELSE NULL END,
           'username',    (SELECT username   FROM public.user_profiles WHERE id = m_user),
           'full_name',   (SELECT full_name  FROM public.user_profiles WHERE id = m_user),
           'avatar_url',  (SELECT avatar_url FROM public.user_profiles WHERE id = m_user),
           'is_mine',     m_crew = v_mine
         ) ORDER BY m_score DESC), '[]'::jsonb)
    INTO v_rows
    FROM (SELECT user_id AS m_user, crew_id AS m_crew, xp_contributed AS m_score,
                 volume_lbs AS m_vol, sessions AS m_sess, days_active AS m_days
            FROM public.crew_war_contributions
           WHERE war_id = p_war_id) AS all_sides;

  RETURN jsonb_build_object(
    'war_id', p_war_id, 'my_crew_id', v_mine,
    'crew_a_id', v_crew_a, 'crew_b_id', v_crew_b,
    'totals', COALESCE(v_totals, '[]'::jsonb),
    'members', COALESCE(v_rows, '[]'::jsonb));
END;
$$;


ALTER FUNCTION "public"."get_crew_war_breakdown"("p_war_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_crew_weekly_stats"("p_crew_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_since  date  := (now() - interval '7 days')::date;
  v_result jsonb;
BEGIN
  IF p_crew_id IS NULL OR auth.uid() IS NULL THEN
    RETURN '[]'::jsonb;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.crew_members
    WHERE crew_id = p_crew_id AND user_id = auth.uid()
  ) THEN
    RETURN '[]'::jsonb;
  END IF;

  SELECT COALESCE(jsonb_agg(
           jsonb_build_object('user_id', user_id)
           || public._crew_member_week_stats(user_id, v_since)
         ), '[]'::jsonb)
  INTO v_result
  FROM public.crew_members
  WHERE crew_id = p_crew_id;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."get_crew_weekly_stats"("p_crew_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_friend_leaderboard"("p_mode" "text" DEFAULT 'weekly_xp'::"text", "p_limit" integer DEFAULT 20) RETURNS TABLE("user_id" "uuid", "username" "text", "avatar_url" "text", "current_level" integer, "weekly_xp" integer, "weekly_volume" numeric, "weekly_sessions" integer, "is_self" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
#variable_conflict use_column
DECLARE
  v_uid        UUID := auth.uid();
  v_email      TEXT;
  v_limit      INT  := LEAST(GREATEST(COALESCE(p_limit, 20), 1), 50);
  v_mode       TEXT := COALESCE(p_mode, 'weekly_xp');
  v_week_start TIMESTAMPTZ := date_trunc('week', now() AT TIME ZONE 'UTC');
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;
  IF v_mode NOT IN ('weekly_xp', 'weekly_volume', 'weekly_sessions') THEN
    RAISE EXCEPTION 'invalid mode' USING ERRCODE = '22023';
  END IF;

  SELECT email INTO v_email FROM public.user_profiles WHERE id = v_uid;
  IF v_email IS NULL THEN RETURN; END IF;

  RETURN QUERY
    WITH i_follow AS (
      SELECT followee_email AS f_email FROM public.hub_follows WHERE follower_email = v_email
    ),
    follows_me AS (
      SELECT follower_email AS b_follower FROM public.hub_follows WHERE followee_email = v_email
    ),
    candidates AS (
      SELECT f_email AS c_email FROM i_follow
       WHERE f_email IN (SELECT b_follower FROM follows_me)
      UNION
      SELECT v_email
    ),
    weekly_stats AS (
      SELECT user_id AS s_user_id,
             SUM(COALESCE(total_volume, 0))::NUMERIC AS s_volume,
             COUNT(*)::INT AS s_sessions
        FROM public.workout_logs
       WHERE date >= v_week_start::date
         AND NOT COALESCE(implausible, FALSE)
       GROUP BY user_id
    ),
    weekly_xp_per_user AS (
      SELECT user_id AS x_user_id, SUM(COALESCE(weekly_xp, 0))::INT AS x_xp
        FROM public.league_members GROUP BY user_id
    ),
    ranked AS (
      SELECT id AS r_id, username AS r_username, avatar_url AS r_avatar_url,
             current_level AS r_level,
             COALESCE(x_xp, 0)::INT AS r_xp,
             COALESCE(s_volume, 0)::NUMERIC AS r_volume,
             COALESCE(s_sessions, 0)::INT AS r_sessions,
             (id = v_uid) AS r_is_self
        FROM public.user_profiles
        JOIN candidates ON c_email = email
        LEFT JOIN weekly_stats       ON s_user_id = id
        LEFT JOIN weekly_xp_per_user ON x_user_id = id
       WHERE username IS NOT NULL
         AND username NOT LIKE 'deleted_%'
    )
    SELECT r_id, r_username, r_avatar_url, r_level,
           r_xp, r_volume, r_sessions, r_is_self
      FROM ranked
     ORDER BY
       CASE v_mode
         WHEN 'weekly_xp'       THEN r_xp::NUMERIC
         WHEN 'weekly_volume'   THEN r_volume
         WHEN 'weekly_sessions' THEN r_sessions::NUMERIC
       END DESC NULLS LAST,
       r_username ASC
     LIMIT v_limit;
END;
$$;


ALTER FUNCTION "public"."get_friend_leaderboard"("p_mode" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_gym_community_progress"("p_gym_id" "uuid") RETURNS TABLE("member_count" bigint, "active_members" bigint, "workout_count" bigint, "total_volume" numeric, "active_days" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
#variable_conflict use_column
BEGIN
  IF NOT public.is_gym_member_or_owner(p_gym_id, auth.uid()) THEN
    RAISE EXCEPTION 'not a member' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
    WITH members AS (
      SELECT user_id AS m_user_id FROM public.gym_members WHERE gym_id = p_gym_id
    ),
    logs AS (
      SELECT user_id AS w_user_id, date AS w_date, total_volume AS w_volume
        FROM public.workout_logs
       WHERE date >= CURRENT_DATE - 6
         AND NOT COALESCE(implausible, FALSE)
         AND user_id IN (SELECT m_user_id FROM members)
    )
    SELECT
      (SELECT count(*) FROM members),
      (SELECT count(DISTINCT w_user_id) FROM logs),
      (SELECT count(*) FROM logs),
      (SELECT COALESCE(sum(w_volume), 0)::NUMERIC FROM logs),
      (SELECT count(DISTINCT (w_user_id, w_date)) FROM logs);
END;
$$;


ALTER FUNCTION "public"."get_gym_community_progress"("p_gym_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_gym_consistency_leaderboard"("p_gym_id" "uuid", "p_limit" integer DEFAULT 50) RETURNS TABLE("user_id" "uuid", "username" "text", "avatar_url" "text", "value" numeric, "rank" integer)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
#variable_conflict use_column
BEGIN
  IF NOT public.is_gym_member_or_owner(p_gym_id, auth.uid()) THEN
    RAISE EXCEPTION 'not a member' USING ERRCODE = '42501';
  END IF;
  RETURN QUERY
    WITH members AS (
      SELECT user_id AS m_user_id, joined_at AS m_joined_at
        FROM public.gym_members WHERE gym_id = p_gym_id
    ),
    active AS (
      SELECT user_id AS a_user_id, COUNT(DISTINCT date) AS a_days
        FROM public.workout_logs
       WHERE date >= CURRENT_DATE - 6
         AND NOT COALESCE(implausible, FALSE)
         AND user_id IN (SELECT m_user_id FROM members)
       GROUP BY user_id
    ),
    ranked AS (
      SELECT id AS lb_user_id, username AS lb_username, avatar_url AS lb_avatar_url,
             m_joined_at AS lb_joined_at, COALESCE(a_days, 0)::NUMERIC AS lb_value
      FROM public.user_profiles
      JOIN members ON m_user_id = id
      LEFT JOIN active ON a_user_id = id
    )
    SELECT lb_user_id, lb_username, lb_avatar_url, lb_value,
           RANK() OVER (ORDER BY lb_value DESC)::INT
      FROM ranked
     ORDER BY lb_value DESC, lb_joined_at ASC, lb_user_id ASC
     LIMIT LEAST(GREATEST(COALESCE(p_limit, 50), 1), 200);
END;
$$;


ALTER FUNCTION "public"."get_gym_consistency_leaderboard"("p_gym_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_gym_event_rsvps_bulk"("p_event_ids" "uuid"[]) RETURNS TABLE("event_id" "uuid", "user_id" "uuid", "status" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
      #variable_conflict use_column
      DECLARE v_uid UUID := auth.uid(); v_gym UUID;
      BEGIN
        IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501'; END IF;
        IF p_event_ids IS NULL OR array_length(p_event_ids, 1) IS NULL THEN RETURN; END IF;
        SELECT gym_id INTO v_gym FROM public.gym_events WHERE id = p_event_ids[1];
        IF v_gym IS NULL OR NOT public.is_gym_member_or_owner(v_gym, v_uid) THEN
          RAISE EXCEPTION 'not a member' USING ERRCODE = '42501';
        END IF;
        RETURN QUERY
          SELECT event_id, user_id, status::text
            FROM public.gym_event_rsvps WHERE event_id = ANY(p_event_ids);
      END;
      $$;


ALTER FUNCTION "public"."get_gym_event_rsvps_bulk"("p_event_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_gym_id_by_code"("p_code" "text") RETURNS TABLE("id" "uuid", "name" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
#variable_conflict use_column
BEGIN
  IF p_code IS NULL OR length(btrim(p_code)) <> 8 THEN
    RETURN;
  END IF;
  RETURN QUERY
  SELECT id, name
    FROM public.gym_businesses
   WHERE flexyn_code = upper(btrim(p_code))
     AND is_active = TRUE;
END;
$$;


ALTER FUNCTION "public"."get_gym_id_by_code"("p_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_gym_leaderboard"("p_gym_id" "uuid", "p_mode" "text" DEFAULT 'volume'::"text", "p_limit" integer DEFAULT 50) RETURNS TABLE("user_id" "uuid", "username" "text", "avatar_url" "text", "value" numeric, "rank" integer)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
#variable_conflict use_column
DECLARE
  v_mode TEXT := COALESCE(p_mode, 'volume');
BEGIN
  IF v_mode NOT IN ('volume', 'xp', 'streak') THEN
    RAISE EXCEPTION 'invalid mode' USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
    WITH membership AS (
      SELECT user_id AS member_user_id, joined_at AS member_joined_at
        FROM public.gym_members
       WHERE gym_id = p_gym_id
    ),
    ranked AS (
      SELECT
        id               AS lb_user_id,
        username         AS lb_username,
        avatar_url       AS lb_avatar_url,
        member_joined_at AS lb_joined_at,
        CASE v_mode
          WHEN 'volume' THEN COALESCE(total_volume_lbs, 0)::NUMERIC
          WHEN 'xp'     THEN COALESCE(total_xp,         0)::NUMERIC
          WHEN 'streak' THEN COALESCE(workout_streak,   0)::NUMERIC
        END AS lb_value
      FROM public.user_profiles
      JOIN membership ON member_user_id = id
    )
    SELECT lb_user_id, lb_username, lb_avatar_url, lb_value,
           RANK() OVER (ORDER BY lb_value DESC)::INT
      FROM ranked
     ORDER BY lb_value DESC, lb_joined_at ASC, lb_user_id ASC
     LIMIT LEAST(GREATEST(COALESCE(p_limit, 50), 1), 200);
END;
$$;


ALTER FUNCTION "public"."get_gym_leaderboard"("p_gym_id" "uuid", "p_mode" "text", "p_limit" integer) OWNER TO "postgres";


