ALTER FUNCTION "public"."get_gym_public_card"("p_gym_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_gym_public_preview"("p_gym_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_min_members CONSTANT INTEGER := 5;
  v_members INTEGER; v_active INTEGER; v_sessions INTEGER; v_days INTEGER;
  v_shape INTEGER[];
BEGIN
  IF p_gym_id IS NULL THEN
    RETURN jsonb_build_object('member_count', 0, 'meets_threshold', FALSE);
  END IF;

  SELECT count(*) INTO v_members FROM public.gym_members WHERE gym_id = p_gym_id;

  IF v_members IS NULL OR v_members = LEAST(v_members, v_min_members - 1) THEN
    RETURN jsonb_build_object('member_count', COALESCE(v_members, 0), 'meets_threshold', FALSE);
  END IF;

  WITH members AS (
    SELECT user_id AS m_user_id FROM public.gym_members WHERE gym_id = p_gym_id
  ),
  logs AS (
    SELECT user_id AS w_user_id, date AS w_date
      FROM public.workout_logs
     WHERE date >= CURRENT_DATE - 6
       AND NOT COALESCE(implausible, FALSE)
       AND user_id IN (SELECT m_user_id FROM members)
  ),
  per_person AS (
    SELECT count(DISTINCT w_date) AS d FROM logs
     GROUP BY w_user_id ORDER BY count(DISTINCT w_date) DESC LIMIT 8
  )
  SELECT
    (SELECT count(DISTINCT w_user_id) FROM logs),
    (SELECT count(*) FROM logs),
    (SELECT count(DISTINCT (w_user_id, w_date)) FROM logs),
    (SELECT array_agg(d) FROM per_person)
  INTO v_active, v_sessions, v_days, v_shape;

  RETURN jsonb_build_object(
    'member_count', v_members, 'meets_threshold', TRUE,
    'active_members', COALESCE(v_active, 0),
    'session_count', COALESCE(v_sessions, 0),
    'active_days', COALESCE(v_days, 0),
    'streak_shape', COALESCE(to_jsonb(v_shape), '[]'::jsonb));
END;
$$;


ALTER FUNCTION "public"."get_gym_public_preview"("p_gym_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_gym_vs_gym_leaderboard"("p_limit" integer DEFAULT 20) RETURNS TABLE("rank" bigint, "gym_id" "uuid", "gym_name" "text", "logo_url" "text", "city" "text", "state_code" "text", "member_count" bigint, "active_members" bigint, "workout_count" bigint, "score" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
#variable_conflict use_column
DECLARE
  v_min_members CONSTANT INTEGER := 5;
BEGIN
  RETURN QUERY
  WITH member_map AS (
    SELECT gym_id AS m_gym_id, user_id AS m_user_id FROM public.gym_members
  ),
  member_totals AS (
    SELECT m_gym_id AS t_gym_id, COUNT(*) AS t_members FROM member_map GROUP BY m_gym_id
  ),
  recent_workouts AS (
    SELECT user_id AS w_user_id FROM public.workout_logs
     WHERE date >= CURRENT_DATE - 7
       AND NOT COALESCE(implausible, FALSE)
  ),
  member_workouts AS (
    SELECT m_gym_id, m_user_id FROM member_map JOIN recent_workouts ON w_user_id = m_user_id
  ),
  workout_window AS (
    SELECT m_gym_id AS ww_gym_id, COUNT(*) AS ww_workout_count,
           COUNT(DISTINCT m_user_id) AS ww_active_members
      FROM member_workouts GROUP BY m_gym_id
  ),
  scored AS (
    SELECT id AS s_gym_id, name AS s_gym_name, logo_url AS s_logo_url,
           city AS s_city, state_code AS s_state_code,
           COALESCE(t_members, 0)::BIGINT AS s_member_count,
           COALESCE(ww_active_members, 0)::BIGINT AS s_active_members,
           COALESCE(ww_workout_count, 0)::BIGINT AS s_workout_count,
           ROUND(COALESCE(ww_workout_count, 0) *
                 LOG(COALESCE(ww_active_members, 0) + 1)::NUMERIC, 2) AS s_score
      FROM public.gym_businesses
      LEFT JOIN workout_window ON ww_gym_id = id
      LEFT JOIN member_totals  ON t_gym_id  = id
     WHERE is_active = TRUE
       AND COALESCE(ww_workout_count, 0) > 0
       AND COALESCE(t_members, 0) >= v_min_members
  )
  SELECT ROW_NUMBER() OVER (ORDER BY s_score DESC, s_workout_count DESC),
         s_gym_id, s_gym_name, s_logo_url, s_city, s_state_code,
         s_member_count, s_active_members, s_workout_count, s_score
    FROM scored ORDER BY s_score DESC, s_workout_count DESC LIMIT p_limit;
END;
$$;


