CREATE OR REPLACE FUNCTION "public"."get_leaderboard_around_me"("p_board" "text", "p_period" "text" DEFAULT 'alltime'::"text", "p_radius" integer DEFAULT 3) RETURNS TABLE("rank" integer, "user_id" "uuid", "username" "text", "full_name" "text", "avatar_url" "text", "value" numeric, "is_me" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
#variable_conflict use_column
DECLARE
  v_uid    UUID := auth.uid();
  v_radius INT  := LEAST(GREATEST(COALESCE(p_radius, 3), 1), 25);
  v_board  TEXT := COALESCE(p_board, 'xp');
  v_period TEXT := COALESCE(p_period, 'alltime');
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;
  IF v_board NOT IN ('volume', 'xp', 'achievements', 'distance') THEN
    RAISE EXCEPTION 'invalid board' USING ERRCODE = '22023';
  END IF;
  IF v_period <> 'alltime' THEN
    RAISE EXCEPTION 'around-me supports alltime only' USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
    WITH base AS (
      SELECT
        user_id    AS user_id,
        username   AS username,
        full_name  AS full_name,
        avatar_url AS avatar_url,
        CASE v_board
          WHEN 'xp'           THEN xp_value
          WHEN 'volume'       THEN volume_value
          WHEN 'distance'     THEN distance_value
          WHEN 'achievements' THEN achievements_value
          ELSE 0::NUMERIC
        END AS value
      FROM public.leaderboard_eligible_profiles
    ),
    live AS (
      SELECT user_id, username, full_name, avatar_url, value
      FROM base
      WHERE value > 0
    ),
    ranked AS (
      SELECT
        (ROW_NUMBER() OVER (ORDER BY value DESC, user_id ASC))::INT AS rank,
        user_id, username, full_name, avatar_url, value
      FROM live
    ),
    me AS (
      SELECT rank AS my_rank FROM ranked WHERE user_id = v_uid
    )
    SELECT rank, user_id, username, full_name, avatar_url, value,
           (user_id = v_uid) AS is_me
    FROM ranked
    WHERE (SELECT my_rank FROM me) IS NOT NULL
      AND rank BETWEEN (SELECT my_rank FROM me) - v_radius
                   AND (SELECT my_rank FROM me) + v_radius
    UNION ALL
    SELECT rank, user_id, username, full_name, avatar_url, value, false
    FROM ranked
    WHERE (SELECT my_rank FROM me) IS NULL
      AND rank <= (v_radius * 2) + 1
    ORDER BY rank;
END;
$$;


ALTER FUNCTION "public"."get_leaderboard_around_me"("p_board" "text", "p_period" "text", "p_radius" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_my_quest_stats"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid     uuid := auth.uid();
  v_day     date;
  v_streak  integer;
  v_longest integer;
  v_last    date;
  v_perfect integer;
  v_claimed integer;
  v_coins   integer;
  v_xp      integer;
  v_crewxp  integer;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;
  v_day := (public.user_local_now(v_uid))::date;
  IF v_day IS NULL THEN
    v_day := (now() AT TIME ZONE 'utc')::date;
  END IF;
  SELECT current_streak, longest_streak, last_perfect_date, perfect_days,
         quests_claimed, coins_earned, xp_earned, crew_xp_earned
    INTO v_streak, v_longest, v_last, v_perfect,
         v_claimed, v_coins, v_xp, v_crewxp
    FROM public.user_quest_stats
   WHERE user_id = v_uid;
  RETURN jsonb_build_object(
    'current_streak',    COALESCE(v_streak, 0),
    'longest_streak',    COALESCE(v_longest, 0),
    'last_perfect_date', v_last,
    'perfect_days',      COALESCE(v_perfect, 0),
    'quests_claimed',    COALESCE(v_claimed, 0),
    'coins_earned',      COALESCE(v_coins, 0),
    'xp_earned',         COALESCE(v_xp, 0),
    'crew_xp_earned',    COALESCE(v_crewxp, 0),
    'bonus_claimed_today', COALESCE(v_last = v_day, FALSE),
    'is_current',          COALESCE(v_last >= v_day - 1, FALSE)
  );
END;
$$;


ALTER FUNCTION "public"."get_my_quest_stats"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_my_referral_code"() RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_existing TEXT;
  v_code TEXT;
  v_attempts INT := 0;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501'; END IF;
  SELECT referral_code INTO v_existing FROM public.user_profiles WHERE id = v_uid;
  IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
  LOOP
    v_attempts := v_attempts + 1;
    IF v_attempts > 10 THEN
      RAISE EXCEPTION 'could not allocate referral code after 10 attempts' USING ERRCODE = '23505';
    END IF;
    v_code := public.generate_referral_code();
    BEGIN
      UPDATE public.user_profiles SET referral_code = v_code
       WHERE id = v_uid AND referral_code IS NULL;
      IF FOUND THEN RETURN v_code;
      ELSE
        SELECT referral_code INTO v_existing FROM public.user_profiles WHERE id = v_uid;
        IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
      END IF;
    EXCEPTION WHEN unique_violation THEN CONTINUE; END;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."get_my_referral_code"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_my_trainer_revenue"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
        SELECT jsonb_build_object(
          'gross_cents',  COALESCE(SUM(amount_paid_cents)    FILTER (WHERE is_mock = FALSE), 0),
          'payout_cents', COALESCE(SUM(trainer_payout_cents) FILTER (WHERE is_mock = FALSE), 0),
          'fee_cents',    COALESCE(SUM(platform_fee_cents)   FILTER (WHERE is_mock = FALSE), 0),
          'sales',                COUNT(*)                    FILTER (WHERE is_mock = FALSE),
          'mock_sales',           COUNT(*)                    FILTER (WHERE is_mock = TRUE)
        )
        FROM public.trainer_purchases
        WHERE trainer_id = auth.uid();
      $$;


