CREATE OR REPLACE FUNCTION "public"."get_org_analytics"("p_org_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_members        INT := 0;
  v_active_7d      INT := 0;
  v_workouts_7d    INT := 0;
  v_avg_streak     NUMERIC := 0;
  v_min_cohort     CONSTANT INT := 5;
  v_min_activity   CONSTANT INT := 2;
  v_round_to       CONSTANT INT := 5;
BEGIN
  IF NOT public.is_org_admin(p_org_id) THEN
    RAISE EXCEPTION 'admin_only' USING ERRCODE = '42501';
  END IF;

  SELECT COUNT(*) INTO v_members FROM public.organization_members WHERE org_id = p_org_id;

  IF v_members < v_min_cohort THEN
    RETURN jsonb_build_object(
      'members', v_members,
      'cohort_too_small', true,
      'min_cohort', v_min_cohort
    );
  END IF;

  WITH member_map AS (
    SELECT id AS m_uid, email AS m_email
      FROM public.user_profiles
     WHERE id IN (
       SELECT user_id FROM public.organization_members
        WHERE org_id = p_org_id
     )
  ),
  recent_logs AS (
    SELECT user_id AS log_uid, created_by AS log_email
      FROM public.workout_logs
     WHERE created_at > now() - INTERVAL '7 days'
       AND (
         user_id      IN (SELECT m_uid   FROM member_map)
         OR created_by IN (SELECT m_email FROM member_map)
       )
  ),
  canon AS (
    SELECT COALESCE(
             log_uid::text,
             (SELECT m_uid::text FROM member_map WHERE m_email = log_email LIMIT 1)
           ) AS canonical_actor
      FROM recent_logs
  ),
  unique_actors AS (
    SELECT DISTINCT canonical_actor FROM canon
     WHERE canonical_actor IS NOT NULL
  )
  SELECT
    (SELECT COUNT(*) FROM unique_actors),
    (SELECT COUNT(*) FROM recent_logs)
   INTO v_active_7d, v_workouts_7d;

  SELECT COALESCE(AVG(COALESCE(workout_streak, 0)), 0)
    INTO v_avg_streak
    FROM public.user_profiles
   WHERE id IN (SELECT user_id FROM public.organization_members WHERE org_id = p_org_id);

  IF v_active_7d < v_min_activity THEN
    RETURN jsonb_build_object(
      'members',           v_members,
      'active_7d',         NULL,
      'workouts_7d',       NULL,
      'avg_workout_streak', ROUND(v_avg_streak, 1),
      'participation_pct', NULL,
      'cohort_too_small',  false,
      'low_activity',      true
    );
  END IF;

  RETURN jsonb_build_object(
    'members',           v_members,
    'active_7d',         v_round_to * ROUND(v_active_7d::numeric / v_round_to),
    'workouts_7d',       v_round_to * ROUND(v_workouts_7d::numeric / v_round_to),
    'avg_workout_streak', ROUND(v_avg_streak, 1),
    'participation_pct', v_round_to * ROUND(100.0 * v_active_7d / v_members / v_round_to),
    'cohort_too_small',  false,
    'low_activity',      false
  );
END;
$$;


ALTER FUNCTION "public"."get_org_analytics"("p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_osm_gyms_cached"("p_min_lat" double precision, "p_max_lat" double precision, "p_min_lng" double precision, "p_max_lng" double precision, "p_limit" integer DEFAULT 300, "p_max_age_days" integer DEFAULT 30) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_gyms  JSONB;
  v_total INTEGER;
  v_known INTEGER;
  v_fresh INTEGER;
BEGIN
  IF p_min_lat IS NULL OR p_max_lat IS NULL
     OR p_min_lng IS NULL OR p_max_lng IS NULL THEN
    RETURN jsonb_build_object(
      'gyms', '[]'::jsonb, 'tiles_total', 0, 'tiles_known', 0, 'tiles_fresh', 0);
  END IF;

  WITH picked AS (
    SELECT osm_type, osm_id, name, latitude, longitude, brand, website
      FROM public.osm_gym_cache
     WHERE latitude  BETWEEN p_min_lat AND p_max_lat
       AND longitude BETWEEN p_min_lng AND p_max_lng
     LIMIT p_limit
  )
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'osmType', osm_type, 'osmId', osm_id, 'name', name,
           'lat', latitude, 'lon', longitude,
           'brand', brand, 'website', website
         )), '[]'::jsonb)
    INTO v_gyms
    FROM picked;

  WITH want AS (
    SELECT gy AS ty, gx AS tx
      FROM generate_series(floor(p_min_lat / 0.1)::INTEGER,
                           floor(p_max_lat / 0.1)::INTEGER) AS gy,
           generate_series(floor(p_min_lng / 0.1)::INTEGER,
                           floor(p_max_lng / 0.1)::INTEGER) AS gx
  )
  SELECT count(*) INTO v_total FROM want;

  WITH want AS (
    SELECT gy AS ty, gx AS tx
      FROM generate_series(floor(p_min_lat / 0.1)::INTEGER,
                           floor(p_max_lat / 0.1)::INTEGER) AS gy,
           generate_series(floor(p_min_lng / 0.1)::INTEGER,
                           floor(p_max_lng / 0.1)::INTEGER) AS gx
  )
  SELECT
    count(*) FILTER (WHERE tile_y IS NOT NULL),
    count(*) FILTER (
      WHERE filled_at > now() - make_interval(days => p_max_age_days))
    INTO v_known, v_fresh
    FROM want
    LEFT JOIN public.osm_gym_tiles ON tile_y = ty AND tile_x = tx;

  RETURN jsonb_build_object(
    'gyms', v_gyms,
    'tiles_total', COALESCE(v_total, 0),
    'tiles_known', COALESCE(v_known, 0),
    'tiles_fresh', COALESCE(v_fresh, 0));
END;
$$;


ALTER FUNCTION "public"."get_osm_gyms_cached"("p_min_lat" double precision, "p_max_lat" double precision, "p_min_lng" double precision, "p_max_lng" double precision, "p_limit" integer, "p_max_age_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_pending_duel_invite_public"("p_token" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_id              UUID;
  v_username        TEXT;
  v_avatar_url      TEXT;
  v_duel_type       TEXT;
  v_window_hours    INT;
  v_expires_at      TIMESTAMPTZ;
  v_claimed_by_id   UUID;
BEGIN
  IF p_token IS NULL OR length(p_token) < 8 THEN
    RETURN NULL;
  END IF;

  SELECT id, challenger_username, challenger_avatar_url, duel_type,
         window_hours, expires_at, claimed_by_id
    INTO v_id, v_username, v_avatar_url, v_duel_type,
         v_window_hours, v_expires_at, v_claimed_by_id
    FROM public.pending_duel_invites
   WHERE claim_token = p_token;

  IF v_id IS NULL THEN
    RETURN NULL;
  END IF;

  RETURN jsonb_build_object(
    'id',                    v_id,
    'challenger_username',   v_username,
    'challenger_avatar_url', v_avatar_url,
    'duel_type',             v_duel_type,
    'window_hours',          v_window_hours,
    'expires_at',            v_expires_at,
    'is_claimed',            v_claimed_by_id IS NOT NULL,
    'is_expired',            v_expires_at < NOW()
  );
END;
$$;


ALTER FUNCTION "public"."get_pending_duel_invite_public"("p_token" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_people_you_may_know"("p_email" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 8) RETURNS TABLE("user_id" "uuid", "mutual_count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid   UUID := auth.uid();
  v_limit INT  := LEAST(GREATEST(COALESCE(p_limit, 8), 1), 50);
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  WITH
    i_follow AS (
      SELECT followee_id AS fid
        FROM public.hub_follows
       WHERE follower_id = v_uid
    ),
    follow_me AS (
      SELECT follower_id AS fid
        FROM public.hub_follows
       WHERE followee_id = v_uid
    ),
    hidden AS (
      SELECT id AS hidden_id
        FROM public.user_profiles
       WHERE hide_from_search IS TRUE
    ),
    candidates AS (
      SELECT followee_id AS candidate_id,
             COUNT(*)    AS mutuals
        FROM public.hub_follows
       WHERE follower_id IN (SELECT fid FROM follow_me)
         AND followee_id IS NOT NULL
         AND followee_id <> v_uid
         AND followee_id NOT IN (SELECT fid FROM i_follow)
         AND followee_id NOT IN (SELECT hidden_id FROM hidden)
       GROUP BY followee_id
    )
  SELECT candidate_id, mutuals
    FROM candidates
   ORDER BY mutuals DESC
   LIMIT v_limit;
END;
$$;


ALTER FUNCTION "public"."get_people_you_may_know"("p_email" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_period_leaderboard"("p_board" "text", "p_period" "text", "p_limit" integer DEFAULT 100) RETURNS TABLE("rank" integer, "user_id" "uuid", "username" "text", "full_name" "text", "avatar_url" "text", "value" numeric)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
#variable_conflict use_column
DECLARE
  v_uid    UUID := auth.uid();
  v_limit  INT  := LEAST(GREATEST(COALESCE(p_limit, 100), 1), 200);
  v_period TEXT := COALESCE(p_period, 'alltime');
  v_board  TEXT := COALESCE(p_board, 'volume');
  v_since  TIMESTAMPTZ;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;
  IF v_board NOT IN ('volume', 'xp', 'sessions', 'achievements', 'distance') THEN
    RAISE EXCEPTION 'invalid board' USING ERRCODE = '22023';
  END IF;
  IF v_period NOT IN ('weekly', 'monthly', 'alltime') THEN
    RAISE EXCEPTION 'invalid period' USING ERRCODE = '22023';
  END IF;

  IF v_board IN ('achievements', 'distance') THEN
    v_period := 'alltime';
  END IF;

  IF v_period = 'alltime' THEN
    RETURN QUERY
      WITH base AS (
        SELECT user_id AS user_id, username AS username, full_name AS full_name,
               avatar_url AS avatar_url,
               CASE v_board
                 WHEN 'xp'           THEN xp_value
                 WHEN 'volume'       THEN volume_value
                 WHEN 'distance'     THEN distance_value
                 WHEN 'achievements' THEN achievements_value
                 ELSE 0::NUMERIC
               END AS value
          FROM public.leaderboard_eligible_profiles
      ),
      live AS (
        SELECT user_id, username, full_name, avatar_url, value FROM base WHERE value > 0
      )
      SELECT (ROW_NUMBER() OVER (ORDER BY value DESC, user_id ASC))::INT AS rank,
             user_id, username, full_name, avatar_url, value
        FROM live ORDER BY value DESC, user_id ASC LIMIT v_limit;
    RETURN;
  END IF;

  v_since := CASE v_period
    WHEN 'weekly'  THEN date_trunc('week',  now() AT TIME ZONE 'UTC')
    WHEN 'monthly' THEN date_trunc('month', now() AT TIME ZONE 'UTC')
    ELSE NULL
  END;

  RETURN QUERY
    WITH stats AS (
      SELECT user_id AS user_id,
             SUM(COALESCE(total_volume, 0))::NUMERIC AS agg_volume,
             COUNT(*)::NUMERIC AS agg_sessions
        FROM public.workout_logs
       WHERE (v_since IS NULL OR date >= v_since::date)
         AND NOT COALESCE(implausible, FALSE)
       GROUP BY user_id
    ),
    eligible AS (
      SELECT user_id, username, full_name, avatar_url
        FROM public.leaderboard_eligible_profiles
    ),
    joined AS (
      SELECT user_id, username, full_name, avatar_url,
             CASE v_board WHEN 'sessions' THEN agg_sessions ELSE agg_volume END AS value
        FROM stats JOIN eligible USING (user_id)
    ),
    live AS (
      SELECT user_id, username, full_name, avatar_url, value FROM joined WHERE value > 0
    )
    SELECT (ROW_NUMBER() OVER (ORDER BY value DESC, user_id ASC))::INT AS rank,
           user_id, username, full_name, avatar_url, value
      FROM live ORDER BY value DESC, user_id ASC LIMIT v_limit;
END;
$$;


ALTER FUNCTION "public"."get_period_leaderboard"("p_board" "text", "p_period" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_post_emoji_summary"("p_post_id" "uuid") RETURNS TABLE("top_emoji" "text", "total_count" integer)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
    WITH counts AS (
      SELECT emoji, COUNT(*)::INT AS n
        FROM public.hub_reactions
       WHERE post_id = p_post_id AND reaction_type IS NULL
       GROUP BY emoji
    )
    SELECT
      (SELECT emoji FROM counts ORDER BY n DESC, emoji LIMIT 1),
      COALESCE((SELECT SUM(n)::INT FROM counts), 0);
END;
$$;


