CREATE OR REPLACE FUNCTION "public"."get_public_crews"("p_query" "text" DEFAULT NULL::"text", "p_sort" "text" DEFAULT 'volume'::"text", "p_limit" integer DEFAULT 20, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_uid    uuid := auth.uid();
  v_q      text;
  v_sort   text := lower(COALESCE(p_sort, 'volume'));
  v_limit  int  := LEAST(GREATEST(COALESCE(p_limit, 20), 1), 50);
  v_offset int  := GREATEST(COALESCE(p_offset, 0), 0);
  v_out    jsonb;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;

  IF NOT (v_sort IN ('volume', 'members', 'level', 'new')) THEN
    v_sort := 'volume';
  END IF;

  v_q := btrim(regexp_replace(lower(COALESCE(p_query, '')), '[,()%*]', '', 'g'));
  v_q := NULLIF(left(v_q, 60), '');
  IF v_q IS NOT NULL THEN
    v_q := '%' || v_q || '%';
  END IF;

  WITH memberships AS (
    SELECT crew_id AS k_crew, user_id AS k_user
      FROM public.crew_members
  ),
  volumes AS (
    SELECT id AS k_user,
           COALESCE(total_volume_lbs, 0)::numeric AS v_member
      FROM public.user_profiles
  ),
  rollup AS (
    SELECT k_crew,
           COUNT(*)::int AS n_members,
           COALESCE(SUM(v_member), 0)::numeric AS n_volume
      FROM memberships
      LEFT JOIN volumes USING (k_user)
     GROUP BY k_crew
  ),
  mine AS (
    SELECT crew_id AS k_crew
      FROM public.crew_members
     WHERE user_id = v_uid
  ),
  listed AS (
    SELECT id                          AS k_crew,
           name                        AS c_name,
           tag                         AS c_tag,
           description                 AS c_desc,
           avatar_url                  AS c_avatar,
           COALESCE(max_capacity, 16)  AS c_cap,
           COALESCE(crew_level, 1)     AS c_level,
           COALESCE(trophies, 0)       AS c_trophies,
           COALESCE(wars_won, 0)       AS c_won,
           COALESCE(wars_lost, 0)      AS c_lost,
           created_at                  AS c_created
      FROM public.crews
     WHERE is_public = TRUE
  ),
  merged AS (
    SELECT k_crew, c_name, c_tag, c_desc, c_avatar, c_cap,
           c_level, c_trophies, c_won, c_lost, c_created,
           COALESCE(n_members, 0)                AS c_members,
           COALESCE(n_volume, 0)::numeric        AS c_volume,
           (k_crew IN (SELECT k_crew FROM mine)) AS c_mine
      FROM listed
      LEFT JOIN rollup USING (k_crew)
  ),
  filtered AS (
    SELECT * FROM merged
     WHERE v_q IS NULL
        OR c_name ILIKE v_q
        OR COALESCE(c_tag, '')  ILIKE v_q
        OR COALESCE(c_desc, '') ILIKE v_q
  ),
  ordered AS (
    SELECT * FROM filtered
     ORDER BY
       CASE WHEN v_sort = 'volume'  THEN c_volume  END DESC NULLS LAST,
       CASE WHEN v_sort = 'members' THEN c_members END DESC NULLS LAST,
       CASE WHEN v_sort = 'level'   THEN c_level   END DESC NULLS LAST,
       CASE WHEN v_sort = 'new'     THEN c_created END DESC NULLS LAST,
       c_members DESC,
       k_crew
     LIMIT v_limit OFFSET v_offset
  ),
  numbered AS (
    SELECT *, ROW_NUMBER() OVER () AS c_seq FROM ordered
  )
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'id',               k_crew,
           'name',             c_name,
           'tag',              c_tag,
           'description',      c_desc,
           'avatar_url',       c_avatar,
           'member_count',     c_members,
           'max_capacity',     c_cap,
           'total_volume_lbs', c_volume,
           'crew_level',       c_level,
           'trophies',         c_trophies,
           'wars_won',         c_won,
           'wars_lost',        c_lost,
           'is_member',        c_mine
         ) ORDER BY c_seq), '[]'::jsonb)
    INTO v_out
    FROM numbered;

  RETURN COALESCE(v_out, '[]'::jsonb);
END;
$$;


ALTER FUNCTION "public"."get_public_crews"("p_query" "text", "p_sort" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_public_profile_by_username"("p_username" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_clean TEXT := regexp_replace(COALESCE(p_username, ''), '^@', '');
  v_authed BOOLEAN := (auth.uid() IS NOT NULL);
  v_result JSONB;
BEGIN
  IF v_clean = '' THEN RETURN NULL; END IF;
  SELECT jsonb_build_object(
    'id',                          id,
    'username',                    username,
    'full_name',                   full_name,
    'bio',                         bio,
    'avatar_url',                  avatar_url,
    'current_level',               current_level,
    'total_xp',                    total_xp,
    'prestige_level',              prestige_level,
    'workout_streak',              workout_streak,
    'longest_workout_streak',      longest_workout_streak,
    'achievements_unlocked_count', achievements_unlocked_count,
    'league_tier',                 league_tier,
    'is_private',                  is_private,
    'email',                       CASE WHEN v_authed THEN email ELSE NULL END
  )
  INTO v_result
  FROM public.user_profiles
  WHERE username = v_clean
  LIMIT 1;
  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."get_public_profile_by_username"("p_username" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_suggested_crews"("p_limit" integer DEFAULT 12) RETURNS TABLE("id" "uuid", "name" "text", "description" "text", "member_count" integer, "max_capacity" integer, "is_public" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
#variable_conflict use_column
DECLARE
  v_uid   uuid := auth.uid();
  v_limit int  := LEAST(GREATEST(COALESCE(p_limit, 12), 1), 50);
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
    WITH counts AS (
      SELECT crew_id AS k_crew, COUNT(*)::int AS n_members
        FROM public.crew_members
       GROUP BY crew_id
    ),
    mine AS (
      SELECT crew_id AS k_crew
        FROM public.crew_members
       WHERE user_id = v_uid
    ),
    listed AS (
      SELECT id                         AS k_crew,
             name                       AS c_name,
             description                AS c_desc,
             COALESCE(max_capacity, 16) AS c_cap,
             is_public                  AS c_public
        FROM public.crews
       WHERE is_public = TRUE
    )
    SELECT k_crew, c_name, c_desc, n_members, c_cap, c_public
      FROM listed
      JOIN counts USING (k_crew)
     WHERE NOT (k_crew IN (SELECT k_crew FROM mine))
       AND n_members = LEAST(n_members, c_cap - 1)
     ORDER BY n_members DESC, k_crew
     LIMIT v_limit;
END;
$$;


ALTER FUNCTION "public"."get_suggested_crews"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_suggested_followees"("p_limit" integer DEFAULT 8) RETURNS TABLE("user_id" "uuid", "username" "text", "avatar_url" "text", "current_level" integer, "follower_count" integer, "active_until" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
#variable_conflict use_column
DECLARE
  v_uid    UUID := auth.uid();
  v_email  TEXT;
  v_limit  INT  := LEAST(GREATEST(COALESCE(p_limit, 8), 1), 20);
  v_since  DATE := (now() AT TIME ZONE 'UTC')::date - INTERVAL '30 days';
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;

  SELECT email INTO v_email FROM public.user_profiles WHERE id = v_uid;

  RETURN QUERY
  WITH
    already_followed AS (
      SELECT followee_email AS followed_email
        FROM public.hub_follows
       WHERE follower_email = v_email
    ),
    follower_counts AS (
      SELECT followee_email AS counted_email,
             COUNT(*)::INT  AS followers
        FROM public.hub_follows
       GROUP BY followee_email
    ),
    eligible AS (
      SELECT id            AS cand_id,
             username      AS cand_username,
             email         AS cand_email,
             avatar_url    AS cand_avatar,
             current_level AS cand_level,
             active_until  AS cand_active_until,
             created_at    AS cand_created_at
        FROM public.user_profiles
       WHERE id <> v_uid
         AND email IS NOT NULL
         AND username IS NOT NULL
         AND username NOT LIKE 'deleted_%'
         AND last_login_date >= v_since
         AND hide_from_search IS NOT TRUE
         AND email NOT IN (SELECT followed_email FROM already_followed)
    )
  SELECT cand_id,
         cand_username,
         cand_avatar,
         cand_level,
         COALESCE(followers, 0),
         cand_active_until
    FROM eligible
    LEFT JOIN follower_counts ON counted_email = cand_email
   ORDER BY COALESCE(followers, 0) DESC, cand_created_at ASC
   LIMIT v_limit;
END;
$$;


ALTER FUNCTION "public"."get_suggested_followees"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_top_crews"("p_metric" "text" DEFAULT 'volume'::"text", "p_limit" integer DEFAULT 25) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_uid    uuid := auth.uid();
  v_metric text := lower(COALESCE(p_metric, 'volume'));
  v_limit  int  := LEAST(GREATEST(COALESCE(p_limit, 25), 3), 100);
  v_season uuid;
  v_out    jsonb;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;

  IF NOT (v_metric IN ('volume', 'trophies', 'points')) THEN
    v_metric := 'volume';
  END IF;

  SELECT id INTO v_season
    FROM public.crew_seasons
   WHERE status = 'active'
   ORDER BY season_number DESC
   LIMIT 1;

  WITH memberships AS (
    SELECT crew_id AS k_crew, user_id AS k_user
      FROM public.crew_members
  ),
  volumes AS (
    SELECT id AS k_user,
           COALESCE(total_volume_lbs, 0)::numeric AS v_member
      FROM public.user_profiles
  ),
  rollup AS (
    SELECT k_crew,
           COUNT(*)::int AS n_members,
           COALESCE(SUM(v_member), 0)::numeric AS n_volume
      FROM memberships
      LEFT JOIN volumes USING (k_user)
     GROUP BY k_crew
  ),
  season_points AS (
    SELECT crew_id AS k_crew,
           COALESCE(points, 0)::numeric AS n_points
      FROM public.crew_season_stats
     WHERE season_id = v_season
  ),
  mine AS (
    SELECT crew_id AS k_crew
      FROM public.crew_members
     WHERE user_id = v_uid
  ),
  listed AS (
    SELECT id                         AS k_crew,
           name                       AS c_name,
           tag                        AS c_tag,
           avatar_url                 AS c_avatar,
           COALESCE(max_capacity, 16) AS c_cap,
           COALESCE(crew_level, 1)    AS c_level,
           COALESCE(trophies, 0)      AS c_trophies
      FROM public.crews
     WHERE is_public = TRUE
  ),
  base AS (
    SELECT k_crew, c_name, c_tag, c_avatar, c_cap, c_level, c_trophies,
           COALESCE(n_members, 0) AS c_members,
           CASE
             WHEN v_metric = 'trophies' THEN c_trophies::numeric
             WHEN v_metric = 'points'   THEN COALESCE(n_points, 0)
             ELSE COALESCE(n_volume, 0)
           END                    AS c_value,
           (k_crew IN (SELECT k_crew FROM mine)) AS c_mine
      FROM listed
      LEFT JOIN rollup        USING (k_crew)
      LEFT JOIN season_points USING (k_crew)
  ),
  ranked AS (
    SELECT *,
           CAST(ROW_NUMBER() OVER (ORDER BY c_value DESC, c_members DESC, k_crew) AS int) AS c_rank
      FROM base
  ),
  me AS (
    SELECT c_rank AS my_rank FROM ranked WHERE c_mine LIMIT 1
  ),
  picked AS (
    SELECT * FROM ranked
     WHERE c_rank = LEAST(c_rank, v_limit)
        OR c_rank BETWEEN (SELECT GREATEST(my_rank - 2, 1) FROM me)
                      AND (SELECT my_rank + 2 FROM me)
  )
  SELECT jsonb_build_object(
           'metric',  v_metric,
           'my_rank', (SELECT my_rank FROM me),
           'total',   (SELECT COUNT(*)::int FROM ranked),
           'rows',    COALESCE((
             SELECT jsonb_agg(jsonb_build_object(
                      'rank',         c_rank,
                      'id',           k_crew,
                      'name',         c_name,
                      'tag',          c_tag,
                      'avatar_url',   c_avatar,
                      'member_count', c_members,
                      'max_capacity', c_cap,
                      'crew_level',   c_level,
                      'trophies',     c_trophies,
                      'value',        c_value,
                      'is_member',    c_mine
                    ) ORDER BY c_rank)
               FROM picked
           ), '[]'::jsonb)
         )
    INTO v_out;

  RETURN v_out;
END;
$$;


ALTER FUNCTION "public"."get_top_crews"("p_metric" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_trophy_progress"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid UUID := auth.uid(); v_email TEXT := COALESCE(auth.email(), '');
  v_workouts NUMERIC := 0; v_volume NUMERIC := 0; v_lifts NUMERIC := 0;
  v_streak NUMERIC := 0; v_months NUMERIC := 0; v_quests NUMERIC := 0;
  v_perfect NUMERIC := 0; v_maxdist NUMERIC := 0; v_totdist NUMERIC := 0;
  v_acttypes NUMERIC := 0; v_level NUMERIC := 1; v_prestige NUMERIC := 0;
  v_goals NUMERIC := 0; v_duelwins NUMERIC := 0; v_bounties NUMERIC := 0;
  v_gaunt NUMERIC := 0; v_gauntpath NUMERIC := 0; v_crew NUMERIC := 0;
  v_crewwars NUMERIC := 0; v_posts NUMERIC := 0; v_checkins NUMERIC := 0;
  v_capsules NUMERIC := 0; v_relics NUMERIC := 0;
  v_meals NUMERIC := 0; v_ndays NUMERIC := 0; v_sleep NUMERIC := 0;
  v_journal NUMERIC := 0; v_debriefs NUMERIC := 0; v_regimens NUMERIC := 0;
  v_duelplay NUMERIC := 0; v_comments NUMERIC := 0; v_followers NUMERIC := 0;
  v_coins NUMERIC := 0; v_market NUMERIC := 0;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE='42501'; END IF;

  SELECT workout_streak, current_level, prestige_level, total_volume_lbs
    INTO v_streak, v_level, v_prestige, v_volume FROM public.user_profiles WHERE id = v_uid;
  v_streak := COALESCE(v_streak,0); v_level := COALESCE(v_level,1);
  v_prestige := COALESCE(v_prestige,0); v_volume := COALESCE(v_volume,0);

  SELECT COUNT(*) INTO v_workouts FROM public.workout_logs WHERE user_id=v_uid OR created_by=v_email;
  SELECT COUNT(DISTINCT date_trunc('month', date)) INTO v_months FROM public.workout_logs
   WHERE (user_id=v_uid OR created_by=v_email) AND date IS NOT NULL;
  SELECT COUNT(DISTINCT lower(trim(elem ->> 'name'))) INTO v_lifts FROM public.workout_logs
    CROSS JOIN LATERAL jsonb_array_elements(exercises) AS elem
   WHERE (user_id=v_uid OR created_by=v_email) AND jsonb_typeof(exercises)='array'
     AND COALESCE(trim(elem ->> 'name'),'') <> '';
  SELECT COALESCE(MAX(distance_meters),0), COALESCE(SUM(distance_meters),0), COUNT(DISTINCT activity_type)
    INTO v_maxdist, v_totdist, v_acttypes FROM public.cardio_logs WHERE user_id=v_uid OR created_by=v_email;
  SELECT quests_claimed, perfect_days INTO v_quests, v_perfect FROM public.user_quest_stats WHERE user_id=v_uid;
  v_quests := COALESCE(v_quests,0); v_perfect := COALESCE(v_perfect,0);
  SELECT COUNT(*) INTO v_goals FROM public.goals WHERE (user_id=v_uid OR created_by=v_email) AND status='completed';
  SELECT COUNT(*) INTO v_duelwins FROM public.duels WHERE winner_id=v_uid;
  SELECT COUNT(*) INTO v_duelplay FROM public.duels WHERE challenger_id=v_uid OR opponent_id=v_uid;
  SELECT COUNT(*) INTO v_bounties FROM public.bounties WHERE claimed_by_id=v_uid;
  SELECT challenges_completed, CASE WHEN COALESCE(path_completed,false) THEN 1 ELSE 0 END
    INTO v_gaunt, v_gauntpath FROM public.user_gauntlet_progress WHERE user_id=v_uid;
  v_gaunt := COALESCE(v_gaunt,0); v_gauntpath := COALESCE(v_gauntpath,0);
  SELECT COUNT(*) INTO v_crew FROM public.crew_members WHERE user_id=v_uid;
  SELECT COUNT(DISTINCT war_id) INTO v_crewwars FROM public.crew_war_contributions WHERE user_id=v_uid;
  SELECT COUNT(*) INTO v_posts FROM public.hub_posts WHERE user_id=v_uid OR created_by=v_email;
  SELECT COUNT(*) INTO v_checkins FROM public.gym_checkins WHERE user_id=v_uid;
  SELECT COUNT(*) INTO v_capsules FROM public.user_capsules WHERE user_id=v_uid AND COALESCE(is_opened,false);
  SELECT COUNT(*) INTO v_relics FROM public.user_inventory
   WHERE user_id=v_uid AND item_rarity IN ('legendary','mythic','animated');

  SELECT COUNT(*) INTO v_meals FROM public.nutrition_logs WHERE user_id=v_uid OR created_by=v_email;
  SELECT COUNT(DISTINCT date) INTO v_ndays FROM public.nutrition_logs
   WHERE (user_id=v_uid OR created_by=v_email) AND date IS NOT NULL;
  SELECT COUNT(*) INTO v_sleep FROM public.sleep_logs WHERE user_id=v_uid;
  SELECT COUNT(*) INTO v_journal FROM public.journal_entries WHERE user_id=v_uid;
  SELECT COUNT(*) INTO v_debriefs FROM public.weekly_debriefs WHERE user_id=v_uid;
  SELECT COUNT(*) INTO v_regimens FROM public.regimens WHERE user_id=v_uid OR created_by=v_email;
  SELECT COUNT(*) INTO v_comments FROM public.hub_comments WHERE user_id=v_uid OR created_by=v_email;
  SELECT COUNT(*) INTO v_followers FROM public.hub_follows WHERE followee_id=v_uid;
  SELECT COALESCE(SUM(delta),0) INTO v_coins FROM public.flex_coin_ledger WHERE user_id=v_uid AND delta>0;
  SELECT COUNT(*) INTO v_market FROM public.marketplace_listings WHERE seller_user_id=v_uid AND status='completed';

  RETURN jsonb_build_object(
    'workouts',v_workouts,'volumeLbs',v_volume,'distinctLifts',v_lifts,'workoutStreak',v_streak,
    'activeMonths',v_months,'questsClaimed',v_quests,'perfectDays',v_perfect,'maxDistanceM',v_maxdist,
    'totalDistanceM',v_totdist,'activityTypes',v_acttypes,'level',v_level,'prestige',v_prestige,
    'goalsDone',v_goals,'duelWins',v_duelwins,'bountiesClaimed',v_bounties,'gauntletDone',v_gaunt,
    'gauntletPath',v_gauntpath,'crewCount',v_crew,'crewWars',v_crewwars,'posts',v_posts,
    'checkins',v_checkins,'capsulesOpened',v_capsules,'legendaries',v_relics,
    'meals',v_meals,'nutritionDays',v_ndays,'sleepLogs',v_sleep,'journalEntries',v_journal,
    'debriefs',v_debriefs,'regimens',v_regimens,'duelsPlayed',v_duelplay,'comments',v_comments,
    'followers',v_followers,'coinsEarned',v_coins,'marketSales',v_market);
END; $$;


ALTER FUNCTION "public"."get_trophy_progress"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."gift_flex_coins"("p_recipient_id" "uuid", "p_amount" integer, "p_message" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_sender UUID := auth.uid();
  v_sender_balance INTEGER;
  v_sender_username TEXT;
  v_recipient_email TEXT;
  v_recipient_lang  TEXT;
  v_gift_id UUID;
BEGIN
  IF v_sender IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;
  IF p_recipient_id IS NULL THEN
    RAISE EXCEPTION 'recipient_id required' USING ERRCODE = '22023';
  END IF;
  IF p_amount IS NULL OR p_amount < 1 OR p_amount > 10000 THEN
    RAISE EXCEPTION 'amount must be 1..10000' USING ERRCODE = '22023';
  END IF;
  IF p_recipient_id = v_sender THEN
    RETURN jsonb_build_object('ok', false, 'error', 'SELF_GIFT');
  END IF;

  SELECT flex_coins, username
    INTO v_sender_balance, v_sender_username
    FROM public.user_profiles
    WHERE id = v_sender
    FOR UPDATE;

  IF v_sender_balance IS NULL THEN
    RAISE EXCEPTION 'sender profile missing' USING ERRCODE = '22023';
  END IF;
  IF v_sender_balance < p_amount THEN
    RETURN jsonb_build_object('ok', false, 'error', 'INSUFFICIENT_FUNDS',
      'balance', v_sender_balance);
  END IF;

  SELECT u.email, prof.preferred_language
    INTO v_recipient_email, v_recipient_lang
    FROM auth.users u
    LEFT JOIN public.user_profiles prof ON prof.id = u.id
   WHERE u.id = p_recipient_id;
  IF v_recipient_email IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'RECIPIENT_NOT_FOUND');
  END IF;

  UPDATE public.user_profiles
     SET flex_coins = GREATEST(0, COALESCE(flex_coins, 0) - p_amount)
   WHERE id = v_sender;

  UPDATE public.user_profiles
     SET flex_coins = COALESCE(flex_coins, 0) + p_amount
   WHERE id = p_recipient_id;

  INSERT INTO public.coin_gifts (sender_id, recipient_id, amount, message)
  VALUES (v_sender, p_recipient_id, p_amount, NULLIF(p_message, ''))
  RETURNING id INTO v_gift_id;

  INSERT INTO public.notifications
    (user_id, user_email, type, title, body, icon, link_url, metadata)
  VALUES
    (p_recipient_id,
     v_recipient_email,
     'coin_gift',
     'You received a coin gift!',
     COALESCE('@' || NULLIF(v_sender_username, '') || ' sent you ' || p_amount::text || ' coins',
              'You received ' || p_amount::text || ' coins'),
     '💰',
     '/hub',
     jsonb_build_object(
       'amount',         p_amount,
       'senderId',       v_sender,
       'senderUsername', v_sender_username,
       'giftMessage',    NULLIF(p_message, ''),
       'giftId',         v_gift_id
     ));

  RETURN jsonb_build_object('ok', true, 'giftId', v_gift_id, 'amount', p_amount);
END;
$$;


ALTER FUNCTION "public"."gift_flex_coins"("p_recipient_id" "uuid", "p_amount" integer, "p_message" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."grant_achievement_milestones"("p_unlocked_count" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid             UUID := auth.uid();
  v_email           TEXT;
  v_server_count    INT;
  v_safe_count      INT;
  v_already_awarded INT;
  v_milestone       RECORD;
  v_granted_count   INT := 0;
  v_granted_payload JSONB := '[]'::jsonb;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;
  IF p_unlocked_count IS NULL OR p_unlocked_count < 0 THEN
    RAISE EXCEPTION 'invalid unlocked_count' USING ERRCODE = '22023';
  END IF;

  SELECT email, COALESCE(milestone_capsules_awarded, 0)
    INTO v_email, v_already_awarded
    FROM public.user_profiles WHERE id = v_uid FOR UPDATE;

  IF v_email IS NULL THEN
    RAISE EXCEPTION 'user_profile not found' USING ERRCODE = '22023';
  END IF;

  SELECT COUNT(*)::int INTO v_server_count
    FROM public.user_trophies WHERE user_id = v_uid;

  v_safe_count := LEAST(p_unlocked_count, v_server_count);

  FOR v_milestone IN
    SELECT * FROM (VALUES
      (1, 5, 'standard'), (2, 10, 'standard'), (3, 25, 'premium'),
      (4, 50, 'premium'), (5, 100, 'elite')
    ) AS m(idx, threshold, capsule_type)
    WHERE m.threshold <= v_safe_count AND m.idx > v_already_awarded
    ORDER BY m.idx
  LOOP
    INSERT INTO public.user_capsules (user_id, user_email, capsule_type)
    VALUES (v_uid, v_email, v_milestone.capsule_type);
    v_granted_count := v_granted_count + 1;
    v_granted_payload := v_granted_payload || jsonb_build_object(
      'threshold', v_milestone.threshold, 'type', v_milestone.capsule_type);
  END LOOP;

  IF v_granted_count = 0 THEN
    RETURN jsonb_build_object('granted_count', 0, 'granted', '[]'::jsonb,
      'awarded_total', v_already_awarded, 'server_count', v_server_count);
  END IF;

  UPDATE public.user_profiles
     SET milestone_capsules_awarded = v_already_awarded + v_granted_count
   WHERE id = v_uid;

  RETURN jsonb_build_object('granted_count', v_granted_count,
    'granted', v_granted_payload,
    'awarded_total', v_already_awarded + v_granted_count,
    'server_count', v_server_count);
END;
$$;


ALTER FUNCTION "public"."grant_achievement_milestones"("p_unlocked_count" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."grant_action_xp"("p_action_type" "text", "p_xp" integer) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid    uuid    := auth.uid();
  v_day    date;
  v_before integer;
  v_cap    integer;
  v_credit integer;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE='42501'; END IF;
  IF p_xp IS NULL OR p_xp <= 0 THEN RETURN 0; END IF;

  v_cap := CASE p_action_type
    WHEN 'workout_completed' THEN 4000
    WHEN 'cardio_completed'  THEN 2400
    WHEN 'comeback_bonus'    THEN 200
    WHEN 'water_logged'      THEN 24
    WHEN 'meal_logged'       THEN 30
    WHEN 'recipe_created'    THEN 75
    WHEN 'regimen_created'   THEN 200
    WHEN 'goal_completed'    THEN 500
    WHEN 'crew_xp_fuel'      THEN 100
    WHEN 'daily_quest'       THEN 400
    WHEN 'quest_perfect_day' THEN 150
    ELSE NULL
  END;

  IF v_cap IS NULL THEN RETURN 0; END IF;

  v_day := (public.user_local_now(v_uid))::date;
  IF v_day IS NULL THEN
    v_day := (now() AT TIME ZONE 'utc')::date;
  END IF;

  SELECT COALESCE(amount, 0) INTO v_before
    FROM public.action_xp_ledger
   WHERE user_id = v_uid AND day = v_day AND action_type = p_action_type;
  v_before := COALESCE(v_before, 0);

  v_credit := LEAST(p_xp, GREATEST(0, v_cap - v_before));
  IF v_credit <= 0 THEN RETURN 0; END IF;

  INSERT INTO public.action_xp_ledger (user_id, day, action_type, amount)
  VALUES (v_uid, v_day, p_action_type, v_credit)
  ON CONFLICT (user_id, day, action_type)
  DO UPDATE SET amount = public.action_xp_ledger.amount + v_credit;

  PERFORM public.increment_user_xp(v_uid, v_credit);
  RETURN v_credit;
END;
$$;


ALTER FUNCTION "public"."grant_action_xp"("p_action_type" "text", "p_xp" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."grant_eligible_trophies"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid    UUID := auth.uid();
  v_email  TEXT := COALESCE(auth.email(), '');
  v_sig    JSONB;
  v_new    TEXT[] := ARRAY[]::TEXT[];
  v_round  TEXT[];
  v_cap    INTEGER := 50;
  v_pass   INTEGER;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;

  v_sig := public.get_trophy_progress();

  FOR v_pass IN 1..6 LOOP
    WITH owned (tid) AS (
      SELECT trophy_id FROM public.user_trophies WHERE user_id = v_uid
    ),
    named (tid, needed, have) AS (
      VALUES
        ('first_rep',        1::numeric,       (v_sig ->> 'workouts')::numeric),
        ('consistent',       10,               (v_sig ->> 'workouts')::numeric),
        ('committed',        50,               (v_sig ->> 'workouts')::numeric),
        ('centurion',        100,              (v_sig ->> 'workouts')::numeric),
        ('tonnage_ton',      2000,             (v_sig ->> 'volumeLbs')::numeric),
        ('tonnage_10t',      20000,            (v_sig ->> 'volumeLbs')::numeric),
        ('tonnage_100t',     200000,           (v_sig ->> 'volumeLbs')::numeric),
        ('tonnage_million',  1000000,          (v_sig ->> 'volumeLbs')::numeric),
        ('variety_10',       10,               (v_sig ->> 'distinctLifts')::numeric),
        ('variety_25',       25,               (v_sig ->> 'distinctLifts')::numeric),
        ('variety_50',       50,               (v_sig ->> 'distinctLifts')::numeric),
        ('variety_100',      100,              (v_sig ->> 'distinctLifts')::numeric),
        ('regimen_1',        1,                (v_sig ->> 'regimens')::numeric),
        ('regimen_5',        5,                (v_sig ->> 'regimens')::numeric),
        ('regimen_10',       10,               (v_sig ->> 'regimens')::numeric),
        ('regimen_25',       25,               (v_sig ->> 'regimens')::numeric),
        ('streak_spark',     7,                (v_sig ->> 'workoutStreak')::numeric),
        ('streak_blaze',     30,               (v_sig ->> 'workoutStreak')::numeric),
        ('streak_inferno',   100,              (v_sig ->> 'workoutStreak')::numeric),
        ('streak_eternal',   365,              (v_sig ->> 'workoutStreak')::numeric),
        ('longevity_3',      3,                (v_sig ->> 'activeMonths')::numeric),
        ('longevity_6',      6,                (v_sig ->> 'activeMonths')::numeric),
        ('longevity_12',     12,               (v_sig ->> 'activeMonths')::numeric),
        ('longevity_24',     24,               (v_sig ->> 'activeMonths')::numeric),
        ('quest_10',         10,               (v_sig ->> 'questsClaimed')::numeric),
        ('quest_100',        100,              (v_sig ->> 'questsClaimed')::numeric),
        ('quest_500',        500,              (v_sig ->> 'questsClaimed')::numeric),
        ('perfect_7',        7,                (v_sig ->> 'perfectDays')::numeric),
        ('perfect_30',       30,               (v_sig ->> 'perfectDays')::numeric),
        ('perfect_100',      100,              (v_sig ->> 'perfectDays')::numeric),
        ('cardio_5k',        5000,             (v_sig ->> 'maxDistanceM')::numeric),
        ('cardio_10k',       10000,            (v_sig ->> 'maxDistanceM')::numeric),
        ('cardio_half',      21097,            (v_sig ->> 'maxDistanceM')::numeric),
        ('cardio_marathon',  42195,            (v_sig ->> 'maxDistanceM')::numeric),
        ('distance_50k',     50000,            (v_sig ->> 'totalDistanceM')::numeric),
        ('distance_250k',    250000,           (v_sig ->> 'totalDistanceM')::numeric),
        ('distance_1000k',   1000000,          (v_sig ->> 'totalDistanceM')::numeric),
        ('cross_3',          3,                (v_sig ->> 'activityTypes')::numeric),
        ('cross_5',          5,                (v_sig ->> 'activityTypes')::numeric),
        ('cross_8',          8,                (v_sig ->> 'activityTypes')::numeric),
        ('meal_1',           1,                (v_sig ->> 'meals')::numeric),
        ('meal_50',          50,               (v_sig ->> 'meals')::numeric),
        ('meal_250',         250,              (v_sig ->> 'meals')::numeric),
        ('meal_1000',        1000,             (v_sig ->> 'meals')::numeric),
        ('nday_7',           7,                (v_sig ->> 'nutritionDays')::numeric),
        ('nday_30',          30,               (v_sig ->> 'nutritionDays')::numeric),
        ('nday_100',         100,              (v_sig ->> 'nutritionDays')::numeric),
        ('nday_365',         365,              (v_sig ->> 'nutritionDays')::numeric),
        ('sleep_7',          7,                (v_sig ->> 'sleepLogs')::numeric),
        ('sleep_30',         30,               (v_sig ->> 'sleepLogs')::numeric),
        ('sleep_100',        100,              (v_sig ->> 'sleepLogs')::numeric),
        ('journal_1',        1,                (v_sig ->> 'journalEntries')::numeric),
        ('journal_10',       10,               (v_sig ->> 'journalEntries')::numeric),
        ('journal_50',       50,               (v_sig ->> 'journalEntries')::numeric),
        ('debrief_1',        1,                (v_sig ->> 'debriefs')::numeric),
        ('debrief_10',       10,               (v_sig ->> 'debriefs')::numeric),
        ('debrief_52',       52,               (v_sig ->> 'debriefs')::numeric),
        ('level_tier1',      10,               (v_sig ->> 'level')::numeric),
        ('level_tier2',      25,               (v_sig ->> 'level')::numeric),
        ('level_tier3',      50,               (v_sig ->> 'level')::numeric),
        ('level_apex',       100,              (v_sig ->> 'level')::numeric),
        ('prestige_1',       1,                (v_sig ->> 'prestige')::numeric),
        ('prestige_3',       3,                (v_sig ->> 'prestige')::numeric),
        ('prestige_5',       5,                (v_sig ->> 'prestige')::numeric),
        ('goal_first',       1,                (v_sig ->> 'goalsDone')::numeric),
        ('goal_10',          10,               (v_sig ->> 'goalsDone')::numeric),
        ('goal_50',          50,               (v_sig ->> 'goalsDone')::numeric),
        ('duel_challenger',  1,                (v_sig ->> 'duelWins')::numeric),
        ('duel_champion',    10,               (v_sig ->> 'duelWins')::numeric),
        ('duel_gladiator',   50,               (v_sig ->> 'duelWins')::numeric),
        ('duel_immortal',    200,              (v_sig ->> 'duelWins')::numeric),
        ('duelplay_1',       1,                (v_sig ->> 'duelsPlayed')::numeric),
        ('duelplay_25',      25,               (v_sig ->> 'duelsPlayed')::numeric),
        ('duelplay_100',     100,              (v_sig ->> 'duelsPlayed')::numeric),
        ('bounty_1',         1,                (v_sig ->> 'bountiesClaimed')::numeric),
        ('bounty_10',        10,               (v_sig ->> 'bountiesClaimed')::numeric),
        ('bounty_50',        50,               (v_sig ->> 'bountiesClaimed')::numeric),
        ('gauntlet_5',       5,                (v_sig ->> 'gauntletDone')::numeric),
        ('gauntlet_path',    1,                (v_sig ->> 'gauntletPath')::numeric),
        ('crew_squad',       1,                (v_sig ->> 'crewCount')::numeric),
        ('crewwar_1',        1,                (v_sig ->> 'crewWars')::numeric),
        ('crewwar_10',       10,               (v_sig ->> 'crewWars')::numeric),
        ('crewwar_50',       50,               (v_sig ->> 'crewWars')::numeric),
        ('post_1',           1,                (v_sig ->> 'posts')::numeric),
        ('post_10',          10,               (v_sig ->> 'posts')::numeric),
        ('post_50',          50,               (v_sig ->> 'posts')::numeric),
        ('post_200',         200,              (v_sig ->> 'posts')::numeric),
        ('comment_1',        1,                (v_sig ->> 'comments')::numeric),
        ('comment_25',       25,               (v_sig ->> 'comments')::numeric),
        ('comment_100',      100,              (v_sig ->> 'comments')::numeric),
        ('follower_1',       1,                (v_sig ->> 'followers')::numeric),
        ('follower_10',      10,               (v_sig ->> 'followers')::numeric),
        ('follower_50',      50,               (v_sig ->> 'followers')::numeric),
        ('follower_200',     200,              (v_sig ->> 'followers')::numeric),
        ('checkin_1',        1,                (v_sig ->> 'checkins')::numeric),
        ('checkin_25',       25,               (v_sig ->> 'checkins')::numeric),
        ('checkin_100',      100,              (v_sig ->> 'checkins')::numeric),
        ('checkin_365',      365,              (v_sig ->> 'checkins')::numeric),
        ('capsule_1',        1,                (v_sig ->> 'capsulesOpened')::numeric),
        ('capsule_25',       25,               (v_sig ->> 'capsulesOpened')::numeric),
        ('capsule_100',      100,              (v_sig ->> 'capsulesOpened')::numeric),
        ('relic_1',          1,                (v_sig ->> 'legendaries')::numeric),
        ('relic_5',          5,                (v_sig ->> 'legendaries')::numeric),
        ('relic_25',         25,               (v_sig ->> 'legendaries')::numeric),
        ('coin_1k',          1000,             (v_sig ->> 'coinsEarned')::numeric),
        ('coin_10k',         10000,            (v_sig ->> 'coinsEarned')::numeric),
        ('coin_100k',        100000,           (v_sig ->> 'coinsEarned')::numeric),
        ('market_1',         1,                (v_sig ->> 'marketSales')::numeric),
        ('market_10',        10,               (v_sig ->> 'marketSales')::numeric),
        ('market_50',        50,               (v_sig ->> 'marketSales')::numeric),
        ('capstone_iron',         0, 0),
        ('capstone_consistency',  0, 0),
        ('capstone_endurance',    0, 0),
        ('capstone_nutrition',    0, 0),
        ('capstone_recovery',     0, 0),
        ('capstone_progression',  0, 0),
        ('capstone_arena',        0, 0),
        ('capstone_community',    0, 0),
        ('capstone_collection',   0, 0),
        ('capstone_apex',         0, 0)
    ),
    reqs (tid, req) AS (
      VALUES
        ('crewwar_1', 'crew_squad'),
        ('capstone_iron','centurion'), ('capstone_iron','tonnage_million'),
        ('capstone_iron','variety_100'), ('capstone_iron','regimen_25'),
        ('capstone_consistency','streak_eternal'), ('capstone_consistency','longevity_24'),
        ('capstone_consistency','quest_500'), ('capstone_consistency','perfect_100'),
        ('capstone_endurance','cardio_marathon'), ('capstone_endurance','distance_1000k'),
        ('capstone_endurance','cross_8'),
        ('capstone_nutrition','meal_1000'), ('capstone_nutrition','nday_365'),
        ('capstone_recovery','sleep_100'), ('capstone_recovery','journal_50'),
        ('capstone_recovery','debrief_52'),
        ('capstone_progression','level_apex'), ('capstone_progression','prestige_5'),
        ('capstone_progression','goal_50'),
        ('capstone_arena','duel_immortal'), ('capstone_arena','duelplay_100'),
        ('capstone_arena','bounty_50'), ('capstone_arena','gauntlet_path'),
        ('capstone_community','crewwar_50'), ('capstone_community','post_200'),
        ('capstone_community','comment_100'), ('capstone_community','follower_200'),
        ('capstone_community','checkin_365'),
        ('capstone_collection','capsule_100'), ('capstone_collection','relic_25'),
        ('capstone_collection','coin_100k'), ('capstone_collection','market_50'),
        ('capstone_apex','capstone_iron'), ('capstone_apex','capstone_consistency'),
        ('capstone_apex','capstone_endurance'), ('capstone_apex','capstone_nutrition'),
        ('capstone_apex','capstone_recovery'), ('capstone_apex','capstone_progression'),
        ('capstone_apex','capstone_arena'), ('capstone_apex','capstone_community'),
        ('capstone_apex','capstone_collection')
    ),
    ladder (lad, base, step, have) AS (
      VALUES
        ('sessions',  100::numeric,     100::numeric,     (v_sig ->> 'workouts')::numeric),
        ('tonnage',   1000000,          1000000,          (v_sig ->> 'volumeLbs')::numeric),
        ('variety',   100,              50,               (v_sig ->> 'distinctLifts')::numeric),
        ('regimen',   25,               25,               (v_sig ->> 'regimens')::numeric),
        ('streak',    365,              365,              (v_sig ->> 'workoutStreak')::numeric),
        ('longevity', 24,               12,               (v_sig ->> 'activeMonths')::numeric),
        ('quests',    500,              500,              (v_sig ->> 'questsClaimed')::numeric),
        ('perfect',   100,              100,              (v_sig ->> 'perfectDays')::numeric),
        ('distance',  1000000,          1000000,          (v_sig ->> 'totalDistanceM')::numeric),
        ('meals',     1000,             1000,             (v_sig ->> 'meals')::numeric),
        ('ndays',     365,              365,              (v_sig ->> 'nutritionDays')::numeric),
        ('sleep',     100,              100,              (v_sig ->> 'sleepLogs')::numeric),
        ('journal',   50,               50,               (v_sig ->> 'journalEntries')::numeric),
        ('debrief',   52,               52,               (v_sig ->> 'debriefs')::numeric),
        ('prestige',  5,                1,                (v_sig ->> 'prestige')::numeric),
        ('goals',     50,               50,               (v_sig ->> 'goalsDone')::numeric),
        ('duel',      200,              200,              (v_sig ->> 'duelWins')::numeric),
        ('duelplay',  100,              100,              (v_sig ->> 'duelsPlayed')::numeric),
        ('bounty',    50,               50,               (v_sig ->> 'bountiesClaimed')::numeric),
        ('crewwar',   50,               50,               (v_sig ->> 'crewWars')::numeric),
        ('social',    200,              200,              (v_sig ->> 'posts')::numeric),
        ('comments',  100,              100,              (v_sig ->> 'comments')::numeric),
        ('followers', 200,              200,              (v_sig ->> 'followers')::numeric),
        ('gym',       365,              365,              (v_sig ->> 'checkins')::numeric),
        ('capsule',   100,              100,              (v_sig ->> 'capsulesOpened')::numeric),
        ('relic',     25,               25,               (v_sig ->> 'legendaries')::numeric),
        ('coins',     100000,           100000,           (v_sig ->> 'coinsEarned')::numeric),
        ('market',    50,               50,               (v_sig ->> 'marketSales')::numeric)
    ),
    tails (tid) AS (
      SELECT lad || '_x' || k
        FROM ladder
        CROSS JOIN LATERAL generate_series(
          1,
          LEAST(v_cap::numeric, GREATEST(0::numeric, floor((have - base) / step)))::integer
        ) AS k
    ),
    candidate (tid) AS (
      SELECT tid FROM named WHERE have >= needed
      UNION
      SELECT tid FROM tails
    ),
    unmet (tid) AS (
      SELECT tid FROM reqs WHERE req NOT IN (SELECT tid FROM owned)
    ),
    eligible (tid) AS (
      SELECT tid FROM candidate
      EXCEPT
      SELECT tid FROM unmet
    ),
    ins AS (
      INSERT INTO public.user_trophies (user_id, user_email, trophy_id)
      SELECT v_uid, v_email, tid FROM eligible
      ON CONFLICT (user_id, trophy_id) DO NOTHING
      RETURNING trophy_id
    )
    SELECT COALESCE(array_agg(trophy_id), ARRAY[]::TEXT[]) INTO v_round FROM ins;

    v_new := v_new || v_round;
    EXIT WHEN array_length(v_round, 1) IS NULL;
  END LOOP;

  UPDATE public.user_profiles
     SET achievements_unlocked_count = (
           SELECT count(*) FROM public.user_trophies WHERE user_id = v_uid)
   WHERE id = v_uid;

  RETURN jsonb_build_object('newly_granted', to_jsonb(v_new));
END;
$$;


ALTER FUNCTION "public"."grant_eligible_trophies"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."grant_first_workout_capsule"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid     UUID := auth.uid();
  v_email   TEXT;
  v_already BOOLEAN;
  v_balance INTEGER;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;

  SELECT email, COALESCE(first_workout_capsule_granted, FALSE)
    INTO v_email, v_already
    FROM public.user_profiles WHERE id = v_uid FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'profile not found' USING ERRCODE = '22023';
  END IF;

  IF v_already THEN
    RETURN jsonb_build_object('granted', false, 'reason', 'already_granted');
  END IF;

  IF v_email IS NULL OR v_email = '' THEN
    v_email := 'guest_' || v_uid || '@flexyn.guest';
  END IF;

  INSERT INTO public.user_capsules (user_id, user_email, capsule_type)
  VALUES (v_uid, v_email, 'premium');

  UPDATE public.user_profiles
     SET flex_coins = COALESCE(flex_coins, 0) + 75,
         first_workout_capsule_granted = TRUE
   WHERE id = v_uid
  RETURNING flex_coins INTO v_balance;

  RETURN jsonb_build_object(
    'granted',      true,
    'capsule_type', 'premium',
    'coins',        75,
    'new_balance',  v_balance
  );
END;
$$;


ALTER FUNCTION "public"."grant_first_workout_capsule"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."grant_flex_coins"("p_user_id" "uuid", "p_delta" integer) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF p_user_id IS NULL THEN
    RAISE EXCEPTION 'no user_id' USING ERRCODE = '22023';
  END IF;
  IF p_delta IS NULL OR p_delta = 0 THEN RETURN; END IF;
  UPDATE public.user_profiles
     SET flex_coins = GREATEST(0, COALESCE(flex_coins, 0) + p_delta)
   WHERE id = p_user_id;
END;
$$;


ALTER FUNCTION "public"."grant_flex_coins"("p_user_id" "uuid", "p_delta" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."grant_league_shield"("p_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  c_lifetime_cap CONSTANT INTEGER := 3;
  v_lifetime INTEGER;
  v_owned    INTEGER;
BEGIN
  IF p_user_id IS NULL THEN
    RAISE EXCEPTION 'user_id required' USING ERRCODE = '22023';
  END IF;

  SELECT COALESCE(league_shields_lifetime, 0), COALESCE(league_shields_owned, 0)
    INTO v_lifetime, v_owned
    FROM public.user_profiles WHERE id = p_user_id;

  IF v_lifetime IS NULL THEN
    RAISE EXCEPTION 'no such profile' USING ERRCODE = '22023';
  END IF;

  IF v_lifetime >= c_lifetime_cap THEN
    RETURN jsonb_build_object('granted', FALSE, 'reason', 'lifetime_cap',
                              'owned', v_owned, 'lifetime', v_lifetime);
  END IF;

  UPDATE public.user_profiles
     SET league_shields_owned    = COALESCE(league_shields_owned, 0) + 1,
         league_shields_lifetime = COALESCE(league_shields_lifetime, 0) + 1
   WHERE id = p_user_id;

  RETURN jsonb_build_object('granted', TRUE, 'owned', v_owned + 1,
                            'lifetime', v_lifetime + 1, 'cap', c_lifetime_cap);
END;
$$;


ALTER FUNCTION "public"."grant_league_shield"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."grant_level_up_rewards"("p_new_level" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid             UUID := auth.uid();
  v_email           TEXT;
  v_prev_through    INT;
  v_level_cap       INT;
  v_lvl             INT;
  v_standard_count  INT := 0;
  v_premium_count   INT := 0;
  v_elite_count     INT := 0;
  v_coins_total     INT := 0;
  v_new_balance     INT;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;
  IF p_new_level IS NULL OR p_new_level < 1 THEN
    RAISE EXCEPTION 'invalid level' USING ERRCODE = '22023';
  END IF;

  SELECT COALESCE(level_capsules_awarded_through, 0),
         email,
         GREATEST(COALESCE(current_level, 1), 1)
    INTO v_prev_through, v_email, v_level_cap
    FROM public.user_profiles
   WHERE id = v_uid
   FOR UPDATE;

  IF p_new_level > v_level_cap THEN
    p_new_level := v_level_cap;
  END IF;

  UPDATE public.user_profiles
     SET level_capsules_awarded_through = p_new_level
   WHERE id = v_uid
     AND COALESCE(level_capsules_awarded_through, 0) = v_prev_through
     AND v_prev_through < p_new_level;

  IF NOT FOUND THEN
    SELECT flex_coins INTO v_new_balance
      FROM public.user_profiles WHERE id = v_uid;
    RETURN jsonb_build_object(
      'already_granted', TRUE,
      'awarded_through', v_prev_through,
      'standard',        0,
      'premium',         0,
      'elite',           0,
      'coins',           0,
      'new_balance',     COALESCE(v_new_balance, 0)
    );
  END IF;

  FOR v_lvl IN GREATEST(v_prev_through + 1, 2) .. p_new_level LOOP
    v_coins_total := v_coins_total + 25;

    IF v_lvl % 3 = 0 THEN
      INSERT INTO public.user_capsules (user_id, user_email, capsule_type)
        VALUES (v_uid, v_email, 'standard');
      v_standard_count := v_standard_count + 1;
    END IF;

    IF v_lvl % 10 = 0 THEN
      INSERT INTO public.user_capsules (user_id, user_email, capsule_type)
        VALUES (v_uid, v_email, 'premium');
      v_premium_count := v_premium_count + 1;
      v_coins_total := v_coins_total + 100;
    END IF;

    IF v_lvl % 25 = 0 THEN
      INSERT INTO public.user_capsules (user_id, user_email, capsule_type)
        VALUES (v_uid, v_email, 'elite');
      v_elite_count := v_elite_count + 1;
    END IF;
  END LOOP;

  UPDATE public.user_profiles
     SET flex_coins = COALESCE(flex_coins, 0) + v_coins_total
   WHERE id = v_uid
  RETURNING flex_coins INTO v_new_balance;

  RETURN jsonb_build_object(
    'already_granted', FALSE,
    'awarded_through', p_new_level,
    'standard',        v_standard_count,
    'premium',         v_premium_count,
    'elite',           v_elite_count,
    'coins',           v_coins_total,
    'new_balance',     COALESCE(v_new_balance, 0)
  );
END;
$$;


ALTER FUNCTION "public"."grant_level_up_rewards"("p_new_level" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."grant_streak_capsule"("p_kind" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid     UUID := auth.uid();
  v_email   TEXT;
  v_day     INTEGER;
  v_through INTEGER;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;
  IF p_kind IS NULL OR p_kind NOT IN ('login', 'workout') THEN
    RAISE EXCEPTION 'kind must be login or workout' USING ERRCODE = '22023';
  END IF;

  IF p_kind = 'login' THEN
    SELECT COALESCE(login_streak, 0), COALESCE(login_streak_capsule_through, 0), email
      INTO v_day, v_through, v_email
      FROM public.user_profiles WHERE id = v_uid FOR UPDATE;
  ELSE
    SELECT COALESCE(workout_streak, 0), COALESCE(workout_streak_capsule_through, 0), email
      INTO v_day, v_through, v_email
      FROM public.user_profiles WHERE id = v_uid FOR UPDATE;
  END IF;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'profile not found' USING ERRCODE = '22023';
  END IF;

  IF v_day NOT IN (30, 60, 100) THEN
    RETURN jsonb_build_object('granted', false, 'reason', 'not_a_milestone', 'day', v_day);
  END IF;

  IF v_through >= v_day THEN
    RETURN jsonb_build_object('granted', false, 'reason', 'already_granted', 'day', v_day);
  END IF;

  IF v_email IS NULL OR v_email = '' THEN
    v_email := 'guest_' || v_uid || '@flexyn.guest';
  END IF;

  INSERT INTO public.user_capsules (user_id, user_email, capsule_type)
  VALUES (v_uid, v_email, 'elite');

  IF p_kind = 'login' THEN
    UPDATE public.user_profiles SET login_streak_capsule_through = v_day WHERE id = v_uid;
  ELSE
    UPDATE public.user_profiles SET workout_streak_capsule_through = v_day WHERE id = v_uid;
  END IF;

  RETURN jsonb_build_object('granted', true, 'capsule_type', 'elite', 'day', v_day);
END;
$$;


ALTER FUNCTION "public"."grant_streak_capsule"("p_kind" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."grant_welcome_capsule"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid      UUID := auth.uid();
  v_email    TEXT;
  v_existing INTEGER;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;

  SELECT email INTO v_email
    FROM public.user_profiles WHERE id = v_uid FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'profile not found' USING ERRCODE = '22023';
  END IF;

  SELECT count(*) INTO v_existing
    FROM public.user_capsules WHERE user_id = v_uid;

  IF v_existing > 0 THEN
    RETURN jsonb_build_object('granted', false, 'reason', 'already_has_capsules');
  END IF;

  IF v_email IS NULL OR v_email = '' THEN
    v_email := 'guest_' || v_uid || '@flexyn.guest';
  END IF;

  INSERT INTO public.user_capsules (user_id, user_email, capsule_type)
  VALUES (v_uid, v_email, 'standard');

  RETURN jsonb_build_object('granted', true, 'capsule_type', 'standard');
END;
$$;


ALTER FUNCTION "public"."grant_welcome_capsule"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."grant_xp_milestone_achievements"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid   UUID := auth.uid();
  v_email TEXT := COALESCE(NULLIF(public.current_user_email(), ''), '');
  v_total INTEGER;
  v_new   JSONB := '[]'::jsonb;
  v_count INTEGER;
  v_row   RECORD;
  v_has   BOOLEAN;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;

  SELECT COALESCE(total_xp, 0) INTO v_total
    FROM public.user_profiles WHERE id = v_uid;

  IF v_total IS NULL THEN
    RETURN jsonb_build_object('new_achievements', v_new, 'unlocked_count', 0);
  END IF;

  FOR v_row IN
    SELECT * FROM (VALUES
      ('xp_250',   250,   10,  'First Steps'),
      ('xp_1000',  1000,  25,  'Getting Serious'),
      ('xp_5000',  5000,  50,  'Dedicated'),
      ('xp_10000', 10000, 100, 'Elite Athlete'),
      ('xp_25000', 25000, 200, 'Legend')
    ) AS m(tid, threshold, bonus, label)
    ORDER BY threshold
  LOOP
    IF v_total >= v_row.threshold THEN
      SELECT EXISTS (
        SELECT 1 FROM public.user_trophies
         WHERE user_id = v_uid AND trophy_id = v_row.tid
      ) INTO v_has;

      IF NOT v_has THEN
        INSERT INTO public.user_trophies (user_id, user_email, trophy_id)
        VALUES (v_uid, v_email, v_row.tid)
        ON CONFLICT (user_id, trophy_id) DO NOTHING;

        PERFORM public.increment_user_xp(v_uid, v_row.bonus);

        v_new := v_new || jsonb_build_object(
          'id', v_row.tid, 'name', v_row.label, 'xp_awarded', v_row.bonus);
        v_total := v_total + v_row.bonus;
      END IF;
    END IF;
  END LOOP;

  SELECT count(*) INTO v_count
    FROM public.user_trophies WHERE user_id = v_uid;

  UPDATE public.user_profiles
     SET achievements_unlocked_count = v_count
   WHERE id = v_uid;

  RETURN jsonb_build_object('new_achievements', v_new, 'unlocked_count', v_count);
END;
$$;


ALTER FUNCTION "public"."grant_xp_milestone_achievements"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_streak_capsule_marks"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF current_user IN ('postgres', 'service_role') THEN RETURN NEW; END IF;
  IF NEW.login_streak_capsule_through IS DISTINCT FROM OLD.login_streak_capsule_through THEN
    RAISE EXCEPTION 'login_streak_capsule_through is RPC-only' USING ERRCODE = '42501';
  END IF;
  IF NEW.workout_streak_capsule_through IS DISTINCT FROM OLD.workout_streak_capsule_through THEN
    RAISE EXCEPTION 'workout_streak_capsule_through is RPC-only' USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END;
$$;


