CREATE OR REPLACE FUNCTION "public"."gym_event_rsvp_count_sync"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.status = 'going' THEN
      UPDATE public.gym_events
         SET rsvp_count = COALESCE(rsvp_count, 0) + 1
       WHERE id = NEW.event_id;
    END IF;
    RETURN NEW;
  ELSIF TG_OP = 'UPDATE' THEN
    IF OLD.status = 'going' AND NEW.status <> 'going' THEN
      UPDATE public.gym_events
         SET rsvp_count = GREATEST(0, COALESCE(rsvp_count, 0) - 1)
       WHERE id = NEW.event_id;
    ELSIF OLD.status <> 'going' AND NEW.status = 'going' THEN
      UPDATE public.gym_events
         SET rsvp_count = COALESCE(rsvp_count, 0) + 1
       WHERE id = NEW.event_id;
    END IF;
    RETURN NEW;
  ELSIF TG_OP = 'DELETE' THEN
    IF OLD.status = 'going' THEN
      UPDATE public.gym_events
         SET rsvp_count = GREATEST(0, COALESCE(rsvp_count, 0) - 1)
       WHERE id = OLD.event_id;
    END IF;
    RETURN OLD;
  END IF;
  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."gym_event_rsvp_count_sync"() OWNER TO "postgres";


