CREATE TABLE IF NOT EXISTS "public"."gym_rival_assignments" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid" NOT NULL,
    "rival_id" "uuid" NOT NULL,
    "assigned_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "status" "public"."gym_rival_status" DEFAULT 'active'::"public"."gym_rival_status" NOT NULL,
    "overthrown_at" timestamp with time zone,
    "overthrow_counted" boolean DEFAULT false NOT NULL,
    "initiator_confirmed" boolean DEFAULT false NOT NULL,
    "rival_confirmed" boolean DEFAULT false NOT NULL,
    "accepted_at" timestamp with time zone,
    "winner_id" "uuid",
    "settled_at" timestamp with time zone,
    "rival_type" "text" DEFAULT 'gym'::"text" NOT NULL,
    "match_gap" numeric,
    CONSTRAINT "different_users" CHECK (("user_id" <> "rival_id"))
);


ALTER TABLE "public"."gym_rival_assignments" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."gym_rival_confirm"("p_assignment_id" "uuid") RETURNS SETOF "public"."gym_rival_assignments"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid     UUID := auth.uid();
  v_owner   UUID;
  v_rival   UUID;
  v_status  TEXT;
  v_init_ok BOOLEAN;
  v_riv_ok  BOOLEAN;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;

  SELECT user_id, rival_id, status, initiator_confirmed, rival_confirmed
    INTO v_owner, v_rival, v_status, v_init_ok, v_riv_ok
    FROM public.gym_rival_assignments
   WHERE id = p_assignment_id
   FOR UPDATE;

  IF v_owner IS NULL THEN
    RAISE EXCEPTION 'match_not_found' USING ERRCODE = '22023';
  END IF;
  IF v_status <> 'pending' THEN
    RETURN QUERY SELECT * FROM public.gym_rival_assignments WHERE id = p_assignment_id;
    RETURN;
  END IF;

  IF v_uid = v_owner THEN
    UPDATE public.gym_rival_assignments SET initiator_confirmed = TRUE WHERE id = p_assignment_id;
    v_init_ok := TRUE;
  ELSIF v_uid = v_rival THEN
    UPDATE public.gym_rival_assignments SET rival_confirmed = TRUE WHERE id = p_assignment_id;
    v_riv_ok := TRUE;
  ELSE
    RAISE EXCEPTION 'not_part_of_match' USING ERRCODE = '42501';
  END IF;

  IF v_init_ok AND v_riv_ok THEN
    UPDATE public.gym_rival_assignments
       SET status = 'active', accepted_at = now()
     WHERE id = p_assignment_id;
  END IF;

  RETURN QUERY SELECT * FROM public.gym_rival_assignments WHERE id = p_assignment_id;
END;
$$;


ALTER FUNCTION "public"."gym_rival_confirm"("p_assignment_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."gym_rival_decline"("p_assignment_id" "uuid") RETURNS SETOF "public"."gym_rival_assignments"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid UUID := auth.uid(); v_owner UUID; v_rival UUID; v_status TEXT; v_other UUID; v_name TEXT;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501'; END IF;

  SELECT user_id, rival_id, status INTO v_owner, v_rival, v_status
    FROM public.gym_rival_assignments WHERE id = p_assignment_id FOR UPDATE;

  IF v_owner IS NULL THEN RAISE EXCEPTION 'match_not_found' USING ERRCODE = '22023'; END IF;
  IF v_uid <> v_owner AND v_uid <> v_rival THEN RAISE EXCEPTION 'not_part_of_match' USING ERRCODE = '42501'; END IF;

  -- Locked once live — you can only bail before both accept.
  IF v_status <> 'pending' THEN
    RETURN QUERY SELECT * FROM public.gym_rival_assignments WHERE id = p_assignment_id;
    RETURN;
  END IF;

  UPDATE public.gym_rival_assignments SET status = 'reassigned' WHERE id = p_assignment_id;

  v_other := CASE WHEN v_uid = v_owner THEN v_rival ELSE v_owner END;
  SELECT username INTO v_name FROM public.user_profiles WHERE id = v_uid;
  INSERT INTO public.notifications (user_id, user_email, type, title, body, icon, link_url, metadata)
  SELECT v_other, email, 'nemesis_assigned',
    '@' || COALESCE(v_name, 'Your rival') || ' declined the challenge',
    'They backed out before the match started. Roll a new rival when you''re ready.',
    '🎯', '/workout',
    jsonb_build_object('assignment_id', p_assignment_id, 'result', 'declined')
  FROM auth.users WHERE id = v_other;

  RETURN QUERY SELECT * FROM public.gym_rival_assignments WHERE id = p_assignment_id;
END;
$$;


ALTER FUNCTION "public"."gym_rival_decline"("p_assignment_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."gym_rival_match_gap"("p_out_a" numeric, "p_cad_a" numeric, "p_str_a" numeric, "p_age_a" numeric, "p_lvl_a" integer, "p_out_b" numeric, "p_cad_b" numeric, "p_str_b" numeric, "p_age_b" numeric, "p_lvl_b" integer) RETURNS numeric
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT (
      3.0 * (ABS(COALESCE(p_out_a, 0) - COALESCE(p_out_b, 0))
             / GREATEST(COALESCE(p_out_a, 0), COALESCE(p_out_b, 0), 1))
    + 2.0 * LEAST(1.0, ABS(COALESCE(p_cad_a, 0) - COALESCE(p_cad_b, 0)) / 4.0)
    + 1.5 * LEAST(1.0, ABS(COALESCE(p_lvl_a, 1) - COALESCE(p_lvl_b, 1))::numeric / 10.0)
    + CASE WHEN p_str_a IS NOT NULL AND p_str_b IS NOT NULL
           THEN 2.0 * (ABS(p_str_a - p_str_b) / GREATEST(p_str_a, p_str_b, 1))
           ELSE 0.0 END
    + CASE WHEN p_age_a IS NOT NULL AND p_age_b IS NOT NULL
           THEN 1.0 * LEAST(1.0, ABS(p_age_a - p_age_b) / 20.0)
           ELSE 0.0 END
  ) / (
      6.5
    + CASE WHEN p_str_a IS NOT NULL AND p_str_b IS NOT NULL THEN 2.0 ELSE 0.0 END
    + CASE WHEN p_age_a IS NOT NULL AND p_age_b IS NOT NULL THEN 1.0 ELSE 0.0 END
  );
$$;


ALTER FUNCTION "public"."gym_rival_match_gap"("p_out_a" numeric, "p_cad_a" numeric, "p_str_a" numeric, "p_age_a" numeric, "p_lvl_a" integer, "p_out_b" numeric, "p_cad_b" numeric, "p_str_b" numeric, "p_age_b" numeric, "p_lvl_b" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."gym_rival_net_rating"("p_uid" "uuid", "p_since" timestamp with time zone, "p_type" "text" DEFAULT 'gym'::"text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_volume NUMERIC := 0; v_distance NUMERIC := 0;
BEGIN
  IF p_type = 'cardio' THEN
    SELECT COALESCE(SUM(distance_meters), 0) INTO v_distance
      FROM public.cardio_logs WHERE user_id = p_uid AND date >= p_since::date;
    RETURN round((v_distance / 1000) * 20);
  ELSE
    v_volume := public.gym_rival_volume_lbs(p_uid, p_since, NULL);
    RETURN round(v_volume / 100);
  END IF;
END;
$$;


ALTER FUNCTION "public"."gym_rival_net_rating"("p_uid" "uuid", "p_since" timestamp with time zone, "p_type" "text") OWNER TO "postgres";


