CREATE OR REPLACE FUNCTION "public"."gym_rival_record"("p_uid" "uuid") RETURNS TABLE("wins" integer, "losses" integer)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    COALESCE(COUNT(*) FILTER (WHERE winner_id = p_uid), 0)::int AS wins,
    COALESCE(COUNT(*) FILTER (
      WHERE status = 'completed' AND winner_id IS NOT NULL AND winner_id <> p_uid
    ), 0)::int AS losses
  FROM public.gym_rival_assignments
  WHERE user_id = p_uid OR rival_id = p_uid;
$$;


ALTER FUNCTION "public"."gym_rival_record"("p_uid" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."gym_rival_roll"("p_type" "text" DEFAULT 'gym'::"text") RETURNS SETOF "public"."gym_rival_assignments"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_type TEXT := CASE WHEN p_type = 'cardio' THEN 'cardio' ELSE 'gym' END;
  v_label TEXT := CASE WHEN p_type = 'cardio' THEN 'Cardio Rival' ELSE 'Gym Rival' END;
  v_out_a NUMERIC; v_cad_a NUMERIC; v_str_a NUMERIC; v_age_a NUMERIC; v_lvl_a INTEGER;
  v_out_b NUMERIC; v_cad_b NUMERIC; v_str_b NUMERIC; v_age_b NUMERIC; v_lvl_b INTEGER;
  v_pass INTEGER; v_cand UUID; v_gap NUMERIC; v_best_gap NUMERIC;
  v_rival UUID; v_new_id UUID; v_name TEXT;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501'; END IF;

  SELECT weekly_output, cadence, strength, lifter_age, lifter_level
    INTO v_out_a, v_cad_a, v_str_a, v_age_a, v_lvl_a
    FROM public.gym_rival_user_stats(v_uid, v_type);

  FOR v_pass IN 1..2 LOOP
    EXIT WHEN v_rival IS NOT NULL;
    FOR v_cand IN
      SELECT id FROM public.user_profiles
       WHERE id <> v_uid
         AND COALESCE(nemesis_opt_out, FALSE) = FALSE
         AND username IS NOT NULL
         AND last_active_at IS NOT NULL
         AND last_active_at >= now() - interval '7 days'
         AND id NOT IN (SELECT id FROM auth.users WHERE email IS NULL)
         AND id NOT IN (
           SELECT user_id FROM public.gym_rival_assignments WHERE status IN ('pending','active')
           UNION
           SELECT rival_id FROM public.gym_rival_assignments WHERE status IN ('pending','active'))
         AND (v_pass = 2 OR id NOT IN (
           SELECT rival_id FROM public.gym_rival_assignments
            WHERE user_id = v_uid AND assigned_at >= now() - interval '21 days'
           UNION
           SELECT user_id FROM public.gym_rival_assignments
            WHERE rival_id = v_uid AND assigned_at >= now() - interval '21 days'))
       LIMIT 200
    LOOP
      SELECT weekly_output, cadence, strength, lifter_age, lifter_level
        INTO v_out_b, v_cad_b, v_str_b, v_age_b, v_lvl_b
        FROM public.gym_rival_user_stats(v_cand, v_type);
      v_gap := public.gym_rival_match_gap(v_out_a, v_cad_a, v_str_a, v_age_a, v_lvl_a,
                                          v_out_b, v_cad_b, v_str_b, v_age_b, v_lvl_b);
      IF v_best_gap IS NULL
         OR v_gap < v_best_gap - 0.02
         OR (ABS(v_gap - v_best_gap) <= 0.02 AND random() < 0.5) THEN
        v_best_gap := v_gap; v_rival := v_cand;
      END IF;
    END LOOP;
  END LOOP;

  IF v_rival IS NULL THEN RETURN; END IF;

  UPDATE public.gym_rival_assignments SET status = 'reassigned'
   WHERE status IN ('pending','active') AND (user_id = v_uid OR rival_id = v_uid);

  INSERT INTO public.gym_rival_assignments
    (user_id, rival_id, status, rival_type, initiator_confirmed, rival_confirmed, match_gap)
  VALUES (v_uid, v_rival, 'pending', v_type, FALSE, FALSE, v_best_gap)
  RETURNING id INTO v_new_id;

  SELECT username INTO v_name FROM public.user_profiles WHERE id = v_uid;

  INSERT INTO public.notifications (user_id, user_email, type, title, body, icon, link_url, metadata)
  SELECT v_rival, email, 'nemesis_assigned',
    '🎯 @' || COALESCE(v_name, 'someone') || ' wants to be your ' || v_label,
    'Confirm to start this week''s challenge — first one to go AFK forfeits.',
    '🎯', '/workout',
    jsonb_build_object('assignment_id', v_new_id, 'initiator_id', v_uid, 'rival_type', v_type)
  FROM auth.users WHERE id = v_rival AND email IS NOT NULL;

  RETURN QUERY SELECT * FROM public.gym_rival_assignments WHERE id = v_new_id;
END;
$$;


ALTER FUNCTION "public"."gym_rival_roll"("p_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."gym_rival_settle_week"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_id UUID; v_owner UUID; v_rival UUID; v_accepted TIMESTAMPTZ; v_since TIMESTAMPTZ; v_type TEXT;
  v_net_a INT; v_net_b INT; v_winner UUID; v_loser UUID;
  v_xp INT; v_coins INT; v_caps INT; v_wemail TEXT; v_wname TEXT; v_lname TEXT; v_settled INT := 0;
BEGIN
  FOR v_id IN
    SELECT id FROM public.gym_rival_assignments
     WHERE status = 'active' AND accepted_at IS NOT NULL
       AND date_trunc('week', accepted_at) + interval '7 days' <= now()
  LOOP
    SELECT user_id, rival_id, accepted_at, rival_type INTO v_owner, v_rival, v_accepted, v_type
      FROM public.gym_rival_assignments WHERE id = v_id;
    v_since := date_trunc('week', v_accepted);
    v_net_a := public.gym_rival_net_rating(v_owner, v_since, v_type);
    v_net_b := public.gym_rival_net_rating(v_rival, v_since, v_type);
    IF v_net_a > v_net_b THEN v_winner := v_owner; v_loser := v_rival;
    ELSIF v_net_b > v_net_a THEN v_winner := v_rival; v_loser := v_owner;
    ELSE v_winner := NULL; v_loser := NULL; END IF;

    IF v_winner IS NOT NULL THEN
      v_xp := 5000; v_coins := 500; v_caps := 5;
      PERFORM public.award_xp_internal(v_winner, v_xp);
      UPDATE public.user_profiles SET flex_coins = COALESCE(flex_coins, 0) + v_coins WHERE id = v_winner;
      SELECT email INTO v_wemail FROM auth.users WHERE id = v_winner;
      INSERT INTO public.user_capsules (user_id, user_email, capsule_type)
      SELECT v_winner, v_wemail, 'standard' FROM generate_series(1, v_caps);
      SELECT username INTO v_lname FROM public.user_profiles WHERE id = v_loser;
      INSERT INTO public.notifications (user_id, user_email, type, title, body, icon, link_url, metadata)
      SELECT v_winner, email, 'nemesis_overthrown', '🏆 You won your Rival week!',
        'You out-trained @' || COALESCE(v_lname, 'your rival') || '. +' || v_xp || ' XP, +' || v_coins || ' coins, ' || v_caps || ' capsules.',
        '🏆', '/workout', jsonb_build_object('assignment_id', v_id, 'result', 'win', 'xp', v_xp, 'coins', v_coins, 'capsules', v_caps)
      FROM auth.users WHERE id = v_winner;
      SELECT username INTO v_wname FROM public.user_profiles WHERE id = v_winner;
      INSERT INTO public.notifications (user_id, user_email, type, title, body, icon, link_url, metadata)
      SELECT v_loser, email, 'nemesis_overthrown', 'Your Rival week ended',
        '@' || COALESCE(v_wname, 'your rival') || ' edged you out this week. Roll a new rival and get them next time.',
        '🎯', '/workout', jsonb_build_object('assignment_id', v_id, 'result', 'loss')
      FROM auth.users WHERE id = v_loser;
    ELSE
      SELECT email INTO v_wemail FROM auth.users WHERE id = v_owner;
      INSERT INTO public.notifications (user_id, user_email, type, title, body, icon, link_url, metadata)
      VALUES (v_owner, v_wemail, 'nemesis_overthrown', 'Your Rival week ended in a draw',
        'Dead even — no winner this week. Roll a new rival.', '🤝', '/workout',
        jsonb_build_object('assignment_id', v_id, 'result', 'draw'));
      SELECT email INTO v_wemail FROM auth.users WHERE id = v_rival;
      INSERT INTO public.notifications (user_id, user_email, type, title, body, icon, link_url, metadata)
      VALUES (v_rival, v_wemail, 'nemesis_overthrown', 'Your Rival week ended in a draw',
        'Dead even — no winner this week. Roll a new rival.', '🤝', '/workout',
        jsonb_build_object('assignment_id', v_id, 'result', 'draw'));
    END IF;

    UPDATE public.gym_rival_assignments SET status = 'completed', winner_id = v_winner, settled_at = now() WHERE id = v_id;
    v_settled := v_settled + 1;
  END LOOP;
  RETURN v_settled;
END;
$$;


ALTER FUNCTION "public"."gym_rival_settle_week"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."gym_rival_user_stats"("p_uid" "uuid", "p_type" "text" DEFAULT 'gym'::"text") RETURNS TABLE("weekly_output" numeric, "cadence" numeric, "strength" numeric, "lifter_age" numeric, "lifter_level" integer)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_out NUMERIC := 0; v_cad NUMERIC := 0; v_str NUMERIC;
  v_age NUMERIC; v_lvl INTEGER; v_weight NUMERIC; v_best NUMERIC;
BEGIN
  SELECT weight_lbs, age, current_level INTO v_weight, v_age, v_lvl
    FROM public.user_profiles WHERE id = p_uid;

  IF p_type = 'cardio' THEN
    SELECT COALESCE(SUM(distance_meters), 0) / 4.0, COUNT(DISTINCT date)::numeric / 4.0
      INTO v_out, v_cad FROM public.cardio_logs
     WHERE user_id = p_uid AND date >= (now() - interval '28 days')::date;
  ELSE
    v_out := public.gym_rival_volume_lbs(p_uid, now() - interval '28 days', NULL) / 4.0;
    SELECT COUNT(DISTINCT created_at::date)::numeric / 4.0 INTO v_cad
      FROM public.workout_logs
     WHERE user_id = p_uid AND created_at >= now() - interval '28 days'
       AND NOT COALESCE(implausible, FALSE);
  END IF;

  IF v_weight IS NOT NULL AND v_weight > 0 THEN
    SELECT MAX((public._best_1rm_from_exercises(exercises)->>'e1rm')::numeric) INTO v_best
      FROM public.workout_logs
     WHERE user_id = p_uid AND created_at > now() - interval '90 days'
       AND NOT COALESCE(implausible, FALSE);
    IF v_best IS NOT NULL THEN v_str := v_best / v_weight; END IF;
  END IF;

  RETURN QUERY SELECT COALESCE(v_out, 0), COALESCE(v_cad, 0), v_str, v_age, v_lvl;
END;
$$;


ALTER FUNCTION "public"."gym_rival_user_stats"("p_uid" "uuid", "p_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."gym_rival_void_stale"("p_assignment_id" "uuid") RETURNS SETOF "public"."gym_rival_assignments"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid      UUID := auth.uid();
  v_owner    UUID;
  v_rival    UUID;
  v_status   TEXT;
  v_type     TEXT;
  v_accepted TIMESTAMPTZ;
  v_a_logged BOOLEAN;
  v_b_logged BOOLEAN;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;

  SELECT user_id, rival_id, status, rival_type, accepted_at
    INTO v_owner, v_rival, v_status, v_type, v_accepted
    FROM public.gym_rival_assignments
   WHERE id = p_assignment_id;

  IF v_owner IS NULL OR (v_uid <> v_owner AND v_uid <> v_rival) THEN
    RAISE EXCEPTION 'not_part_of_match' USING ERRCODE = '42501';
  END IF;

  IF v_status <> 'active' OR v_accepted IS NULL
     OR now() < v_accepted + interval '48 hours' THEN
    RETURN QUERY SELECT * FROM public.gym_rival_assignments WHERE id = p_assignment_id;
    RETURN;
  END IF;

  IF v_type = 'cardio' THEN
    SELECT EXISTS (
      SELECT 1 FROM public.cardio_logs WHERE user_id = v_owner AND date >= v_accepted::date
    ) INTO v_a_logged;
    SELECT EXISTS (
      SELECT 1 FROM public.cardio_logs WHERE user_id = v_rival AND date >= v_accepted::date
    ) INTO v_b_logged;
  ELSE
    SELECT EXISTS (
      SELECT 1 FROM public.workout_logs WHERE user_id = v_owner AND created_at >= v_accepted
    ) INTO v_a_logged;
    SELECT EXISTS (
      SELECT 1 FROM public.workout_logs WHERE user_id = v_rival AND created_at >= v_accepted
    ) INTO v_b_logged;
  END IF;

  IF NOT v_a_logged OR NOT v_b_logged THEN
    UPDATE public.gym_rival_assignments SET status = 'void' WHERE id = p_assignment_id;
  END IF;

  RETURN QUERY SELECT * FROM public.gym_rival_assignments WHERE id = p_assignment_id;
END;
$$;


ALTER FUNCTION "public"."gym_rival_void_stale"("p_assignment_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."gym_rival_void_stale_all"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_id       UUID;
  v_owner    UUID;
  v_rival    UUID;
  v_type     TEXT;
  v_accepted TIMESTAMPTZ;
  v_a        BOOLEAN;
  v_b        BOOLEAN;
  v_count    INT := 0;
BEGIN
  FOR v_id IN
    SELECT id FROM public.gym_rival_assignments
     WHERE status = 'active'
       AND accepted_at IS NOT NULL
       AND now() >= accepted_at + interval '48 hours'
  LOOP
    SELECT user_id, rival_id, accepted_at, rival_type
      INTO v_owner, v_rival, v_accepted, v_type
      FROM public.gym_rival_assignments WHERE id = v_id;

    IF v_type = 'cardio' THEN
      SELECT EXISTS (
        SELECT 1 FROM public.cardio_logs WHERE user_id = v_owner AND date >= v_accepted::date
      ) INTO v_a;
      SELECT EXISTS (
        SELECT 1 FROM public.cardio_logs WHERE user_id = v_rival AND date >= v_accepted::date
      ) INTO v_b;
    ELSE
      SELECT EXISTS (
        SELECT 1 FROM public.workout_logs WHERE user_id = v_owner AND created_at >= v_accepted
      ) INTO v_a;
      SELECT EXISTS (
        SELECT 1 FROM public.workout_logs WHERE user_id = v_rival AND created_at >= v_accepted
      ) INTO v_b;
    END IF;

    IF NOT v_a OR NOT v_b THEN
      UPDATE public.gym_rival_assignments SET status = 'void' WHERE id = v_id;
      v_count := v_count + 1;
    END IF;
  END LOOP;
  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."gym_rival_void_stale_all"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."gym_rival_volume_lbs"("p_uid" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS numeric
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $_$
DECLARE v_bw NUMERIC; v_vol NUMERIC := 0;
BEGIN
  SELECT weight_lbs INTO v_bw FROM public.user_profiles WHERE id = p_uid;
  IF v_bw IS NULL OR v_bw <= 0 THEN v_bw := 0; END IF;

  SELECT COALESCE(SUM(
           (COALESCE(v_bw * public.bodyweight_load_factor(ex->>'name'), 0)
            + COALESCE(NULLIF(s->>'weight','')::numeric, 0))
           * (s->>'reps')::numeric), 0)
    INTO v_vol
    FROM public.workout_logs,
         jsonb_array_elements(COALESCE(exercises, '[]'::jsonb)) AS ex,
         jsonb_array_elements(COALESCE(ex->'sets', '[]'::jsonb)) AS s
   WHERE user_id = p_uid
     AND created_at >= p_from
     AND (p_to IS NULL OR created_at < p_to)
     AND NOT COALESCE(implausible, FALSE)
     AND (s->>'reps') ~ '^[0-9]+$'
     AND (s->>'weight' IS NULL OR s->>'weight' = '' OR (s->>'weight') ~ '^[0-9]+(\.[0-9]+)?$');

  RETURN COALESCE(v_vol, 0);
END;
$_$;


ALTER FUNCTION "public"."gym_rival_volume_lbs"("p_uid" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."gym_rival_week_state"("p_assignment_id" "uuid") RETURNS TABLE("week_since" timestamp with time zone, "week_ends" timestamp with time zone, "you_volume" numeric, "them_volume" numeric, "you_distance" numeric, "them_distance" numeric, "you_logged" boolean, "them_logged" boolean, "afk_deadline" timestamp with time zone, "is_stalled" boolean, "you_bw_missing" boolean, "them_bw_missing" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_owner UUID; v_rival UUID; v_status TEXT; v_type TEXT;
  v_accepted TIMESTAMPTZ; v_assigned TIMESTAMPTZ;
  v_you UUID; v_them UUID;
  v_since TIMESTAMPTZ; v_ends TIMESTAMPTZ; v_deadline TIMESTAMPTZ;
  v_yv NUMERIC := 0; v_tv NUMERIC := 0; v_yd NUMERIC := 0; v_td NUMERIC := 0;
  v_yl BOOLEAN := FALSE; v_tl BOOLEAN := FALSE; v_stalled BOOLEAN := FALSE;
  v_ybw BOOLEAN := FALSE; v_tbw BOOLEAN := FALSE;
  v_w NUMERIC; v_bwsets INT;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501'; END IF;

  SELECT user_id, rival_id, status, rival_type, accepted_at, assigned_at
    INTO v_owner, v_rival, v_status, v_type, v_accepted, v_assigned
    FROM public.gym_rival_assignments WHERE id = p_assignment_id;

  IF v_owner IS NULL OR (v_uid <> v_owner AND v_uid <> v_rival) THEN
    RAISE EXCEPTION 'not_part_of_match' USING ERRCODE = '42501';
  END IF;

  IF v_uid = v_owner THEN v_you := v_owner; v_them := v_rival;
  ELSE v_you := v_rival; v_them := v_owner; END IF;

  v_stalled  := (v_status = 'active' AND v_accepted IS NULL);
  v_since    := date_trunc('week', COALESCE(v_accepted, v_assigned, now()));
  v_ends     := v_since + interval '7 days';
  v_deadline := v_accepted + interval '48 hours';

  v_yv := public.gym_rival_volume_lbs(v_you,  v_since, v_ends);
  v_tv := public.gym_rival_volume_lbs(v_them, v_since, v_ends);

  SELECT COALESCE(SUM(distance_meters), 0) INTO v_yd FROM public.cardio_logs
   WHERE user_id = v_you AND date >= v_since::date AND date < v_ends::date;
  SELECT COALESCE(SUM(distance_meters), 0) INTO v_td FROM public.cardio_logs
   WHERE user_id = v_them AND date >= v_since::date AND date < v_ends::date;

  IF v_accepted IS NOT NULL THEN
    IF v_type = 'cardio' THEN
      SELECT EXISTS (SELECT 1 FROM public.cardio_logs
                      WHERE user_id = v_you AND date >= v_accepted::date) INTO v_yl;
      SELECT EXISTS (SELECT 1 FROM public.cardio_logs
                      WHERE user_id = v_them AND date >= v_accepted::date) INTO v_tl;
    ELSE
      SELECT EXISTS (SELECT 1 FROM public.workout_logs
                      WHERE user_id = v_you AND created_at >= v_accepted) INTO v_yl;
      SELECT EXISTS (SELECT 1 FROM public.workout_logs
                      WHERE user_id = v_them AND created_at >= v_accepted) INTO v_tl;
    END IF;
  END IF;

  IF v_type <> 'cardio' THEN
    SELECT weight_lbs INTO v_w FROM public.user_profiles WHERE id = v_you;
    SELECT COUNT(*) INTO v_bwsets
      FROM public.workout_logs,
           jsonb_array_elements(COALESCE(exercises, '[]'::jsonb)) AS ex,
           jsonb_array_elements(COALESCE(ex->'sets', '[]'::jsonb)) AS s
     WHERE user_id = v_you AND created_at >= v_since AND created_at < v_ends
       AND public.bodyweight_load_factor(ex->>'name') > 0;
    v_ybw := (COALESCE(v_w, 0) <= 0 AND COALESCE(v_bwsets, 0) > 0);

    SELECT weight_lbs INTO v_w FROM public.user_profiles WHERE id = v_them;
    SELECT COUNT(*) INTO v_bwsets
      FROM public.workout_logs,
           jsonb_array_elements(COALESCE(exercises, '[]'::jsonb)) AS ex,
           jsonb_array_elements(COALESCE(ex->'sets', '[]'::jsonb)) AS s
     WHERE user_id = v_them AND created_at >= v_since AND created_at < v_ends
       AND public.bodyweight_load_factor(ex->>'name') > 0;
    v_tbw := (COALESCE(v_w, 0) <= 0 AND COALESCE(v_bwsets, 0) > 0);
  END IF;

  RETURN QUERY SELECT v_since, v_ends, v_yv, v_tv, v_yd, v_td, v_yl, v_tl,
                      v_deadline, v_stalled, v_ybw, v_tbw;
END;
$$;


ALTER FUNCTION "public"."gym_rival_week_state"("p_assignment_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."handle_new_user"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_row    JSONB;
  v_id     UUID;
  v_email  TEXT;
  v_name   TEXT;
  v_avatar TEXT;
BEGIN
  v_row    := to_jsonb(NEW);
  v_id     := (v_row->>'id')::uuid;
  v_email  := v_row->>'email';
  v_name   := v_row->'raw_user_meta_data'->>'full_name';
  v_avatar := v_row->'raw_user_meta_data'->>'avatar_url';

  IF v_email IS NULL THEN
    v_email := format('guest_%s@flexyn.guest', v_id);
  END IF;

  INSERT INTO public.user_profiles (id, email, full_name, avatar_url)
  VALUES (v_id, v_email, v_name, v_avatar)
  ON CONFLICT (id) DO NOTHING;

  RETURN NEW;
END;
$$;


