CREATE OR REPLACE FUNCTION "public"."hub_posts_guard_counters"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF current_user IN ('postgres', 'service_role') THEN RETURN NEW; END IF;
  IF TG_OP = 'INSERT' THEN NEW.like_count := 0; NEW.dislike_count := 0; NEW.comment_count := 0; RETURN NEW; END IF;
  IF NEW.like_count IS DISTINCT FROM OLD.like_count OR NEW.dislike_count IS DISTINCT FROM OLD.dislike_count
     OR NEW.comment_count IS DISTINCT FROM OLD.comment_count THEN
    RAISE EXCEPTION 'post counters are RPC-only (use increment_hub_post_counter)' USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END;
$$;


