CREATE OR REPLACE FUNCTION "public"."increment_flex_coins"("p_delta" integer) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid          UUID := auth.uid();
  v_max_per_call CONSTANT INTEGER := 2500;
  v_max_per_day  CONSTANT INTEGER := 25000;
  v_requested    INTEGER;
  v_before       INTEGER;
  v_after        INTEGER;
  v_credit       INTEGER;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;
  IF p_delta IS NULL OR p_delta = 0 THEN RETURN; END IF;

  IF p_delta < 0 THEN
    UPDATE public.user_profiles
       SET flex_coins = GREATEST(0, COALESCE(flex_coins, 0) + p_delta)
     WHERE id = v_uid;
    RETURN;
  END IF;

  v_requested := LEAST(p_delta, v_max_per_call);

  SELECT COALESCE(granted, 0) INTO v_before
    FROM public.flex_coin_grant_ledger
   WHERE user_id = v_uid AND day = (now() AT TIME ZONE 'utc')::date;
  v_before := COALESCE(v_before, 0);

  v_after  := LEAST(v_max_per_day, v_before + v_requested);
  v_credit := v_after - v_before;
  IF v_credit <= 0 THEN RETURN; END IF;

  INSERT INTO public.flex_coin_grant_ledger (user_id, day, granted)
  VALUES (v_uid, (now() AT TIME ZONE 'utc')::date, v_credit)
  ON CONFLICT (user_id, day)
  DO UPDATE SET granted = LEAST(v_max_per_day, public.flex_coin_grant_ledger.granted + v_credit);

  UPDATE public.user_profiles
     SET flex_coins = GREATEST(0, COALESCE(flex_coins, 0) + v_credit)
   WHERE id = v_uid;
END;
$$;


ALTER FUNCTION "public"."increment_flex_coins"("p_delta" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."increment_hub_post_counter"("p_post_id" "uuid", "p_field" "text", "p_delta" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE v_uid UUID := auth.uid(); v_new_value INT;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501'; END IF;
  IF p_post_id IS NULL OR p_field IS NULL THEN RAISE EXCEPTION 'post_id and field required' USING ERRCODE = '22023'; END IF;
  IF p_field = 'like_count' THEN
    UPDATE public.hub_posts SET like_count = (SELECT count(*) FROM public.hub_reactions WHERE post_id = p_post_id AND reaction_type = 'like')
     WHERE id = p_post_id RETURNING like_count INTO v_new_value;
  ELSIF p_field = 'dislike_count' THEN
    UPDATE public.hub_posts SET dislike_count = (SELECT count(*) FROM public.hub_reactions WHERE post_id = p_post_id AND reaction_type = 'dislike')
     WHERE id = p_post_id RETURNING dislike_count INTO v_new_value;
  ELSIF p_field = 'comment_count' THEN
    UPDATE public.hub_posts SET comment_count = (SELECT count(*) FROM public.hub_comments WHERE post_id = p_post_id)
     WHERE id = p_post_id RETURNING comment_count INTO v_new_value;
  ELSE RAISE EXCEPTION 'invalid field: %', p_field USING ERRCODE = '22023'; END IF;
  IF v_new_value IS NULL THEN RAISE EXCEPTION 'post not found' USING ERRCODE = '22023'; END IF;
  RETURN jsonb_build_object('success', TRUE, 'post_id', p_post_id, 'field', p_field, 'new_value', v_new_value);
END;
$$;


ALTER FUNCTION "public"."increment_hub_post_counter"("p_post_id" "uuid", "p_field" "text", "p_delta" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."increment_league_xp"("p_league_member_id" "uuid", "p_amount" integer) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_call_cap CONSTANT integer := 2000;
  v_week_cap CONSTANT integer := 150000;
  v_amt integer;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE='42501'; END IF;
  IF p_amount IS NULL OR p_amount <= 0 THEN RETURN; END IF;
  v_amt := LEAST(p_amount, v_call_cap);
  UPDATE public.league_members
     SET weekly_xp = LEAST(v_week_cap, COALESCE(weekly_xp, 0) + v_amt)
   WHERE id = p_league_member_id AND user_id = v_uid;
END;
$$;


