CREATE OR REPLACE FUNCTION "public"."increment_overthrow_count"("p_user_id" "uuid" DEFAULT NULL::"uuid", "p_assignment_id" "uuid" DEFAULT NULL::"uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid       UUID := auth.uid();
  v_a_id      UUID;
  v_a_user    UUID;
  v_a_status  TEXT;
  v_a_counted BOOLEAN;
  v_new_count INT;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;

  v_a_id := p_assignment_id;
  IF v_a_id IS NULL THEN
    SELECT id INTO v_a_id
      FROM public.gym_rival_assignments
     WHERE user_id = v_uid
       AND status = 'overthrown'
       AND COALESCE(overthrow_counted, FALSE) = FALSE
     ORDER BY assigned_at DESC
     LIMIT 1;
    IF v_a_id IS NULL THEN
      SELECT overthrow_count INTO v_new_count FROM public.user_profiles WHERE id = v_uid;
      RETURN COALESCE(v_new_count, 0);
    END IF;
  END IF;

  SELECT user_id, status, overthrow_counted
    INTO v_a_user, v_a_status, v_a_counted
    FROM public.gym_rival_assignments
   WHERE id = v_a_id
   FOR UPDATE;
  IF v_a_user IS NULL THEN
    RAISE EXCEPTION 'assignment_not_found' USING ERRCODE = '22023';
  END IF;
  IF v_a_user IS DISTINCT FROM v_uid THEN
    RAISE EXCEPTION 'not_your_assignment' USING ERRCODE = '42501';
  END IF;
  IF v_a_status IS DISTINCT FROM 'overthrown' THEN
    RAISE EXCEPTION 'assignment_not_overthrown' USING ERRCODE = '22023';
  END IF;
  IF v_a_counted THEN
    SELECT overthrow_count INTO v_new_count FROM public.user_profiles WHERE id = v_uid;
    RETURN COALESCE(v_new_count, 0);
  END IF;

  UPDATE public.gym_rival_assignments SET overthrow_counted = TRUE WHERE id = v_a_id;
  UPDATE public.user_profiles
     SET overthrow_count = COALESCE(overthrow_count, 0) + 1
   WHERE id = v_uid
   RETURNING overthrow_count INTO v_new_count;
  RETURN COALESCE(v_new_count, 1);
END;
$$;


ALTER FUNCTION "public"."increment_overthrow_count"("p_user_id" "uuid", "p_assignment_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."increment_user_distance"("p_delta" numeric) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_call_cap CONSTANT numeric := 200000; v_day_cap CONSTANT numeric := 500000;
  v_before numeric; v_credit numeric;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE='42501'; END IF;
  IF p_delta IS NULL OR p_delta = 0 THEN RETURN; END IF;
  IF p_delta < 0 THEN
    UPDATE public.user_profiles SET total_distance_meters = GREATEST(0, COALESCE(total_distance_meters,0)+p_delta) WHERE id = v_uid;
    RETURN;
  END IF;
  SELECT COALESCE(granted,0) INTO v_before FROM public.user_stat_grant_ledger
   WHERE user_id=v_uid AND day=(now() AT TIME ZONE 'utc')::date AND stat='distance';
  v_before := COALESCE(v_before,0);
  v_credit := LEAST(p_delta, v_call_cap, GREATEST(0, v_day_cap - v_before));
  IF v_credit <= 0 THEN RETURN; END IF;
  INSERT INTO public.user_stat_grant_ledger (user_id, day, stat, granted)
  VALUES (v_uid, (now() AT TIME ZONE 'utc')::date, 'distance', v_credit)
  ON CONFLICT (user_id, day, stat) DO UPDATE SET granted = public.user_stat_grant_ledger.granted + v_credit;
  UPDATE public.user_profiles SET total_distance_meters = GREATEST(0, COALESCE(total_distance_meters,0)+v_credit) WHERE id = v_uid;
END;
$$;


ALTER FUNCTION "public"."increment_user_distance"("p_delta" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."increment_user_volume"("p_delta" numeric) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_call_cap CONSTANT numeric := 100000; v_day_cap CONSTANT numeric := 300000;
  v_before numeric; v_credit numeric;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE='42501'; END IF;
  IF p_delta IS NULL OR p_delta = 0 THEN RETURN; END IF;
  IF p_delta < 0 THEN
    UPDATE public.user_profiles SET total_volume_lbs = GREATEST(0, COALESCE(total_volume_lbs,0)+p_delta) WHERE id = v_uid;
    RETURN;
  END IF;
  SELECT COALESCE(granted,0) INTO v_before FROM public.user_stat_grant_ledger
   WHERE user_id=v_uid AND day=(now() AT TIME ZONE 'utc')::date AND stat='volume';
  v_before := COALESCE(v_before,0);
  v_credit := LEAST(p_delta, v_call_cap, GREATEST(0, v_day_cap - v_before));
  IF v_credit <= 0 THEN RETURN; END IF;
  INSERT INTO public.user_stat_grant_ledger (user_id, day, stat, granted)
  VALUES (v_uid, (now() AT TIME ZONE 'utc')::date, 'volume', v_credit)
  ON CONFLICT (user_id, day, stat) DO UPDATE SET granted = public.user_stat_grant_ledger.granted + v_credit;
  UPDATE public.user_profiles SET total_volume_lbs = GREATEST(0, COALESCE(total_volume_lbs,0)+v_credit) WHERE id = v_uid;
END;
$$;


ALTER FUNCTION "public"."increment_user_volume"("p_delta" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."increment_user_xp"("p_user_id" "uuid", "p_xp" integer) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid       UUID := auth.uid();
  v_total_xp  BIGINT;
  v_level     INTEGER := 1;
  v_today     INTEGER;
  v_grant     INTEGER;
  v_daily_cap CONSTANT INTEGER := 50000;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;
  IF p_xp IS NULL OR p_xp <= 0 THEN RETURN; END IF;
  IF p_xp > 100000 THEN
    RAISE EXCEPTION 'xp out of range' USING ERRCODE = '22023';
  END IF;

  SELECT COALESCE(SUM(amount), 0) INTO v_today
    FROM public.xp_grant_log
    WHERE user_id = v_uid
      AND granted_at > now() - interval '24 hours';

  v_grant := LEAST(p_xp, GREATEST(0, v_daily_cap - v_today));
  IF v_grant <= 0 THEN RETURN; END IF;

  INSERT INTO public.xp_grant_log (user_id, amount) VALUES (v_uid, v_grant);

  UPDATE public.user_profiles
    SET total_xp   = COALESCE(total_xp, 0) + v_grant,
        updated_at = now()
    WHERE id = v_uid
    RETURNING total_xp INTO v_total_xp;

  IF NOT FOUND THEN RETURN; END IF;

  SELECT COALESCE(MAX(level), 1) INTO v_level
    FROM public.xp_level_thresholds
    WHERE total_xp_required <= v_total_xp;

  UPDATE public.user_profiles SET current_level = v_level WHERE id = v_uid;
END;
$$;


ALTER FUNCTION "public"."increment_user_xp"("p_user_id" "uuid", "p_xp" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."invite_to_crew"("p_crew_id" "uuid", "p_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_uid    uuid := auth.uid();
  v_mod    integer;
  v_banned integer;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;
  IF p_crew_id IS NULL OR p_user_id IS NULL THEN
    RAISE EXCEPTION 'crew_id and user_id required' USING ERRCODE = '22023';
  END IF;

  SELECT COUNT(*) INTO v_mod
    FROM public.crew_members
   WHERE crew_id = p_crew_id
     AND user_id = v_uid
     AND (is_admin = TRUE OR role IN ('leader', 'moderator'));

  IF v_mod = 0 THEN
    RAISE EXCEPTION 'only a crew leader or moderator can invite'
      USING ERRCODE = '42501';
  END IF;

  SELECT COUNT(*) INTO v_banned
    FROM public.crew_bans WHERE crew_id = p_crew_id AND user_id = p_user_id;

  IF NOT (v_banned = 0) THEN
    RAISE EXCEPTION 'that person is banned from this crew' USING ERRCODE = '42501';
  END IF;

  INSERT INTO public.crew_invites (crew_id, invited_user_id, invited_by, expires_at)
  VALUES (p_crew_id, p_user_id, v_uid, now() + INTERVAL '14 days')
  ON CONFLICT (crew_id, invited_user_id) DO UPDATE
    SET invited_by = v_uid, created_at = now(),
        expires_at = now() + INTERVAL '14 days', accepted_at = NULL;

  RETURN jsonb_build_object('ok', TRUE, 'invited', TRUE);
END;
$$;


ALTER FUNCTION "public"."invite_to_crew"("p_crew_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


