CREATE OR REPLACE FUNCTION "public"."is_bio_clean"("p_bio" "text") RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  patterns TEXT[] := ARRAY[
    'nigger', 'nigga', 'kike', 'faggot', 'tranny', 'chink', 'spic', 'gook',
    'retard', 'whore', 'pedo', 'pedophile', 'rapist'
  ];
  pat  TEXT;
  norm TEXT;
  leet TEXT;
BEGIN
  IF p_bio IS NULL OR length(p_bio) = 0 THEN RETURN TRUE; END IF;
  norm := regexp_replace(lower(p_bio), '\s+', ' ', 'g');
  leet := translate(norm, '013457', 'oietas');
  FOREACH pat IN ARRAY patterns LOOP
    IF norm ~ ('\m' || pat || '\M') THEN RETURN FALSE; END IF;
    IF leet ~ ('\m' || pat || '\M') THEN RETURN FALSE; END IF;
  END LOOP;
  RETURN TRUE;
END;
$$;


ALTER FUNCTION "public"."is_bio_clean"("p_bio" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."is_blocked"("p_viewer_id" "uuid", "p_author_email" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.user_blocks
     WHERE blocker_id = p_viewer_id
       AND lower(blocked_email) = lower(p_author_email)
  ) OR EXISTS (
    SELECT 1
      FROM public.user_blocks b
      JOIN public.user_profiles p ON p.id = p_viewer_id
     WHERE lower(b.blocker_email) = lower(p_author_email)
       AND lower(b.blocked_email) = lower(p.email)
  );
$$;


