CREATE OR REPLACE FUNCTION "public"."is_crew_moderator"("p_crew_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
