CREATE OR REPLACE FUNCTION "public"."is_in_quiet_hours"("p_user_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_start INTEGER; v_end INTEGER; v_offset INTEGER; v_local_hour INTEGER;
BEGIN
  SELECT quiet_hours_start, quiet_hours_end, COALESCE(timezone_offset_minutes, 0)
    INTO v_start, v_end, v_offset
    FROM public.user_profiles WHERE id = p_user_id;
  IF v_start IS NULL OR v_end IS NULL THEN RETURN FALSE; END IF;
  v_local_hour := EXTRACT(HOUR FROM (now() + (v_offset || ' minutes')::interval))::int;
  IF v_start = v_end THEN RETURN FALSE;
  ELSIF v_start < v_end THEN RETURN v_local_hour >= v_start AND v_local_hour < v_end;
  ELSE RETURN v_local_hour >= v_start OR v_local_hour < v_end;
  END IF;
END; $$;


