CREATE OR REPLACE FUNCTION "public"."is_text_clean"("p_text" "text", "p_strict" boolean DEFAULT false) RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  loose_patterns TEXT[] := ARRAY[
    'nigger', 'nigga', 'kike', 'faggot', 'tranny', 'chink', 'spic', 'gook',
    'retard', 'whore',
    'pedo', 'pedophile', 'rapist'
  ];
  strict_patterns TEXT[] := ARRAY[
    'nigger', 'nigga', 'kike', 'faggot', 'tranny', 'chink', 'spic', 'gook',
    'retard', 'whore', 'rape',
    'pedo', 'pedophile', 'rapist'
  ];
  patterns TEXT[];
  pat  TEXT;
  norm TEXT;
  leet TEXT;
BEGIN
  IF p_text IS NULL OR length(p_text) = 0 THEN
    RETURN TRUE;
  END IF;
  patterns := CASE WHEN p_strict THEN strict_patterns ELSE loose_patterns END;
  norm := regexp_replace(lower(p_text), '\s+', ' ', 'g');
  leet := translate(norm, '013457', 'oietas');
  FOREACH pat IN ARRAY patterns LOOP
    IF norm ~ ('\m' || pat || '\M') THEN RETURN FALSE; END IF;
    IF leet ~ ('\m' || pat || '\M') THEN RETURN FALSE; END IF;
  END LOOP;
  RETURN TRUE;
END;
$$;


ALTER FUNCTION "public"."is_text_clean"("p_text" "text", "p_strict" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."is_username_clean"("p_username" "text") RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_catalog'
    AS $_$
DECLARE
  patterns TEXT[] := ARRAY[
    'nigger', 'nigga', 'kike', 'faggot', 'tranny', 'chink', 'spic', 'gook',
    'retard', 'whore',
    'pedo', 'pedophile', 'rapist', 'rape',
    'admin', 'administrator', 'moderator', 'mod', 'support', 'staff',
    'flexyn_official', 'flexyn_admin', 'flexyn_support'
  ];
  pat  TEXT;
  norm TEXT;
  leet TEXT;
BEGIN
  IF p_username IS NULL OR length(p_username) = 0 THEN
    RETURN TRUE;
  END IF;
  norm := lower(p_username);
  leet := translate(norm, '013457', 'oietas');
  FOREACH pat IN ARRAY patterns LOOP
    IF norm ~ ('(^|_)' || pat || '($|_)') THEN RETURN FALSE; END IF;
    IF leet ~ ('(^|_)' || pat || '($|_)') THEN RETURN FALSE; END IF;
  END LOOP;
  RETURN TRUE;
END;
$_$;


ALTER FUNCTION "public"."is_username_clean"("p_username" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."join_crew_atomic"("p_crew_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_uid       uuid := auth.uid();
  v_public    boolean;
  v_cap       integer;
  v_count     integer;
  v_existing  integer;
  v_elsewhere integer;
  v_banned    integer;
  v_invited   integer;
  v_req       text;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;
  IF p_crew_id IS NULL THEN
    RAISE EXCEPTION 'crew_id required' USING ERRCODE = '22023';
  END IF;

  SELECT is_public, COALESCE(max_capacity, 16)
    INTO v_public, v_cap
    FROM public.crews
   WHERE id = p_crew_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'crew not found' USING ERRCODE = '22023';
  END IF;

  SELECT COUNT(*) INTO v_existing
    FROM public.crew_members
   WHERE crew_id = p_crew_id AND user_id = v_uid;

  IF NOT (v_existing = 0) THEN
    RETURN jsonb_build_object('success', TRUE, 'already_member', TRUE,
                              'status', 'already_member', 'crew_id', p_crew_id);
  END IF;

  SELECT COUNT(*) INTO v_elsewhere
    FROM public.crew_members
   WHERE user_id = v_uid AND NOT (crew_id = p_crew_id);

  IF NOT (v_elsewhere = 0) THEN
    RAISE EXCEPTION 'already_in_crew' USING ERRCODE = '23505';
  END IF;

  SELECT COUNT(*) INTO v_banned
    FROM public.crew_bans
   WHERE crew_id = p_crew_id AND user_id = v_uid;

  IF NOT (v_banned = 0) THEN
    RAISE EXCEPTION 'banned_from_crew' USING ERRCODE = '42501';
  END IF;

  SELECT COUNT(*) INTO v_invited
    FROM public.crew_invites
   WHERE crew_id = p_crew_id
     AND invited_user_id = v_uid
     AND accepted_at IS NULL
     AND expires_at = GREATEST(expires_at, now());

  IF v_public IS NOT TRUE AND v_invited = 0 THEN
    SELECT status INTO v_req
      FROM public.crew_join_requests
     WHERE crew_id = p_crew_id AND user_id = v_uid;

    IF v_req = 'pending' THEN
      RETURN jsonb_build_object('success', TRUE, 'already_member', FALSE,
                                'status', 'pending', 'crew_id', p_crew_id);
    END IF;

    INSERT INTO public.crew_join_requests (crew_id, user_id, status, created_at)
    VALUES (p_crew_id, v_uid, 'pending', now())
    ON CONFLICT (crew_id, user_id) DO UPDATE
      SET status = 'pending', created_at = now(),
          decided_by = NULL, decided_at = NULL;

    RETURN jsonb_build_object('success', TRUE, 'already_member', FALSE,
                              'status', 'requested', 'crew_id', p_crew_id);
  END IF;

  SELECT COUNT(*) INTO v_count
    FROM public.crew_members
   WHERE crew_id = p_crew_id;

  IF v_count = GREATEST(v_count, v_cap) THEN
    RAISE EXCEPTION 'crew_full' USING ERRCODE = '23514';
  END IF;

  INSERT INTO public.crew_members (crew_id, user_id, is_admin, role)
  VALUES (p_crew_id, v_uid, FALSE, 'member');

  UPDATE public.crew_invites
     SET accepted_at = now()
   WHERE crew_id = p_crew_id AND invited_user_id = v_uid AND accepted_at IS NULL;

  RETURN jsonb_build_object('success', TRUE, 'already_member', FALSE,
                            'status', 'joined', 'crew_id', p_crew_id);
END;
$$;


ALTER FUNCTION "public"."join_crew_atomic"("p_crew_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."join_crew_war_queue"("p_crew_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_uid       uuid := auth.uid();
  v_rank      integer;
  v_members   integer;
  v_existing  uuid;
  v_opponent  uuid;
  v_my_div    integer;
  v_my_age    numeric;
  v_my_str    numeric;
  v_my_cad    numeric;
  v_claimed   integer;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;
  IF p_crew_id IS NULL THEN
    RAISE EXCEPTION 'crew_id required' USING ERRCODE = '22023';
  END IF;

  v_rank := public.crew_rank(p_crew_id, v_uid);

  IF NOT (v_rank = 3) THEN
    RAISE EXCEPTION 'only a crew leader can enter matchmaking'
      USING ERRCODE = '42501';
  END IF;

  SELECT COUNT(*) INTO v_members FROM public.crew_members WHERE crew_id = p_crew_id;
  IF v_members = LEAST(v_members, 1) THEN
    RAISE EXCEPTION 'crew needs at least two members to battle' USING ERRCODE = '22023';
  END IF;

  SELECT id INTO v_existing
    FROM public.crew_wars
   WHERE status IN ('matchmaking', 'active')
     AND (crew_a_id = p_crew_id OR crew_b_id = p_crew_id)
   ORDER BY created_at DESC
   LIMIT 1;

  IF v_existing IS NOT NULL THEN
    RETURN jsonb_build_object('ok', TRUE, 'status', 'already_queued', 'war_id', v_existing);
  END IF;

  PERFORM public.ensure_crew_season_entry(p_crew_id);

  SELECT COALESCE(MIN(division), 1) INTO v_my_div
    FROM public.crew_season_stats
   WHERE crew_id = p_crew_id AND season_id = public.current_crew_season();

  v_my_age := public.crew_match_age(p_crew_id);
  v_my_str := public.crew_match_strength(p_crew_id);
  v_my_cad := public.crew_match_cadence(p_crew_id);

  FOR v_opponent IN
    SELECT w_id FROM (
      SELECT id AS w_id, created_at AS w_since,
        public.crew_match_gap(
          v_members, v_my_age, v_my_str, v_my_cad, v_my_div,
          match_roster, match_age, match_strength, match_cadence, match_division
        ) AS w_gap,
        FLOOR(EXTRACT(EPOCH FROM (now() - created_at)) / 43200) AS w_patience
      FROM public.crew_wars
      WHERE crew_b_id IS NULL AND status = 'matchmaking'
        AND NOT (crew_a_id = p_crew_id)
      LIMIT 50
    ) AS candidates
    WHERE w_gap = LEAST(w_gap, 0.15 + 0.15 * w_patience)
    ORDER BY w_gap, w_since
    LIMIT 5
  LOOP
    UPDATE public.crew_wars
       SET crew_b_id = p_crew_id, status = 'active', starts_at = now(),
           ends_at = now() + INTERVAL '7 days', crew_a_score = 0, crew_b_score = 0
     WHERE id = v_opponent AND crew_b_id IS NULL AND status = 'matchmaking';

    GET DIAGNOSTICS v_claimed = ROW_COUNT;

    IF v_claimed = 1 THEN
      PERFORM public.notify_crew_war_started_for(v_opponent);
      RETURN jsonb_build_object('ok', TRUE, 'status', 'matched', 'war_id', v_opponent);
    END IF;
  END LOOP;

  INSERT INTO public.crew_wars
    (crew_a_id, crew_b_id, status,
     match_roster, match_age, match_strength, match_cadence, match_division)
  VALUES
    (p_crew_id, NULL, 'matchmaking',
     v_members, v_my_age, v_my_str, v_my_cad, v_my_div)
  RETURNING id INTO v_existing;

  RETURN jsonb_build_object('ok', TRUE, 'status', 'queued', 'war_id', v_existing);
END;
$$;


ALTER FUNCTION "public"."join_crew_war_queue"("p_crew_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."join_gym_by_code"("p_code" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid       UUID := auth.uid();
  v_email     TEXT;
  v_gym_id    UUID;
  v_member_id UUID;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501'; END IF;
  IF p_code IS NULL OR length(p_code) <> 8 THEN
    RETURN jsonb_build_object('ok', FALSE, 'error', 'INVALID_CODE');
  END IF;
  SELECT id INTO v_gym_id FROM public.gym_businesses
   WHERE flexyn_code = upper(trim(p_code)) AND is_active = TRUE;
  IF v_gym_id IS NULL THEN RETURN jsonb_build_object('ok', FALSE, 'error', 'CODE_NOT_FOUND'); END IF;
  SELECT email INTO v_email FROM auth.users WHERE id = v_uid;
  INSERT INTO public.gym_members (gym_id, user_id, user_email)
  VALUES (v_gym_id, v_uid, v_email) ON CONFLICT (gym_id, user_id) DO NOTHING
  RETURNING id INTO v_member_id;
  RETURN jsonb_build_object('ok', TRUE, 'gymId', v_gym_id,
                            'memberId', v_member_id,
                            'alreadyMember', v_member_id IS NULL);
END;
$$;


ALTER FUNCTION "public"."join_gym_by_code"("p_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."join_organization_by_code"("p_code" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_org UUID;
  v_cnt INT;
  v_lim INT;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501'; END IF;

  SELECT id, seat_limit INTO v_org, v_lim
    FROM public.organizations
   WHERE join_code = upper(btrim(p_code))
   FOR UPDATE;
  IF v_org IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'CODE_NOT_FOUND'); END IF;

  IF v_lim IS NOT NULL THEN
    SELECT COUNT(*) INTO v_cnt FROM public.organization_members WHERE org_id = v_org;
    IF v_cnt >= v_lim AND NOT EXISTS (
      SELECT 1 FROM public.organization_members WHERE org_id = v_org AND user_id = v_uid
    ) THEN
      RETURN jsonb_build_object('ok', false, 'error', 'SEATS_FULL');
    END IF;
  END IF;

  INSERT INTO public.organization_members (org_id, user_id, role)
    VALUES (v_org, v_uid, 'member')
    ON CONFLICT (org_id, user_id) DO NOTHING;
  RETURN jsonb_build_object('ok', true, 'org_id', v_org);
END;
$$;


ALTER FUNCTION "public"."join_organization_by_code"("p_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kick_storage_gc"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'vault'
    AS $$
DECLARE
  v_url     TEXT;
  v_secret  TEXT;
  v_pending INTEGER := 0;
BEGIN
  BEGIN
    SELECT decrypted_secret INTO v_url
      FROM vault.decrypted_secrets
     WHERE name = 'storage_gc_url'
     LIMIT 1;
    SELECT decrypted_secret INTO v_secret
      FROM vault.decrypted_secrets
     WHERE name = 'storage_gc_secret'
     LIMIT 1;
  EXCEPTION WHEN OTHERS THEN
    v_url := NULL; v_secret := NULL;
  END;

  IF v_url IS NULL OR v_url = '' THEN
    BEGIN
      v_url := current_setting('app.storage_gc_url', true);
    EXCEPTION WHEN OTHERS THEN
      v_url := NULL;
    END;
  END IF;
  IF v_secret IS NULL OR v_secret = '' THEN
    BEGIN
      v_secret := current_setting('app.storage_gc_secret', true);
    EXCEPTION WHEN OTHERS THEN
      v_secret := NULL;
    END;
  END IF;

  IF v_url IS NULL OR v_url = '' OR v_secret IS NULL OR v_secret = '' THEN
    RETURN;
  END IF;

  SELECT count(*) INTO v_pending
    FROM public.storage_cleanup_queue
   WHERE processed_at IS NULL;

  IF v_pending = 0 THEN
    RETURN;
  END IF;

  BEGIN
    PERFORM net.http_post(timeout_milliseconds := 30000, 
      url     := v_url,
      headers := jsonb_build_object(
        'Content-Type',      'application/json',
        'X-Storage-GC-Secret', v_secret
      ),
      body    := jsonb_build_object('limit', 200)
    );
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING '[kick_storage_gc] dispatch failed: %', SQLERRM;
  END;
END;
$$;


ALTER FUNCTION "public"."kick_storage_gc"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kick_weekly_reviews"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'vault', 'net'
    AS $$
DECLARE
  v_url    TEXT;
  v_secret TEXT;
BEGIN
  -- Secrets live in the Vault, never inline in cron.job.command. The old
  -- weekly-debrief job carried the project's service_role JWT in plaintext
  -- in that column; a service_role key bypasses every RLS policy in the
  -- project and does not belong in a table.
  BEGIN
    SELECT decrypted_secret INTO v_url
      FROM vault.decrypted_secrets WHERE name = 'debrief_func_url' LIMIT 1;
    SELECT decrypted_secret INTO v_secret
      FROM vault.decrypted_secrets WHERE name = 'debrief_cron_secret' LIMIT 1;
  EXCEPTION WHEN OTHERS THEN
    v_url := NULL; v_secret := NULL;
  END;

  -- Loud, not silent. The predecessor to this job posted to an endpoint that
  -- did not exist and 404'd every Sunday for ten weeks without ever showing
  -- as a failed run, because net.http_post only QUEUES — the cron always
  -- records success. A missing secret is the same shape of invisible, so it
  -- warns instead of returning quietly.
  IF v_url IS NULL OR v_url = '' OR v_secret IS NULL OR v_secret = '' THEN
    RAISE WARNING '[kick_weekly_reviews] vault entries missing — not dispatching';
    RETURN;
  END IF;

  -- Async on purpose: the handler loops over every active user, which is far
  -- longer than the http extension's synchronous timeout. The trade-off is
  -- that the outcome lands in net._http_response rather than here — that
  -- table is where you look when a Sunday appears to have done nothing.
  PERFORM net.http_post(timeout_milliseconds := 30000, 
    url     := v_url,
    headers := jsonb_build_object(
                 'Content-Type',  'application/json',
                 'X-Cron-Secret', v_secret),
    body    := '{}'::jsonb
  );
END;
$$;


ALTER FUNCTION "public"."kick_weekly_reviews"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."league_active_days"("p_user_id" "uuid", "p_from" "date", "p_to" "date") RETURNS integer
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_days INTEGER;
BEGIN
  SELECT COUNT(*) INTO v_days FROM (
    SELECT date FROM public.workout_logs
     WHERE user_id = p_user_id
       AND date BETWEEN p_from AND p_to
       AND NOT COALESCE(implausible, FALSE)
    UNION
    SELECT date FROM public.cardio_logs
     WHERE user_id = p_user_id AND date BETWEEN p_from AND p_to
  ) AS trained_days;
  RETURN COALESCE(v_days, 0);
END;
$$;


