CREATE OR REPLACE FUNCTION "public"."league_season_name"("p_number" integer) RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_words CONSTANT TEXT[] := ARRAY[
    'Foundation', 'Ascent', 'Forge', 'Summit',
    'Ironclad', 'Vanguard', 'Bedrock', 'Apex'
  ];
BEGIN
  IF p_number IS NULL OR p_number < 1 THEN
    RETURN 'Season 1 · Foundation';
  END IF;
  RETURN 'Season ' || p_number || ' · ' || v_words[((p_number - 1) % 8) + 1];
END;
$$;


ALTER FUNCTION "public"."league_season_name"("p_number" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."league_season_record_internal"("p_user_id" "uuid", "p_email" "text", "p_tier" "text", "p_qualified" boolean, "p_xp" integer) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_season   UUID;
  v_existing TEXT;
  v_rank_new INTEGER;
  v_rank_old INTEGER;
BEGIN
  IF p_user_id IS NULL THEN
    RETURN;
  END IF;

  v_season := public.current_league_season();
  IF v_season IS NULL THEN
    RETURN;
  END IF;

  INSERT INTO public.league_season_stats
    (season_id, user_id, user_email, best_tier, weeks_qualified, season_xp)
  VALUES
    (v_season, p_user_id, COALESCE(p_email, ''), COALESCE(p_tier, 'bronze'),
     CASE WHEN p_qualified THEN 1 ELSE 0 END, GREATEST(0, COALESCE(p_xp, 0)))
  ON CONFLICT (season_id, user_id) DO UPDATE
    SET weeks_qualified = public.league_season_stats.weeks_qualified
                          + CASE WHEN p_qualified THEN 1 ELSE 0 END,
        season_xp       = public.league_season_stats.season_xp
                          + GREATEST(0, COALESCE(p_xp, 0));

  SELECT best_tier INTO v_existing
    FROM public.league_season_stats
   WHERE season_id = v_season AND user_id = p_user_id;

  v_rank_new := CASE COALESCE(p_tier, 'bronze')
                  WHEN 'bronze' THEN 1 WHEN 'silver' THEN 2 WHEN 'gold' THEN 3
                  WHEN 'platinum' THEN 4 WHEN 'diamond' THEN 5 WHEN 'legend' THEN 6
                  ELSE 1 END;
  v_rank_old := CASE COALESCE(v_existing, 'bronze')
                  WHEN 'bronze' THEN 1 WHEN 'silver' THEN 2 WHEN 'gold' THEN 3
                  WHEN 'platinum' THEN 4 WHEN 'diamond' THEN 5 WHEN 'legend' THEN 6
                  ELSE 1 END;

  IF v_rank_new > v_rank_old THEN
    UPDATE public.league_season_stats
       SET best_tier = p_tier
     WHERE season_id = v_season AND user_id = p_user_id;
  END IF;
END;
$$;


ALTER FUNCTION "public"."league_season_record_internal"("p_user_id" "uuid", "p_email" "text", "p_tier" "text", "p_qualified" boolean, "p_xp" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."leave_crew"("p_crew_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_uid      uuid := auth.uid();
  v_member   integer;
  v_leader   boolean;
  v_leaders  integer;
  v_members  integer;
  v_war      integer;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;
  IF p_crew_id IS NULL THEN
    RAISE EXCEPTION 'crew_id required' USING ERRCODE = '22023';
  END IF;

  SELECT COUNT(*) INTO v_member
    FROM public.crew_members WHERE crew_id = p_crew_id AND user_id = v_uid;

  IF v_member = 0 THEN
    RETURN jsonb_build_object('ok', FALSE, 'reason', 'not_a_member');
  END IF;

  SELECT is_admin INTO v_leader
    FROM public.crew_members WHERE crew_id = p_crew_id AND user_id = v_uid;

  SELECT COUNT(*) INTO v_members
    FROM public.crew_members WHERE crew_id = p_crew_id;

  SELECT COUNT(*) INTO v_leaders
    FROM public.crew_members WHERE crew_id = p_crew_id AND is_admin = TRUE;

  IF v_leader IS TRUE AND v_leaders = 1 AND NOT (v_members = 1) THEN
    RETURN jsonb_build_object('ok', FALSE, 'reason', 'promote_first');
  END IF;

  IF v_members = 1 THEN
    SELECT COUNT(*) INTO v_war
      FROM public.crew_wars
     WHERE status IN ('matchmaking', 'active')
       AND (crew_a_id = p_crew_id OR crew_b_id = p_crew_id);

    IF NOT (v_war = 0) THEN
      RETURN jsonb_build_object('ok', FALSE, 'reason', 'active_war');
    END IF;

    DELETE FROM public.crew_members WHERE crew_id = p_crew_id AND user_id = v_uid;
    DELETE FROM public.crews WHERE id = p_crew_id;

    RETURN jsonb_build_object('ok', TRUE, 'left', TRUE, 'crew_deleted', TRUE);
  END IF;

  DELETE FROM public.crew_members WHERE crew_id = p_crew_id AND user_id = v_uid;

  RETURN jsonb_build_object('ok', TRUE, 'left', TRUE, 'crew_deleted', FALSE);
END;
$$;


ALTER FUNCTION "public"."leave_crew"("p_crew_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."leave_crew_war_queue"("p_crew_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_uid     uuid := auth.uid();
  v_rank    integer;
  v_removed integer;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;

  v_rank := public.crew_rank(p_crew_id, v_uid);
  IF NOT (v_rank = 3) THEN
    RAISE EXCEPTION 'only a crew leader can leave the queue' USING ERRCODE = '42501';
  END IF;

  DELETE FROM public.crew_wars
   WHERE crew_a_id = p_crew_id
     AND crew_b_id IS NULL
     AND status = 'matchmaking';

  GET DIAGNOSTICS v_removed = ROW_COUNT;
  RETURN jsonb_build_object('ok', TRUE, 'removed', v_removed);
END;
$$;


ALTER FUNCTION "public"."leave_crew_war_queue"("p_crew_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."legend_season_board"("p_limit" integer DEFAULT 20) RETURNS TABLE("user_id" "uuid", "username" "text", "avatar_url" "text", "season_xp" integer, "weeks_qualified" integer)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
#variable_conflict use_column
DECLARE
  v_season UUID;
  v_limit  INTEGER;
  v_uid    UUID;
  v_name   TEXT;
  v_avatar TEXT;
  v_xp     INTEGER;
  v_weeks  INTEGER;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;

  SELECT id INTO v_season
    FROM public.league_seasons
   WHERE status = 'active'
   ORDER BY season_number DESC
   LIMIT 1;

  IF v_season IS NULL THEN
    RETURN;
  END IF;

  v_limit := GREATEST(1, LEAST(COALESCE(p_limit, 20), 100));

  FOR v_uid, v_xp, v_weeks IN
    SELECT user_id, season_xp, weeks_qualified
      FROM public.league_season_stats
     WHERE season_id = v_season
       AND best_tier = 'legend'
     ORDER BY season_xp DESC, weeks_qualified DESC
     LIMIT v_limit
  LOOP
    SELECT username, avatar_url INTO v_name, v_avatar
      FROM public.public_profiles
     WHERE id = v_uid;

    user_id         := v_uid;
    username        := v_name;
    avatar_url      := v_avatar;
    season_xp       := v_xp;
    weeks_qualified := v_weeks;
    RETURN NEXT;
  END LOOP;

  RETURN;
END;
$$;


ALTER FUNCTION "public"."legend_season_board"("p_limit" integer) OWNER TO "postgres";


