CREATE OR REPLACE FUNCTION "public"."list_crew_join_requests"("p_crew_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_out JSONB; v_id UUID; v_msg TEXT; v_at TIMESTAMPTZ;
  v_username TEXT; v_full TEXT; v_avatar TEXT; v_level INTEGER;
BEGIN
  IF v_uid IS NULL OR p_crew_id IS NULL THEN RETURN '[]'::jsonb; END IF;
  IF NOT public.crew_can_review(p_crew_id, v_uid) THEN RETURN '[]'::jsonb; END IF;

  v_out := '[]'::jsonb;

  FOR v_id, v_msg, v_at IN
    SELECT user_id, message, created_at
      FROM public.crew_join_requests
     WHERE crew_id = p_crew_id AND status = 'pending'
     ORDER BY created_at ASC
  LOOP
    SELECT username, full_name, avatar_url, current_level
      INTO v_username, v_full, v_avatar, v_level
      FROM public.user_profiles WHERE id = v_id;

    v_out := v_out || jsonb_build_array(jsonb_build_object(
      'user_id', v_id, 'username', v_username, 'full_name', v_full,
      'avatar_url', v_avatar, 'current_level', v_level,
      'message', v_msg, 'created_at', v_at));
  END LOOP;

  RETURN v_out;
END;
$$;


ALTER FUNCTION "public"."list_crew_join_requests"("p_crew_id" "uuid") OWNER TO "postgres";


