CREATE OR REPLACE FUNCTION "public"."list_reports_for_admin"("p_status" "text" DEFAULT 'pending'::"text", "p_limit" integer DEFAULT 50) RETURNS TABLE("id" "uuid", "reporter_email" "text", "reported_type" "text", "reported_id" "uuid", "reported_author_email" "text", "reason" "text", "detail" "text", "status" "text", "content_snippet" "text", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT public.is_app_admin(auth.uid()) THEN
    RAISE EXCEPTION 'admin_only' USING ERRCODE = '42501';
  END IF;
  RETURN QUERY
    SELECT
      r.id,
      r.reporter_email,
      r.reported_type,
      r.reported_id,
      r.reported_author_email,
      r.reason,
      r.detail,
      r.status,
      CASE r.reported_type
        WHEN 'post'    THEN (SELECT substring(content FROM 1 FOR 280) FROM public.hub_posts    WHERE id = r.reported_id)
        WHEN 'comment' THEN (SELECT substring(content FROM 1 FOR 280) FROM public.hub_comments WHERE id = r.reported_id)
        ELSE NULL
      END,
      r.created_at
    FROM public.hub_reports r
    WHERE r.status = p_status
    ORDER BY r.created_at DESC
    LIMIT p_limit;
END;
$$;


