CREATE OR REPLACE FUNCTION "public"."mark_message_read"("p_message_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid      UUID := auth.uid();
  v_email    TEXT := NULLIF(public.current_user_email(), '');
  v_conv     UUID;
  v_receipts BOOLEAN;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;
  IF p_message_id IS NULL THEN
    RAISE EXCEPTION 'message_id required' USING ERRCODE = '22023';
  END IF;

  SELECT conversation_id INTO v_conv
    FROM public.hub_messages
   WHERE id = p_message_id
     AND read_at IS NULL
     AND (created_by IS DISTINCT FROM v_email)
     AND (user_id    IS DISTINCT FROM v_uid);

  IF v_conv IS NULL THEN
    RETURN;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.hub_conversations
     WHERE id = v_conv
       AND (v_email = ANY(participant_emails)
            OR v_uid = ANY(participant_ids))
  ) THEN
    RAISE EXCEPTION 'not a conversation participant' USING ERRCODE = '42501';
  END IF;

  SELECT coalesce(read_receipts_enabled, TRUE)
    INTO v_receipts
    FROM public.user_profiles
   WHERE id = v_uid;

  IF v_receipts IS NOT NULL AND NOT v_receipts THEN
    RETURN;
  END IF;

  UPDATE public.hub_messages
     SET read_at = now()
   WHERE id = p_message_id
     AND read_at IS NULL;
END;
$$;


ALTER FUNCTION "public"."mark_message_read"("p_message_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mark_messages_delivered"("p_conv_ids" "uuid"[]) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_email TEXT := lower(coalesce(NULLIF(public.current_user_email(), ''), ''));
  v_uid   UUID := auth.uid();
  v_ok    UUID[];
  v_done  INTEGER := 0;
BEGIN
  IF v_email = '' THEN
    RETURN 0;
  END IF;
  IF p_conv_ids IS NULL OR array_length(p_conv_ids, 1) IS NULL THEN
    RETURN 0;
  END IF;
  IF NOT (array_length(p_conv_ids, 1) = least(array_length(p_conv_ids, 1), 200)) THEN
    RAISE EXCEPTION 'too_many_conversations' USING ERRCODE = '22023';
  END IF;

  SELECT array_agg(id)
    INTO v_ok
    FROM public.hub_conversations
   WHERE id = ANY (p_conv_ids)
     AND (
       v_email = ANY (
         ARRAY(
           SELECT lower(participant_email)
             FROM unnest(coalesce(participant_emails, ARRAY[]::text[]))
               AS participant_email
         )
       )
       OR v_uid = ANY (coalesce(participant_ids, ARRAY[]::uuid[]))
     );

  IF v_ok IS NULL THEN
    RETURN 0;
  END IF;

  UPDATE public.hub_messages
     SET delivered_at = now()
   WHERE conversation_id = ANY (v_ok)
     AND delivered_at IS NULL
     AND status <> 'scheduled'
     AND NOT (lower(coalesce(sender_email, created_by, '')) = v_email);

  GET DIAGNOSTICS v_done = ROW_COUNT;
  RETURN v_done;
END;
$$;


ALTER FUNCTION "public"."mark_messages_delivered"("p_conv_ids" "uuid"[]) OWNER TO "postgres";


