CREATE OR REPLACE FUNCTION "public"."mark_workout_active"("p_duration_minutes" integer DEFAULT 90) RETURNS timestamp with time zone
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid    UUID := auth.uid();
  v_capped INT  := LEAST(GREATEST(COALESCE(p_duration_minutes, 90), 1), 240);
  v_until  TIMESTAMPTZ;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;
  v_until := now() + (v_capped || ' minutes')::interval;
  UPDATE public.user_profiles SET active_until = v_until WHERE id = v_uid;
  RETURN v_until;
END;
$$;


