CREATE OR REPLACE FUNCTION "public"."my_league_season"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid    UUID := auth.uid();
  v_season UUID;
  v_num    INTEGER;
  v_name   TEXT;
  v_starts TIMESTAMPTZ;
  v_ends   TIMESTAMPTZ;
  v_tier   TEXT;
  v_weeks  INTEGER;
  v_xp     INTEGER;
  v_rank   INTEGER;
  v_field  INTEGER;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;

  v_season := public.current_league_season();

  IF v_season IS NULL THEN
    SELECT season_number, name, starts_at, ends_at
      INTO v_num, v_name, v_starts, v_ends
      FROM public.league_seasons
     WHERE status = 'active'
       AND starts_at = GREATEST(starts_at, now())
       AND NOT (starts_at = now())
     ORDER BY season_number
     LIMIT 1;

    IF v_num IS NULL THEN
      RETURN NULL;
    END IF;

    RETURN jsonb_build_object(
      'pre_season',      TRUE,
      'season_number',   v_num,
      'name',            v_name,
      'starts_at',       v_starts,
      'ends_at',         v_ends,
      'best_tier',       'bronze',
      'weeks_qualified', 0,
      'weeks_needed',    2,
      'season_xp',       0,
      'season_rank',     NULL,
      'field_size',      0
    );
  END IF;

  SELECT season_number, name, starts_at, ends_at
    INTO v_num, v_name, v_starts, v_ends
    FROM public.league_seasons WHERE id = v_season;

  SELECT best_tier, weeks_qualified, season_xp
    INTO v_tier, v_weeks, v_xp
    FROM public.league_season_stats
   WHERE season_id = v_season AND user_id = v_uid;

  SELECT COUNT(*) INTO v_field
    FROM public.league_season_stats WHERE season_id = v_season;

  SELECT COUNT(*) + 1 INTO v_rank
    FROM public.league_season_stats
   WHERE season_id = v_season
     AND season_xp > COALESCE(v_xp, 0);

  RETURN jsonb_build_object(
    'pre_season',      FALSE,
    'season_number',   v_num,
    'name',            v_name,
    'starts_at',       v_starts,
    'ends_at',         v_ends,
    'best_tier',       COALESCE(v_tier, 'bronze'),
    'weeks_qualified', COALESCE(v_weeks, 0),
    'weeks_needed',    2,
    'season_xp',       COALESCE(v_xp, 0),
    'season_rank',     CASE WHEN v_xp IS NULL THEN NULL ELSE v_rank END,
    'field_size',      COALESCE(v_field, 0)
  );
END;
$$;


ALTER FUNCTION "public"."my_league_season"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."my_league_shields"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
