CREATE OR REPLACE FUNCTION "public"."notification_type_category"("p_type" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
  SELECT CASE p_type
    WHEN 'streak_milestone'         THEN 'streak'
    WHEN 'streak_break_warning'     THEN 'streak'
    WHEN 'streak_rescued'           THEN 'streak'
    WHEN 'quest_claimed'            THEN 'quests'
    WHEN 'quest_expiry_warning'     THEN 'quests'
    WHEN 'league_promoted'          THEN 'league'
    WHEN 'league_demoted'           THEN 'league'
    WHEN 'league_held'              THEN 'league'
    WHEN 'league_promotion'         THEN 'league'
    WHEN 'league_demotion'          THEN 'league'
    WHEN 'friend_post'              THEN 'social'
    WHEN 'friend_follow'            THEN 'social'
    WHEN 'comment_reply'            THEN 'social'
    WHEN 'post_reaction'            THEN 'social'
    WHEN 'post_like'                THEN 'social'
    WHEN 'sticker_reaction'         THEN 'social'
    WHEN 'trade_offer'              THEN 'social'
    WHEN 'crew_everyone'            THEN 'social'
    WHEN 'coin_gift'                THEN 'social'
    WHEN 'gym_member_joined'        THEN 'social'
    WHEN 'story_reaction'           THEN 'social'
    WHEN 'dm_received'              THEN 'social'
    WHEN 'pr_set'                   THEN 'achievements'
    WHEN 'capsule_earned'           THEN 'achievements'
    WHEN 'coin_milestone'           THEN 'achievements'
    WHEN 'welcome_back'             THEN 'engagement'
    WHEN 'weekly_gauntlet_started'  THEN 'engagement'
    WHEN 'memory_reengagement'      THEN 'engagement'
    WHEN 'referral_success'         THEN 'engagement'
    WHEN 'comeback_protocol'        THEN 'engagement'
    WHEN 'duel_invite'              THEN 'competitive'
    WHEN 'duel_result'              THEN 'competitive'
    WHEN 'bounty_claim'             THEN 'competitive'
    WHEN 'bounty_beaten'            THEN 'competitive'
    WHEN 'crew_war_started'         THEN 'competitive'
    WHEN 'crew_war_resolved'        THEN 'competitive'
    WHEN 'nemesis_assigned'         THEN 'competitive'
    WHEN 'nemesis_overthrown'       THEN 'competitive'
    WHEN 'gauntlet_path_completed'  THEN 'competitive'
    WHEN 'crew_challenge_created'   THEN 'competitive'
    WHEN 'crew_challenge_completed' THEN 'competitive'
    ELSE NULL
  END;
$$;


ALTER FUNCTION "public"."notification_type_category"("p_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notifications_add_metadata_names"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_name  TEXT;
  v_other UUID;
BEGIN
  IF NEW.type NOT IN ('crew_war_started', 'crew_war_resolved', 'nemesis_assigned') THEN
    RETURN NEW;
  END IF;

  IF NEW.metadata IS NULL THEN
    NEW.metadata := '{}'::jsonb;
  END IF;

  IF NEW.type IN ('crew_war_started', 'crew_war_resolved') THEN
    IF NEW.metadata ? 'opponent_crew_name' THEN
      RETURN NEW;
    END IF;
    SELECT name INTO v_name
      FROM public.crews
     WHERE id = (NEW.metadata ->> 'opponent_crew_id')::UUID;
    IF v_name IS NOT NULL THEN
      NEW.metadata := NEW.metadata || jsonb_build_object('opponent_crew_name', v_name);
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.metadata ? 'rival_display_name' THEN
    RETURN NEW;
  END IF;

  IF NEW.metadata ? 'initiator_id' THEN
    SELECT username INTO v_name
      FROM public.user_profiles
     WHERE id = (NEW.metadata ->> 'initiator_id')::UUID;

  ELSIF NEW.metadata ? 'rival_id' THEN
    SELECT username INTO v_name
      FROM public.user_profiles
     WHERE id = (NEW.metadata ->> 'rival_id')::UUID;

  ELSIF NEW.metadata ? 'assignment_id' THEN
    SELECT CASE WHEN user_id = NEW.user_id THEN rival_id ELSE user_id END
      INTO v_other
      FROM public.gym_rival_assignments
     WHERE id = (NEW.metadata ->> 'assignment_id')::UUID;

    IF v_other IS NOT NULL THEN
      SELECT username INTO v_name
        FROM public.user_profiles
       WHERE id = v_other;
    END IF;
  END IF;

  IF v_name IS NOT NULL THEN
    NEW.metadata := NEW.metadata || jsonb_build_object('rival_display_name', v_name);
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."notifications_add_metadata_names"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notifications_fill_user_email"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.user_email IS NULL THEN
    SELECT email INTO NEW.user_email FROM public.user_profiles WHERE id = NEW.user_id;
  END IF;
  IF NEW.user_email IS NULL THEN
    SELECT email INTO NEW.user_email FROM auth.users WHERE id = NEW.user_id;
  END IF;
  IF NEW.user_email IS NULL THEN
    NEW.user_email := 'user_' || COALESCE(NEW.user_id::text, 'unknown') || '@flexyn.invalid';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."notifications_fill_user_email"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_bounty_beaten_for"("p_bounty_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_sender    UUID := auth.uid();
  v_bounty    public.bounties%ROWTYPE;
  v_email     TEXT;
  v_lang      TEXT;
  v_text      JSONB;
  v_id        UUID;
  v_claimant  TEXT;
BEGIN
  IF v_sender IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;
  IF p_bounty_id IS NULL THEN
    RAISE EXCEPTION 'bounty_id required' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_bounty FROM public.bounties WHERE id = p_bounty_id;
  IF v_bounty IS NULL THEN
    RETURN NULL;
  END IF;
  IF v_bounty.claimed_by_id IS DISTINCT FROM v_sender THEN
    RAISE EXCEPTION 'not your claim' USING ERRCODE = '42501';
  END IF;
  IF v_bounty.target_user_id = v_sender THEN
    RETURN NULL;
  END IF;

  SELECT u.email, prof.preferred_language
    INTO v_email, v_lang
    FROM auth.users u
    LEFT JOIN public.user_profiles prof ON prof.id = u.id
   WHERE u.id = v_bounty.target_user_id;
  IF v_email IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT username INTO v_claimant
    FROM public.user_profiles
   WHERE id = v_sender;

  v_text := public.bounty_beaten_text(COALESCE(v_lang, 'en'), COALESCE(v_claimant, 'Someone'));

  INSERT INTO public.notifications
    (user_id, user_email, type, title, body, icon, link_url, metadata)
  VALUES
    (v_bounty.target_user_id,
     v_email,
     'bounty_beaten',
     v_text ->> 'title',
     v_text ->> 'body',
     '👑',
     '/bounties',
     jsonb_build_object(
       'bounty_id',       p_bounty_id,
       'claimant_id',     v_sender,
       'claimant_name',   v_claimant
     ))
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."notify_bounty_beaten_for"("p_bounty_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_bounty_claim_for"("p_bounty_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_sender    UUID := auth.uid();
  v_bounty    public.bounties%ROWTYPE;
  v_email     TEXT;
  v_lang      TEXT;
  v_text      JSONB;
  v_id        UUID;
  v_claimant  TEXT;
BEGIN
  IF v_sender IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;
  IF p_bounty_id IS NULL THEN
    RAISE EXCEPTION 'bounty_id required' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_bounty FROM public.bounties WHERE id = p_bounty_id;
  IF v_bounty IS NULL THEN
    RETURN NULL;
  END IF;
  -- Caller must be the actual claimant; the target should never notify themselves.
  IF v_bounty.claimed_by_id IS DISTINCT FROM v_sender THEN
    RAISE EXCEPTION 'not your claim' USING ERRCODE = '42501';
  END IF;
  IF v_bounty.target_user_id = v_sender THEN
    RETURN NULL;
  END IF;

  SELECT u.email, prof.preferred_language
    INTO v_email, v_lang
    FROM auth.users u
    LEFT JOIN public.user_profiles prof ON prof.id = u.id
   WHERE u.id = v_bounty.target_user_id;
  IF v_email IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT username INTO v_claimant
    FROM public.user_profiles
   WHERE id = v_sender;

  v_text := public.bounty_claim_text(COALESCE(v_lang, 'en'), COALESCE(v_claimant, 'Someone'));

  INSERT INTO public.notifications
    (user_id, user_email, type, title, body, icon, link_url, metadata)
  VALUES
    (v_bounty.target_user_id,
     v_email,
     'bounty_claim',
     v_text ->> 'title',
     v_text ->> 'body',
     '🎯',
     '/bounties',
     jsonb_build_object(
       'bounty_id',       p_bounty_id,
       'claimant_id',     v_sender,
       'claimant_name',   v_claimant,
       'metric',          v_bounty.metric,
       'exercise_name',   v_bounty.exercise_name,
       'target_value',    v_bounty.target_value
     ))
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."notify_bounty_claim_for"("p_bounty_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_comment_reply_for"("p_comment_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_caller          UUID := auth.uid();
  v_comment         RECORD;
  v_parent          RECORD;
  v_post            RECORD;
  v_recipient_id    UUID;
  v_recipient_email TEXT;
  v_recipient_lang  TEXT;
  v_commenter_name  TEXT;
  v_snippet         TEXT;
  v_is_reply        BOOLEAN;
  v_text            JSONB;
  v_id              UUID;
BEGIN
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;
  IF p_comment_id IS NULL THEN
    RAISE EXCEPTION 'comment_id required' USING ERRCODE = '22023';
  END IF;

  SELECT id, user_id, post_id, parent_comment_id, content, body,
         author_name, author_email
    INTO v_comment
    FROM public.hub_comments
   WHERE id = p_comment_id;

  IF v_comment.id IS NULL THEN RETURN NULL; END IF;
  IF v_comment.user_id IS DISTINCT FROM v_caller THEN
    RAISE EXCEPTION 'not your comment' USING ERRCODE = '42501';
  END IF;

  v_is_reply := v_comment.parent_comment_id IS NOT NULL;

  IF v_is_reply THEN
    SELECT user_id INTO v_parent FROM public.hub_comments WHERE id = v_comment.parent_comment_id;
    v_recipient_id := v_parent.user_id;
  ELSE
    SELECT user_id, author_email INTO v_post FROM public.hub_posts WHERE id = v_comment.post_id;
    v_recipient_id := v_post.user_id;
  END IF;

  IF v_recipient_id IS NULL THEN RETURN NULL; END IF;
  IF v_recipient_id = v_caller THEN RETURN NULL; END IF;

  SELECT u.email, prof.preferred_language
    INTO v_recipient_email, v_recipient_lang
    FROM auth.users u
    LEFT JOIN public.user_profiles prof ON prof.id = u.id
   WHERE u.id = v_recipient_id;
  IF v_recipient_email IS NULL THEN RETURN NULL; END IF;

  SELECT username INTO v_commenter_name FROM public.user_profiles WHERE id = v_caller;
  v_commenter_name := COALESCE(
    v_commenter_name,
    split_part(COALESCE(v_comment.author_email, ''), '@', 1),
    'Someone'
  );

  v_snippet := substring(COALESCE(v_comment.body, v_comment.content, '') FROM 1 FOR 80);
  IF length(COALESCE(v_comment.body, v_comment.content, '')) > 80 THEN
    v_snippet := v_snippet || '…';
  END IF;

  v_text := public.comment_reply_text(
    COALESCE(v_recipient_lang, 'en'),
    v_commenter_name,
    v_snippet,
    v_is_reply
  );

  INSERT INTO public.notifications
    (user_id, user_email, type, title, body, icon, link_url, metadata)
  VALUES
    (v_recipient_id, v_recipient_email, 'comment_reply',
     v_text ->> 'title', v_text ->> 'body', '💬', '/hub',
     jsonb_build_object(
       'comment_id', p_comment_id,
       'post_id', v_comment.post_id,
       'parent_comment_id', v_comment.parent_comment_id,
       'commenter_id', v_caller,
       'commenter_name', v_commenter_name,
       'is_reply', v_is_reply
     ))
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."notify_comment_reply_for"("p_comment_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_crew_challenge_completed_for"("p_challenge_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_caller       UUID := auth.uid();
  v_chal_id      UUID;
  v_chal_crew_id UUID;
  v_chal_title   TEXT;
  v_chal_metric  TEXT;
  v_chal_target  INTEGER;
  v_chal_status  TEXT;
  v_crew_name    TEXT;
  v_count        INT := 0;
BEGIN
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;
  IF p_challenge_id IS NULL THEN
    RAISE EXCEPTION 'challenge_id required' USING ERRCODE = '22023';
  END IF;

  SELECT id, crew_id, title, metric, target_value, status
    INTO v_chal_id, v_chal_crew_id, v_chal_title, v_chal_metric,
         v_chal_target, v_chal_status
    FROM public.crew_challenges
   WHERE id = p_challenge_id;
  IF v_chal_id IS NULL THEN RETURN 0; END IF;
  IF v_chal_status <> 'completed' THEN RETURN 0; END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.crew_members
     WHERE crew_id = v_chal_crew_id
       AND user_id = v_caller
  ) THEN
    RAISE EXCEPTION 'not a crew member' USING ERRCODE = '42501';
  END IF;

  SELECT name INTO v_crew_name FROM public.crews WHERE id = v_chal_crew_id;

  WITH member_rows AS (
    SELECT user_id AS member_user_id
      FROM public.crew_members
     WHERE crew_id = v_chal_crew_id
  ),
  recipient AS (
    SELECT id                                 AS notif_user_id,
           email                              AS notif_email,
           COALESCE(preferred_language, 'en') AS notif_lang
      FROM public.user_profiles
     WHERE email IS NOT NULL
       AND id IN (SELECT member_user_id FROM member_rows)
  ),
  localized AS (
    SELECT notif_user_id,
           notif_email,
           public.crew_challenge_completed_text(notif_lang, v_chal_title, v_crew_name) AS notif_text
      FROM recipient
  ),
  inserted AS (
    INSERT INTO public.notifications
      (user_id, user_email, type, title, body, icon, link_url, metadata)
    SELECT notif_user_id,
           notif_email,
           'crew_challenge_completed',
           notif_text ->> 'title',
           notif_text ->> 'body',
           '🏆',
           '/hub',
           jsonb_build_object(
             'challenge_id', p_challenge_id,
             'crew_id',      v_chal_crew_id,
             'metric',       v_chal_metric,
             'target_value', v_chal_target
           )
      FROM localized
    RETURNING 1
  )
  SELECT count(*) INTO v_count FROM inserted;

  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."notify_crew_challenge_completed_for"("p_challenge_id" "uuid") OWNER TO "postgres";


