CREATE OR REPLACE FUNCTION "public"."notify_crew_war_resolved_for"("p_war_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_sender    UUID := auth.uid();
  v_war       public.crew_wars%ROWTYPE;
  v_crew_a    public.crews%ROWTYPE;
  v_crew_b    public.crews%ROWTYPE;
  v_member    RECORD;
  v_count     INT := 0;
  v_outcome   TEXT;
  v_opponent  TEXT;
  v_text      JSONB;
BEGIN
  IF v_sender IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;
  IF p_war_id IS NULL THEN
    RAISE EXCEPTION 'war_id required' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_war FROM public.crew_wars WHERE id = p_war_id;
  IF v_war IS NULL OR v_war.status <> 'completed' THEN
    RETURN 0;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.crew_members
     WHERE user_id = v_sender
       AND crew_id IN (v_war.crew_a_id, v_war.crew_b_id)
  ) THEN
    RAISE EXCEPTION 'not your war' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_crew_a FROM public.crews WHERE id = v_war.crew_a_id;
  SELECT * INTO v_crew_b FROM public.crews WHERE id = v_war.crew_b_id;

  -- Crew A side
  IF v_war.winner_crew_id IS NULL                    THEN v_outcome := 'tied';
  ELSIF v_war.winner_crew_id = v_war.crew_a_id       THEN v_outcome := 'won';
  ELSE                                                    v_outcome := 'lost'; END IF;
  v_opponent := COALESCE(v_crew_b.name, 'rival crew');

  FOR v_member IN
    SELECT cm.user_id, up.email, prof.preferred_language
      FROM public.crew_members cm
      JOIN public.user_profiles up   ON up.id = cm.user_id
      LEFT JOIN public.user_profiles prof ON prof.id = cm.user_id
     WHERE cm.crew_id = v_war.crew_a_id
       AND up.email IS NOT NULL
  LOOP
    v_text := public.crew_war_resolved_text(
      COALESCE(v_member.preferred_language, 'en'), v_opponent, v_outcome);
    INSERT INTO public.notifications
      (user_id, user_email, type, title, body, icon, link_url, metadata)
    VALUES
      (v_member.user_id, v_member.email, 'crew_war_resolved',
       v_text ->> 'title', NULL,
       CASE v_outcome WHEN 'won' THEN '🏆' WHEN 'lost' THEN '💪' ELSE '🤝' END,
       '/hub',
       jsonb_build_object('war_id', p_war_id, 'outcome', v_outcome,
                          'opponent_crew_id', v_war.crew_b_id,
                          'crew_a_score', v_war.crew_a_score,
                          'crew_b_score', v_war.crew_b_score));
    v_count := v_count + 1;
  END LOOP;

  -- Crew B side
  IF v_war.winner_crew_id IS NULL                    THEN v_outcome := 'tied';
  ELSIF v_war.winner_crew_id = v_war.crew_b_id       THEN v_outcome := 'won';
  ELSE                                                    v_outcome := 'lost'; END IF;
  v_opponent := COALESCE(v_crew_a.name, 'rival crew');

  FOR v_member IN
    SELECT cm.user_id, up.email, prof.preferred_language
      FROM public.crew_members cm
      JOIN public.user_profiles up   ON up.id = cm.user_id
      LEFT JOIN public.user_profiles prof ON prof.id = cm.user_id
     WHERE cm.crew_id = v_war.crew_b_id
       AND up.email IS NOT NULL
  LOOP
    v_text := public.crew_war_resolved_text(
      COALESCE(v_member.preferred_language, 'en'), v_opponent, v_outcome);
    INSERT INTO public.notifications
      (user_id, user_email, type, title, body, icon, link_url, metadata)
    VALUES
      (v_member.user_id, v_member.email, 'crew_war_resolved',
       v_text ->> 'title', NULL,
       CASE v_outcome WHEN 'won' THEN '🏆' WHEN 'lost' THEN '💪' ELSE '🤝' END,
       '/hub',
       jsonb_build_object('war_id', p_war_id, 'outcome', v_outcome,
                          'opponent_crew_id', v_war.crew_a_id,
                          'crew_a_score', v_war.crew_a_score,
                          'crew_b_score', v_war.crew_b_score));
    v_count := v_count + 1;
  END LOOP;

  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."notify_crew_war_resolved_for"("p_war_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_crew_war_started_for"("p_war_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_sender    UUID := auth.uid();
  v_war       public.crew_wars%ROWTYPE;
  v_crew_a    public.crews%ROWTYPE;
  v_crew_b    public.crews%ROWTYPE;
  v_member    RECORD;
  v_count     INT := 0;
  v_text      JSONB;
BEGIN
  IF v_sender IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;
  IF p_war_id IS NULL THEN
    RAISE EXCEPTION 'war_id required' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_war FROM public.crew_wars WHERE id = p_war_id;
  IF v_war IS NULL OR v_war.status <> 'active' OR v_war.crew_a_id IS NULL OR v_war.crew_b_id IS NULL THEN
    RETURN 0;
  END IF;
  -- Caller must be a member of one of the two crews.
  IF NOT EXISTS (
    SELECT 1 FROM public.crew_members
     WHERE user_id = v_sender
       AND crew_id IN (v_war.crew_a_id, v_war.crew_b_id)
  ) THEN
    RAISE EXCEPTION 'not your war' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_crew_a FROM public.crews WHERE id = v_war.crew_a_id;
  SELECT * INTO v_crew_b FROM public.crews WHERE id = v_war.crew_b_id;

  -- Notify crew A members (opponent = crew B)
  FOR v_member IN
    SELECT cm.user_id, up.email, prof.preferred_language
      FROM public.crew_members cm
      JOIN public.user_profiles up   ON up.id = cm.user_id
      LEFT JOIN public.user_profiles prof ON prof.id = cm.user_id
     WHERE cm.crew_id = v_war.crew_a_id
       AND up.email IS NOT NULL
  LOOP
    v_text := public.crew_war_started_text(
      COALESCE(v_member.preferred_language, 'en'),
      COALESCE(v_crew_b.name, 'rival crew')
    );
    INSERT INTO public.notifications
      (user_id, user_email, type, title, body, icon, link_url, metadata)
    VALUES
      (v_member.user_id, v_member.email, 'crew_war_started',
       v_text ->> 'title', v_text ->> 'body',
       '⚔️', '/hub',
       jsonb_build_object('war_id', p_war_id, 'opponent_crew_id', v_war.crew_b_id));
    v_count := v_count + 1;
  END LOOP;

  -- Notify crew B members (opponent = crew A)
  FOR v_member IN
    SELECT cm.user_id, up.email, prof.preferred_language
      FROM public.crew_members cm
      JOIN public.user_profiles up   ON up.id = cm.user_id
      LEFT JOIN public.user_profiles prof ON prof.id = cm.user_id
     WHERE cm.crew_id = v_war.crew_b_id
       AND up.email IS NOT NULL
  LOOP
    v_text := public.crew_war_started_text(
      COALESCE(v_member.preferred_language, 'en'),
      COALESCE(v_crew_a.name, 'rival crew')
    );
    INSERT INTO public.notifications
      (user_id, user_email, type, title, body, icon, link_url, metadata)
    VALUES
      (v_member.user_id, v_member.email, 'crew_war_started',
       v_text ->> 'title', v_text ->> 'body',
       '⚔️', '/hub',
       jsonb_build_object('war_id', p_war_id, 'opponent_crew_id', v_war.crew_a_id));
    v_count := v_count + 1;
  END LOOP;

  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."notify_crew_war_started_for"("p_war_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_dm_received"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_email TEXT; v_rcpt_id UUID; v_rcpt_lang TEXT; v_text JSONB; v_emails TEXT[];
  v_content TEXT;
BEGIN
  -- Held for later delivery: the recipient cannot read it yet (mig 295),
  -- so announcing it now is a notification that leads nowhere.
  IF NEW.status = 'scheduled' THEN RETURN NEW; END IF;

  v_content := btrim(coalesce(NEW.content, NEW.body, ''));

  -- Poll votes are control messages, not chat.
  IF left(v_content, 14) = '[POLL_VOTE_V1]' THEN RETURN NEW; END IF;

  -- A message with no text is still a message when it carries media.
  IF v_content = ''
     AND NEW.attachment_url IS NULL
     AND NEW.sticker_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT participant_emails INTO v_emails
    FROM public.hub_conversations WHERE id = NEW.conversation_id;
  IF v_emails IS NULL THEN RETURN NEW; END IF;

  FOREACH v_email IN ARRAY v_emails LOOP
    CONTINUE WHEN lower(v_email) = lower(COALESCE(NEW.sender_email, ''));
    SELECT id, COALESCE(preferred_language, 'en') INTO v_rcpt_id, v_rcpt_lang
      FROM public.user_profiles WHERE lower(email) = lower(v_email);
    CONTINUE WHEN v_rcpt_id IS NULL;
    CONTINUE WHEN public.is_blocked(v_rcpt_id, NEW.sender_email);

    v_text := public.dm_received_text(v_rcpt_lang, NEW.sender_name);
    INSERT INTO public.notifications
      (user_id, user_email, type, title, body, icon, link_url, metadata)
    VALUES (v_rcpt_id, v_email, 'dm_received', v_text->>'title', v_text->>'body',
            NULLIF(NEW.sender_avatar, ''), '/messages',
            jsonb_build_object('conversation_id', NEW.conversation_id));
  END LOOP;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."notify_dm_received"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_duel_invite_for"("p_opponent_id" "uuid", "p_duel_id" "uuid", "p_duel_type" "text" DEFAULT 'open'::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_sender     UUID := auth.uid();
  v_email      TEXT;
  v_lang       TEXT;
  v_text       JSONB;
  v_id         UUID;
  v_challenger TEXT;
  v_is_real    BOOLEAN;
BEGIN
  IF v_sender IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;
  IF p_opponent_id IS NULL OR p_duel_id IS NULL THEN
    RAISE EXCEPTION 'opponent_id and duel_id required' USING ERRCODE = '22023';
  END IF;
  IF p_opponent_id = v_sender THEN
    RETURN NULL;
  END IF;

  SELECT TRUE INTO v_is_real
    FROM public.duels
   WHERE id = p_duel_id
     AND challenger_id = v_sender
     AND opponent_id   = p_opponent_id
   LIMIT 1;
  IF v_is_real IS NOT TRUE THEN
    RAISE EXCEPTION 'not your duel' USING ERRCODE = '42501';
  END IF;

  SELECT u.email, prof.preferred_language
    INTO v_email, v_lang
    FROM auth.users u
    LEFT JOIN public.user_profiles prof ON prof.id = u.id
   WHERE u.id = p_opponent_id;
  IF v_email IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT username INTO v_challenger
    FROM public.user_profiles
   WHERE id = v_sender;

  v_text := public.duel_invite_text(
    COALESCE(v_lang, 'en'),
    COALESCE(v_challenger, 'Someone'),
    COALESCE(p_duel_type, 'open')
  );

  INSERT INTO public.notifications
    (user_id, user_email, type, title, body, icon, link_url, metadata)
  VALUES
    (p_opponent_id,
     v_email,
     'duel_invite',
     v_text ->> 'title',
     v_text ->> 'body',
     '⚔️',
     '/duels',
     jsonb_build_object(
       'duel_id',         p_duel_id,
       'duel_type',       COALESCE(p_duel_type, 'open'),
       'challenger_id',   v_sender,
       'challenger_name', v_challenger
     ))
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."notify_duel_invite_for"("p_opponent_id" "uuid", "p_duel_id" "uuid", "p_duel_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_duel_result_for"("p_recipient_id" "uuid", "p_duel_id" "uuid", "p_outcome" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_actor        UUID := auth.uid();
  v_winner       UUID;
  v_status       TEXT;
  v_challenger   UUID;
  v_opponent     UUID;
  v_actor_name   TEXT;
  v_actor_email  TEXT;
  v_real_outcome TEXT;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;
  IF p_recipient_id IS NULL OR p_duel_id IS NULL THEN
    RAISE EXCEPTION 'recipient_id and duel_id required' USING ERRCODE = '22023';
  END IF;
  SELECT winner_id, status, challenger_id, opponent_id
    INTO v_winner, v_status, v_challenger, v_opponent
    FROM public.duels WHERE id = p_duel_id;
  IF v_status IS DISTINCT FROM 'completed' THEN
    RAISE EXCEPTION 'duel_not_completed' USING ERRCODE = '22023';
  END IF;
  IF v_actor NOT IN (v_challenger, v_opponent) THEN
    RAISE EXCEPTION 'not a duel participant' USING ERRCODE = '42501';
  END IF;
  IF p_recipient_id NOT IN (v_challenger, v_opponent) OR p_recipient_id = v_actor THEN
    RAISE EXCEPTION 'invalid recipient' USING ERRCODE = '22023';
  END IF;
  v_real_outcome := CASE
    WHEN v_winner IS NULL          THEN 'tied'
    WHEN v_winner = p_recipient_id THEN 'won'
    ELSE                                'lost'
  END;

  SELECT username, email INTO v_actor_name, v_actor_email
    FROM public.user_profiles WHERE id = v_actor;
  IF v_actor_name IS NULL OR v_actor_name = '' THEN
    v_actor_name := COALESCE(SPLIT_PART(v_actor_email, '@', 1), 'Someone');
  END IF;

  PERFORM public._notify_duel_result_inner(p_recipient_id, p_duel_id, v_real_outcome, v_actor_name);
  RETURN p_duel_id;
END;
$$;


ALTER FUNCTION "public"."notify_duel_result_for"("p_recipient_id" "uuid", "p_duel_id" "uuid", "p_outcome" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_friend_follow_for"("p_user_id" "uuid", "p_follower_name" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_sender UUID := auth.uid(); v_sender_email TEXT; v_email TEXT;
  v_lang TEXT; v_name TEXT; v_text JSONB; v_id UUID;
BEGIN
  IF v_sender IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE='42501'; END IF;
  IF p_user_id IS NULL THEN RAISE EXCEPTION 'user_id required' USING ERRCODE='22023'; END IF;
  IF p_user_id = v_sender THEN RETURN NULL; END IF;
  SELECT username, email INTO v_name, v_sender_email FROM public.user_profiles WHERE id = v_sender;
  IF v_sender_email IS NULL THEN RETURN NULL; END IF;
  SELECT email INTO v_email FROM auth.users WHERE id = p_user_id;
  IF v_email IS NULL THEN RETURN NULL; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.hub_follows
                  WHERE follower_email = v_sender_email AND followee_email = v_email) THEN
    RAISE EXCEPTION 'no such follow' USING ERRCODE='42501';
  END IF;
  IF v_name IS NULL OR v_name = '' THEN
    v_name := COALESCE(SPLIT_PART(v_sender_email,'@',1),'Someone');
  ELSE v_name := '@' || v_name; END IF;
  SELECT preferred_language INTO v_lang FROM public.user_profiles WHERE id = p_user_id;
  v_text := public.friend_follow_text(COALESCE(v_lang,'en'), v_name);
  INSERT INTO public.notifications (user_id,user_email,type,title,body,icon,link_url,metadata)
  VALUES (p_user_id,v_email,'friend_follow',v_text->>'title',v_text->>'body','👋','/hub',
          jsonb_build_object('followerName',v_name)) RETURNING id INTO v_id;
  RETURN v_id;
END; $$;


ALTER FUNCTION "public"."notify_friend_follow_for"("p_user_id" "uuid", "p_follower_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_friend_post_for"("p_user_id" "uuid", "p_post_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_sender UUID := auth.uid(); v_sender_email TEXT; v_name TEXT; v_email TEXT;
  v_lang TEXT; v_author TEXT; v_body TEXT; v_text JSONB; v_id UUID;
BEGIN
  IF v_sender IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE='42501'; END IF;
  IF p_user_id IS NULL OR p_post_id IS NULL THEN
    RAISE EXCEPTION 'user_id and post_id required' USING ERRCODE='22023'; END IF;
  IF p_user_id = v_sender THEN RETURN NULL; END IF;
  SELECT username, email INTO v_name, v_sender_email FROM public.user_profiles WHERE id = v_sender;
  IF v_sender_email IS NULL THEN RETURN NULL; END IF;
  SELECT author_email, body INTO v_author, v_body FROM public.hub_posts WHERE id = p_post_id;
  IF v_author IS NULL THEN RAISE EXCEPTION 'post not found' USING ERRCODE='22023'; END IF;
  IF v_author <> v_sender_email THEN RAISE EXCEPTION 'not your post' USING ERRCODE='42501'; END IF;
  SELECT email INTO v_email FROM auth.users WHERE id = p_user_id;
  IF v_email IS NULL THEN RETURN NULL; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.hub_follows
                  WHERE follower_email = v_email AND followee_email = v_sender_email) THEN
    RAISE EXCEPTION 'recipient does not follow you' USING ERRCODE='42501';
  END IF;
  IF v_name IS NULL OR v_name = '' THEN
    v_name := COALESCE(SPLIT_PART(v_sender_email,'@',1),'Someone');
  ELSE v_name := '@' || v_name; END IF;
  SELECT preferred_language INTO v_lang FROM public.user_profiles WHERE id = p_user_id;
  v_text := public.friend_post_text(COALESCE(v_lang,'en'), v_name);
  INSERT INTO public.notifications (user_id,user_email,type,title,body,icon,link_url,metadata)
  VALUES (p_user_id,v_email,'friend_post',v_text->>'title',
          COALESCE(SUBSTRING(COALESCE(v_body,'') FROM 1 FOR 100),''),'✨','/hub',
          jsonb_build_object('posterName',v_name,'postId',p_post_id)) RETURNING id INTO v_id;
  RETURN v_id;
END; $$;


ALTER FUNCTION "public"."notify_friend_post_for"("p_user_id" "uuid", "p_post_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_gym_owner_on_join"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_owner_id    UUID;
  v_owner_email TEXT;
  v_gym_name    TEXT;
  v_joiner_name TEXT;
  v_recent_count INT;
  v_total_members INT;
BEGIN
  SELECT gb.owner_id, u.email, gb.name, gb.member_count
    INTO v_owner_id, v_owner_email, v_gym_name, v_total_members
    FROM public.gym_businesses gb
    JOIN auth.users u ON u.id = gb.owner_id
   WHERE gb.id = NEW.gym_id;

  IF v_owner_id IS NULL OR v_owner_id = NEW.user_id THEN
    RETURN NEW;
  END IF;

  SELECT COUNT(*) INTO v_recent_count
    FROM public.notifications
   WHERE user_id = v_owner_id
     AND type = 'gym_member_joined'
     AND (metadata ->> 'gymId') = NEW.gym_id::text
     AND created_at > now() - INTERVAL '10 minutes';
  IF v_recent_count > 0 THEN
    RETURN NEW;
  END IF;

  SELECT COALESCE(username, NULLIF(split_part(email, '@', 1), ''))
    INTO v_joiner_name
    FROM public.user_profiles
   WHERE id = NEW.user_id;

  INSERT INTO public.notifications
    (user_id, user_email, type, title, body, icon, link_url, metadata)
  VALUES
    (v_owner_id,
     v_owner_email,
     'gym_member_joined',
     'New gym member',
     COALESCE('@' || NULLIF(v_joiner_name, '') || ' joined ' || v_gym_name,
              'A new member joined ' || v_gym_name),
     '🏋',
     '/gym/' || NEW.gym_id::text,
     jsonb_build_object(
       'gymId',       NEW.gym_id,
       'joinerId',    NEW.user_id,
       'joinerName',  v_joiner_name,
       'memberCount', v_total_members
     ));

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."notify_gym_owner_on_join"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_gym_rival_assigned_for"("p_rival_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id    UUID := auth.uid();
  v_user_email TEXT;
  v_user_lang  TEXT;
  v_rival_name TEXT;
  v_text       JSONB;
  v_id         UUID;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;
  IF p_rival_id IS NULL THEN
    RAISE EXCEPTION 'rival_id required' USING ERRCODE = '22023';
  END IF;
  IF p_rival_id = v_user_id THEN
    RAISE EXCEPTION 'cannot be your own rival' USING ERRCODE = '22023';
  END IF;

  SELECT email INTO v_user_email FROM auth.users WHERE id = v_user_id;
  IF v_user_email IS NULL THEN
    RETURN NULL;
  END IF;
  SELECT preferred_language INTO v_user_lang FROM public.user_profiles WHERE id = v_user_id;
  SELECT username INTO v_rival_name FROM public.user_profiles WHERE id = p_rival_id;

  v_text := public.gym_rival_assigned_text(
    COALESCE(v_user_lang, 'en'),
    COALESCE(v_rival_name, 'a rival')
  );

  INSERT INTO public.notifications
    (user_id, user_email, type, title, body, icon, link_url, metadata)
  VALUES
    (v_user_id, v_user_email, 'nemesis_assigned',
     v_text ->> 'title', v_text ->> 'body', '🎯', '/dashboard',
     jsonb_build_object('rival_id', p_rival_id, 'rival_name', v_rival_name))
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."notify_gym_rival_assigned_for"("p_rival_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_gym_rival_overthrown_for"("p_assignment_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id        UUID := auth.uid();
  v_user_email     TEXT;
  v_user_lang      TEXT;
  v_rival_id       UUID;
  v_dethroned_name TEXT;
  v_status         TEXT;
  v_owner          UUID;
  v_text           JSONB;
  v_id             UUID;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;
  IF p_assignment_id IS NULL THEN
    RAISE EXCEPTION 'assignment_id required' USING ERRCODE = '22023';
  END IF;

  SELECT user_id, rival_id, status
    INTO v_owner, v_rival_id, v_status
    FROM public.gym_rival_assignments
   WHERE id = p_assignment_id;

  IF v_owner IS NULL THEN
    RETURN NULL;
  END IF;
  IF v_owner <> v_user_id THEN
    RAISE EXCEPTION 'not your assignment' USING ERRCODE = '42501';
  END IF;
  IF v_status <> 'overthrown' THEN
    RETURN NULL;
  END IF;

  SELECT email INTO v_user_email FROM auth.users WHERE id = v_user_id;
  IF v_user_email IS NULL THEN
    RETURN NULL;
  END IF;
  SELECT preferred_language INTO v_user_lang FROM public.user_profiles WHERE id = v_user_id;
  SELECT username INTO v_dethroned_name FROM public.user_profiles WHERE id = v_rival_id;

  v_text := public.gym_rival_overthrown_text(
    COALESCE(v_user_lang, 'en'),
    COALESCE(v_dethroned_name, 'your rival')
  );

  INSERT INTO public.notifications
    (user_id, user_email, type, title, body, icon, link_url, metadata)
  VALUES
    (v_user_id, v_user_email, 'nemesis_overthrown',
     v_text ->> 'title', v_text ->> 'body', '👑', '/dashboard',
     jsonb_build_object('assignment_id', p_assignment_id,
                        'dethroned_user_id', v_rival_id,
                        'dethroned_name', v_dethroned_name))
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."notify_gym_rival_overthrown_for"("p_assignment_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_league_resolution_for"("p_user_id" "uuid", "p_outcome" "text", "p_from_tier" "text", "p_to_tier" "text", "p_coins" integer, "p_capsule" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_sender UUID := auth.uid(); v_email TEXT; v_lang TEXT;
  v_text JSONB; v_id UUID; v_league UUID;
BEGIN
  IF v_sender IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE='42501'; END IF;
  IF p_user_id IS NULL THEN RAISE EXCEPTION 'user_id required' USING ERRCODE='22023'; END IF;
  IF p_outcome NOT IN ('promote','demote','hold') THEN
    RAISE EXCEPTION 'outcome must be promote/demote/hold' USING ERRCODE='22023'; END IF;
  SELECT league_id INTO v_league FROM public.league_members
   WHERE user_id = v_sender
     AND league_id IN (SELECT league_id FROM public.league_members WHERE user_id = p_user_id)
     AND league_id IN (SELECT id FROM public.leagues WHERE is_resolved = TRUE) LIMIT 1;
  IF v_league IS NULL THEN RAISE EXCEPTION 'no shared resolved league' USING ERRCODE='42501'; END IF;
  SELECT email INTO v_email FROM auth.users WHERE id = p_user_id;
  IF v_email IS NULL THEN RETURN NULL; END IF;
  SELECT preferred_language INTO v_lang FROM public.user_profiles WHERE id = p_user_id;
  v_text := public.league_resolution_text(COALESCE(v_lang,'en'),p_outcome,
              COALESCE(p_from_tier,''),COALESCE(p_to_tier,''),COALESCE(p_coins,0),p_capsule);
  INSERT INTO public.notifications (user_id,user_email,type,title,body,icon,link_url,metadata)
  VALUES (p_user_id,v_email,
    CASE p_outcome WHEN 'promote' THEN 'league_promoted'
                   WHEN 'demote' THEN 'league_demoted' ELSE 'league_held' END,
    v_text->>'title',v_text->>'body','🏆','/dashboard',
    jsonb_build_object('outcome',p_outcome,'coins',COALESCE(p_coins,0))) RETURNING id INTO v_id;
  RETURN v_id;
END; $$;


ALTER FUNCTION "public"."notify_league_resolution_for"("p_user_id" "uuid", "p_outcome" "text", "p_from_tier" "text", "p_to_tier" "text", "p_coins" integer, "p_capsule" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_league_resolution_internal"("p_user_id" "uuid", "p_outcome" "text", "p_from_tier" "text", "p_to_tier" "text", "p_coins" integer, "p_capsule" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_email TEXT;
  v_lang  TEXT;
  v_text  JSONB;
  v_id    UUID;
  v_type  TEXT;
BEGIN
  IF p_user_id IS NULL THEN
    RETURN NULL;
  END IF;
  IF p_outcome NOT IN ('promote', 'demote', 'hold') THEN
    RETURN NULL;
  END IF;

  SELECT email INTO v_email FROM auth.users WHERE id = p_user_id;
  IF v_email IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT preferred_language INTO v_lang FROM public.user_profiles WHERE id = p_user_id;

  v_text := public.league_resolution_text(
    COALESCE(v_lang, 'en'), p_outcome,
    COALESCE(p_from_tier, ''), COALESCE(p_to_tier, ''),
    COALESCE(p_coins, 0), p_capsule
  );

  v_type := CASE p_outcome
              WHEN 'promote' THEN 'league_promoted'
              WHEN 'demote'  THEN 'league_demoted'
              ELSE 'league_held'
            END;

  INSERT INTO public.notifications (user_id, user_email, type, title, body, icon, link_url, metadata)
  VALUES (p_user_id, v_email, v_type,
          v_text->>'title', v_text->>'body', '🏆', '/dashboard',
          jsonb_build_object('outcome', p_outcome, 'coins', COALESCE(p_coins, 0)))
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."notify_league_resolution_internal"("p_user_id" "uuid", "p_outcome" "text", "p_from_tier" "text", "p_to_tier" "text", "p_coins" integer, "p_capsule" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_push_fanout"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_url TEXT; v_secret TEXT; v_body JSONB; v_category TEXT;
  v_prefs JSONB; v_quiet BOOLEAN; v_snoozed BOOLEAN;
BEGIN
  BEGIN
    SELECT decrypted_secret INTO v_url
      FROM vault.decrypted_secrets WHERE name = 'send_push_url' LIMIT 1;
    SELECT decrypted_secret INTO v_secret
      FROM vault.decrypted_secrets WHERE name = 'send_push_secret' LIMIT 1;
  EXCEPTION WHEN OTHERS THEN
    v_url := NULL; v_secret := NULL;
  END;
  IF v_url IS NULL OR v_url = '' THEN
    BEGIN v_url := current_setting('app.send_push_url', true);
    EXCEPTION WHEN OTHERS THEN v_url := NULL; END;
  END IF;
  IF v_secret IS NULL OR v_secret = '' THEN
    BEGIN v_secret := current_setting('app.send_push_secret', true);
    EXCEPTION WHEN OTHERS THEN v_secret := NULL; END;
  END IF;
  IF v_url IS NULL OR v_url = '' OR v_secret IS NULL OR v_secret = '' THEN
    RETURN NEW;
  END IF;

  BEGIN
    v_category := public.notification_type_category(NEW.type);
    IF v_category IS NOT NULL THEN
      SELECT notification_prefs INTO v_prefs FROM public.user_profiles WHERE id = NEW.user_id;
      IF v_prefs IS NOT NULL AND v_prefs ? v_category AND (v_prefs ->> v_category) = 'false' THEN
        RETURN NEW;
      END IF;
    END IF;
  EXCEPTION WHEN undefined_function THEN NULL;
  WHEN OTHERS THEN NULL;
  END;

  IF v_category IS NOT NULL THEN
    BEGIN
      v_snoozed := public.is_category_snoozed(NEW.user_id, v_category);
      IF v_snoozed THEN RETURN NEW; END IF;
    EXCEPTION WHEN undefined_function THEN NULL;
    WHEN OTHERS THEN NULL;
    END;
  END IF;

  BEGIN
    v_quiet := public.is_in_quiet_hours(NEW.user_id);
    IF v_quiet THEN RETURN NEW; END IF;
  EXCEPTION WHEN undefined_function THEN NULL;
  WHEN OTHERS THEN NULL;
  END;

  v_body := jsonb_build_object(
    'user_id', NEW.user_id,
    'title',   COALESCE(NEW.title, 'Flexyn'),
    'body',    COALESCE(NEW.body,  ''),
    'icon',    NEW.icon,
    'url',     COALESCE(NEW.link_url, '/'),
    'tag',     NEW.type
  );

  BEGIN
    PERFORM net.http_post(timeout_milliseconds := 30000, 
      url     := v_url,
      body    := v_body,
      headers := jsonb_build_object(
        'Content-Type',       'application/json',
        'X-Send-Push-Secret', v_secret
      )
    );
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING '[notify_push_fanout] dispatch failed: %', SQLERRM;
  END;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."notify_push_fanout"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_push_fanout_batch"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_url TEXT; v_secret TEXT; v_chunk JSONB;
BEGIN
  BEGIN
    SELECT decrypted_secret INTO v_url
      FROM vault.decrypted_secrets WHERE name = 'send_push_url' LIMIT 1;
    SELECT decrypted_secret INTO v_secret
      FROM vault.decrypted_secrets WHERE name = 'send_push_secret' LIMIT 1;
  EXCEPTION WHEN OTHERS THEN
    v_url := NULL; v_secret := NULL;
  END;
  IF v_url IS NULL OR v_url = '' THEN
    BEGIN v_url := current_setting('app.send_push_url', true);
    EXCEPTION WHEN OTHERS THEN v_url := NULL; END;
  END IF;
  IF v_secret IS NULL OR v_secret = '' THEN
    BEGIN v_secret := current_setting('app.send_push_secret', true);
    EXCEPTION WHEN OTHERS THEN v_secret := NULL; END;
  END IF;
  IF v_url IS NULL OR v_url = '' OR v_secret IS NULL OR v_secret = '' THEN
    RETURN NULL;
  END IF;

  FOR v_chunk IN
    WITH candidate AS (
      SELECT user_id                   AS target_user_id,
             COALESCE(title, 'Flexyn') AS push_title,
             COALESCE(body, '')        AS push_body,
             icon                      AS push_icon,
             COALESCE(link_url, '/')   AS push_url,
             type                      AS push_tag,
             public.notification_type_category(type) AS push_category
        FROM new_rows
    ),
    prefs AS (
      SELECT id AS pref_user_id, notification_prefs AS pref_json
        FROM public.user_profiles
       WHERE id IN (SELECT target_user_id FROM candidate)
    ),
    eligible AS (
      SELECT target_user_id, push_title, push_body, push_icon, push_url, push_tag
        FROM candidate
        LEFT JOIN prefs ON pref_user_id = target_user_id
       WHERE (
               push_category IS NULL
               OR pref_json IS NULL
               OR NOT (pref_json ? push_category)
               OR (pref_json ->> push_category) <> 'false'
             )
         AND (
               push_category IS NULL
               OR NOT COALESCE(public.is_category_snoozed(target_user_id, push_category), false)
             )
         AND NOT COALESCE(public.is_in_quiet_hours(target_user_id), false)
    ),
    numbered AS (
      SELECT row_number() OVER () AS rn,
             jsonb_build_object(
               'user_id', target_user_id,
               'title',   push_title,
               'body',    push_body,
               'icon',    push_icon,
               'url',     push_url,
               'tag',     push_tag
             ) AS push_payload
        FROM eligible
    )
    SELECT jsonb_agg(push_payload)
      FROM numbered
     GROUP BY (rn - 1) / 200
  LOOP
    BEGIN
      PERFORM net.http_post(timeout_milliseconds := 30000, 
        url     := v_url,
        body    := jsonb_build_object('notifications', v_chunk),
        headers := jsonb_build_object(
          'Content-Type',       'application/json',
          'X-Send-Push-Secret', v_secret
        )
      );
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING '[notify_push_fanout_batch] dispatch failed: %', SQLERRM;
    END;
  END LOOP;

  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."notify_push_fanout_batch"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_report_email"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'vault'
    AS $$
DECLARE
  v_to     TEXT;
  v_url    TEXT;
  v_secret TEXT;
  v_body   JSONB;
BEGIN
  SELECT decrypted_secret INTO v_to     FROM vault.decrypted_secrets WHERE name = 'report_notify_to';
  SELECT decrypted_secret INTO v_url    FROM vault.decrypted_secrets WHERE name = 'report_notify_url';
  SELECT decrypted_secret INTO v_secret FROM vault.decrypted_secrets WHERE name = 'report_notify_secret';

  IF v_to IS NULL OR v_to = '' OR v_url IS NULL OR v_url = '' OR v_secret IS NULL OR v_secret = '' THEN
    RETURN NEW;
  END IF;

  v_body := jsonb_build_object(
    'to', v_to,
    'report', jsonb_build_object(
      'id',                    NEW.id,
      'reported_type',         NEW.reported_type,
      'reported_id',           NEW.reported_id,
      'reported_author_email', NEW.reported_author_email,
      'reporter_email',        NEW.reporter_email,
      'reason',                NEW.reason,
      'detail',                NEW.detail,
      'created_at',            NEW.created_at
    )
  );

  PERFORM net.http_post(
    url     := v_url,
    headers := jsonb_build_object('Content-Type', 'application/json', 'x-report-secret', v_secret),
    body    := v_body
  );

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RETURN NEW;
END $$;


ALTER FUNCTION "public"."notify_report_email"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_report_resolved"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_lang     TEXT;
  v_text     JSONB;
  v_reporter UUID;
BEGIN
  IF OLD.status IS NOT DISTINCT FROM NEW.status THEN RETURN NEW; END IF;
  IF NEW.status NOT IN ('reviewed', 'actioned', 'dismissed') THEN RETURN NEW; END IF;

  v_reporter := NEW.reporter_user_id;
  IF v_reporter IS NULL THEN RETURN NEW; END IF;

  SELECT COALESCE(preferred_language, 'en')
    INTO v_lang
    FROM public.user_profiles
   WHERE id = v_reporter;
  v_lang := COALESCE(v_lang, 'en');

  v_text := public.report_resolution_text(v_lang, NEW.status);

  INSERT INTO public.notifications (user_id, user_email, type, title, body, icon, metadata)
  VALUES (
    v_reporter,
    NEW.reporter_email,
    'report_resolved',
    v_text->>'title',
    v_text->>'body',
    CASE NEW.status
      WHEN 'actioned'  THEN '✅'
      WHEN 'dismissed' THEN '👀'
      ELSE                  '🛡️'
    END,
    jsonb_build_object(
      'report_id',     NEW.id,
      'status',        NEW.status,
      'reported_type', NEW.reported_type
    )
  );

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."notify_report_resolved"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."open_capsule_atomic"("p_capsule_id" "uuid", "p_candidates" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid          UUID := auth.uid();
  v_email        TEXT;
  v_type         TEXT;
  v_roll         JSONB;
  v_shape        JSONB;
  v_item         JSONB;
  v_rarity       TEXT;
  v_category     TEXT;
  v_variant      TEXT;
  v_inventory_id UUID;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;
  IF p_capsule_id IS NULL THEN
    RAISE EXCEPTION 'capsule_id required' USING ERRCODE = '22023';
  END IF;

  UPDATE public.user_capsules
     SET is_opened = TRUE, opened_at = now()
   WHERE id = p_capsule_id AND user_id = v_uid AND is_opened = FALSE
  RETURNING capsule_type INTO v_type;

  IF v_type IS NULL THEN
    RAISE EXCEPTION 'capsule not found or already opened' USING ERRCODE = '22023';
  END IF;
  v_type := COALESCE(v_type, 'standard');

  v_roll     := public._roll_capsule_rarity(v_uid, v_type);
  v_rarity   := v_roll ->> 'rarity';
  v_shape    := public._roll_capsule_shape(v_type);
  v_category := v_shape ->> 'category';
  v_variant  := v_shape ->> 'variant';
  v_item     := public._pick_loot_item(v_rarity, v_category);
  v_category := COALESCE(v_item ->> 'item_type', v_category);

  SELECT email INTO v_email FROM public.user_profiles WHERE id = v_uid;
  IF v_email IS NULL OR v_email = '' THEN
    v_email := 'guest_' || v_uid || '@flexyn.guest';
  END IF;

  INSERT INTO public.user_inventory
    (user_id, user_email, item_id, item_name, item_emoji, item_rarity, item_type, variant, acquired_via)
  VALUES
    (v_uid, v_email, v_item ->> 'item_id', v_item ->> 'item_name', v_item ->> 'item_emoji',
     v_rarity, v_category, v_variant, 'capsule')
  RETURNING id INTO v_inventory_id;

  UPDATE public.user_capsules
     SET rolled_rarity = v_rarity, rolled_category = v_category,
         rolled_variant = v_variant, finalized_at = now()
   WHERE id = p_capsule_id;

  RETURN jsonb_build_object(
    'capsule_id', p_capsule_id, 'capsule_type', v_type,
    'rarity', v_rarity, 'category', v_category, 'variant', v_variant,
    'inventory_id', v_inventory_id,
    'item_id', v_item ->> 'item_id', 'item_name', v_item ->> 'item_name',
    'item_emoji', v_item ->> 'item_emoji', 'item_type', v_category,
    'pity', v_roll ->> 'pity',
    'since_epic', (v_roll ->> 'since_epic')::INTEGER,
    'since_legendary', (v_roll ->> 'since_legendary')::INTEGER
  );
END;
$$;


ALTER FUNCTION "public"."open_capsule_atomic"("p_capsule_id" "uuid", "p_candidates" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ops_collect_alerts"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_cron integer := 0;
  v_http integer := 0;
BEGIN
  INSERT INTO public.ops_alerts (source, ref, detail, source_id, observed_at)
  SELECT 'cron', jobname, left(coalesce(return_message, ''), 500), runid, coalesce(end_time, start_time, now())
    FROM cron.job_run_details
    JOIN (SELECT jobid AS j_id, jobname FROM cron.job) jobs ON jobid = j_id
   WHERE status = 'failed'
     AND start_time > now() - interval '2 hours'
  ON CONFLICT (source, source_id) DO NOTHING;
  GET DIAGNOSTICS v_cron = ROW_COUNT;

  INSERT INTO public.ops_alerts (source, ref, detail, source_id, observed_at)
  SELECT 'http', coalesce(status_code::text, 'no response'),
         left(coalesce(error_msg, content, ''), 500), id, created
    FROM net._http_response
   WHERE created > now() - interval '2 hours'
     AND (status_code IS NULL OR status_code < 200 OR status_code >= 300
          OR timed_out IS TRUE OR error_msg IS NOT NULL)
  ON CONFLICT (source, source_id) DO NOTHING;
  GET DIAGNOSTICS v_http = ROW_COUNT;

  DELETE FROM public.ops_alerts WHERE observed_at < now() - interval '90 days';
  RETURN v_cron + v_http;
END;
$$;


ALTER FUNCTION "public"."ops_collect_alerts"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ops_health"("p_secret" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_expected text;
  v_count    integer;
  v_recent   jsonb;
  v_last_collect timestamptz;
BEGIN
  SELECT decrypted_secret INTO v_expected
    FROM vault.decrypted_secrets WHERE name = 'ops_health_secret';
  IF v_expected IS NULL OR p_secret IS NULL OR p_secret <> v_expected THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  SELECT count(*) INTO v_count
    FROM public.ops_alerts WHERE observed_at > now() - interval '24 hours';
  SELECT coalesce(jsonb_agg(row_to_json(r)), '[]'::jsonb) INTO v_recent
    FROM (SELECT source, ref, count(*) AS n, max(observed_at) AS last_seen, max(detail) AS sample
            FROM public.ops_alerts
           WHERE observed_at > now() - interval '24 hours'
           GROUP BY source, ref
           ORDER BY count(*) DESC
           LIMIT 10) r;
  SELECT max(start_time) INTO v_last_collect
    FROM cron.job_run_details
    JOIN (SELECT jobid AS j_id, jobname FROM cron.job) jobs ON jobid = j_id
   WHERE jobname = 'ops-collect-alerts' AND status = 'succeeded';
  RETURN jsonb_build_object(
    'ok', v_count = 0 AND v_last_collect > now() - interval '3 hours',
    'alerts_24h', v_count,
    'collector_last_ok', v_last_collect,
    'groups', v_recent
  );
END;
$$;


ALTER FUNCTION "public"."ops_health"("p_secret" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pair_waiting_crew_wars"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_a       uuid;
  v_a_crew  uuid;
  v_a_since timestamptz;
  v_a_ros   integer;
  v_a_age   numeric;
  v_a_str   numeric;
  v_a_cad   numeric;
  v_a_div   integer;
  v_b       uuid;
  v_b_crew  uuid;
  v_claimed integer;
  v_paired  integer := 0;
BEGIN
  FOR v_a, v_a_crew, v_a_since, v_a_ros, v_a_age, v_a_str, v_a_cad, v_a_div IN
    SELECT id, crew_a_id, created_at,
           match_roster, match_age, match_strength, match_cadence, match_division
      FROM public.crew_wars
     WHERE crew_b_id IS NULL AND status = 'matchmaking'
     ORDER BY created_at
     LIMIT 100
  LOOP
    PERFORM 1 FROM public.crew_wars
      WHERE id = v_a AND crew_b_id IS NULL AND status = 'matchmaking';
    IF NOT FOUND THEN
      CONTINUE;
    END IF;

    SELECT w_id, w_crew INTO v_b, v_b_crew
      FROM (
        SELECT
          id AS w_id,
          crew_a_id AS w_crew,
          created_at AS w_since,
          public.crew_match_gap(
            v_a_ros, v_a_age, v_a_str, v_a_cad, v_a_div,
            match_roster, match_age, match_strength, match_cadence, match_division
          ) AS w_gap
        FROM public.crew_wars
        WHERE crew_b_id IS NULL
          AND status = 'matchmaking'
          AND NOT (id = v_a)
          AND NOT (crew_a_id = v_a_crew)
      ) AS candidates
     WHERE w_gap = LEAST(
             w_gap,
             0.15 + 0.15 * FLOOR(EXTRACT(EPOCH FROM (now() - v_a_since)) / 43200)
           )
     ORDER BY w_gap, w_since
     LIMIT 1;

    IF v_b IS NULL THEN
      CONTINUE;
    END IF;

    UPDATE public.crew_wars
       SET crew_b_id    = v_b_crew,
           status       = 'active',
           starts_at    = now(),
           ends_at      = now() + INTERVAL '7 days',
           crew_a_score = 0,
           crew_b_score = 0
     WHERE id = v_a
       AND crew_b_id IS NULL
       AND status = 'matchmaking';

    GET DIAGNOSTICS v_claimed = ROW_COUNT;

    IF v_claimed = 1 THEN
      DELETE FROM public.crew_wars
       WHERE id = v_b AND crew_b_id IS NULL AND status = 'matchmaking';
      PERFORM public.notify_crew_war_started_for(v_a);
      v_paired := v_paired + 1;
    END IF;
  END LOOP;

  RETURN v_paired;
END;
$$;


ALTER FUNCTION "public"."pair_waiting_crew_wars"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."perform_prestige"("p_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_new_level INT; v_cur_level INT; v_prestige INT;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;
  IF p_user_id IS NULL OR p_user_id <> auth.uid() THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  UPDATE public.user_profiles
     SET prestige_level     = COALESCE(prestige_level, 0) + 1,
         total_xp           = 0,
         current_level      = 1,
         prestige_dismissed = FALSE,
         prestiged_at       = array_append(COALESCE(prestiged_at, '{}'), NOW()),
         flex_coins         = COALESCE(flex_coins, 0)
                              + ((COALESCE(prestige_level, 0) + 1) * 500)
   WHERE id = p_user_id
     AND COALESCE(current_level, 1) >= 100
     AND COALESCE(prestige_level, 0) < 10
  RETURNING prestige_level INTO v_new_level;
  IF v_new_level IS NOT NULL THEN
    RETURN jsonb_build_object('ok', true, 'prestige_level', v_new_level,
                              'coins_awarded', v_new_level * 500);
  END IF;
  SELECT COALESCE(current_level, 1), COALESCE(prestige_level, 0)
    INTO v_cur_level, v_prestige
    FROM public.user_profiles WHERE id = p_user_id;
  IF v_cur_level IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'user not found');
  ELSIF v_prestige >= 10 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'max prestige reached');
  ELSE
    RETURN jsonb_build_object('ok', false, 'error', 'not eligible');
  END IF;
END; $$;


ALTER FUNCTION "public"."perform_prestige"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."populate_blocked_id"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.blocked_id IS NULL AND NEW.blocked_email IS NOT NULL THEN
    SELECT id INTO NEW.blocked_id FROM public.user_profiles
     WHERE lower(email) = lower(NEW.blocked_email) LIMIT 1;
  END IF;
  RETURN NEW;
END;
$$;


