CREATE OR REPLACE FUNCTION "public"."public_crew_badges"("p_user_ids" "uuid"[]) RETURNS TABLE("member_id" "uuid", "badge_crew_id" "uuid", "crew_name" "text", "crew_tag" "text", "crew_avatar_url" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid    UUID;
  v_crew   UUID;
  v_name   TEXT;
  v_tag    TEXT;
  v_avatar TEXT;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;
  IF p_user_ids IS NULL OR array_length(p_user_ids, 1) IS NULL THEN
    RETURN;
  END IF;

  FOREACH v_uid IN ARRAY p_user_ids LOOP
    SELECT crew_id INTO v_crew
      FROM public.crew_members
     WHERE user_id = v_uid
     ORDER BY joined_at DESC
     LIMIT 1;

    IF v_crew IS NOT NULL THEN
      SELECT name, tag, avatar_url
        INTO v_name, v_tag, v_avatar
        FROM public.crews
       WHERE id = v_crew;

      member_id       := v_uid;
      badge_crew_id   := v_crew;
      crew_name       := v_name;
      crew_tag        := v_tag;
      crew_avatar_url := v_avatar;
      RETURN NEXT;
    END IF;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."public_crew_badges"("p_user_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."purchase_branded_item"("p_sku" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid          UUID := auth.uid();
  v_email        TEXT := NULLIF(public.current_user_email(), '');
  v_price        INTEGER;
  v_balance      INTEGER;
  v_new_balance  INTEGER;
  v_already      INTEGER;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;

  CASE p_sku
    WHEN 'flx_dumbbell' THEN v_price := 25;
    WHEN 'flx_band'     THEN v_price := 25;
    WHEN 'flx_chalk'    THEN v_price := 25;
    WHEN 'flx_shoes'    THEN v_price := 25;
    WHEN 'flx_water'    THEN v_price := 25;
    WHEN 'flx_apple'    THEN v_price := 25;
    WHEN 'flx_egg'      THEN v_price := 25;
    WHEN 'flx_alarm'    THEN v_price := 25;
    WHEN 'flx_pencil'   THEN v_price := 25;
    WHEN 'flx_sweat'    THEN v_price := 25;
    WHEN 'flx_logo'     THEN v_price := 50;
    WHEN 'flx_day_one'  THEN v_price := 50;
    WHEN 'flx_keychain' THEN v_price := 50;
    WHEN 'flx_bottle'   THEN v_price := 50;
    WHEN 'flx_muscle'   THEN v_price := 50;
    WHEN 'flx_lightbolt' THEN v_price := 50;
    WHEN 'flx_target'   THEN v_price := 50;
    WHEN 'flx_med1'     THEN v_price := 50;
    WHEN 'flx_med2'     THEN v_price := 50;
    WHEN 'flx_med3'     THEN v_price := 50;
    WHEN 'flx_og'       THEN v_price := 120;
    WHEN 'flx_anvil'    THEN v_price := 80;
    WHEN 'flx_belt'     THEN v_price := 100;
    WHEN 'flx_swords'   THEN v_price := 100;
    WHEN 'flx_shield'   THEN v_price := 100;
    WHEN 'flx_rocket'   THEN v_price := 100;
    WHEN 'flx_diamond'  THEN v_price := 100;
    WHEN 'flx_runner'   THEN v_price := 100;
    WHEN 'flx_streak'   THEN v_price := 200;
    WHEN 'flx_dragon'   THEN v_price := 200;
    WHEN 'flx_eagle'    THEN v_price := 200;
    WHEN 'flx_galaxy'   THEN v_price := 200;
    WHEN 'flx_lion'     THEN v_price := 200;
    WHEN 'flx_crown'    THEN v_price := 400;
    WHEN 'flx_trophy'   THEN v_price := 400;
    WHEN 'flx_radiance' THEN v_price := 400;
    WHEN 'flx_comet'    THEN v_price := 400;
    WHEN 'flx_sparkles' THEN v_price := 1000;
    ELSE
      RAISE EXCEPTION 'unknown_sku: %', p_sku USING ERRCODE = '22023';
  END CASE;

  SELECT COUNT(*) INTO v_already
    FROM public.user_branded_items
   WHERE user_id = v_uid AND sku = p_sku;
  IF v_already > 0 THEN
    RAISE EXCEPTION 'already_owned' USING ERRCODE = '22023';
  END IF;

  SELECT COALESCE(flex_coins, 0) INTO v_balance
    FROM public.user_profiles
   WHERE id = v_uid FOR UPDATE;
  IF v_balance IS NULL THEN
    RAISE EXCEPTION 'buyer_profile_not_found' USING ERRCODE = '22023';
  END IF;

  IF v_balance < v_price THEN
    RAISE EXCEPTION 'insufficient_coins: have %, need %', v_balance, v_price
      USING ERRCODE = '22023';
  END IF;

  v_new_balance := v_balance - v_price;
  UPDATE public.user_profiles
     SET flex_coins = v_new_balance
   WHERE id = v_uid;

  INSERT INTO public.user_branded_items (user_id, user_email, sku)
  VALUES (v_uid, v_email, p_sku);

  RETURN jsonb_build_object(
    'success',     true,
    'sku',         p_sku,
    'price',       v_price,
    'new_balance', v_new_balance
  );
END;
$$;


ALTER FUNCTION "public"."purchase_branded_item"("p_sku" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."purchase_bundle"("p_bundle_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_buyer_id      UUID := auth.uid();
  v_buyer_email   TEXT;
  v_bundle_status TEXT;
  v_bundle_seller UUID;
  v_discount_pct  NUMERIC;
  v_lid           UUID;
  v_price         INTEGER;
  v_inv           UUID;
  v_total_price   INTEGER := 0;
  v_discounted    INTEGER;
  v_buyer_coins   INTEGER;
  v_listing_ids   UUID[] := '{}';
BEGIN
  IF v_buyer_id IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;

  v_buyer_email := NULLIF(public.current_user_email(), '');

  SELECT status, seller_user_id, discount_pct
    INTO v_bundle_status, v_bundle_seller, v_discount_pct
    FROM public.marketplace_bundles
   WHERE id = p_bundle_id
     FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'bundle_not_found';
  END IF;
  IF v_bundle_status <> 'active' THEN
    RAISE EXCEPTION 'bundle_not_available';
  END IF;
  IF v_bundle_seller = v_buyer_id THEN
    RAISE EXCEPTION 'cannot_buy_own_bundle';
  END IF;

  -- Only the BUNDLE OWNER's own listings are part of the deal.
  FOR v_lid, v_price IN
    SELECT id, asking_price
      FROM public.marketplace_listings
     WHERE bundle_id = p_bundle_id
       AND seller_user_id = v_bundle_seller
       AND status = 'active'
       AND listing_type = 'sale'
       FOR UPDATE
  LOOP
    v_total_price := v_total_price + COALESCE(v_price, 0);
    v_listing_ids := array_append(v_listing_ids, v_lid);
  END LOOP;

  IF array_length(v_listing_ids, 1) IS NULL THEN
    RAISE EXCEPTION 'bundle_empty';
  END IF;

  v_discounted := GREATEST(1, ROUND(v_total_price * (1 - v_discount_pct / 100)));

  SELECT COALESCE(flex_coins, 0) INTO v_buyer_coins
    FROM public.user_profiles
   WHERE id = v_buyer_id
     FOR UPDATE;
  IF v_buyer_coins IS NULL THEN
    RAISE EXCEPTION 'buyer profile not found' USING ERRCODE = '22023';
  END IF;
  IF v_buyer_coins < v_discounted THEN
    RAISE EXCEPTION 'insufficient_coins';
  END IF;

  UPDATE public.user_profiles
     SET flex_coins = flex_coins - v_discounted
   WHERE id = v_buyer_id;

  -- THE FIX. One credit, of exactly what the buyer was debited.
  UPDATE public.user_profiles
     SET flex_coins = COALESCE(flex_coins, 0) + v_discounted
   WHERE id = v_bundle_seller;

  FOR v_lid, v_inv IN
    SELECT id, inventory_id
      FROM public.marketplace_listings
     WHERE id = ANY(v_listing_ids)
  LOOP
    UPDATE public.user_inventory
       SET user_id    = v_buyer_id,
           user_email = v_buyer_email,
           is_listed  = false
     WHERE id = v_inv;

    UPDATE public.marketplace_listings
       SET status = 'completed'
     WHERE id = v_lid;
  END LOOP;

  UPDATE public.marketplace_bundles
     SET status = 'completed'
   WHERE id = p_bundle_id;

  RETURN jsonb_build_object(
    'bundle_id',     p_bundle_id,
    'listing_count', array_length(v_listing_ids, 1),
    'total_price',   v_total_price,
    'paid_price',    v_discounted,
    'buyer_coins',   v_buyer_coins - v_discounted
  );
END;
$$;


ALTER FUNCTION "public"."purchase_bundle"("p_bundle_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."purchase_crew_perk"("p_crew_id" "uuid", "p_perk_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_uid     uuid := auth.uid();
  v_admin   integer;
  v_base    integer;
  v_max     integer;
  v_effect  text;
  v_active  boolean;
  v_owned   integer;
  v_price   integer;
  v_balance integer;
  v_after   integer;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;
  IF p_crew_id IS NULL OR p_perk_key IS NULL THEN
    RAISE EXCEPTION 'crew_id and perk_key required' USING ERRCODE = '22023';
  END IF;

  SELECT COUNT(*) INTO v_admin
    FROM public.crew_members
   WHERE crew_id = p_crew_id AND user_id = v_uid AND is_admin = TRUE;

  IF v_admin = 0 THEN
    RAISE EXCEPTION 'only a crew leader can spend the treasury'
      USING ERRCODE = '42501';
  END IF;

  SELECT base_cost, max_purchases, effect, active
    INTO v_base, v_max, v_effect, v_active
    FROM public.crew_perks
   WHERE perk_key = p_perk_key;

  IF NOT FOUND OR v_active IS NOT TRUE THEN
    RAISE EXCEPTION 'no such perk' USING ERRCODE = '22023';
  END IF;

  SELECT treasury_coins INTO v_balance
    FROM public.crews WHERE id = p_crew_id FOR UPDATE;

  SELECT COUNT(*) INTO v_owned
    FROM public.crew_perk_purchases
   WHERE crew_id = p_crew_id AND perk_key = p_perk_key;

  IF v_owned = GREATEST(v_owned, v_max) THEN
    RETURN jsonb_build_object('ok', FALSE, 'reason', 'maxed',
                              'owned', v_owned, 'balance', v_balance);
  END IF;

  v_price := public.crew_perk_price(v_base, v_owned);

  IF v_balance = LEAST(v_balance, v_price) AND NOT (v_balance = v_price) THEN
    RETURN jsonb_build_object('ok', FALSE, 'reason', 'insufficient',
                              'price', v_price, 'balance', v_balance);
  END IF;

  UPDATE public.crews
     SET treasury_coins = treasury_coins - v_price
   WHERE id = p_crew_id
   RETURNING treasury_coins INTO v_after;

  INSERT INTO public.crew_perk_purchases (crew_id, perk_key, cost, bought_by)
  VALUES (p_crew_id, p_perk_key, v_price, v_uid);

  INSERT INTO public.crew_treasury_ledger
    (crew_id, delta, balance_after, reason, actor_user_id)
  VALUES (p_crew_id, -v_price, v_after, 'perk:' || p_perk_key, v_uid);

  IF v_effect = 'extra_seat' THEN
    UPDATE public.crews
       SET max_capacity = LEAST(20, COALESCE(max_capacity, 16) + 1)
     WHERE id = p_crew_id;
  END IF;

  RETURN jsonb_build_object('ok', TRUE, 'perk_key', p_perk_key,
                            'price', v_price, 'balance', v_after,
                            'owned', v_owned + 1);
END;
$$;


ALTER FUNCTION "public"."purchase_crew_perk"("p_crew_id" "uuid", "p_perk_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."purchase_listing"("p_listing_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_buyer_uid    UUID := auth.uid();
  v_buyer_email  TEXT := NULLIF(public.current_user_email(), '');
  v_buyer_coins  INTEGER;
  v_listing      public.marketplace_listings%ROWTYPE;
  v_inventory    public.user_inventory%ROWTYPE;
  v_new_inv_id   UUID;
BEGIN
  IF v_buyer_uid IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE='42501'; END IF;
  IF p_listing_id IS NULL THEN RAISE EXCEPTION 'listing_id required' USING ERRCODE='22023'; END IF;

  SELECT * INTO v_listing FROM public.marketplace_listings WHERE id=p_listing_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'listing not found' USING ERRCODE='22023'; END IF;
  IF v_listing.status<>'active' THEN RAISE EXCEPTION 'listing is %', v_listing.status USING ERRCODE='22023'; END IF;
  IF v_listing.listing_type<>'sale' THEN RAISE EXCEPTION 'only sale listings can be purchased via this RPC' USING ERRCODE='22023'; END IF;
  IF v_listing.seller_user_id=v_buyer_uid THEN RAISE EXCEPTION 'cannot purchase your own listing' USING ERRCODE='22023'; END IF;

  SELECT * INTO v_inventory FROM public.user_inventory
    WHERE id=v_listing.inventory_id AND user_id=v_listing.seller_user_id FOR UPDATE;
  IF NOT FOUND THEN
    UPDATE public.marketplace_listings SET status='cancelled' WHERE id=p_listing_id;
    RAISE EXCEPTION 'item no longer available' USING ERRCODE='22023';
  END IF;

  SELECT COALESCE(flex_coins,0) INTO v_buyer_coins FROM public.user_profiles WHERE id=v_buyer_uid FOR UPDATE;
  IF v_buyer_coins IS NULL THEN RAISE EXCEPTION 'buyer profile not found' USING ERRCODE='22023'; END IF;
  IF v_buyer_coins < v_listing.asking_price THEN
    RAISE EXCEPTION 'insufficient_coins: have %, need %', v_buyer_coins, v_listing.asking_price USING ERRCODE='22023';
  END IF;

  UPDATE public.user_profiles SET flex_coins=flex_coins-v_listing.asking_price WHERE id=v_buyer_uid;
  UPDATE public.user_profiles SET flex_coins=COALESCE(flex_coins,0)+v_listing.asking_price WHERE id=v_listing.seller_user_id;
  UPDATE public.user_inventory
     SET user_id=v_buyer_uid, user_email=v_buyer_email, is_listed=false
   WHERE id=v_inventory.id RETURNING id INTO v_new_inv_id;
  UPDATE public.marketplace_listings SET status='completed' WHERE id=p_listing_id;

  RETURN jsonb_build_object('listing_id',p_listing_id,'inventory_id',v_new_inv_id,
                            'price',v_listing.asking_price,'buyer_coins',v_buyer_coins-v_listing.asking_price);
END; $$;


ALTER FUNCTION "public"."purchase_listing"("p_listing_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."purchase_shop_item"("p_sku" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_email TEXT := NULLIF(public.current_user_email(), '');
  v_price INTEGER; v_kind TEXT; v_subtype TEXT; v_amount INTEGER;
  v_balance INTEGER; v_new_balance INTEGER; v_capsule_id UUID;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE='42501'; END IF;
  CASE p_sku
    WHEN 'capsule_standard' THEN v_price:=100; v_kind:='capsule';      v_subtype:='standard';
    WHEN 'capsule_premium'  THEN v_price:=350; v_kind:='capsule';      v_subtype:='premium';
    WHEN 'capsule_elite'    THEN v_price:=1000;v_kind:='capsule';      v_subtype:='elite';
    WHEN 'streak_freeze'    THEN v_price:=200; v_kind:='streak_freeze';v_amount:=1;
    ELSE RAISE EXCEPTION 'unknown_sku: %', p_sku USING ERRCODE='22023';
  END CASE;
  SELECT COALESCE(flex_coins,0) INTO v_balance FROM public.user_profiles WHERE id=v_uid FOR UPDATE;
  IF v_balance IS NULL THEN RAISE EXCEPTION 'buyer profile not found' USING ERRCODE='22023'; END IF;
  IF v_balance < v_price THEN
    RAISE EXCEPTION 'insufficient_coins: have %, need %', v_balance, v_price USING ERRCODE='22023';
  END IF;
  v_new_balance := v_balance - v_price;
  UPDATE public.user_profiles SET flex_coins=v_new_balance WHERE id=v_uid;
  IF v_kind='capsule' THEN
    INSERT INTO public.user_capsules (user_id,user_email,capsule_type)
    VALUES (v_uid,v_email,v_subtype) RETURNING id INTO v_capsule_id;
    RETURN jsonb_build_object('success',true,'sku',p_sku,'price',v_price,
      'new_balance',v_new_balance,'granted_kind','capsule',
      'granted_id',v_capsule_id,'granted_subtype',v_subtype);
  ELSIF v_kind='streak_freeze' THEN
    UPDATE public.user_profiles
      SET streak_freezes_available=COALESCE(streak_freezes_available,0)+v_amount
      WHERE id=v_uid;
    RETURN jsonb_build_object('success',true,'sku',p_sku,'price',v_price,
      'new_balance',v_new_balance,'granted_kind','streak_freeze','granted_amount',v_amount);
  END IF;
  RAISE EXCEPTION 'unhandled_grant_kind: %', v_kind USING ERRCODE='22023';
END; $$;


ALTER FUNCTION "public"."purchase_shop_item"("p_sku" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."purge_expired_stories"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_deleted integer := 0;
  v_paths   text[];
BEGIN
  CREATE TEMP TABLE IF NOT EXISTS _expiring_stories (id uuid, image_url text) ON COMMIT DROP;
  DELETE FROM _expiring_stories;

  INSERT INTO _expiring_stories (id, image_url)
  SELECT id, image_url
    FROM public.stories
   WHERE expires_at = least(expires_at, now())
     AND NOT (id IN (
       SELECT story_id
         FROM public.story_highlight_items
        WHERE story_id IS NOT NULL
     ));

  DELETE FROM public.stories
   WHERE id IN (SELECT id FROM _expiring_stories);

  GET DIAGNOSTICS v_deleted = ROW_COUNT;

  SELECT array_agg(split_part(image_url, '/uploads/', 2))
    INTO v_paths
    FROM _expiring_stories
   WHERE image_url IS NOT NULL
     AND image_url LIKE '%/uploads/%';

  IF v_paths IS NOT NULL THEN
    PERFORM public.enqueue_storage_cleanup('uploads', v_paths, 'story_expiry');
  END IF;

  RETURN v_deleted;
END;
$$;


ALTER FUNCTION "public"."purge_expired_stories"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."purge_message_request"("p_conv_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_email    TEXT := public.current_user_email();
  v_parts    TEXT[];
  v_accepted TEXT[];
  v_group    BOOLEAN;
  v_paths    TEXT[];
  v_other    TEXT;
  v_deleted  INTEGER := 0;
BEGIN
  IF v_email = '' THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;
  IF p_conv_id IS NULL THEN
    RETURN FALSE;
  END IF;

  SELECT participant_emails, accepted_emails, coalesce(is_group, FALSE)
    INTO v_parts, v_accepted, v_group
    FROM public.hub_conversations
   WHERE id = p_conv_id;

  IF v_parts IS NULL THEN
    RETURN FALSE;
  END IF;

  IF NOT (
    v_email = ANY (
      ARRAY(
        SELECT lower(participant_email)
          FROM unnest(v_parts) AS participant_email
      )
    )
  ) THEN
    RAISE EXCEPTION 'not_a_participant' USING ERRCODE = '42501';
  END IF;

  IF v_group OR NOT (coalesce(array_length(v_parts, 1), 0) = 2) THEN
    RAISE EXCEPTION 'not_a_message_request' USING ERRCODE = '42501';
  END IF;

  IF v_email = ANY (
    ARRAY(
      SELECT lower(accepted_email)
        FROM unnest(coalesce(v_accepted, ARRAY[]::text[])) AS accepted_email
    )
  ) THEN
    RAISE EXCEPTION 'conversation_already_accepted' USING ERRCODE = '42501';
  END IF;

  SELECT lower(participant_email)
    INTO v_other
    FROM unnest(v_parts) AS participant_email
   WHERE NOT (lower(participant_email) = v_email)
   LIMIT 1;

  IF v_other IS NOT NULL THEN
    INSERT INTO public.dm_request_blocks (blocker_email, blocked_email)
    VALUES (v_email, v_other)
    ON CONFLICT (blocker_email, blocked_email) DO NOTHING;
  END IF;

  SELECT array_agg(split_part(attachment_url, '/uploads/', 2))
    INTO v_paths
    FROM public.hub_messages
   WHERE conversation_id = p_conv_id
     AND attachment_url IS NOT NULL
     AND attachment_url LIKE '%/uploads/%';

  IF v_paths IS NOT NULL THEN
    PERFORM public.enqueue_storage_cleanup('uploads', v_paths, 'dm_request_purge');
  END IF;

  DELETE FROM public.hub_conversations WHERE id = p_conv_id;
  GET DIAGNOSTICS v_deleted = ROW_COUNT;
  RETURN (v_deleted = 1);
END;
$$;


ALTER FUNCTION "public"."purge_message_request"("p_conv_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."quest_expiry_text"("p_language" "text", "p_remaining" integer) RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
  SELECT CASE COALESCE(p_language, 'en')
    WHEN 'es' THEN jsonb_build_object('title', '⏳ ' || p_remaining || ' misiones por terminar', 'body', 'Las misiones se reinician a medianoche. ¡No pierdas las monedas!')
    WHEN 'fr' THEN jsonb_build_object('title', '⏳ ' || p_remaining || ' missions à terminer',   'body', 'Les missions se réinitialisent à minuit. Ne perdez pas les pièces !')
    WHEN 'de' THEN jsonb_build_object('title', '⏳ ' || p_remaining || ' Quests offen',          'body', 'Quests werden um Mitternacht zurückgesetzt. Hol dir die Münzen!')
    WHEN 'pt' THEN jsonb_build_object('title', '⏳ ' || p_remaining || ' missões pendentes',     'body', 'As missões reiniciam à meia-noite. Não perca as moedas!')
    WHEN 'it' THEN jsonb_build_object('title', '⏳ ' || p_remaining || ' missioni da finire',    'body', 'Le missioni si resettano a mezzanotte. Non perdere le monete!')
    WHEN 'ja' THEN jsonb_build_object('title', '⏳ ' || p_remaining || '個のクエスト未達成',     'body', '深夜にリセットされます。コインを取り逃さないで！')
    WHEN 'ko' THEN jsonb_build_object('title', '⏳ ' || p_remaining || '개의 퀘스트 미완료',     'body', '자정에 초기화됩니다. 코인을 놓치지 마세요!')
    WHEN 'zh' THEN jsonb_build_object('title', '⏳ 还有 ' || p_remaining || ' 个任务未完成',     'body', '任务将在午夜重置。别错过金币！')
    WHEN 'ar' THEN jsonb_build_object('title', '⏳ ' || p_remaining || ' مهام متبقية',           'body', 'تُعاد المهام عند منتصف الليل. لا تفوّت العملات!')
    WHEN 'hi' THEN jsonb_build_object('title', '⏳ ' || p_remaining || ' क्वेस्ट बाकी',           'body', 'क्वेस्ट आधी रात को रीसेट होते हैं। सिक्के मत खोएं!')
    WHEN 'ru' THEN jsonb_build_object('title', '⏳ Осталось ' || p_remaining || ' заданий',      'body', 'Задания сбрасываются в полночь. Не упустите монеты!')
    WHEN 'tr' THEN jsonb_build_object('title', '⏳ ' || p_remaining || ' görev bitmedi',         'body', 'Görevler gece yarısı sıfırlanır. Madeni paraları kaçırma!')
    WHEN 'pl' THEN jsonb_build_object('title', '⏳ ' || p_remaining || ' zadań do ukończenia',   'body', 'Zadania resetują się o północy. Nie trać monet!')
    WHEN 'nl' THEN jsonb_build_object('title', '⏳ ' || p_remaining || ' quests open',           'body', 'Quests resetten om middernacht. Mis de munten niet!')
    ELSE              jsonb_build_object('title', '⏳ ' || p_remaining || ' quests left today',  'body', 'Quests reset at midnight. Don''t miss the coins!')
  END;
$$;


ALTER FUNCTION "public"."quest_expiry_text"("p_language" "text", "p_remaining" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."recompute_active_crew_wars"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_war  uuid;
  v_done integer := 0;
BEGIN
  FOR v_war IN
    SELECT id FROM public.crew_wars
     WHERE status = 'active' AND crew_b_id IS NOT NULL
     ORDER BY ends_at
     LIMIT 200
  LOOP
    PERFORM public.recompute_crew_war(v_war);
    v_done := v_done + 1;
  END LOOP;

  RETURN v_done;
END;
$$;


ALTER FUNCTION "public"."recompute_active_crew_wars"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."recompute_crew_war"("p_war_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_crew_a uuid; v_crew_b uuid; v_start timestamptz; v_end timestamptz; v_status text;
  v_crew uuid; v_user uuid; v_email text;
  v_vol numeric; v_sess integer; v_days integer;
  v_cap bigint; v_vol_c bigint; v_sess_c integer; v_days_c integer;
  v_score integer; v_n_a integer; v_n_b integer; v_field integer;
  v_score_a integer; v_score_b integer; v_touched integer := 0;
BEGIN
  IF p_war_id IS NULL THEN RETURN 0; END IF;

  SELECT crew_a_id, crew_b_id, starts_at, ends_at, status
    INTO v_crew_a, v_crew_b, v_start, v_end, v_status
    FROM public.crew_wars WHERE id = p_war_id;

  IF v_crew_b IS NULL OR v_start IS NULL OR v_end IS NULL THEN RETURN 0; END IF;

  FOR v_crew IN SELECT unnest(ARRAY[v_crew_a, v_crew_b])
  LOOP
    FOR v_user IN
      SELECT user_id FROM public.crew_members WHERE crew_id = v_crew LIMIT 40
    LOOP
      SELECT lower(email) INTO v_email FROM public.user_profiles WHERE id = v_user;

      SELECT COALESCE(SUM(public._duel_calc_volume(exercises)), 0),
             COUNT(*), COUNT(DISTINCT "date")
        INTO v_vol, v_sess, v_days
        FROM public.workout_logs
       WHERE (user_id = v_user OR (v_email IS NOT NULL AND lower(created_by) = v_email))
         AND created_at BETWEEN v_start AND v_end
         AND NOT COALESCE(implausible, FALSE);

      v_cap    := public.crew_member_volume_ceiling(v_user);
      v_vol_c  := LEAST(v_cap, GREATEST(0, FLOOR(COALESCE(v_vol, 0))))::bigint;
      v_sess_c := LEAST(28, GREATEST(0, COALESCE(v_sess, 0)));
      v_days_c := LEAST(7,  GREATEST(0, COALESCE(v_days, 0)));
      v_score  := public._crew_war_score(v_vol_c, v_sess_c, v_days_c);

      INSERT INTO public.crew_war_contributions
        (war_id, user_id, crew_id, xp_contributed, volume_lbs, sessions, days_active, updated_at)
      VALUES (p_war_id, v_user, v_crew, v_score, v_vol_c, v_sess_c, v_days_c, now())
      ON CONFLICT (war_id, user_id) DO UPDATE
        SET xp_contributed = v_score, volume_lbs = v_vol_c, sessions = v_sess_c,
            days_active = v_days_c, crew_id = v_crew, updated_at = now();

      v_touched := v_touched + 1;
    END LOOP;
  END LOOP;

  SELECT COUNT(*) INTO v_n_a FROM public.crew_war_contributions
   WHERE war_id = p_war_id AND crew_id = v_crew_a;
  SELECT COUNT(*) INTO v_n_b FROM public.crew_war_contributions
   WHERE war_id = p_war_id AND crew_id = v_crew_b;

  v_field := GREATEST(1, LEAST(v_n_a, v_n_b));

  SELECT COALESCE(SUM(xp_contributed), 0) INTO v_score_a FROM (
    SELECT xp_contributed FROM public.crew_war_contributions
     WHERE war_id = p_war_id AND crew_id = v_crew_a
     ORDER BY xp_contributed DESC LIMIT v_field) AS fielded_a;

  SELECT COALESCE(SUM(xp_contributed), 0) INTO v_score_b FROM (
    SELECT xp_contributed FROM public.crew_war_contributions
     WHERE war_id = p_war_id AND crew_id = v_crew_b
     ORDER BY xp_contributed DESC LIMIT v_field) AS fielded_b;

  UPDATE public.crew_wars
     SET crew_a_score = v_score_a, crew_b_score = v_score_b, scored_at = now()
   WHERE id = p_war_id;

  RETURN v_touched;
END;
$$;


ALTER FUNCTION "public"."recompute_crew_war"("p_war_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reconcile_my_workout_volume"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_total_delta NUMERIC := 0;
  v_count INT := 0;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501';
  END IF;

  SELECT COALESCE(SUM(COALESCE(total_volume, 0)), 0)::NUMERIC, COUNT(*)
    INTO v_total_delta, v_count
    FROM public.workout_logs
   WHERE user_id = v_uid
     AND volume_credited_at IS NULL
     AND COALESCE(total_volume, 0) > 0
     AND NOT COALESCE(implausible, FALSE)
     AND created_at > now() - INTERVAL '7 days';

  IF v_count = 0 THEN
    RETURN jsonb_build_object('reconciled', 0, 'delta', 0);
  END IF;

  PERFORM public.increment_user_volume(v_total_delta);

  UPDATE public.workout_logs
     SET volume_credited_at = now()
   WHERE user_id = v_uid
     AND volume_credited_at IS NULL
     AND COALESCE(total_volume, 0) > 0
     AND NOT COALESCE(implausible, FALSE)
     AND created_at > now() - INTERVAL '7 days';

  RETURN jsonb_build_object('reconciled', v_count, 'delta', v_total_delta);
END;
$$;


ALTER FUNCTION "public"."reconcile_my_workout_volume"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_monthly_xp"("p_user_id" "uuid", "p_email" "text", "p_tier" "text", "p_amount" integer) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid         UUID := auth.uid();
  v_email       TEXT;
  v_month_start DATE := date_trunc('month', now() AT TIME ZONE 'UTC')::date;
  v_month_end   DATE := (date_trunc('month', now() AT TIME ZONE 'UTC') + INTERVAL '1 month - 1 day')::date;
  v_league_id   UUID;
  v_member_id   UUID;
  v_safe_amount INT;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;

  IF p_user_id IS NOT NULL AND p_user_id <> v_uid THEN
    RAISE EXCEPTION 'cannot record xp for another user' USING ERRCODE = '42501';
  END IF;

  SELECT email INTO v_email FROM public.user_profiles WHERE id = v_uid;
  IF v_email IS NULL THEN
    RAISE EXCEPTION 'profile missing' USING ERRCODE = 'P0002';
  END IF;

  IF p_tier IS NULL OR p_tier NOT IN ('bronze','silver','gold','platinum','diamond','master','grandmaster') THEN
    RAISE EXCEPTION 'invalid tier' USING ERRCODE = '22023';
  END IF;

  IF p_amount IS NULL OR p_amount <= 0 THEN RETURN; END IF;
  v_safe_amount := LEAST(p_amount, 5000);

  SELECT id INTO v_league_id
    FROM public.monthly_leagues
   WHERE tier        = p_tier
     AND month_start = v_month_start
     AND is_resolved = false
     AND member_count < 200
   ORDER BY created_at DESC
   LIMIT 1;

  IF v_league_id IS NULL THEN
    INSERT INTO public.monthly_leagues (tier, month_start, month_end, member_count)
    VALUES (p_tier, v_month_start, v_month_end, 0)
    RETURNING id INTO v_league_id;
  END IF;

  INSERT INTO public.monthly_league_members (league_id, user_id, user_email, monthly_xp)
  VALUES (v_league_id, v_uid, v_email, v_safe_amount)
  ON CONFLICT (league_id, user_id)
  DO UPDATE SET monthly_xp = public.monthly_league_members.monthly_xp + v_safe_amount
  RETURNING id INTO v_member_id;

  IF v_member_id IS NOT NULL THEN
    UPDATE public.monthly_leagues
       SET member_count = (SELECT COUNT(*) FROM public.monthly_league_members WHERE league_id = v_league_id)
     WHERE id = v_league_id;
  END IF;
END;
$$;


ALTER FUNCTION "public"."record_monthly_xp"("p_user_id" "uuid", "p_email" "text", "p_tier" "text", "p_amount" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."refund_coach_chat_quota"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_day  date := (now() AT TIME ZONE 'utc')::date;
  v_rows integer;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN;
  END IF;

  UPDATE public.coach_chat_quota
     SET call_count = GREATEST(call_count - 1, 0)
   WHERE user_id = auth.uid()
     AND day = v_day;

  GET DIAGNOSTICS v_rows = ROW_COUNT;

  IF v_rows > 0 THEN
    UPDATE public.coach_chat_daily_total
       SET call_count = GREATEST(call_count - 1, 0)
     WHERE day = v_day;
  END IF;
END;
$$;


ALTER FUNCTION "public"."refund_coach_chat_quota"() OWNER TO "postgres";


