CREATE OR REPLACE FUNCTION "public"."reject_gym_verification"("p_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_uid UUID := auth.uid(); v_rows INT; v_reason TEXT;
BEGIN
  IF NOT public.is_app_admin(v_uid) THEN RAISE EXCEPTION 'admin_only' USING ERRCODE = '42501'; END IF;
  v_reason := NULLIF(btrim(COALESCE(p_reason, '')), '');
  IF v_reason IS NOT NULL THEN v_reason := LEFT(v_reason, 280); END IF;
  UPDATE public.gym_verification_queue
     SET status = 'rejected', rejection_reason = v_reason,
         reviewed_at = now(), reviewed_by = v_uid
   WHERE id = p_id AND status = 'pending';
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  IF v_rows = 0 THEN
    IF EXISTS (SELECT 1 FROM public.gym_verification_queue WHERE id = p_id) THEN
      RAISE EXCEPTION 'already_processed' USING ERRCODE = '22023';
    END IF;
    RAISE EXCEPTION 'verification_not_found' USING ERRCODE = 'P0002';
  END IF;
END;
$$;


ALTER FUNCTION "public"."reject_gym_verification"("p_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."release_scheduled_messages"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_count INTEGER := 0;
  v_id    UUID;
  v_conv  UUID;
  v_text  TEXT;
BEGIN
  FOR v_id IN
    SELECT id
      FROM public.hub_messages
     WHERE status = 'scheduled'
       AND scheduled_at <= now()
     ORDER BY scheduled_at
  LOOP
    UPDATE public.hub_messages
       SET status       = 'sent',
           created_at   = now(),
           created_date = now(),
           scheduled_at = NULL
     WHERE id = v_id;

    SELECT conversation_id,
           left(coalesce(NULLIF(btrim(body), ''), content, ''), 80)
      INTO v_conv, v_text
      FROM public.hub_messages
     WHERE id = v_id;

    UPDATE public.hub_conversations
       SET last_message_at      = now(),
           last_message_preview = COALESCE(NULLIF(v_text, ''), '📎 Attachment')
     WHERE id = v_conv;

    v_count := v_count + 1;
  END LOOP;

  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."release_scheduled_messages"() OWNER TO "postgres";


