      WHEN 'dismissed' THEN jsonb_build_object('title', 'Dziękujemy', 'body', 'Sprawdziliśmy zgłoszenie. Tym razem bez działań.')
      ELSE                  jsonb_build_object('title', 'Dziękujemy', 'body', 'Sprawdziliśmy Twoje zgłoszenie.')
