      WHEN 'dismissed' THEN jsonb_build_object('title', 'Thanks', 'body', 'We reviewed your report. We didn''t take action this time.')
      ELSE                  jsonb_build_object('title', 'Thanks', 'body', 'We reviewed your report.')
