CREATE OR REPLACE FUNCTION "public"."resolve_due_crew_wars"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_war      uuid;
  v_crew_a   uuid;
  v_crew_b   uuid;
  v_score_a  integer;
  v_score_b  integer;
  v_winner   uuid;
  v_loser    uuid;
  v_mvp      uuid;
  v_member   uuid;
  v_resolved integer := 0;
BEGIN
  FOR v_war IN
    SELECT id
      FROM public.crew_wars
     WHERE status = 'active'
       AND crew_b_id IS NOT NULL
       AND now() = GREATEST(now(), ends_at)
       AND NOT (now() = ends_at)
     ORDER BY ends_at
     LIMIT 200
  LOOP
    PERFORM public.recompute_crew_war(v_war);

    PERFORM 1 FROM public.crew_wars WHERE id = v_war FOR UPDATE;

    SELECT crew_a_id, crew_b_id, crew_a_score, crew_b_score
      INTO v_crew_a, v_crew_b, v_score_a, v_score_b
      FROM public.crew_wars WHERE id = v_war;

    IF v_score_a = v_score_b THEN
      v_winner := NULL;
      v_loser  := NULL;
    ELSIF v_score_a = GREATEST(v_score_a, v_score_b) THEN
      v_winner := v_crew_a;
      v_loser  := v_crew_b;
    ELSE
      v_winner := v_crew_b;
      v_loser  := v_crew_a;
    END IF;

    v_mvp := NULL;
    IF v_winner IS NOT NULL THEN
      SELECT user_id INTO v_mvp
        FROM public.crew_war_contributions
       WHERE war_id = v_war
         AND crew_id = v_winner
         AND NOT (xp_contributed = 0)
       ORDER BY xp_contributed DESC, updated_at
       LIMIT 1;
    END IF;

    UPDATE public.crew_wars
       SET status = 'completed', winner_crew_id = v_winner, mvp_user_id = v_mvp
     WHERE id = v_war AND status = 'active';

    UPDATE public.crew_wars
       SET rewarded_at = now()
     WHERE id = v_war AND rewarded_at IS NULL;

    IF FOUND THEN
      IF v_winner IS NOT NULL THEN
        FOR v_member IN
          SELECT user_id FROM public.crew_members WHERE crew_id = v_winner
        LOOP
          PERFORM public.increment_user_xp(v_member, 250);
          PERFORM public.grant_flex_coins(v_member, 100);
        END LOOP;

        IF v_mvp IS NOT NULL THEN
          PERFORM public.increment_user_xp(v_mvp, 150);
          PERFORM public.grant_flex_coins(v_mvp, 50);
        END IF;

        PERFORM public.award_crew_progress(v_winner, 400, 30, 3, 'win');
        PERFORM public.award_crew_progress(v_loser,  150,  0, 0, 'loss');
      ELSE
        PERFORM public.award_crew_progress(v_crew_a, 250, 12, 1, 'draw');
        PERFORM public.award_crew_progress(v_crew_b, 250, 12, 1, 'draw');
      END IF;
    END IF;

    PERFORM public.notify_crew_war_resolved_for(v_war);
    v_resolved := v_resolved + 1;
  END LOOP;

  PERFORM public.pair_waiting_crew_wars();

  DELETE FROM public.crew_wars
   WHERE crew_b_id IS NULL
     AND status = 'matchmaking'
     AND created_at = LEAST(created_at, now() - INTERVAL '3 days');

  RETURN v_resolved;
END;
$$;


ALTER FUNCTION "public"."resolve_due_crew_wars"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_league_bracket_internal"("p_league_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  c_min_bracket CONSTANT INTEGER := 5;
  c_decay_grace CONSTANT INTEGER := 2;

  v_tier        TEXT;
  v_week_start  DATE;
  v_week_end    DATE;
  v_promote_pct NUMERIC;
  v_demote_pct  NUMERIC;
  v_min_days    INTEGER;
  v_min_xp      INTEGER;
  v_coins       INTEGER;
  v_capsule     TEXT;

  v_qualified   INTEGER := 0;
  v_promote_n   INTEGER := 0;
  v_demote_n    INTEGER := 0;
  v_rank        INTEGER := 0;
  v_touched     INTEGER := 0;

  v_mid         UUID;
  v_uid         UUID;
  v_email       TEXT;
  v_days        INTEGER;
  v_xp          INTEGER;
  v_is_q        BOOLEAN;
  v_outcome     TEXT;
  v_new_tier    TEXT;
  v_pay         INTEGER;
  v_cap         TEXT;
  v_quiet       INTEGER;
  v_shields     INTEGER;
  v_shielded    BOOLEAN;
BEGIN
  SELECT tier, week_start, week_end
    INTO v_tier, v_week_start, v_week_end
    FROM public.leagues
   WHERE id = p_league_id;

  IF v_tier IS NULL THEN
    RETURN 0;
  END IF;

  SELECT promote_pct, demote_pct, min_days, min_xp, reward_coins, reward_capsule
    INTO v_promote_pct, v_demote_pct, v_min_days, v_min_xp, v_coins, v_capsule
    FROM (VALUES
      ('bronze',   0.50, 0.00, 1, 0,   50, NULL::TEXT),
      ('silver',   0.40, 0.10, 1, 0,  100, NULL),
      ('gold',     0.30, 0.15, 2, 0,  200, 'standard'),
      ('platinum', 0.25, 0.20, 2, 0,  350, 'premium'),
      ('diamond',  0.20, 0.20, 3, 0,  600, 'premium'),
      ('legend',   0.00, 0.20, 3, 0, 1000, 'elite')
    ) AS cfg(tier_id, promote_pct, demote_pct, min_days, min_xp, reward_coins, reward_capsule)
   WHERE tier_id = v_tier;

  IF v_promote_pct IS NULL THEN
    RETURN 0;
  END IF;

  FOR v_mid IN
    SELECT id FROM public.league_members WHERE league_id = p_league_id
  LOOP
    SELECT user_id, COALESCE(weekly_xp, 0) INTO v_uid, v_xp
      FROM public.league_members WHERE id = v_mid;

    v_days := public.league_active_days(v_uid, v_week_start, v_week_end);
    v_is_q := (v_days >= v_min_days) AND (v_xp >= v_min_xp);

    UPDATE public.league_members
       SET active_days = v_days, qualified = v_is_q
     WHERE id = v_mid;
  END LOOP;

  SELECT COUNT(*) INTO v_qualified
    FROM public.league_members
   WHERE league_id = p_league_id AND qualified = TRUE;

  IF v_qualified >= c_min_bracket THEN
    v_promote_n := GREATEST(1, CEIL(v_qualified * v_promote_pct))::INTEGER;
    v_demote_n  := FLOOR(v_qualified * v_demote_pct)::INTEGER;
    IF v_promote_pct = 0 THEN
      v_promote_n := 0;
    END IF;
  END IF;

  FOR v_mid IN
    SELECT id FROM public.league_members
     WHERE league_id = p_league_id AND qualified = TRUE
     ORDER BY weekly_xp DESC NULLS LAST, joined_at ASC
  LOOP
    v_rank := v_rank + 1;

    SELECT user_id, user_email, COALESCE(weekly_xp, 0)
      INTO v_uid, v_email, v_xp
      FROM public.league_members WHERE id = v_mid;

    v_shielded := FALSE;

    IF v_promote_n > 0 AND v_rank <= v_promote_n THEN
      v_outcome  := 'promote';
      v_new_tier := CASE v_tier
                      WHEN 'bronze'   THEN 'silver'
                      WHEN 'silver'   THEN 'gold'
                      WHEN 'gold'     THEN 'platinum'
                      WHEN 'platinum' THEN 'diamond'
                      WHEN 'diamond'  THEN 'legend'
                      ELSE v_tier
                    END;
      v_pay := CASE WHEN v_rank = 1 THEN (v_coins * 3) / 2 ELSE v_coins END;
      v_cap := v_capsule;

    ELSIF v_demote_n > 0 AND v_rank > (v_qualified - v_demote_n) THEN
      SELECT COALESCE(league_shields_owned, 0) INTO v_shields
        FROM public.user_profiles WHERE id = v_uid;

      IF v_shields >= 1 THEN
        UPDATE public.user_profiles
           SET league_shields_owned = league_shields_owned - 1,
               league_shield_used_at = now()
         WHERE id = v_uid;
        v_shielded := TRUE;
        v_outcome  := 'hold';
        v_new_tier := v_tier;
        v_pay      := 0;
        v_cap      := NULL;
      ELSE
        v_outcome  := 'demote';
        v_new_tier := CASE v_tier
                        WHEN 'silver'   THEN 'bronze'
                        WHEN 'gold'     THEN 'silver'
                        WHEN 'platinum' THEN 'gold'
                        WHEN 'diamond'  THEN 'platinum'
                        WHEN 'legend'   THEN 'diamond'
                        ELSE v_tier
                      END;
        v_pay := 0;
        v_cap := NULL;
      END IF;

    ELSE
      v_outcome  := 'hold';
      v_new_tier := v_tier;
      v_pay      := GREATEST(1, v_coins / 4);
      v_cap      := NULL;
    END IF;

    UPDATE public.league_members
       SET rank = v_rank, outcome = v_outcome, coins_awarded = COALESCE(v_pay, 0)
     WHERE id = v_mid;

    UPDATE public.user_profiles
       SET league_inactive_weeks = 0
     WHERE id = v_uid;

    IF v_new_tier IS DISTINCT FROM v_tier THEN
      UPDATE public.user_profiles SET league_tier = v_new_tier WHERE id = v_uid;
    END IF;

    IF v_pay > 0 THEN
      UPDATE public.user_profiles
         SET flex_coins = COALESCE(flex_coins, 0) + v_pay
       WHERE id = v_uid;
    END IF;

    IF v_cap IS NOT NULL THEN
      INSERT INTO public.user_capsules (user_id, user_email, capsule_type)
      VALUES (v_uid, v_email, v_cap);
    END IF;

    PERFORM public.league_season_record_internal(v_uid, v_email, v_tier, TRUE, v_xp);

    IF v_outcome IN ('promote', 'demote') OR v_shielded THEN
      PERFORM public.notify_league_resolution_internal(
        v_uid, v_outcome, v_tier, v_new_tier, COALESCE(v_pay, 0), v_cap);
    END IF;

    v_touched := v_touched + 1;
  END LOOP;

  FOR v_mid IN
    SELECT id FROM public.league_members
     WHERE league_id = p_league_id AND qualified = FALSE
  LOOP
    SELECT user_id, user_email INTO v_uid, v_email
      FROM public.league_members WHERE id = v_mid;

    UPDATE public.league_members
       SET outcome = 'unranked', coins_awarded = 0
     WHERE id = v_mid;

    UPDATE public.user_profiles
       SET league_inactive_weeks = COALESCE(league_inactive_weeks, 0) + 1
     WHERE id = v_uid;

    PERFORM public.league_season_record_internal(v_uid, v_email, v_tier, FALSE, 0);

    SELECT COALESCE(league_inactive_weeks, 0), COALESCE(league_shields_owned, 0)
      INTO v_quiet, v_shields
      FROM public.user_profiles WHERE id = v_uid;

    IF v_quiet > c_decay_grace AND v_tier <> 'bronze' THEN
      IF v_shields >= 1 THEN
        UPDATE public.user_profiles
           SET league_shields_owned = league_shields_owned - 1,
               league_shield_used_at = now()
         WHERE id = v_uid;
        PERFORM public.notify_league_resolution_internal(
          v_uid, 'hold', v_tier, v_tier, 0, NULL);
      ELSE
        v_new_tier := CASE v_tier
                        WHEN 'silver'   THEN 'bronze'
                        WHEN 'gold'     THEN 'silver'
                        WHEN 'platinum' THEN 'gold'
                        WHEN 'diamond'  THEN 'platinum'
                        WHEN 'legend'   THEN 'diamond'
                        ELSE v_tier
                      END;
        UPDATE public.user_profiles SET league_tier = v_new_tier WHERE id = v_uid;
        UPDATE public.league_members SET outcome = 'decayed' WHERE id = v_mid;
        PERFORM public.notify_league_resolution_internal(
          v_uid, 'demote', v_tier, v_new_tier, 0, NULL);
      END IF;
    END IF;

    v_touched := v_touched + 1;
  END LOOP;

  UPDATE public.leagues
     SET qualified_count = v_qualified,
         resolved_at = now()
   WHERE id = p_league_id;

  RETURN v_touched;
END;
$$;


ALTER FUNCTION "public"."resolve_league_bracket_internal"("p_league_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_profile_email"("p_id" "uuid" DEFAULT NULL::"uuid", "p_username" "text" DEFAULT NULL::"text") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_email text;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'resolve_profile_email requires authentication' USING ERRCODE = '42501';
  END IF;
  SELECT email INTO v_email FROM public.user_profiles
   WHERE (p_id IS NOT NULL AND id = p_id)
      OR (p_username IS NOT NULL AND username = p_username)
   LIMIT 1;
  RETURN v_email;
END;
$$;


ALTER FUNCTION "public"."resolve_profile_email"("p_id" "uuid", "p_username" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_report"("p_report_id" "uuid", "p_action" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT public.is_app_admin(auth.uid()) THEN
    RAISE EXCEPTION 'admin_only' USING ERRCODE = '42501';
  END IF;
  IF p_action NOT IN ('reviewed', 'actioned', 'dismissed') THEN
    RAISE EXCEPTION 'invalid_action' USING ERRCODE = '22023';
  END IF;
  UPDATE public.hub_reports
     SET status = p_action
   WHERE id = p_report_id;
END;
$$;


ALTER FUNCTION "public"."resolve_report"("p_report_id" "uuid", "p_action" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."respond_to_trade_offer"("p_offer_id" "uuid", "p_accept" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_me          UUID := auth.uid();
  v_from_user   UUID;
  v_to_user     UUID;
  v_from_inv    UUID;
  v_to_inv      UUID;
  v_listing     UUID;
  v_status      TEXT;
  v_first       UUID;
  v_second      UUID;
  v_from_owner  UUID;
  v_from_escrow UUID;
  v_to_owner    UUID;
  v_to_escrow   UUID;
  v_to_listed   BOOLEAN;
  v_from_email  TEXT;
  v_to_email    TEXT;
  v_other_id    UUID;
  v_other_inv   UUID;
BEGIN
  IF v_me IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;

  SELECT from_user_id, to_user_id, from_inventory_id, to_inventory_id, listing_id, status
    INTO v_from_user, v_to_user, v_from_inv, v_to_inv, v_listing, v_status
    FROM public.trade_offers WHERE id = p_offer_id FOR UPDATE;

  IF v_from_user IS NULL   THEN RAISE EXCEPTION 'offer_not_found'; END IF;
  IF v_to_user <> v_me     THEN RAISE EXCEPTION 'not_your_offer'; END IF;
  IF v_status <> 'pending' THEN RAISE EXCEPTION 'offer_not_pending'; END IF;

  IF NOT p_accept THEN
    UPDATE public.trade_offers SET status = 'declined', responded_at = now() WHERE id = p_offer_id;
    UPDATE public.user_inventory SET escrow_offer_id = NULL, is_listed = FALSE
     WHERE id = v_from_inv AND escrow_offer_id = p_offer_id;
    RETURN jsonb_build_object('status', 'declined', 'offer_id', p_offer_id);
  END IF;

  IF v_from_inv < v_to_inv THEN
    v_first := v_from_inv; v_second := v_to_inv;
  ELSE
    v_first := v_to_inv; v_second := v_from_inv;
  END IF;
  PERFORM 1 FROM public.user_inventory WHERE id = v_first FOR UPDATE;
  PERFORM 1 FROM public.user_inventory WHERE id = v_second FOR UPDATE;

  SELECT user_id, escrow_offer_id, user_email
    INTO v_from_owner, v_from_escrow, v_from_email
    FROM public.user_inventory WHERE id = v_from_inv;

  SELECT user_id, escrow_offer_id, is_listed, user_email
    INTO v_to_owner, v_to_escrow, v_to_listed, v_to_email
    FROM public.user_inventory WHERE id = v_to_inv;

  IF v_from_owner IS NULL OR v_to_owner IS NULL THEN RAISE EXCEPTION 'item_no_longer_exists'; END IF;
  IF v_from_owner <> v_from_user THEN RAISE EXCEPTION 'offer_item_changed_hands'; END IF;
  IF v_from_escrow IS DISTINCT FROM p_offer_id THEN RAISE EXCEPTION 'offer_item_not_escrowed'; END IF;
  IF v_to_owner <> v_to_user THEN RAISE EXCEPTION 'your_item_changed_hands'; END IF;
  IF v_to_escrow IS NOT NULL THEN RAISE EXCEPTION 'your_item_in_escrow'; END IF;

  UPDATE public.user_inventory
     SET user_id = v_to_user, user_email = v_to_email,
         escrow_offer_id = NULL, is_listed = FALSE, acquired_via = 'trade'
   WHERE id = v_from_inv;

  UPDATE public.user_inventory
     SET user_id = v_from_user, user_email = v_from_email,
         escrow_offer_id = NULL, is_listed = FALSE, acquired_via = 'trade'
   WHERE id = v_to_inv;

  UPDATE public.trade_offers SET status = 'accepted', responded_at = now() WHERE id = p_offer_id;

  IF v_listing IS NOT NULL THEN
    UPDATE public.marketplace_listings SET status = 'completed'
     WHERE id = v_listing AND status = 'active';
  END IF;

  FOR v_other_id, v_other_inv IN
    SELECT id, from_inventory_id FROM public.trade_offers
     WHERE status = 'pending' AND id <> p_offer_id
       AND (from_inventory_id IN (v_from_inv, v_to_inv)
         OR to_inventory_id IN (v_from_inv, v_to_inv))
  LOOP
    UPDATE public.trade_offers SET status = 'cancelled', responded_at = now() WHERE id = v_other_id;
    UPDATE public.user_inventory SET escrow_offer_id = NULL, is_listed = FALSE
     WHERE id = v_other_inv AND escrow_offer_id = v_other_id;
  END LOOP;

  RETURN jsonb_build_object('status', 'accepted', 'offer_id', p_offer_id);
END;
$$;


ALTER FUNCTION "public"."respond_to_trade_offer"("p_offer_id" "uuid", "p_accept" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rls_auto_enable"() RETURNS "event_trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."rls_auto_enable"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."roll_crew_seasons"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_season  uuid;
  v_num     integer;
  v_new     uuid;
  v_crew    uuid;
  v_div     integer;
  v_rolled  integer := 0;
BEGIN
  SELECT id, season_number INTO v_season, v_num
    FROM public.crew_seasons
   WHERE status = 'active'
     AND now() = GREATEST(now(), ends_at)
     AND NOT (now() = ends_at)
   ORDER BY season_number
   LIMIT 1;

  IF v_season IS NULL THEN
    PERFORM public.current_crew_season();
    RETURN 0;
  END IF;

  UPDATE public.crew_seasons
     SET status = 'completed'
   WHERE id = v_season AND status = 'active';

  IF NOT FOUND THEN
    RETURN 0;
  END IF;

  INSERT INTO public.crew_seasons (season_number, starts_at, ends_at, status)
  VALUES (v_num + 1, now(), now() + INTERVAL '28 days', 'active')
  RETURNING id INTO v_new;

  FOR v_crew, v_div IN
    SELECT crew_id, division
      FROM public.crew_season_stats
     WHERE season_id = v_season
  LOOP
    DECLARE
      v_size   integer;
      v_rank   integer;
      v_points integer;
      v_next   integer := v_div;
    BEGIN
      SELECT COUNT(*) INTO v_size
        FROM public.crew_season_stats
       WHERE season_id = v_season AND division = v_div;

      IF v_size = GREATEST(v_size, 8) THEN
        SELECT points INTO v_points
          FROM public.crew_season_stats
         WHERE season_id = v_season AND crew_id = v_crew;

        SELECT COUNT(*) + 1 INTO v_rank
          FROM public.crew_season_stats
         WHERE season_id = v_season
           AND division  = v_div
           AND points    = GREATEST(points, COALESCE(v_points, 0) + 1);

        IF v_rank = LEAST(v_rank, 3) AND NOT (v_div = 1) THEN
          v_next := v_div - 1;
        ELSIF v_rank = GREATEST(v_rank, v_size - 2) THEN
          v_next := v_div + 1;
        END IF;
      END IF;

      INSERT INTO public.crew_season_stats (season_id, crew_id, division)
      VALUES (v_new, v_crew, GREATEST(1, v_next))
      ON CONFLICT (season_id, crew_id) DO NOTHING;
    END;

    v_rolled := v_rolled + 1;
  END LOOP;

  RETURN v_rolled;
END;
$$;


ALTER FUNCTION "public"."roll_crew_seasons"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."roll_league_seasons"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  c_min_weeks CONSTANT INTEGER := 2;

  v_season   UUID;
  v_number   INTEGER;
  v_next     INTEGER;
  v_uid      UUID;
  v_email    TEXT;
  v_tier     TEXT;
  v_weeks    INTEGER;
  v_champ    UUID;
  v_rank     INTEGER := 0;
  v_awarded  INTEGER := 0;
BEGIN
  SELECT id, season_number INTO v_season, v_number
    FROM public.league_seasons
   WHERE status = 'active'
     AND now() = GREATEST(now(), ends_at)
     AND NOT (now() = ends_at)
   ORDER BY season_number
   LIMIT 1;

  IF v_season IS NULL THEN
    RETURN 0;
  END IF;

  UPDATE public.league_seasons
     SET status = 'completed'
   WHERE id = v_season AND status = 'active';

  IF NOT FOUND THEN
    RETURN 0;
  END IF;

  FOR v_uid IN
    SELECT user_id FROM public.league_season_stats
     WHERE season_id = v_season
     ORDER BY season_xp DESC, weeks_qualified DESC
  LOOP
    v_rank := v_rank + 1;
    UPDATE public.league_season_stats
       SET final_rank = v_rank
     WHERE season_id = v_season AND user_id = v_uid;
  END LOOP;

  SELECT user_id INTO v_champ
    FROM public.league_season_stats
   WHERE season_id = v_season
     AND best_tier = 'legend'
     AND weeks_qualified >= c_min_weeks
   ORDER BY season_xp DESC, weeks_qualified DESC
   LIMIT 1;

  FOR v_uid IN
    SELECT user_id FROM public.league_season_stats
     WHERE season_id = v_season
       AND weeks_qualified >= c_min_weeks
  LOOP
    SELECT user_email, best_tier, weeks_qualified
      INTO v_email, v_tier, v_weeks
      FROM public.league_season_stats
     WHERE season_id = v_season AND user_id = v_uid;

    PERFORM public.award_league_season_internal(v_uid, v_email, v_number, v_tier, FALSE);

    IF v_champ IS NOT NULL AND v_uid = v_champ THEN
      PERFORM public.award_league_season_internal(v_uid, v_email, v_number, v_tier, TRUE);
    END IF;

    UPDATE public.league_season_stats
       SET awarded_at = now()
     WHERE season_id = v_season AND user_id = v_uid;

    PERFORM public.notify_league_resolution_internal(
      v_uid, 'hold', v_tier, v_tier, 0, NULL);

    v_awarded := v_awarded + 1;
  END LOOP;

  UPDATE public.user_profiles
     SET league_tier = CASE COALESCE(league_tier, 'bronze')
                         WHEN 'legend'   THEN 'diamond'
                         WHEN 'diamond'  THEN 'platinum'
                         WHEN 'platinum' THEN 'gold'
                         WHEN 'gold'     THEN 'silver'
                         WHEN 'silver'   THEN 'bronze'
                         ELSE 'bronze'
                       END
   WHERE COALESCE(league_tier, 'bronze') <> 'bronze';

  v_next := v_number + 1;
  INSERT INTO public.league_seasons (season_number, name, starts_at, ends_at, status)
  VALUES (v_next, public.league_season_name(v_next), now(), now() + INTERVAL '28 days', 'active')
  ON CONFLICT DO NOTHING;

  RETURN v_awarded;
END;
$$;


ALTER FUNCTION "public"."roll_league_seasons"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."roll_weekly_leagues"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_id      UUID;
  v_claimed INTEGER := 0;
BEGIN
  FOR v_id IN
    SELECT id FROM public.leagues
     WHERE is_resolved = FALSE
       AND week_end = LEAST(week_end, CURRENT_DATE)
       AND NOT (week_end = CURRENT_DATE)
     ORDER BY week_start
  LOOP
    UPDATE public.leagues
       SET is_resolved = TRUE
     WHERE id = v_id AND is_resolved = FALSE;

    IF FOUND THEN
      PERFORM public.resolve_league_bracket_internal(v_id);
      v_claimed := v_claimed + 1;
    END IF;
  END LOOP;

  RETURN v_claimed;
END;
$$;


ALTER FUNCTION "public"."roll_weekly_leagues"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."run_quest_expiry_reminders"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_now       TIMESTAMPTZ := now();
  v_count     INTEGER := 0;
  v_row       RECORD;
  v_text      JSONB;
  v_remaining INTEGER;
BEGIN
  FOR v_row IN
    UPDATE public.user_profiles AS p
       SET last_quest_nudge_at = v_now
     WHERE p.timezone_offset_minutes IS NOT NULL
       AND (p.last_quest_nudge_at IS NULL OR p.last_quest_nudge_at < v_now - INTERVAL '6 hours')
       AND (p.notification_prefs IS NULL
            OR (p.notification_prefs ->> 'quests') IS NULL
            OR (p.notification_prefs ->> 'quests') <> 'false')
       AND EXTRACT(HOUR FROM (v_now + (p.timezone_offset_minutes || ' minutes')::interval) AT TIME ZONE 'UTC')
           BETWEEN 21 AND 22
       AND EXISTS (
             SELECT 1 FROM public.user_daily_quests q
              WHERE q.user_id = p.id
                AND q.quest_date = ((v_now + (p.timezone_offset_minutes || ' minutes')::interval) AT TIME ZONE 'UTC')::date
                AND q.completed_at IS NULL
           )
    RETURNING p.id AS user_id, p.email AS user_email, p.preferred_language,
              p.timezone_offset_minutes
  LOOP
    IF v_row.user_email IS NULL THEN CONTINUE; END IF;
    SELECT COUNT(*) INTO v_remaining
      FROM public.user_daily_quests q
     WHERE q.user_id = v_row.user_id
       AND q.quest_date = ((v_now + (v_row.timezone_offset_minutes || ' minutes')::interval) AT TIME ZONE 'UTC')::date
       AND q.completed_at IS NULL;
    IF v_remaining < 1 THEN CONTINUE; END IF;
    v_text := public.quest_expiry_text(COALESCE(v_row.preferred_language, 'en'), v_remaining);
    INSERT INTO public.notifications
      (user_id, user_email, type, title, body, icon, link_url, metadata)
    VALUES
      (v_row.user_id, v_row.user_email, 'quest_expiry_warning',
       v_text ->> 'title', v_text ->> 'body', '⏳', '/dashboard',
       jsonb_build_object('remaining', v_remaining));
    v_count := v_count + 1;
  END LOOP;
  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."run_quest_expiry_reminders"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."run_streak_break_reminders"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_now      TIMESTAMPTZ := now();
  v_count    INTEGER     := 0;
  v_row      RECORD;
  v_streak   INTEGER;
  v_title    TEXT;
  v_body     TEXT;
  v_text     JSONB;
  v_lang     TEXT;
BEGIN
  FOR v_row IN
    UPDATE public.user_profiles AS p
       SET last_streak_nudge_at = v_now
     WHERE p.timezone_offset_minutes IS NOT NULL
       AND p.workout_streak >= 2
       AND (p.last_workout_date IS NULL
            OR p.last_workout_date <> ((v_now + (p.timezone_offset_minutes || ' minutes')::interval) AT TIME ZONE 'UTC')::date)
       AND (p.last_streak_nudge_at IS NULL
            OR p.last_streak_nudge_at < v_now - INTERVAL '18 hours')
       AND EXTRACT(HOUR FROM (v_now + (p.timezone_offset_minutes || ' minutes')::interval) AT TIME ZONE 'UTC')
           BETWEEN 18 AND 20
    RETURNING p.id AS user_id, p.email AS user_email, p.workout_streak,
              p.full_name, p.preferred_language
  LOOP
    v_streak := v_row.workout_streak;
    IF v_row.user_email IS NULL THEN CONTINUE; END IF;
    v_lang  := COALESCE(v_row.preferred_language, 'en');
    v_text  := public.streak_break_text(v_lang, v_streak);
    v_title := v_text ->> 'title';
    v_body  := v_text ->> 'body';

    INSERT INTO public.notifications
      (user_id, user_email, type, title, body, icon, link_url, metadata)
    VALUES
      (v_row.user_id, v_row.user_email, 'streak_break_warning',
       v_title, v_body, '🔥', '/workouts',
       jsonb_build_object('workout_streak', v_streak));

    v_count := v_count + 1;
  END LOOP;

  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."run_streak_break_reminders"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."run_welcome_back_reminders"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_now   TIMESTAMPTZ := now();
  v_count INTEGER := 0;
  v_row   RECORD;
  v_text  JSONB;
BEGIN
  FOR v_row IN
    UPDATE public.user_profiles AS p
       SET last_welcome_back_at = v_now
     WHERE p.timezone_offset_minutes IS NOT NULL
       AND p.last_login_date IS NOT NULL
       AND p.last_login_date <= (v_now AT TIME ZONE 'UTC')::date - INTERVAL '3 days'
       AND p.last_login_date >  (v_now AT TIME ZONE 'UTC')::date - INTERVAL '30 days'
       AND (p.last_welcome_back_at IS NULL OR p.last_welcome_back_at < v_now - INTERVAL '5 days')
       AND (p.notification_prefs IS NULL
            OR (p.notification_prefs ->> 'engagement') IS NULL
            OR (p.notification_prefs ->> 'engagement') <> 'false')
       AND EXTRACT(HOUR FROM (v_now + (p.timezone_offset_minutes || ' minutes')::interval) AT TIME ZONE 'UTC')
           BETWEEN 18 AND 20
    RETURNING p.id AS user_id, p.email AS user_email, p.preferred_language
  LOOP
    IF v_row.user_email IS NULL THEN CONTINUE; END IF;
    v_text := public.welcome_back_text(COALESCE(v_row.preferred_language, 'en'));
    INSERT INTO public.notifications
      (user_id, user_email, type, title, body, icon, link_url, metadata)
    VALUES
      (v_row.user_id, v_row.user_email, 'welcome_back',
       v_text ->> 'title', v_text ->> 'body', '👋', '/dashboard', '{}'::jsonb);
    v_count := v_count + 1;
  END LOOP;
  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."run_welcome_back_reminders"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."schedule_my_message"("p_conversation_id" "uuid", "p_recipient_email" "text", "p_content" "text", "p_send_at" timestamp with time zone) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid   UUID := auth.uid();
  v_email TEXT := NULLIF(public.current_user_email(), '');
  v_id    UUID;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;
  IF p_send_at IS NULL OR p_send_at <= now() THEN
    RAISE EXCEPTION 'send_at_in_past' USING ERRCODE = '22023';
  END IF;
  IF p_content IS NULL OR length(trim(p_content)) = 0 THEN
    RAISE EXCEPTION 'empty_message' USING ERRCODE = '22023';
  END IF;
  IF p_conversation_id IS NULL THEN
    RAISE EXCEPTION 'conversation_id required' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.hub_conversations
     WHERE id = p_conversation_id
       AND (v_email = ANY(participant_emails)
            OR v_uid = ANY(participant_ids))
  ) THEN
    RAISE EXCEPTION 'not a conversation participant' USING ERRCODE = '42501';
  END IF;

  INSERT INTO public.hub_messages
    (created_by, user_id, conversation_id, sender_email, content,
     scheduled_at, status)
  VALUES
    (v_email, v_uid, p_conversation_id, v_email, p_content,
     p_send_at, 'scheduled')
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."schedule_my_message"("p_conversation_id" "uuid", "p_recipient_email" "text", "p_content" "text", "p_send_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."schedule_workout"("p_date" "date", "p_hour" smallint, "p_title" "text", "p_workout" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_email   TEXT;
  v_pending INTEGER;
  v_id      UUID;
BEGIN
  IF v_user_id IS NULL THEN RAISE EXCEPTION 'not authenticated'; END IF;
  IF p_hour IS NULL OR p_hour < 0 OR p_hour > 23 THEN RAISE EXCEPTION 'hour must be 0-23'; END IF;
  IF p_workout IS NULL OR jsonb_typeof(p_workout) <> 'object' THEN RAISE EXCEPTION 'workout payload required'; END IF;
  IF p_date IS NULL OR p_date > (CURRENT_DATE + 365) THEN RAISE EXCEPTION 'date out of range'; END IF;

  SELECT email INTO v_email FROM public.user_profiles WHERE id = v_user_id;
  IF v_email IS NULL THEN RAISE EXCEPTION 'profile has no email to notify'; END IF;

  SELECT COUNT(*) INTO v_pending FROM public.scheduled_workouts
   WHERE user_id = v_user_id AND status = 'pending';
  IF v_pending >= 100 THEN RAISE EXCEPTION 'too many scheduled workouts'; END IF;

  INSERT INTO public.scheduled_workouts
    (user_id, user_email, scheduled_date, scheduled_hour, title, workout)
  VALUES
    (v_user_id, v_email, p_date, p_hour, COALESCE(NULLIF(p_title, ''), 'Workout'), p_workout)
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."schedule_workout"("p_date" "date", "p_hour" smallint, "p_title" "text", "p_workout" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_home_gym"("p_gym_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid    UUID;
  v_email  TEXT;
  v_active BOOLEAN;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('ok', FALSE, 'error', 'NOT_AUTHENTICATED');
  END IF;

  IF p_gym_id IS NULL THEN
    UPDATE public.user_profiles SET home_gym_id = NULL WHERE id = v_uid;
    RETURN jsonb_build_object('ok', TRUE, 'gym_id', NULL, 'cleared', TRUE);
  END IF;

  SELECT is_active INTO v_active
    FROM public.gym_businesses
   WHERE id = p_gym_id;

  IF v_active IS NULL THEN
    RETURN jsonb_build_object('ok', FALSE, 'error', 'GYM_NOT_FOUND');
  END IF;
  IF v_active IS NOT TRUE THEN
    RETURN jsonb_build_object('ok', FALSE, 'error', 'GYM_INACTIVE');
  END IF;

  SELECT email INTO v_email FROM auth.users WHERE id = v_uid;

  INSERT INTO public.gym_members (gym_id, user_id, user_email)
  VALUES (p_gym_id, v_uid, COALESCE(v_email, ''))
  ON CONFLICT (gym_id, user_id) DO NOTHING;

  UPDATE public.user_profiles SET home_gym_id = p_gym_id WHERE id = v_uid;

  RETURN jsonb_build_object('ok', TRUE, 'gym_id', p_gym_id);
END;
$$;


ALTER FUNCTION "public"."set_home_gym"("p_gym_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_home_gym_custom"("p_name" "text", "p_lat" double precision, "p_lng" double precision, "p_city" "text" DEFAULT NULL::"text", "p_state" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid      UUID;
  v_email    TEXT;
  v_gym_id   UUID;
  v_name     TEXT;
  v_key      TEXT;
  v_code     TEXT;
  v_mine     INTEGER;
  v_lat_span DOUBLE PRECISION := 0.0045;
  v_lng_span DOUBLE PRECISION;
  v_created  BOOLEAN := FALSE;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('ok', FALSE, 'error', 'NOT_AUTHENTICATED');
  END IF;

  v_name := btrim(COALESCE(p_name, ''));
  IF length(v_name) < 2 THEN
    RETURN jsonb_build_object('ok', FALSE, 'error', 'NAME_REQUIRED');
  END IF;
  v_name := left(v_name, 120);
  v_key  := lower(v_name);

  IF p_lat IS NULL OR p_lng IS NULL
     OR p_lat <  -90 OR p_lat >  90
     OR p_lng < -180 OR p_lng > 180 THEN
    RETURN jsonb_build_object('ok', FALSE, 'error', 'BAD_COORDS');
  END IF;

  v_lng_span := v_lat_span / GREATEST(0.05, cos(radians(p_lat)));

  SELECT id INTO v_gym_id
    FROM public.gym_businesses
   WHERE is_active
     AND lower(btrim(name)) = v_key
     AND latitude  BETWEEN p_lat - v_lat_span AND p_lat + v_lat_span
     AND longitude BETWEEN p_lng - v_lng_span AND p_lng + v_lng_span
   ORDER BY abs(latitude - p_lat) + abs(longitude - p_lng)
   LIMIT 1;

  IF v_gym_id IS NULL THEN
    SELECT count(*) INTO v_mine
      FROM public.gym_businesses
     WHERE source = 'community'
       AND created_by_user_id = v_uid;

    IF v_mine >= 20 THEN
      RETURN jsonb_build_object('ok', FALSE, 'error', 'CREATE_LIMIT');
    END IF;

    v_code := public.generate_flexyn_code();

    BEGIN
      INSERT INTO public.gym_businesses (
        owner_id, name, city, state_code,
        latitude, longitude, flexyn_code,
        source, osm_type, osm_id, created_by_user_id, is_active
      )
      VALUES (
        NULL, v_name, p_city, p_state,
        p_lat, p_lng, v_code,
        'community', NULL, NULL, v_uid, TRUE
      )
      RETURNING id INTO v_gym_id;
      v_created := TRUE;
    EXCEPTION WHEN unique_violation THEN
      v_gym_id := NULL;
    END;

    IF v_gym_id IS NULL THEN
      SELECT id INTO v_gym_id
        FROM public.gym_businesses
       WHERE osm_id IS NULL
         AND source = 'community'
         AND lower(btrim(name)) = v_key
         AND round(latitude::numeric, 3)  = round(p_lat::numeric, 3)
         AND round(longitude::numeric, 3) = round(p_lng::numeric, 3)
       LIMIT 1;
    END IF;

    IF v_gym_id IS NULL THEN
      RETURN jsonb_build_object('ok', FALSE, 'error', 'CREATE_FAILED');
    END IF;
  END IF;

  SELECT email INTO v_email FROM auth.users WHERE id = v_uid;

  INSERT INTO public.gym_members (gym_id, user_id, user_email)
  VALUES (v_gym_id, v_uid, COALESCE(v_email, ''))
  ON CONFLICT (gym_id, user_id) DO NOTHING;

  UPDATE public.user_profiles SET home_gym_id = v_gym_id WHERE id = v_uid;

  RETURN jsonb_build_object(
    'ok', TRUE, 'gym_id', v_gym_id, 'created', v_created);
END;
$$;


ALTER FUNCTION "public"."set_home_gym_custom"("p_name" "text", "p_lat" double precision, "p_lng" double precision, "p_city" "text", "p_state" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_home_gym_from_osm"("p_osm_type" "text", "p_osm_id" bigint, "p_name" "text", "p_lat" double precision, "p_lng" double precision, "p_city" "text" DEFAULT NULL::"text", "p_state" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid     UUID;
  v_email   TEXT;
  v_gym_id  UUID;
  v_name    TEXT;
  v_type    TEXT;
  v_code    TEXT;
  v_mine    INTEGER;
  v_created BOOLEAN := FALSE;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('ok', FALSE, 'error', 'NOT_AUTHENTICATED');
  END IF;

  v_type := lower(COALESCE(p_osm_type, ''));
  IF v_type NOT IN ('node', 'way', 'relation') THEN
    RETURN jsonb_build_object('ok', FALSE, 'error', 'BAD_OSM_TYPE');
  END IF;

  IF p_osm_id IS NULL OR p_osm_id <= 0 THEN
    RETURN jsonb_build_object('ok', FALSE, 'error', 'BAD_OSM_ID');
  END IF;

  v_name := btrim(COALESCE(p_name, ''));
  IF v_name = '' THEN
    RETURN jsonb_build_object('ok', FALSE, 'error', 'NAME_REQUIRED');
  END IF;
  v_name := left(v_name, 120);

  IF p_lat IS NULL OR p_lng IS NULL
     OR p_lat <  -90 OR p_lat >  90
     OR p_lng < -180 OR p_lng > 180 THEN
    RETURN jsonb_build_object('ok', FALSE, 'error', 'BAD_COORDS');
  END IF;

  SELECT id INTO v_gym_id
    FROM public.gym_businesses
   WHERE osm_type = v_type
     AND osm_id   = p_osm_id;

  IF v_gym_id IS NULL THEN
    SELECT count(*) INTO v_mine
      FROM public.gym_businesses
     WHERE source = 'community'
       AND created_by_user_id = v_uid;

    IF v_mine >= 20 THEN
      RETURN jsonb_build_object('ok', FALSE, 'error', 'CREATE_LIMIT');
    END IF;

    v_code := public.generate_flexyn_code();

    INSERT INTO public.gym_businesses (
      owner_id, name, city, state_code,
      latitude, longitude, flexyn_code,
      source, osm_type, osm_id, created_by_user_id, is_active
    )
    VALUES (
      NULL, v_name, p_city, p_state,
      p_lat, p_lng, v_code,
      'community', v_type, p_osm_id, v_uid, TRUE
    )
    ON CONFLICT (osm_type, osm_id) WHERE osm_id IS NOT NULL DO NOTHING
    RETURNING id INTO v_gym_id;

    v_created := v_gym_id IS NOT NULL;

    IF v_gym_id IS NULL THEN
      SELECT id INTO v_gym_id
        FROM public.gym_businesses
       WHERE osm_type = v_type
         AND osm_id   = p_osm_id;
    END IF;

    IF v_gym_id IS NULL THEN
      RETURN jsonb_build_object('ok', FALSE, 'error', 'CREATE_FAILED');
    END IF;
  END IF;

  SELECT email INTO v_email FROM auth.users WHERE id = v_uid;

  INSERT INTO public.gym_members (gym_id, user_id, user_email)
  VALUES (v_gym_id, v_uid, COALESCE(v_email, ''))
  ON CONFLICT (gym_id, user_id) DO NOTHING;

  UPDATE public.user_profiles SET home_gym_id = v_gym_id WHERE id = v_uid;

  RETURN jsonb_build_object(
    'ok', TRUE, 'gym_id', v_gym_id, 'created', v_created);
END;
$$;


ALTER FUNCTION "public"."set_home_gym_from_osm"("p_osm_type" "text", "p_osm_id" bigint, "p_name" "text", "p_lat" double precision, "p_lng" double precision, "p_city" "text", "p_state" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_layout_default"("p_surface" "text", "p_widget_order" "jsonb", "p_section_layouts" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid    UUID := auth.uid();
  v_email  TEXT := NULLIF(public.current_user_email(), '');
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;
  IF p_surface NOT IN ('dashboard', 'workout', 'nutrition') THEN
    RAISE EXCEPTION 'invalid_surface: %', p_surface USING ERRCODE = '22023';
  END IF;
  IF NOT public.is_layout_admin(v_uid) THEN
    RAISE EXCEPTION 'admin_only' USING ERRCODE = '42501';
  END IF;
  IF jsonb_typeof(p_widget_order) <> 'array' THEN
    RAISE EXCEPTION 'widget_order must be a JSONB array' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.app_layout_defaults
    (surface, widget_order, section_layouts, updated_at, updated_by)
  VALUES
    (p_surface, p_widget_order, p_section_layouts, NOW(), v_email)
  ON CONFLICT (surface) DO UPDATE
    SET widget_order    = EXCLUDED.widget_order,
        section_layouts = EXCLUDED.section_layouts,
        updated_at      = NOW(),
        updated_by      = EXCLUDED.updated_by;

  RETURN jsonb_build_object(
    'success',    true,
    'surface',    p_surface,
    'updated_at', NOW()
  );
END;
$$;


ALTER FUNCTION "public"."set_layout_default"("p_surface" "text", "p_widget_order" "jsonb", "p_section_layouts" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_listing_bundle"("p_listing_id" "uuid", "p_bundle_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid            UUID := auth.uid();
  v_listing_seller UUID;
  v_listing_status TEXT;
  v_bundle_seller  UUID;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;
  IF p_listing_id IS NULL THEN
    RAISE EXCEPTION 'listing_id required' USING ERRCODE = '22023';
  END IF;

  SELECT seller_user_id, status INTO v_listing_seller, v_listing_status
    FROM public.marketplace_listings
   WHERE id = p_listing_id
     FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'listing not found' USING ERRCODE = '22023';
  END IF;
  IF v_listing_seller <> v_uid THEN
    RAISE EXCEPTION 'not_your_listing' USING ERRCODE = '42501';
  END IF;
  IF v_listing_status <> 'active' THEN
    RAISE EXCEPTION 'listing is %', v_listing_status USING ERRCODE = '22023';
  END IF;

  IF p_bundle_id IS NOT NULL THEN
    SELECT seller_user_id INTO v_bundle_seller
      FROM public.marketplace_bundles
     WHERE id = p_bundle_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'bundle_not_found';
    END IF;
    IF v_bundle_seller <> v_uid THEN
      RAISE EXCEPTION 'not_your_bundle' USING ERRCODE = '42501';
    END IF;
  END IF;

  UPDATE public.marketplace_listings
     SET bundle_id = p_bundle_id
   WHERE id = p_listing_id;
END;
$$;


ALTER FUNCTION "public"."set_listing_bundle"("p_listing_id" "uuid", "p_bundle_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_listing_featured"("p_listing_id" "uuid", "p_until" timestamp with time zone) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT public.is_app_admin(auth.uid()) THEN
    RAISE EXCEPTION 'admin_only' USING ERRCODE = '42501';
  END IF;
  UPDATE public.marketplace_listings
     SET is_featured    = (p_until IS NOT NULL AND p_until > now()),
         featured_until = p_until
   WHERE id = p_listing_id;
END;
$$;


ALTER FUNCTION "public"."set_listing_featured"("p_listing_id" "uuid", "p_until" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_post_emoji_reaction"("p_post_id" "uuid", "p_emoji" "text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_email TEXT := NULLIF(public.current_user_email(), '');
  v_uid   UUID := auth.uid();
  v_old_emoji TEXT;
  v_new_count INT;
BEGIN
  IF v_email IS NULL OR v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;
  IF p_post_id IS NULL THEN
    RAISE EXCEPTION 'post_id required' USING ERRCODE = '22023';
  END IF;
  IF p_emoji IS NOT NULL AND char_length(p_emoji) > 8 THEN
    RAISE EXCEPTION 'emoji too long' USING ERRCODE = '22023';
  END IF;
  IF p_emoji IS NOT NULL AND p_emoji IN ('like', 'dislike') THEN
    RAISE EXCEPTION 'reserved emoji value' USING ERRCODE = '22023';
  END IF;

  SELECT emoji INTO v_old_emoji
    FROM public.hub_reactions
   WHERE post_id = p_post_id
     AND created_by = v_email
     AND reaction_type IS NULL
   LIMIT 1;

  IF v_old_emoji IS NOT DISTINCT FROM p_emoji THEN
    SELECT COALESCE(emoji_reaction_count, 0) INTO v_new_count
      FROM public.hub_posts WHERE id = p_post_id;
    RETURN v_new_count;
  END IF;

  IF v_old_emoji IS NOT NULL THEN
    DELETE FROM public.hub_reactions
     WHERE post_id = p_post_id
       AND created_by = v_email
       AND reaction_type IS NULL;
    UPDATE public.hub_posts
       SET emoji_reaction_count = GREATEST(0, COALESCE(emoji_reaction_count, 0) - 1)
     WHERE id = p_post_id;
  END IF;

  IF p_emoji IS NOT NULL THEN
    INSERT INTO public.hub_reactions (post_id, created_by, user_id, reaction_type, emoji, user_email)
    VALUES (p_post_id, v_email, v_uid, NULL, p_emoji, v_email);
    UPDATE public.hub_posts
       SET emoji_reaction_count = COALESCE(emoji_reaction_count, 0) + 1
     WHERE id = p_post_id;
  END IF;

  SELECT COALESCE(emoji_reaction_count, 0) INTO v_new_count
    FROM public.hub_posts WHERE id = p_post_id;
  RETURN v_new_count;
END;
$$;


ALTER FUNCTION "public"."set_post_emoji_reaction"("p_post_id" "uuid", "p_emoji" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_post_reaction"("p_post_id" "uuid", "p_reaction" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_email TEXT := NULLIF(public.current_user_email(), '');
  v_uid   UUID := auth.uid();
  v_old   TEXT;
BEGIN
  IF v_email IS NULL OR v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;
  IF p_reaction IS NOT NULL AND p_reaction NOT IN ('like', 'dislike') THEN
    RAISE EXCEPTION 'invalid reaction: %', p_reaction USING ERRCODE = '22023';
  END IF;
  IF p_post_id IS NULL THEN
    RAISE EXCEPTION 'post_id required' USING ERRCODE = '22023';
  END IF;
  SELECT reaction_type INTO v_old FROM public.hub_reactions
   WHERE post_id = p_post_id AND created_by = v_email LIMIT 1;
  IF v_old IS NOT DISTINCT FROM p_reaction THEN RETURN; END IF;
  IF v_old IS NOT NULL THEN
    DELETE FROM public.hub_reactions WHERE post_id = p_post_id AND created_by = v_email;
    IF v_old = 'like' THEN
      UPDATE public.hub_posts SET like_count = GREATEST(0, COALESCE(like_count, 0) - 1) WHERE id = p_post_id;
    ELSIF v_old = 'dislike' THEN
      UPDATE public.hub_posts SET dislike_count = GREATEST(0, COALESCE(dislike_count, 0) - 1) WHERE id = p_post_id;
    END IF;
  END IF;
  IF p_reaction IS NOT NULL THEN
    INSERT INTO public.hub_reactions (post_id, created_by, user_id, reaction_type, emoji, user_email)
    VALUES (p_post_id, v_email, v_uid, p_reaction, p_reaction, v_email);
    IF p_reaction = 'like' THEN
      UPDATE public.hub_posts SET like_count = COALESCE(like_count, 0) + 1 WHERE id = p_post_id;
    ELSIF p_reaction = 'dislike' THEN
      UPDATE public.hub_posts SET dislike_count = COALESCE(dislike_count, 0) + 1 WHERE id = p_post_id;
    END IF;
  END IF;
END;
$$;


ALTER FUNCTION "public"."set_post_reaction"("p_post_id" "uuid", "p_reaction" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_username"("p_username" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_uid UUID; v_clean TEXT; v_current TEXT; v_last TIMESTAMPTZ;
  v_taken BOOLEAN; v_next TIMESTAMPTZ;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN RETURN jsonb_build_object('ok', false, 'reason', 'not_signed_in'); END IF;
  v_clean := ltrim(lower(btrim(coalesce(p_username, ''))), '@');
  IF v_clean !~ '^[a-z0-9_]{3,20}$' THEN RETURN jsonb_build_object('ok', false, 'reason', 'invalid'); END IF;
  SELECT username, username_changed_at INTO v_current, v_last
    FROM public.user_profiles WHERE id = v_uid;
  IF v_current IS NOT NULL AND lower(v_current) = v_clean THEN
    RETURN jsonb_build_object('ok', true, 'reason', 'unchanged', 'username', v_current);
  END IF;
  SELECT EXISTS (SELECT 1 FROM public.user_profiles
                  WHERE lower(username) = v_clean AND id <> v_uid) INTO v_taken;
  IF v_taken THEN RETURN jsonb_build_object('ok', false, 'reason', 'taken'); END IF;
  IF v_current IS NOT NULL AND v_current <> '' AND v_last IS NOT NULL THEN
    v_next := v_last + INTERVAL '30 days';
    IF now() < v_next THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'cooldown', 'next_change_at', v_next);
    END IF;
  END IF;
  BEGIN
    UPDATE public.user_profiles
       SET username = v_clean,
           username_changed_at = CASE
             WHEN v_current IS NULL OR v_current = '' THEN username_changed_at
             ELSE now() END
     WHERE id = v_uid;
  EXCEPTION
    WHEN unique_violation THEN RETURN jsonb_build_object('ok', false, 'reason', 'taken');
    WHEN check_violation  THEN RETURN jsonb_build_object('ok', false, 'reason', 'reserved');
    WHEN OTHERS           THEN RETURN jsonb_build_object('ok', false, 'reason', 'rejected');
  END;
  RETURN jsonb_build_object('ok', true, 'reason', 'changed', 'username', v_clean,
    'next_change_at', CASE WHEN v_current IS NULL OR v_current = ''
                           THEN NULL ELSE now() + INTERVAL '30 days' END);
END;
$_$;


ALTER FUNCTION "public"."set_username"("p_username" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."snooze_notification_category"("p_category" "text", "p_minutes" integer) RETURNS timestamp with time zone
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid    UUID := auth.uid();
  v_until  TIMESTAMPTZ;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;
  IF p_category IS NULL THEN
    RAISE EXCEPTION 'category required' USING ERRCODE = '22023';
  END IF;
  IF p_minutes IS NOT NULL AND (p_minutes < 0 OR p_minutes > 1440) THEN
    RAISE EXCEPTION 'minutes must be 0..1440' USING ERRCODE = '22023';
  END IF;

  IF p_minutes IS NULL OR p_minutes = 0 THEN
    UPDATE public.user_profiles
       SET notification_snoozes = COALESCE(notification_snoozes, '{}'::jsonb) - p_category
     WHERE id = v_uid;
    RETURN NULL;
  END IF;

  v_until := now() + (p_minutes || ' minutes')::interval;
  UPDATE public.user_profiles
     SET notification_snoozes = COALESCE(notification_snoozes, '{}'::jsonb)
       || jsonb_build_object(p_category, to_char(v_until, 'YYYY-MM-DD"T"HH24:MI:SSOF'))
   WHERE id = v_uid;
  RETURN v_until;
END;
$$;


ALTER FUNCTION "public"."snooze_notification_category"("p_category" "text", "p_minutes" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."start_crew_generational_challenge"("p_crew_id" "uuid", "p_template_key" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_uid       uuid := auth.uid();
  v_rank      integer;
  v_level     integer;
  v_title     text;
  v_metric    text;
  v_target    integer;
  v_min_level integer;
  v_trophy    text;
  v_existing  uuid;
  v_new       uuid;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;

  IF p_crew_id IS NULL OR p_template_key IS NULL THEN
    RAISE EXCEPTION 'crew_id and template_key required' USING ERRCODE = '22023';
  END IF;

  v_rank := public.crew_rank(p_crew_id, v_uid);
  IF NOT (v_rank = 3) THEN
    RAISE EXCEPTION 'only a crew leader can start a crew challenge'
      USING ERRCODE = '42501';
  END IF;

  SELECT title, metric, target_value, min_crew_level, trophy_id
    INTO v_title, v_metric, v_target, v_min_level, v_trophy
    FROM public.crew_challenge_templates
   WHERE template_key = p_template_key AND is_active;

  IF v_title IS NULL THEN
    RAISE EXCEPTION 'no such challenge' USING ERRCODE = '22023';
  END IF;

  SELECT COALESCE(crew_level, 1) INTO v_level
    FROM public.crews WHERE id = p_crew_id;

  IF v_level = LEAST(v_level, v_min_level) AND NOT (v_level = v_min_level) THEN
    RAISE EXCEPTION 'crew level % is below the level % this challenge needs',
      v_level, v_min_level USING ERRCODE = '42501';
  END IF;

  SELECT id INTO v_existing
    FROM public.crew_challenges
   WHERE crew_id = p_crew_id AND template_key = p_template_key;

  IF v_existing IS NOT NULL THEN
    RAISE EXCEPTION 'that challenge has already been started by this crew'
      USING ERRCODE = '23505';
  END IF;

  SELECT id INTO v_existing
    FROM public.crew_challenges
   WHERE crew_id = p_crew_id
     AND template_key IS NOT NULL
     AND status = 'active';

  IF v_existing IS NOT NULL THEN
    RAISE EXCEPTION 'this crew is already chasing a challenge'
      USING ERRCODE = '23505';
  END IF;

  INSERT INTO public.crew_challenges
    (crew_id, created_by, title, metric, target_value, current_value,
     starts_at, ends_at, status, template_key)
  VALUES
    (p_crew_id, v_uid, v_title, v_metric, v_target, 0,
     now(), NULL, 'active', p_template_key)
  RETURNING id INTO v_new;

  PERFORM public.notify_crew_challenge_created_for(v_new);

  RETURN v_new;
END;
$$;


ALTER FUNCTION "public"."start_crew_generational_challenge"("p_crew_id" "uuid", "p_template_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."start_dm_conversation"("p_other_email" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid        UUID := auth.uid();
  v_email_raw  TEXT := coalesce(NULLIF(public.current_user_email(), ''), '');
  v_email      TEXT := lower(coalesce(NULLIF(public.current_user_email(), ''), ''));
  v_other      TEXT := lower(trim(coalesce(p_other_email, '')));
  v_key        TEXT;
  v_parts      TEXT[];
  v_accepted   TEXT[];
  v_follows    BOOLEAN := FALSE;
  v_blocked    BOOLEAN := FALSE;
  v_conv_id    UUID;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;

  IF v_email = '' THEN
    SELECT lower(coalesce(email, '')) INTO v_email
      FROM public.user_profiles
     WHERE id = v_uid;
    v_email := coalesce(v_email, '');
    v_email_raw := v_email;
  END IF;

  IF v_email = '' THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;

  IF v_other = '' OR v_other = v_email THEN
    RAISE EXCEPTION 'invalid_recipient' USING ERRCODE = '22023';
  END IF;

  DELETE FROM public.dm_request_blocks
   WHERE blocker_email = v_email
     AND blocked_email = v_other;

  v_key   := least(v_email, v_other) || '|' || greatest(v_email, v_other);
  v_parts := ARRAY[least(v_email, v_other), greatest(v_email, v_other)];

  SELECT id INTO v_conv_id
    FROM public.hub_conversations
   WHERE participant_key = v_key
   LIMIT 1;

  IF v_conv_id IS NOT NULL THEN
    RETURN v_conv_id;
  END IF;

  SELECT EXISTS (
    SELECT 1
      FROM public.hub_follows
     WHERE lower(follower_email) = v_other
       AND lower(followee_email) = v_email
  ) INTO v_follows;

  IF v_follows THEN
    v_accepted := ARRAY[v_email, v_other];
  ELSE
    SELECT EXISTS (
      SELECT 1
        FROM public.dm_request_blocks
       WHERE blocker_email = v_other
         AND blocked_email = v_email
    ) INTO v_blocked;

    IF v_blocked THEN
      RAISE EXCEPTION 'conversation_unavailable' USING ERRCODE = '42501';
    END IF;

    v_accepted := ARRAY[v_email];
  END IF;

  INSERT INTO public.hub_conversations
    (created_by, user_id, participant_key, participant_emails,
     accepted_emails, is_group,
     last_message_at, last_message_preview,
     created_at, created_date, updated_at)
  VALUES
    (v_email_raw, v_uid, v_key, v_parts,
     v_accepted, FALSE,
     now(), '',
     now(), now(), now())
  RETURNING id INTO v_conv_id;

  RETURN v_conv_id;
EXCEPTION WHEN unique_violation THEN
  SELECT id INTO v_conv_id
    FROM public.hub_conversations
   WHERE participant_key = v_key
   LIMIT 1;
  RETURN v_conv_id;
END;
$$;


ALTER FUNCTION "public"."start_dm_conversation"("p_other_email" "text") OWNER TO "postgres";


