CREATE OR REPLACE FUNCTION "public"."streak_break_text"("p_language" "text", "p_streak" integer) RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
  SELECT CASE COALESCE(p_language, 'en')
    WHEN 'es' THEN jsonb_build_object('title', '🔥 Racha de ' || p_streak || ' días en riesgo',  'body', 'Tu racha termina a medianoche. Un entrenamiento rápido la mantiene viva.')
    WHEN 'fr' THEN jsonb_build_object('title', '🔥 Série de ' || p_streak || ' jours en péril', 'body', 'Votre série se termine à minuit. Un entraînement rapide la sauve.')
    WHEN 'de' THEN jsonb_build_object('title', '🔥 ' || p_streak || '-Tage-Streak in Gefahr',   'body', 'Dein Streak endet um Mitternacht. Ein schnelles Training rettet ihn.')
    WHEN 'pt' THEN jsonb_build_object('title', '🔥 Sequência de ' || p_streak || ' dias em risco', 'body', 'Sua sequência termina à meia-noite. Um treino rápido a salva.')
    WHEN 'it' THEN jsonb_build_object('title', '🔥 Serie di ' || p_streak || ' giorni a rischio', 'body', 'La tua serie finisce a mezzanotte. Un allenamento veloce la salva.')
    WHEN 'ja' THEN jsonb_build_object('title', '🔥 ' || p_streak || '日連続記録が危険',          'body', '深夜にストリークが途切れます。短い運動で維持できます。')
    WHEN 'ko' THEN jsonb_build_object('title', '🔥 ' || p_streak || '일 연속 기록 위험',          'body', '자정에 연속 기록이 끊깁니다. 짧은 운동으로 유지하세요.')
    WHEN 'zh' THEN jsonb_build_object('title', '🔥 ' || p_streak || '天连胜面临中断',            'body', '你的连胜将在午夜结束。一次快速锻炼即可保持。')
    WHEN 'ar' THEN jsonb_build_object('title', '🔥 سلسلة ' || p_streak || ' أيام في خطر',          'body', 'تنتهي سلسلتك عند منتصف الليل. تمرين سريع يحافظ عليها.')
    WHEN 'hi' THEN jsonb_build_object('title', '🔥 ' || p_streak || ' दिन की लकीर खतरे में',     'body', 'आपकी लकीर आधी रात को समाप्त होगी। एक छोटा वर्कआउट इसे जीवित रखेगा।')
    WHEN 'ru' THEN jsonb_build_object('title', '🔥 Серия ' || p_streak || ' дней под угрозой',    'body', 'Ваша серия закончится в полночь. Быстрая тренировка её сохранит.')
    WHEN 'tr' THEN jsonb_build_object('title', '🔥 ' || p_streak || ' günlük seri risk altında',  'body', 'Serin gece yarısı sona eriyor. Hızlı bir antrenman onu kurtarır.')
    WHEN 'pl' THEN jsonb_build_object('title', '🔥 ' || p_streak || '-dniowa passa zagrożona',    'body', 'Twoja passa kończy się o północy. Szybki trening ją uratuje.')
    WHEN 'nl' THEN jsonb_build_object('title', '🔥 ' || p_streak || '-daagse reeks loopt gevaar', 'body', 'Je reeks eindigt om middernacht. Een snelle workout houdt hem in leven.')
    ELSE              jsonb_build_object('title', '🔥 ' || p_streak || '-day streak at risk',     'body', 'Your streak ends at midnight. A quick workout keeps it alive.')
  END;
$$;


ALTER FUNCTION "public"."streak_break_text"("p_language" "text", "p_streak" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."streak_rescue_status"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid         UUID := auth.uid();
  v_today       DATE := (now() AT TIME ZONE 'UTC')::date;
  v_month_start DATE := date_trunc('month', now() AT TIME ZONE 'UTC')::date;
  v_streak      INT;
  v_last_date   DATE;
  v_diff        INT;
  v_used        INT;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;

  SELECT workout_streak, last_workout_date INTO v_streak, v_last_date
    FROM public.user_profiles WHERE id = v_uid;
  IF v_streak IS NULL THEN
    RETURN jsonb_build_object('available', false, 'reason', 'no_profile');
  END IF;

  SELECT COUNT(*) INTO v_used FROM public.streak_rescues
   WHERE user_id = v_uid AND month_start = v_month_start;
  IF v_used > 0 THEN
    RETURN jsonb_build_object('available', false, 'reason', 'already_used_this_month',
      'current_streak', v_streak);
  END IF;
  IF v_streak < 3 THEN
    RETURN jsonb_build_object('available', false, 'reason', 'streak_too_short',
      'current_streak', v_streak);
  END IF;
  IF v_last_date IS NULL THEN
    RETURN jsonb_build_object('available', false, 'reason', 'no_last_workout');
  END IF;

  v_diff := v_today - v_last_date;
  IF v_diff <> 2 THEN
    RETURN jsonb_build_object('available', false, 'reason', 'not_at_risk',
      'current_streak', v_streak, 'days_since', v_diff);
  END IF;

  RETURN jsonb_build_object('available', true, 'current_streak', v_streak, 'days_since', v_diff);
END;
$$;


ALTER FUNCTION "public"."streak_rescue_status"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_duel_result_atomic"("p_duel_id" "uuid", "p_result" "jsonb", "p_workout_log_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_duel_id UUID; v_status TEXT; v_winner_id UUID; v_challenger_id UUID; v_opponent_id UUID;
  v_challenger_res JSONB; v_opponent_res JSONB; v_created_at TIMESTAMPTZ; v_expires_at TIMESTAMPTZ;
  v_role TEXT; v_winner UUID; v_completed BOOLEAN := FALSE;
  v_log_owner UUID; v_log_created TIMESTAMPTZ; v_log_exercises JSONB; v_volume NUMERIC;
  v_safe_result JSONB; v_duel_row public.duels%ROWTYPE;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501'; END IF;
  IF p_duel_id IS NULL OR p_result IS NULL THEN RAISE EXCEPTION 'duel_id and result required' USING ERRCODE = '22023'; END IF;
  IF p_workout_log_id IS NULL THEN RAISE EXCEPTION 'workout_log_required' USING ERRCODE = '22023'; END IF;
  SELECT id, status, winner_id, challenger_id, opponent_id, challenger_result, opponent_result, created_at, expires_at
    INTO v_duel_id, v_status, v_winner_id, v_challenger_id, v_opponent_id, v_challenger_res, v_opponent_res, v_created_at, v_expires_at
    FROM public.duels WHERE id = p_duel_id FOR UPDATE;
  IF v_duel_id IS NULL THEN RAISE EXCEPTION 'duel not found' USING ERRCODE = '22023'; END IF;
  IF v_status = 'completed' OR v_status = 'expired' OR v_status = 'declined' THEN
    RETURN jsonb_build_object('duel_id', p_duel_id, 'status', v_status, 'winner_id', v_winner_id, 'already_final', TRUE);
  END IF;
  SELECT user_id, created_at, exercises INTO v_log_owner, v_log_created, v_log_exercises
    FROM public.workout_logs WHERE id = p_workout_log_id;
  IF v_log_owner IS DISTINCT FROM v_uid THEN RAISE EXCEPTION 'invalid_workout_log' USING ERRCODE = '42501'; END IF;

  -- Migration 362: a flagged log cannot buy an award.
  IF public.workout_log_is_flagged(p_workout_log_id) THEN
    RAISE EXCEPTION 'implausible_workout_log' USING ERRCODE = '22023';
  END IF;
  IF v_log_created < v_created_at OR v_log_created > COALESCE(v_expires_at, now()) THEN
    RAISE EXCEPTION 'workout_outside_duel_window' USING ERRCODE = '22023';
  END IF;
  v_safe_result := public._duel_metrics_from_log(v_log_exercises)
                    || jsonb_build_object('workout_log_id', p_workout_log_id, 'server_computed', TRUE);
  v_volume := COALESCE((v_safe_result->>'volume')::NUMERIC, 0);
  IF v_challenger_id = v_uid THEN
    v_role := 'challenger';
    UPDATE public.duels SET challenger_result = v_safe_result WHERE id = p_duel_id;
    v_challenger_res := v_safe_result;
  ELSIF v_opponent_id = v_uid THEN
    v_role := 'opponent';
    UPDATE public.duels SET opponent_result = v_safe_result WHERE id = p_duel_id;
    v_opponent_res := v_safe_result;
  ELSE RAISE EXCEPTION 'not your duel' USING ERRCODE = '42501'; END IF;
  IF v_challenger_res IS NOT NULL AND v_opponent_res IS NOT NULL THEN
    SELECT * INTO v_duel_row FROM public.duels WHERE id = p_duel_id;
    v_winner := public._duel_resolve_winner(v_duel_row);
    UPDATE public.duels SET status = 'completed', winner_id = v_winner WHERE id = p_duel_id;
    v_completed := TRUE;
  END IF;
  RETURN jsonb_build_object('duel_id', p_duel_id, 'role', v_role,
    'status', CASE WHEN v_completed THEN 'completed' ELSE v_status END,
    'winner_id', v_winner, 'completed', v_completed, 'already_final', FALSE, 'server_volume', v_volume);
END;
$$;


ALTER FUNCTION "public"."submit_duel_result_atomic"("p_duel_id" "uuid", "p_result" "jsonb", "p_workout_log_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_gym_verification"("p_business_name" "text", "p_street_address" "text", "p_city" "text", "p_state_code" "text", "p_postal_code" "text", "p_country_code" "text" DEFAULT 'US'::"text", "p_phone" "text" DEFAULT NULL::"text", "p_website_url" "text" DEFAULT NULL::"text", "p_proof_url" "text" DEFAULT NULL::"text", "p_latitude" double precision DEFAULT NULL::double precision, "p_longitude" double precision DEFAULT NULL::double precision) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid   UUID := auth.uid();
  v_email TEXT;
  v_id    UUID;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501'; END IF;
  IF p_business_name IS NULL OR length(trim(p_business_name)) < 2 THEN
    RAISE EXCEPTION 'business_name required' USING ERRCODE = '22023';
  END IF;
  SELECT email INTO v_email FROM auth.users WHERE id = v_uid;
  INSERT INTO public.gym_verification_queue (
    owner_id, owner_email, business_name, street_address, city, state_code,
    postal_code, country_code, phone, website_url, proof_url, latitude, longitude
  ) VALUES (
    v_uid, v_email, p_business_name, p_street_address, p_city, p_state_code,
    p_postal_code, p_country_code, p_phone, p_website_url, p_proof_url, p_latitude, p_longitude
  ) RETURNING id INTO v_id;
  UPDATE public.user_profiles SET account_type = 'gym_owner' WHERE id = v_uid AND account_type = 'user';
  RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."submit_gym_verification"("p_business_name" "text", "p_street_address" "text", "p_city" "text", "p_state_code" "text", "p_postal_code" "text", "p_country_code" "text", "p_phone" "text", "p_website_url" "text", "p_proof_url" "text", "p_latitude" double precision, "p_longitude" double precision) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sweep_expired_bounties"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_bid UUID; v_creator UUID; v_reward INT;
BEGIN
  UPDATE public.bounty_claims SET status = 'expired'
   WHERE status = 'active' AND deadline < now();

  UPDATE public.bounties SET claimed_by_id = NULL
   WHERE claimed_by_id IS NOT NULL
     AND expires_at > now()
     AND id NOT IN (
       SELECT bounty_id FROM public.bounty_claims
        WHERE bounty_id IS NOT NULL AND status IN ('active','completed'));

  FOR v_bid, v_creator, v_reward IN
    SELECT id, target_user_id, reward FROM public.bounties
     WHERE is_user_created AND NOT reward_refunded AND expires_at < now()
       AND id NOT IN (
         SELECT bounty_id FROM public.bounty_claims
          WHERE bounty_id IS NOT NULL AND status = 'completed')
     FOR UPDATE
  LOOP
    UPDATE public.user_profiles SET flex_coins = COALESCE(flex_coins, 0) + v_reward
     WHERE id = v_creator;
    UPDATE public.bounties SET reward_refunded = TRUE WHERE id = v_bid;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."sweep_expired_bounties"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sweep_stale_guest_accounts"("p_older_than_days" integer DEFAULT 7, "p_limit" integer DEFAULT 200) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_cutoff     TIMESTAMPTZ;
  v_days       INTEGER;
  v_limit      INTEGER;
  v_ids        UUID[];
  v_candidates INTEGER;
  v_deleted    INTEGER;
BEGIN
  v_days   := greatest(coalesce(p_older_than_days, 7), 1);
  v_limit  := least(greatest(coalesce(p_limit, 200), 1), 1000);
  v_cutoff := now() - (v_days * INTERVAL '1 day');

  v_ids := ARRAY(
    (
      SELECT id FROM auth.users
       WHERE is_anonymous
         AND created_at < v_cutoff
      INTERSECT
      SELECT id FROM public.user_profiles
       WHERE username   IS NULL
         AND avatar_url IS NULL
         AND coalesce(total_xp, 0) = 0
         AND (last_active_at IS NULL OR last_active_at < v_cutoff)
    )
    EXCEPT SELECT user_id FROM public.workout_logs
    EXCEPT SELECT user_id FROM public.cardio_logs
    EXCEPT SELECT user_id FROM public.nutrition_logs
    EXCEPT SELECT user_id FROM public.hub_posts
    EXCEPT SELECT user_id FROM public.goals
    EXCEPT SELECT user_id FROM public.journal_entries
    EXCEPT SELECT user_id FROM public.body_metrics
    EXCEPT SELECT user_id FROM public.sleep_logs
    EXCEPT SELECT user_id FROM public.mood_logs
    EXCEPT SELECT user_id FROM public.step_logs
    LIMIT v_limit
  );

  v_candidates := coalesce(array_length(v_ids, 1), 0);

  IF v_candidates = 0 THEN
    INSERT INTO public.guest_sweep_log (deleted_count, cutoff_days, candidates)
    VALUES (0, v_days, 0);
    RETURN 0;
  END IF;

  DELETE FROM auth.users WHERE id = ANY(v_ids);
  GET DIAGNOSTICS v_deleted = ROW_COUNT;

  INSERT INTO public.guest_sweep_log (deleted_count, cutoff_days, candidates)
  VALUES (v_deleted, v_days, v_candidates);

  RETURN v_deleted;
END;
$$;


ALTER FUNCTION "public"."sweep_stale_guest_accounts"("p_older_than_days" integer, "p_limit" integer) OWNER TO "postgres";


