CREATE OR REPLACE FUNCTION "public"."sync_my_monthly_league"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid(); v_email text; v_tier text;
  v_month_start date := date_trunc('month', now() AT TIME ZONE 'UTC')::date;
  v_month_end   date := (date_trunc('month', now() AT TIME ZONE 'UTC') + INTERVAL '1 month - 1 day')::date;
  v_xp integer; v_league_id uuid;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE='42501'; END IF;
  SELECT email, league_tier INTO v_email, v_tier FROM public.user_profiles WHERE id = v_uid;
  IF v_email IS NULL THEN RAISE EXCEPTION 'profile missing' USING ERRCODE='P0002'; END IF;
  IF v_tier IS NULL OR v_tier NOT IN
     ('bronze','silver','gold','platinum','diamond','master','grandmaster')
    THEN v_tier := 'bronze'; END IF;
  SELECT COALESCE(SUM(amount),0) INTO v_xp FROM public.xp_grant_log
   WHERE user_id = v_uid AND granted_at >= v_month_start AND granted_at < (v_month_end + 1);
  IF v_xp <= 0 THEN RETURN jsonb_build_object('joined', false, 'reason', 'no xp this month'); END IF;
  SELECT id INTO v_league_id FROM public.monthly_leagues
   WHERE tier=v_tier AND month_start=v_month_start AND is_resolved=false AND member_count<200
   ORDER BY created_at DESC LIMIT 1;
  IF v_league_id IS NULL THEN
    INSERT INTO public.monthly_leagues (tier, month_start, month_end, member_count)
    VALUES (v_tier, v_month_start, v_month_end, 0) RETURNING id INTO v_league_id;
  END IF;
  INSERT INTO public.monthly_league_members (league_id, user_id, user_email, monthly_xp)
  VALUES (v_league_id, v_uid, v_email, v_xp)
  ON CONFLICT (league_id, user_id) DO UPDATE SET monthly_xp = EXCLUDED.monthly_xp;
  UPDATE public.monthly_leagues SET member_count =
    (SELECT count(*) FROM public.monthly_league_members WHERE league_id=v_league_id)
   WHERE id = v_league_id;
  RETURN jsonb_build_object('joined', true, 'league_id', v_league_id,
                            'tier', v_tier, 'monthly_xp', v_xp);
END; $$;


ALTER FUNCTION "public"."sync_my_monthly_league"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_my_weekly_league"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid        UUID := auth.uid();
  v_member_id  UUID;
  v_league_id  UUID;
  v_week_start DATE;
  v_week_end   DATE;
  v_xp         INTEGER;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;

  v_week_start := (date_trunc('week', CURRENT_DATE))::DATE;
  v_week_end   := v_week_start + 6;

  SELECT id INTO v_league_id
    FROM public.leagues
   WHERE week_start = v_week_start
     AND id IN (SELECT league_id FROM public.league_members WHERE user_id = v_uid)
   ORDER BY created_at DESC
   LIMIT 1;

  IF v_league_id IS NULL THEN
    RETURN;
  END IF;

  SELECT id INTO v_member_id
    FROM public.league_members
   WHERE league_id = v_league_id AND user_id = v_uid
   LIMIT 1;

  IF v_member_id IS NULL THEN
    RETURN;
  END IF;

  SELECT COALESCE(SUM(amount), 0) INTO v_xp
    FROM public.xp_grant_log
   WHERE user_id = v_uid
     AND granted_at >= v_week_start::TIMESTAMPTZ
     AND granted_at = LEAST(granted_at, (v_week_end + 1)::TIMESTAMPTZ);

  UPDATE public.league_members
     SET weekly_xp = GREATEST(0, v_xp)
   WHERE id = v_member_id;
END;
$$;


ALTER FUNCTION "public"."sync_my_weekly_league"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_post_collaborator_ids"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_ids    uuid[];
  v_emails text[];
BEGIN
  IF (NEW.collaborator_ids IS NULL OR array_length(NEW.collaborator_ids, 1) IS NULL)
     AND NEW.collaborator_emails IS NOT NULL
     AND array_length(NEW.collaborator_emails, 1) IS NOT NULL THEN
    SELECT array_agg(id) INTO v_ids
      FROM public.user_profiles
     WHERE lower(email) = ANY (SELECT lower(e) FROM unnest(NEW.collaborator_emails) AS e);
    NEW.collaborator_ids := COALESCE(v_ids, '{}');
  END IF;

  IF (NEW.collaborator_emails IS NULL OR array_length(NEW.collaborator_emails, 1) IS NULL)
     AND NEW.collaborator_ids IS NOT NULL
     AND array_length(NEW.collaborator_ids, 1) IS NOT NULL THEN
    SELECT array_agg(email) INTO v_emails
      FROM public.user_profiles
     WHERE id = ANY (NEW.collaborator_ids);
    NEW.collaborator_emails := COALESCE(v_emails, '{}');
  END IF;

  RETURN NEW;
END;
$$;


