CREATE OR REPLACE FUNCTION "public"."toggle_gym_feed_reaction"("p_post_id" "uuid", "p_emoji" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_gym_id  UUID;
  v_deleted INT;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501';
  END IF;
  IF p_emoji IS NULL OR char_length(p_emoji) > 10 OR char_length(p_emoji) = 0 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'INVALID_EMOJI');
  END IF;

  SELECT gym_id INTO v_gym_id
    FROM public.gym_feed_posts WHERE id = p_post_id;
  IF v_gym_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'POST_NOT_FOUND');
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.gym_members
     WHERE gym_id = v_gym_id AND user_id = v_user_id
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'NOT_MEMBER');
  END IF;

  DELETE FROM public.gym_feed_post_reactions
   WHERE post_id = p_post_id AND user_id = v_user_id AND emoji = p_emoji;
  GET DIAGNOSTICS v_deleted = ROW_COUNT;

  IF v_deleted > 0 THEN
    RETURN jsonb_build_object('ok', true, 'removed', true);
  END IF;

  INSERT INTO public.gym_feed_post_reactions (post_id, user_id, emoji)
    VALUES (p_post_id, v_user_id, p_emoji)
    ON CONFLICT (post_id, user_id, emoji) DO NOTHING;

  RETURN jsonb_build_object('ok', true, 'added', true);
END;
$$;


ALTER FUNCTION "public"."toggle_gym_feed_reaction"("p_post_id" "uuid", "p_emoji" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."toggle_pin_crew_message"("p_message_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_crew_id UUID;
  v_new_val BOOLEAN;
BEGIN
  SELECT crew_id INTO v_crew_id
  FROM public.crew_messages
  WHERE id = p_message_id;

  IF NOT EXISTS (
    SELECT 1 FROM public.crew_members
    WHERE crew_id = v_crew_id AND user_id = v_user_id
  ) THEN
    RAISE EXCEPTION 'not_a_crew_member';
  END IF;

  UPDATE public.crew_messages
  SET is_pinned = NOT is_pinned
  WHERE id = p_message_id
  RETURNING is_pinned INTO v_new_val;

  RETURN v_new_val;
END;
$$;


