CREATE OR REPLACE FUNCTION "public"."transfer_crew_leadership"("p_crew_id" "uuid", "p_to_user" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_uid      uuid := auth.uid();
  v_my_rank  integer;
  v_they_are integer;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;
  IF p_crew_id IS NULL OR p_to_user IS NULL THEN
    RAISE EXCEPTION 'crew_id and target required' USING ERRCODE = '22023';
  END IF;

  v_my_rank := public.crew_rank(p_crew_id, v_uid);
  IF NOT (v_my_rank = 3) THEN
    RAISE EXCEPTION 'only a crew leader can hand over the crew' USING ERRCODE = '42501';
  END IF;

  IF p_to_user = v_uid THEN
    RAISE EXCEPTION 'you already lead this crew' USING ERRCODE = '22023';
  END IF;

  v_they_are := public.crew_rank(p_crew_id, p_to_user);
  IF v_they_are = 0 THEN
    RAISE EXCEPTION 'that person is not in this crew' USING ERRCODE = '22023';
  END IF;

  UPDATE public.crew_members
     SET role = 'leader', is_admin = TRUE
   WHERE crew_id = p_crew_id AND user_id = p_to_user;

  UPDATE public.crew_members
     SET role = 'member', is_admin = FALSE
   WHERE crew_id = p_crew_id AND user_id = v_uid;

  RETURN jsonb_build_object('ok', TRUE, 'new_leader', p_to_user);
END;
$$;


ALTER FUNCTION "public"."transfer_crew_leadership"("p_crew_id" "uuid", "p_to_user" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."unban_crew_member"("p_crew_id" "uuid", "p_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_uid   uuid := auth.uid();
  v_admin integer;
  v_gone  integer;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;

  SELECT COUNT(*) INTO v_admin
    FROM public.crew_members
   WHERE crew_id = p_crew_id AND user_id = v_uid AND is_admin = TRUE;

  IF v_admin = 0 THEN
    RAISE EXCEPTION 'only a crew leader can unban' USING ERRCODE = '42501';
  END IF;

  WITH gone AS (
    DELETE FROM public.crew_bans
     WHERE crew_id = p_crew_id AND user_id = p_user_id
    RETURNING 1
  )
  SELECT COUNT(*) INTO v_gone FROM gone;

  RETURN jsonb_build_object('ok', TRUE, 'removed', v_gone);
END;
$$;


ALTER FUNCTION "public"."unban_crew_member"("p_crew_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


