CREATE OR REPLACE FUNCTION "public"."unsend_message_request"("p_conv_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_email    TEXT := public.current_user_email();
  v_parts    TEXT[];
  v_accepted TEXT[];
  v_group    BOOLEAN;
  v_paths    TEXT[];
  v_others   INTEGER;
  v_deleted  INTEGER := 0;
BEGIN
  IF v_email = '' THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;
  IF p_conv_id IS NULL THEN
    RETURN FALSE;
  END IF;

  SELECT participant_emails, accepted_emails, coalesce(is_group, FALSE)
    INTO v_parts, v_accepted, v_group
    FROM public.hub_conversations
   WHERE id = p_conv_id;

  IF v_parts IS NULL THEN
    RETURN FALSE;
  END IF;

  IF NOT (
    v_email = ANY (
      ARRAY(
        SELECT lower(participant_email)
          FROM unnest(v_parts) AS participant_email
      )
    )
  ) THEN
    RAISE EXCEPTION 'not_a_participant' USING ERRCODE = '42501';
  END IF;

  IF v_group OR NOT (coalesce(array_length(v_parts, 1), 0) = 2) THEN
    RAISE EXCEPTION 'not_a_message_request' USING ERRCODE = '42501';
  END IF;

  SELECT count(*)
    INTO v_others
    FROM unnest(v_parts) AS participant_email
   WHERE NOT (lower(participant_email) = v_email)
     AND lower(participant_email) = ANY (
       SELECT lower(accepted_email)
         FROM unnest(coalesce(v_accepted, ARRAY[]::text[])) AS accepted_email
     );

  IF NOT (v_others = 0) THEN
    RAISE EXCEPTION 'conversation_already_accepted' USING ERRCODE = '42501';
  END IF;

  SELECT array_agg(split_part(attachment_url, '/uploads/', 2))
    INTO v_paths
    FROM public.hub_messages
   WHERE conversation_id = p_conv_id
     AND attachment_url IS NOT NULL
     AND attachment_url LIKE '%/uploads/%';

  IF v_paths IS NOT NULL THEN
    PERFORM public.enqueue_storage_cleanup('uploads', v_paths, 'dm_request_unsend');
  END IF;

  DELETE FROM public.hub_conversations WHERE id = p_conv_id;
  GET DIAGNOSTICS v_deleted = ROW_COUNT;
  RETURN (v_deleted = 1);
END;
$$;


ALTER FUNCTION "public"."unsend_message_request"("p_conv_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_notification_pref"("p_category" "text", "p_enabled" boolean) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_uid UUID := auth.uid();
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501'; END IF;
  IF p_category NOT IN ('streak','quests','league','social','achievements','engagement','competitive')
    THEN RAISE EXCEPTION 'unknown category %', p_category USING ERRCODE = '22023'; END IF;
  IF p_enabled IS NULL THEN RAISE EXCEPTION 'enabled required' USING ERRCODE = '22023'; END IF;
  UPDATE public.user_profiles
     SET notification_prefs = jsonb_set(COALESCE(notification_prefs, '{}'::jsonb),
           ARRAY[p_category], to_jsonb(p_enabled), true)
   WHERE id = v_uid;
END; $$;


ALTER FUNCTION "public"."update_notification_pref"("p_category" "text", "p_enabled" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_solo_challenge_progress"("p_volume_lbs" numeric DEFAULT 0, "p_session_count" integer DEFAULT 0, "p_cardio_min" integer DEFAULT 0, "p_prs_hit" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid        UUID := auth.uid();
  v_claim_id   UUID;
  v_chall_id   UUID;
  v_current    NUMERIC;
  v_claimed_at TIMESTAMPTZ;
  v_kind       TEXT;
  v_target     NUMERIC;
  v_derived    NUMERIC;
  v_sessions   INT;
  v_new        NUMERIC;
  v_bumped     INT := 0;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;

  FOR v_claim_id, v_chall_id, v_current, v_claimed_at IN
    SELECT id, challenge_id, progress, claimed_at
      FROM public.solo_challenge_claims
     WHERE user_id = v_uid
       AND status  = 'active'
  LOOP
    SELECT kind, target_value
      INTO v_kind, v_target
      FROM public.solo_challenges
     WHERE id = v_chall_id
       AND is_active = TRUE
       AND expires_at > NOW();

    IF NOT FOUND THEN CONTINUE; END IF;

    IF v_kind = 'weekly_volume' THEN
      SELECT COALESCE(SUM(total_volume), 0)
        INTO v_derived
        FROM public.workout_logs
       WHERE user_id = v_uid
         AND created_at >= v_claimed_at
         AND NOT COALESCE(implausible, FALSE);
    ELSIF v_kind = 'workout_count' THEN
      SELECT COUNT(*)::numeric
        INTO v_derived
        FROM public.workout_logs
       WHERE user_id = v_uid
         AND created_at >= v_claimed_at
         AND NOT COALESCE(implausible, FALSE);
    ELSIF v_kind = 'cardio_minutes' THEN
      SELECT COALESCE(SUM(COALESCE(duration_min, duration_seconds / 60.0)), 0)
        INTO v_derived
        FROM public.cardio_logs
       WHERE user_id = v_uid
         AND created_at >= v_claimed_at;
    ELSIF v_kind = 'beat_any_pr' THEN
      SELECT COUNT(*)::int
        INTO v_sessions
        FROM public.workout_logs
       WHERE user_id = v_uid
         AND created_at >= v_claimed_at
         AND NOT COALESCE(implausible, FALSE);
      v_derived := LEAST(v_current + GREATEST(COALESCE(p_prs_hit, 0), 0), v_sessions);
    ELSE
      v_derived := v_current;
    END IF;

    v_new := LEAST(v_target, GREATEST(v_current, COALESCE(v_derived, 0)));
    IF v_new > v_current THEN
      UPDATE public.solo_challenge_claims
         SET progress = v_new
       WHERE id = v_claim_id;
      v_bumped := v_bumped + 1;
    END IF;
  END LOOP;

  RETURN jsonb_build_object('claims_updated', v_bumped);
END;
$$;


ALTER FUNCTION "public"."update_solo_challenge_progress"("p_volume_lbs" numeric, "p_session_count" integer, "p_cardio_min" integer, "p_prs_hit" integer) OWNER TO "postgres";


