CREATE OR REPLACE FUNCTION "public"."upsert_push_subscription"("p_endpoint" "text", "p_p256dh_key" "text", "p_auth_key" "text", "p_user_agent" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_uid UUID:=auth.uid(); v_email TEXT:=NULLIF(public.current_user_email(), ''); v_id UUID;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE='42501'; END IF;
  IF p_endpoint IS NULL OR p_p256dh_key IS NULL OR p_auth_key IS NULL THEN
    RAISE EXCEPTION 'endpoint, p256dh_key, auth_key all required' USING ERRCODE='22023';
  END IF;
  INSERT INTO public.push_subscriptions
    (user_id,user_email,endpoint,p256dh_key,auth_key,user_agent)
  VALUES (v_uid,v_email,p_endpoint,p_p256dh_key,p_auth_key,p_user_agent)
  ON CONFLICT (endpoint) DO UPDATE SET
    user_id=EXCLUDED.user_id, user_email=EXCLUDED.user_email,
    p256dh_key=EXCLUDED.p256dh_key, auth_key=EXCLUDED.auth_key,
    user_agent=EXCLUDED.user_agent, last_seen_at=now()
  RETURNING id INTO v_id;
  RETURN v_id;
END; $$;


ALTER FUNCTION "public"."upsert_push_subscription"("p_endpoint" "text", "p_p256dh_key" "text", "p_auth_key" "text", "p_user_agent" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."use_streak_rescue"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid         UUID := auth.uid();
  v_today       DATE := (now() AT TIME ZONE 'UTC')::date;
  v_month_start DATE := date_trunc('month', now() AT TIME ZONE 'UTC')::date;
  v_yesterday   DATE := ((now() AT TIME ZONE 'UTC')::date - INTERVAL '1 day')::date;
  v_streak      INT;
  v_last_date   DATE;
  v_diff        INT;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;

  SELECT workout_streak, last_workout_date
    INTO v_streak, v_last_date
    FROM public.user_profiles WHERE id = v_uid FOR UPDATE;

  IF v_streak IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'no_profile');
  END IF;
  IF v_streak < 3 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'streak_too_short', 'current_streak', v_streak);
  END IF;
  IF v_last_date IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'no_last_workout');
  END IF;

  v_diff := v_today - v_last_date;
  IF v_diff <> 2 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_eligible',
      'current_streak', v_streak, 'days_since', v_diff);
  END IF;

  BEGIN
    INSERT INTO public.streak_rescues (user_id, month_start, streak_saved)
    VALUES (v_uid, v_month_start, v_streak);
  EXCEPTION WHEN unique_violation THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'already_used_this_month',
      'current_streak', v_streak);
  END;

  UPDATE public.user_profiles SET last_workout_date = v_yesterday WHERE id = v_uid;

  RETURN jsonb_build_object('ok', true, 'streak_saved', v_streak,
    'next_workout_continues_streak', true);
END;
$$;


ALTER FUNCTION "public"."use_streak_rescue"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."user_daily_quests_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_server_today DATE := (now() AT TIME ZONE 'utc')::date;
BEGIN
  IF current_user IN ('postgres', 'service_role') THEN RETURN NEW; END IF;
  IF TG_OP = 'INSERT' THEN
    IF NEW.quest_date IS NULL
       OR NEW.quest_date < v_server_today - 1
       OR NEW.quest_date > v_server_today + 1 THEN
      RAISE EXCEPTION 'quest_date out of range' USING ERRCODE = '22023';
    END IF;
    NEW.coin_reward := CASE NEW.difficulty
      WHEN 'easy' THEN 8 WHEN 'medium' THEN 20 WHEN 'hard' THEN 50
      WHEN 'crew' THEN 25 ELSE 0 END;
    NEW.xp_reward := CASE NEW.difficulty
      WHEN 'easy' THEN 20 WHEN 'medium' THEN 50 WHEN 'hard' THEN 120
      WHEN 'crew' THEN 60 ELSE 0 END;
    NEW.progress := 0;
    NEW.completed_at := NULL;
    NEW.claimed_at := NULL;
    RETURN NEW;
  END IF;
  IF NEW.coin_reward IS DISTINCT FROM OLD.coin_reward
     OR NEW.xp_reward  IS DISTINCT FROM OLD.xp_reward
     OR NEW.quest_date IS DISTINCT FROM OLD.quest_date
     OR NEW.difficulty IS DISTINCT FROM OLD.difficulty
     OR NEW.quest_id   IS DISTINCT FROM OLD.quest_id THEN
    RAISE EXCEPTION 'quest reward/identity is immutable' USING ERRCODE = '42501';
  END IF;
  IF NEW.claimed_at IS DISTINCT FROM OLD.claimed_at THEN
    RAISE EXCEPTION 'claimed_at is RPC-only (use claim_quest_atomic)' USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."user_daily_quests_guard"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."user_daily_volume_ceiling"("p_user_id" "uuid") RETURNS numeric
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_weight numeric; v_age numeric; v_gender text; v_budget numeric;
BEGIN
  SELECT COALESCE(weight_lbs, 160),
         COALESCE(age, EXTRACT(YEAR FROM age(birthday)), 36),
         COALESCE(lower(gender), 'male')
    INTO v_weight, v_age, v_gender
    FROM public.user_profiles WHERE id = p_user_id;

  IF v_weight IS NULL THEN
    v_weight := 160; v_age := 36; v_gender := 'male';
  END IF;

  v_budget := v_weight * 200;

  IF    v_age = LEAST(v_age, 17) THEN v_budget := v_budget * 0.85;
  ELSIF v_age = LEAST(v_age, 35) THEN v_budget := v_budget;
  ELSIF v_age = LEAST(v_age, 50) THEN v_budget := v_budget * 0.90;
  ELSIF v_age = LEAST(v_age, 65) THEN v_budget := v_budget * 0.75;
  ELSE  v_budget := v_budget * 0.55;
  END IF;

  IF v_gender = 'female' THEN v_budget := v_budget * 0.85; END IF;

  RETURN GREATEST(0, FLOOR(v_budget));
END;
$$;


ALTER FUNCTION "public"."user_daily_volume_ceiling"("p_user_id" "uuid") OWNER TO "postgres";


