ALTER TABLE "public"."user_profiles" OWNER TO "postgres";


COMMENT ON COLUMN "public"."user_profiles"."first_workout_capsule_granted" IS 'TRUE once the user has been granted the first-workout premium capsule reward. Idempotency flag for src/lib/data/capsules.js grantForFirstWorkout.';



COMMENT ON COLUMN "public"."user_profiles"."referred_by" IS 'Dormant denormalization created by mig 173 because the mig 142 trigger already guarded it; not yet populated by claim_referral.';



COMMENT ON COLUMN "public"."user_profiles"."dashboard_layout" IS 'Customize-home state: hiddenSections, widgetOrder, sectionLayouts. NULL = never customized. Written by Dashboard.jsx via db.auth.updateMe.';



COMMENT ON COLUMN "public"."user_profiles"."login_streak_capsule_through" IS 'Highest login-streak day already paid a milestone capsule. Guards grant_streak_capsule against repeat calls.';



COMMENT ON COLUMN "public"."user_profiles"."workout_streak_capsule_through" IS 'Highest workout-streak day already paid a milestone capsule.';



CREATE OR REPLACE VIEW "public"."leaderboard_eligible_profiles" WITH ("security_invoker"='true') AS
 SELECT "id" AS "user_id",
    "username",
    "full_name",
    "avatar_url",
    (COALESCE("total_xp", 0))::numeric AS "xp_value",
    COALESCE("total_volume_lbs", (0)::numeric) AS "volume_value",
    COALESCE("total_distance_meters", (0)::numeric) AS "distance_value",
    (COALESCE("achievements_unlocked_count", 0))::numeric AS "achievements_value"
   FROM "public"."user_profiles"
  WHERE (COALESCE("hide_from_search", false) = false);


ALTER VIEW "public"."leaderboard_eligible_profiles" OWNER TO "postgres";


