CREATE OR REPLACE VIEW "public"."public_profiles" WITH ("security_invoker"='true') AS
 SELECT "id",
    "username",
    "full_name",
    "avatar_url",
    "bio",
        CASE
            WHEN "full_view" THEN "city"
            ELSE NULL::"text"
        END AS "city",
    "country_flag",
        CASE
            WHEN "full_view" THEN "website_url"
            ELSE NULL::"text"
        END AS "website_url",
    "is_private",
    "created_at",
        CASE
            WHEN "full_view" THEN "last_active_at"
            ELSE NULL::timestamp with time zone
        END AS "last_active_at",
        CASE
            WHEN "full_view" THEN "total_xp"
            ELSE NULL::integer
        END AS "total_xp",
        CASE
            WHEN "full_view" THEN "current_level"
            ELSE NULL::integer
        END AS "current_level",
        CASE
            WHEN "full_view" THEN "prestige_level"
            ELSE NULL::integer
        END AS "prestige_level",
        CASE
            WHEN "full_view" THEN "lifetime_xp"
            ELSE NULL::integer
        END AS "lifetime_xp",
        CASE
            WHEN "full_view" THEN "total_volume_lbs"
            ELSE NULL::numeric
        END AS "total_volume_lbs",
        CASE
            WHEN "full_view" THEN "total_distance_meters"
            ELSE NULL::numeric
        END AS "total_distance_meters",
        CASE
            WHEN "full_view" THEN "achievements_unlocked_count"
            ELSE NULL::integer
        END AS "achievements_unlocked_count",
        CASE
            WHEN "full_view" THEN "workout_streak"
            ELSE NULL::integer
        END AS "workout_streak",
        CASE
            WHEN "full_view" THEN "longest_workout_streak"
            ELSE NULL::integer
        END AS "longest_workout_streak",
        CASE
            WHEN "full_view" THEN "league_tier"
            ELSE NULL::"text"
        END AS "league_tier",
    "equipped_title_id",
    "equipped_frame_id",
    "signature_trophy",
    "loot_theme_id",
    "preferred_theme",
        CASE
            WHEN "full_view" THEN "trophy_case"
            ELSE NULL::"jsonb"
        END AS "trophy_case",
    "trophy_case_visible",
    "nemesis_opt_out",
    "story_dms_disabled",
    "default_story_privacy",
    "hide_from_search",
    "display_name"
   FROM ( SELECT "user_profiles"."id",
            "user_profiles"."email",
            "user_profiles"."username",
            "user_profiles"."bio",
            "user_profiles"."avatar_url",
            "user_profiles"."full_name",
            "user_profiles"."onboarding_completed",
            "user_profiles"."onboarding_goal",
            "user_profiles"."onboarding_experience",
            "user_profiles"."onboarding_days_per_week",
            "user_profiles"."total_xp",
            "user_profiles"."current_level",
            "user_profiles"."achievements_unlocked_count",
            "user_profiles"."total_volume_lbs",
            "user_profiles"."total_distance_meters",
            "user_profiles"."account_reset_at",
            "user_profiles"."created_at",
            "user_profiles"."updated_at",
            "user_profiles"."fitness_goals",
            "user_profiles"."fitness_level",
            "user_profiles"."training_days",
            "user_profiles"."preferred_workout_time",
            "user_profiles"."age",
            "user_profiles"."height_cm",
            "user_profiles"."height_inches",
            "user_profiles"."height_unit",
            "user_profiles"."weight_kg",
            "user_profiles"."weight_lbs",
            "user_profiles"."weight_unit",
            "user_profiles"."onboarding_complete",
            "user_profiles"."preferred_theme",
            "user_profiles"."nutrition_onboarding_complete",
            "user_profiles"."flex_coins",
            "user_profiles"."login_streak",
            "user_profiles"."last_login_date",
            "user_profiles"."longest_login_streak",
            "user_profiles"."streak_freezes_available",
            "user_profiles"."workout_streak",
            "user_profiles"."last_workout_date",
            "user_profiles"."longest_workout_streak",
            "user_profiles"."league_tier",
            "user_profiles"."equipped_title_id",
            "user_profiles"."equipped_frame_id",
            "user_profiles"."loot_theme_id",
            "user_profiles"."milestone_capsules_awarded",
            "user_profiles"."timezone_offset_minutes",
            "user_profiles"."last_streak_nudge_at",
            "user_profiles"."preferred_language",
            "user_profiles"."notification_prefs",
            "user_profiles"."last_welcome_back_at",
            "user_profiles"."last_quest_nudge_at",
            "user_profiles"."story_dms_disabled",
            "user_profiles"."default_story_privacy",
            "user_profiles"."city",
            "user_profiles"."country_flag",
            "user_profiles"."trophy_case",
            "user_profiles"."trophy_case_visible",
            "user_profiles"."overthrow_count",
            "user_profiles"."nemesis_opt_out",
            "user_profiles"."prestige_level",
            "user_profiles"."lifetime_xp",
            "user_profiles"."prestiged_at",
            "user_profiles"."prestige_dismissed",
            "user_profiles"."first_workout_capsule_granted",
            "user_profiles"."last_active_at",
            "user_profiles"."last_daily_chest_at",
            "user_profiles"."level_capsules_awarded_through",
            "user_profiles"."active_until",
            "user_profiles"."referral_code",
            "user_profiles"."max_hr_bpm",
            "user_profiles"."quiet_hours_start",
            "user_profiles"."quiet_hours_end",
            "user_profiles"."website_url",
            "user_profiles"."account_type",
            "user_profiles"."is_private",
            "user_profiles"."hide_from_search",
            "user_profiles"."calorie_cycling",
            "user_profiles"."notification_snoozes",
            "user_profiles"."cycle_tracking_enabled",
            "user_profiles"."cycle_length_days",
            "user_profiles"."fitness_assessment",
            "user_profiles"."include_bar_in_volume",
            "user_profiles"."is_trainer",
            "user_profiles"."stripe_connect_id",
            "user_profiles"."trainer_bio",
            "user_profiles"."signature_trophy",
            "user_profiles"."fitness_goals_arr",
            "user_profiles"."onboarding_completed_at",
            "user_profiles"."referred_by",
            "user_profiles"."gender",
            "user_profiles"."weekly_rate_lbs",
            "user_profiles"."nutrition_goal",
            "user_profiles"."activity_level",
            "user_profiles"."target_weight_lbs",
            "user_profiles"."target_date",
            "user_profiles"."dietary_restrictions",
            "user_profiles"."birthday",
            "user_profiles"."dark_mode",
            "user_profiles"."distance_unit",
            "user_profiles"."dashboard_widgets",
            "user_profiles"."read_receipts_enabled",
            "user_profiles"."pity_since_epic",
            "user_profiles"."pity_since_legendary",
            "user_profiles"."dashboard_layout",
            "user_profiles"."login_streak_capsule_through",
            "user_profiles"."workout_streak_capsule_through",
            "user_profiles"."home_gym_id",
            "user_profiles"."league_inactive_weeks",
            "user_profiles"."league_shields_owned",
            "user_profiles"."league_shields_lifetime",
            "user_profiles"."league_shield_used_at",
            "user_profiles"."display_name",
            "user_profiles"."username_changed_at",
            ((NOT "user_profiles"."is_private") OR ("user_profiles"."id" = "auth"."uid"()) OR "public"."viewer_follows"("user_profiles"."email")) AS "full_view"
           FROM "public"."user_profiles"
          WHERE (NOT "public"."viewer_is_blocked_by"("user_profiles"."email"))) "visible_profiles";


ALTER VIEW "public"."public_profiles" OWNER TO "postgres";


COMMENT ON VIEW "public"."public_profiles" IS 'Public projection of user_profiles. SECURITY DEFINER by design: column privileges are per-role, not per-row, so "public columns for everyone, all columns for me" cannot be expressed with RLS + GRANTs alone. Compensating controls: email is not in the column list; row rules (viewer_is_blocked_by, is_private via viewer_follows) are enforced INSIDE the view; anon holds no privileges; authenticated holds SELECT only. See migration 315.';



