CREATE POLICY "Allow public read" ON "public"."checklist_items" FOR SELECT USING (true);



CREATE POLICY "Allow public update" ON "public"."checklist_items" FOR UPDATE USING (true);



CREATE POLICY "Allow public write" ON "public"."checklist_items" FOR INSERT WITH CHECK (true);



CREATE POLICY "Anyone can read reactions" ON "public"."post_sticker_reactions" FOR SELECT USING (true);



CREATE POLICY "Crew admins can assign regimens" ON "public"."crew_assigned_regimens" FOR INSERT WITH CHECK ("public"."is_crew_moderator"("crew_id"));



CREATE POLICY "Crew admins can pin messages" ON "public"."crew_messages" FOR UPDATE USING ("public"."is_crew_moderator"("crew_id")) WITH CHECK ("public"."is_crew_moderator"("crew_id"));



CREATE POLICY "Crew admins can remove assigned regimens" ON "public"."crew_assigned_regimens" FOR DELETE USING ("public"."is_crew_moderator"("crew_id"));



