ALTER TABLE "public"."workout_templates" ENABLE ROW LEVEL SECURITY;


CREATE POLICY "workout_templates: owner full access" ON "public"."workout_templates" USING (((( SELECT NULLIF("public"."current_user_email"(), ''::"text") AS "email") = "created_by") OR (( SELECT "auth"."uid"() AS "uid") = "user_id"))) WITH CHECK (((("created_by" IS NULL) OR ("created_by" = ( SELECT NULLIF("public"."current_user_email"(), ''''::"text") AS "nullif"))) AND (("user_id" IS NULL) OR ("user_id" = ( SELECT "auth"."uid"() AS "uid"))) AND (("created_by" IS NOT NULL) OR ("user_id" IS NOT NULL))));



CREATE POLICY "workout_templates: public templates readable" ON "public"."workout_templates" FOR SELECT USING (("is_public" = true));



CREATE POLICY "xp_claims_insert" ON "public"."crew_xp_claims" FOR INSERT WITH CHECK (("user_id" = ( SELECT "auth"."uid"() AS "uid")));



CREATE POLICY "xp_claims_select" ON "public"."crew_xp_claims" FOR SELECT USING (("user_id" = ( SELECT "auth"."uid"() AS "uid")));



ALTER TABLE "public"."xp_grant_log" ENABLE ROW LEVEL SECURITY;


ALTER TABLE "public"."xp_level_thresholds" ENABLE ROW LEVEL SECURITY;




